template <typename GL>
inline constexpr bool cta2_fused_dense_is_compact_mixed_dp_do_gl =
    std::is_same_v<
        std::remove_cv_t<std::remove_reference_t<GL>>,
        cta2_fused_dense_mixed_dp_do_compact_gl
    >;

template <typename GL>
inline constexpr bool cta2_fused_dense_is_compact_mixed_dp_v_gl =
    std::is_same_v<
        std::remove_cv_t<std::remove_reference_t<GL>>,
        cta2_fused_dense_mixed_dp_v_compact_gl
    >;

template <typename GL>
__device__ __forceinline__ constexpr uint32_t
cta2_fused_dense_mixed_dp_do_transfer_bytes() {
    if constexpr (cta2_fused_dense_is_compact_mixed_dp_do_gl<GL>) {
        return sizeof(cta2_fused_dense_mixed_dp_do_head_tile) +
            sizeof(cta2_fused_dense_mixed_dp_do_tail_tma_tile);
    } else {
        return sizeof(cta2_fused_dense_do_dp_fp8_tile);
    }
}

template <typename GL>
__device__ __forceinline__ constexpr uint32_t
cta2_fused_dense_mixed_dp_v_transfer_bytes() {
    if constexpr (cta2_fused_dense_is_compact_mixed_dp_v_gl<GL>) {
        return sizeof(cta2_fused_dense_mixed_dp_v_head_tile) +
            sizeof(cta2_fused_dense_mixed_dp_v_tail_tma_tile);
    } else {
        return sizeof(cta2_fused_dense_v_fp8_tile);
    }
}

template <typename GL>
__device__ __forceinline__ void
cta2_fused_dense_load_mixed_dp_do_async(
    cta2_fused_dense_do_dp_fp8_tile &dst,
    const GL &src,
    const coord<cta2_fused_dense_do_dp_fp8_tile> &tile_coord,
    semaphore &bar
) {
    if constexpr (cta2_fused_dense_is_compact_mixed_dp_do_gl<GL>) {
        auto &compact = *reinterpret_cast<
            cta2_fused_dense_mixed_dp_do_compact_tma_tile *
        >(&dst);
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            compact,
            src,
            coord<cta2_fused_dense_mixed_dp_do_compact_tma_tile>{
                tile_coord.b, tile_coord.d, tile_coord.r, 0
            },
            bar
        );
    } else {
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            dst,
            src,
            tile_coord,
            bar
        );
    }
}

template <typename GL>
__device__ __forceinline__ void
cta2_fused_dense_load_mixed_dp_v_async(
    cta2_fused_dense_v_fp8_tile &dst,
    const GL &src,
    const coord<cta2_fused_dense_v_fp8_tile> &tile_coord,
    semaphore &bar
) {
    if constexpr (cta2_fused_dense_is_compact_mixed_dp_v_gl<GL>) {
        auto &compact = *reinterpret_cast<
            cta2_fused_dense_mixed_dp_v_compact_tma_tile *
        >(&dst);
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            compact,
            src,
            coord<cta2_fused_dense_mixed_dp_v_compact_tma_tile>{
                tile_coord.b, tile_coord.d, tile_coord.r, 0
            },
            bar
        );
    } else {
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            dst,
            src,
            tile_coord,
            bar
        );
    }
}

__device__ __forceinline__ cta2_fused_dense_mxfp4_scale_tile &
cta2_fused_dense_mixed_dp_v_scale_stage(
    cta2_fused_dense_v_tile &storage
) {
    auto *base = reinterpret_cast<unsigned char *>(&storage);
    return *reinterpret_cast<cta2_fused_dense_mxfp4_scale_tile *>(
        base + sizeof(cta2_fused_dense_v_fp8_tile)
    );
}

__device__ __forceinline__ cta2_fused_dense_mxfp4_scale_tile &
cta2_fused_dense_mixed_dp_do_scale_stage(
    cta2_fused_dense_v_tile &storage
) {
    auto *base = reinterpret_cast<unsigned char *>(&storage);
    return *reinterpret_cast<cta2_fused_dense_mxfp4_scale_tile *>(
        base + sizeof(cta2_fused_dense_v_fp8_tile) +
            sizeof(cta2_fused_dense_mxfp4_scale_tile)
    );
}

static_assert(
    sizeof(cta2_fused_dense_v_fp8_tile) +
            2 * sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_v_tile)
);

__device__ __forceinline__ cta2_fused_dense_do_mxfp4_tile &
cta2_fused_dense_mxfp4_dv_do_stage(
    cta2_fused_dense_do_tile &storage
) {
    // Keep the prepacked dV operand disjoint from the live 8 KiB E4M3 dP
    // operand.  The old base-zero landing address made the two TMA loads in
    // the grouped Q/dO transaction overwrite one another.
    auto *base = reinterpret_cast<unsigned char *>(&storage);
    return *reinterpret_cast<cta2_fused_dense_do_mxfp4_tile *>(
        base + sizeof(cta2_fused_dense_do_dp_fp8_tile)
    );
}

