static_assert(
    sizeof(cta2_fused_dense_do_dp_fp8_tile) +
            sizeof(cta2_fused_dense_do_mxfp4_tile) +
            sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_do_tile)
);

static_assert(
    sizeof(cta2_fused_dense_do_dp_mxfp4_tile) +
            sizeof(cta2_fused_dense_do_mxfp4_tile) +
            sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_do_tile)
);
static_assert(
    sizeof(cta2_fused_dense_v_dp_mxfp4_tile) +
            sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_v_tile)
);

static_assert(
    sizeof(cta2_fused_dense_do_dp_fp8_tile) +
            sizeof(cta2_fused_dense_do_fp8_tile) ==
        sizeof(cta2_fused_dense_do_tile)
);
static_assert(
    sizeof(cta2_fused_dense_do_dp_fp8_tile) +
            sizeof(cta2_fused_dense_do_fp8_head_tile) +
            sizeof(cta2_fused_dense_do_mxfp4_tile) <=
        sizeof(cta2_fused_dense_do_tile)
);
