enum : int {
    kCta2DenseLowpNone = 0,
    kCta2DenseLowpFp8 = 1,
    kCta2DenseLowpFp4 = 2,
    kCta2DenseLowpFp4Fp8Pv = 3,
    kCta2DenseLowpFp4Fp8PvReuseP = 4,
    kCta2DenseLowpFp4Fp8DpPvReuseP = 5,
    kCta2DenseLowpFp4Fp8DpMxFp4DvReuseP = 6,
    kCta2DenseLowpFp4Fp8DpMxFp4DvForwardLogReuseP = 8,
    kCta2DenseLowpFp4Fp8DpMxFp4DvForwardLogSplitQReuseP = 9,
    kCta2DenseLowpFp4MxFp4DpDvForwardLogSplitQReuseP = 10,
    kCta2DenseLowpFp4MxFp4DpDvDsDqDkForwardLogSplitQReuseP = 11,
    kCta2DenseLowpFp4MixedFp8MxFp4DpFp8DvReuseP = 12,
};

constexpr float kCta2DenseFp8DefaultDsQuantScale = 4096.0f;
constexpr float kCta2DenseFp4DefaultDsQuantScale = 4096.0f;
constexpr uint32_t kCta2DenseFp8DsBf16PairDelta =
    (12u << 7) * 0x00010001u;
constexpr uint32_t kCta2DenseFp8DsF32Delta = 12u << 23;
constexpr uint32_t kCta2DenseFp8PvPScaleF32Delta = 8u << 23;
constexpr uint32_t kCta2DenseFp8PvPScaleBf16PairDelta =
    (8u << 7) * 0x00010001u;
constexpr uint32_t kCta2DenseFp8PvDoScaleBf16PairDelta =
    (8u << 7) * 0x00010001u;
constexpr uint32_t kCta2DenseFp8ReuseDsHalfPairDelta =
    (4u << 10) * 0x00010001u;
constexpr uint32_t kCta2DenseFp8DpOperandScaleBf16PairDelta =
    (2u << 7) * 0x00010001u;

template <
    typename DkdvOutT,
    bool DirectTmaDkQ = false,
    int LowpMode = kCta2DenseLowpNone
>
struct cta2_fused_dense_globals_t;

template <typename DkdvOutT, bool DirectTmaDkQ>
struct cta2_fused_dense_globals_t<
    DkdvOutT,
    DirectTmaDkQ,
    kCta2DenseLowpNone
> {
    using q_gl = std::conditional_t<
        DirectTmaDkQ,
        cta2_fused_dense_q_dk_tma_gl,
        cta2_fused_dense_q_gl
    >;
    cta2_fused_dense_k_gl k;
    q_gl q;
    cta2_fused_dense_v_gl v;
    cta2_fused_dense_do_gl dout;
    cta2_fused_dense_output_gl_t<DkdvOutT> dk;
    cta2_fused_dense_output_gl_t<DkdvOutT> dv;
    cta2_fused_dense_dq_gl dq;
    cta2_fused_dense_stats_gl lse_log2;
    cta2_fused_dense_stats_gl dpsum;
    float scale;
    float scale_log2e;
    int seq_len;
};

template <typename DkdvOutT, bool DirectTmaDkQ>
struct cta2_fused_dense_globals_t<
    DkdvOutT,
    DirectTmaDkQ,
    kCta2DenseLowpFp8
> : cta2_fused_dense_globals_t<
        DkdvOutT,
        DirectTmaDkQ,
        kCta2DenseLowpNone
    > {
    cta2_fused_dense_q_fp8_gl q_fp8;
    cta2_fused_dense_k_fp8_gl k_fp8;
    cta2_fused_dense_do_fp8_gl dout_fp8;
    cta2_fused_dense_do_dp_fp8_gl dout_dp_fp8;
    cta2_fused_dense_v_fp8_gl v_fp8;
    float dq_output_scale;
    float dk_output_scale;
    float ds_quant_scale;
    float score_scale_log2e;
};

template <typename DkdvOutT, bool DirectTmaDkQ>
struct cta2_fused_dense_globals_t<
    DkdvOutT,
    DirectTmaDkQ,
    kCta2DenseLowpFp4MixedFp8MxFp4DpFp8DvReuseP
> : cta2_fused_dense_globals_t<
        DkdvOutT,
        DirectTmaDkQ,
        kCta2DenseLowpNone
    > {
    cta2_fused_dense_q_fp4_gl q_fp4;
    cta2_fused_dense_score_q_fp4_gl score_q_fp4;
    cta2_fused_dense_k_fp4_gl k_fp4;
    cta2_fused_dense_score_k_fp4_gl score_k_fp4;
    std::conditional_t<
        TK_FA4_BWD_MIXED_DV_THREE_COMMAND,
        cta2_fused_dense_do_fp8_head_gl,
        cta2_fused_dense_do_fp8_gl
    > dout_fp8;
    cta2_fused_dense_mixed_dp_do_gl dout_dp_fp8;
    cta2_fused_dense_mixed_dp_v_gl v_fp8;
    cta2_fused_dense_mxfp4_scale_tma_gl dout_dp_mxfp4_scale;
    cta2_fused_dense_mxfp4_scale_tma_gl v_dp_mxfp4_scale;
#if TK_FA4_BWD_FP8DPDV_STREAM_DV_TAIL_BF16
    cta2_fused_dense_output_gl_t<float> dv_tail_stream;
#endif
#if TK_FA4_BWD_MIXED_DV_THREE_COMMAND
    cta2_fused_dense_do_mxfp4_gl dout_mxfp4;
    cta2_fused_dense_mxfp4_scale_tma_gl dout_mxfp4_scale;
#endif
    float dq_output_scale;
    float dk_output_scale;
    float ds_quant_scale;
    float score_scale_log2e;
    const float *adaptive_qk_scales;
};

template <typename DkdvOutT, bool DirectTmaDkQ>
struct cta2_fused_dense_globals_t<
    DkdvOutT,
    DirectTmaDkQ,
    kCta2DenseLowpFp4MxFp4DpDvDsDqDkForwardLogSplitQReuseP
