template <
    bool ArmTransaction,
    bool SplitQTransaction = false,
    typename QGL
>
__device__ __forceinline__ void
cta2_fused_dense_load_fp8_score_qdo_dual_elected(
    cta2_fused_dense_score_q_fp8_tile &q_dst,
    const QGL &q_src,
    cta2_fused_dense_do_dp_fp8_tile &do_dp_dst,
    const cta2_fused_dense_do_dp_fp8_gl &do_dp_src,
    cta2_fused_dense_do_fp8_tile &do_dv_dst,
    const cta2_fused_dense_do_fp8_gl &do_dv_src,
    const coord<cta2_fused_dense_score_q_fp8_tile> &q_tile_coord,
    const coord<cta2_fused_dense_do_dp_fp8_tile> &do_dp_tile_coord,
    const coord<cta2_fused_dense_do_fp8_tile> &do_dv_tile_coord,
    semaphore &bar,
    uint32_t additional_expected_bytes = 0,
    semaphore *q_bar = nullptr
) {
    if (laneid() == 0) {
        if constexpr (ArmTransaction) {
            if constexpr (SplitQTransaction) {
                tma::expect_bytes(
                    *q_bar,
                    sizeof(q_dst) + additional_expected_bytes
                );
                tma::expect_bytes(
                    bar,
                    sizeof(do_dp_dst) + sizeof(do_dv_dst)
                );
            } else {
                tma::expect_bytes(
                    bar,
                    sizeof(q_dst) + sizeof(do_dp_dst) +
                        sizeof(do_dv_dst) + additional_expected_bytes
                );
            }
        }
        tma::load_async<dim::ROW, cache_policy::NORMAL>(
            q_dst,
            q_src,
            q_tile_coord,
            SplitQTransaction ? *q_bar : bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dp_dst,
            do_dp_src,
            do_dp_tile_coord,
            bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dv_dst,
            do_dv_src,
            do_dv_tile_coord,
            bar
        );
    }
}

template <bool ArmTransaction, typename QGL>
__device__ __forceinline__ void
cta2_fused_dense_load_fp8_score_qdo_lowp_elected_pair(
    cta2_fused_dense_score_q_fp8_tile &q_dst,
    const QGL &q_src,
    cta2_fused_dense_do_tile &do_storage,
    const cta2_fused_dense_do_dp_fp8_gl &do_dp_src,
    const cta2_fused_dense_do_fp8_gl &do_dv_src,
    const coord<cta2_fused_dense_score_q_fp8_tile> &q_tile_coord,
    int batch_idx,
    int q_tile_idx,
    int head_idx,
    int cta_rank,
    semaphore &bar,
    uint32_t additional_expected_bytes = 0
) {
    auto &do_dp = cta2_fused_dense_fp8_dp_do_stage(do_storage);
    auto &do_dv = cta2_fused_dense_fp8_dv_do_stage(do_storage);
    cta2_fused_dense_load_fp8_score_qdo_dual_elected<
        ArmTransaction
    >(
        q_dst,
        q_src,
        do_dp,
        do_dp_src,
        do_dv,
        do_dv_src,
        q_tile_coord,
        coord<cta2_fused_dense_do_dp_fp8_tile>{
            batch_idx,
            q_tile_idx * 2 + cta_rank,
            head_idx,
            0
        },
        coord<cta2_fused_dense_do_fp8_tile>{
            batch_idx,
            q_tile_idx,
            head_idx,
            cta_rank
        },
        bar,
        additional_expected_bytes
    );
}

template <bool ArmTransaction, bool SplitQTransaction = false>
__device__ __forceinline__ void
cta2_fused_dense_load_dual_fp4_score_qdo_dual_elected(
    cta2_fused_dense_score_q_fp8_tile &q_aligned_dst,
    const cta2_fused_dense_q_fp4_gl &q_aligned_src,
    cta2_fused_dense_score_q_fp4_tile &q_compact_dst,
    const cta2_fused_dense_score_q_fp4_gl &q_compact_src,
    cta2_fused_dense_do_dp_fp8_tile &do_dp_dst,
    const cta2_fused_dense_do_dp_fp8_gl &do_dp_src,
    cta2_fused_dense_do_fp8_tile &do_dv_dst,
    const cta2_fused_dense_do_fp8_gl &do_dv_src,
    const coord<cta2_fused_dense_score_q_fp8_tile> &q_aligned_coord,
    const coord<cta2_fused_dense_score_q_fp4_tile> &q_compact_coord,
    const coord<cta2_fused_dense_do_dp_fp8_tile> &do_dp_coord,
    const coord<cta2_fused_dense_do_fp8_tile> &do_dv_coord,
    semaphore &bar,
    uint32_t additional_expected_bytes = 0,
    semaphore *q_bar = nullptr
) {
    if (laneid() == 0) {
        if constexpr (ArmTransaction) {
            if constexpr (SplitQTransaction) {
                tma::expect_bytes(
                    *q_bar,
                    sizeof(q_aligned_dst) + sizeof(q_compact_dst) +
                        additional_expected_bytes
                );
                tma::expect_bytes(
                    bar,
                    sizeof(do_dp_dst) + sizeof(do_dv_dst)
                );
            } else {
                tma::expect_bytes(
                    bar,
                    sizeof(q_aligned_dst) + sizeof(q_compact_dst) +
                        sizeof(do_dp_dst) + sizeof(do_dv_dst) +
                        additional_expected_bytes
                );
            }
        }
        semaphore &q_transaction = SplitQTransaction ? *q_bar : bar;
        tma::load_async<dim::ROW, cache_policy::NORMAL>(
            q_aligned_dst,
            q_aligned_src,
            q_aligned_coord,
            q_transaction
        );
        tma::load_async<dim::ROW, cache_policy::NORMAL>(
            q_compact_dst,
            q_compact_src,
            q_compact_coord,
            q_transaction
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dp_dst,
            do_dp_src,
            do_dp_coord,
            bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dv_dst,
