template <
    bool ArmTransaction,
    bool SplitQTransaction = false,
    bool LoadQ = true,
    typename DoDpGL
>
__device__ __forceinline__ void
cta2_fused_dense_load_fp4_score_qdo_mixed_dp_elected(
    cta2_fused_dense_score_q_fp4_tile &q_dst,
    const cta2_fused_dense_score_q_fp4_gl &q_src,
    cta2_fused_dense_do_dp_fp8_tile &do_dp_dst,
    const DoDpGL &do_dp_src,
    cta2_fused_dense_do_fp8_tile &do_dv_dst,
    const cta2_fused_dense_do_fp8_gl &do_dv_src,
    cta2_fused_dense_mxfp4_scale_tile &do_scale_dst,
    const cta2_fused_dense_mxfp4_scale_tma_gl &do_scale_src,
    int do_scale_page,
    const coord<cta2_fused_dense_score_q_fp4_tile> &q_tile_coord,
    const coord<cta2_fused_dense_do_dp_fp8_tile> &do_dp_tile_coord,
    const coord<cta2_fused_dense_do_fp8_tile> &do_dv_tile_coord,
    semaphore &bar,
    semaphore &scale_bar,
    uint32_t additional_expected_bytes = 0,
    semaphore *q_bar = nullptr
) {
    if (laneid() == 0) {
        // Keep the winner's Q+dO transaction unchanged.  The independent
        // scale page gets its own phase so it cannot extend the qdo handoff.
        tma::expect_bytes(scale_bar, sizeof(do_scale_dst));
        if constexpr (ArmTransaction) {
            if constexpr (SplitQTransaction) {
                if constexpr (LoadQ) {
                    tma::expect_bytes(
                        *q_bar,
                        sizeof(q_dst) + additional_expected_bytes
                    );
                } else if (additional_expected_bytes != 0) {
                    tma::expect_bytes(*q_bar, additional_expected_bytes);
                }
                tma::expect_bytes(
                    bar,
                    cta2_fused_dense_mixed_dp_do_transfer_bytes<DoDpGL>() +
                        sizeof(do_dv_dst)
                );
            } else {
                tma::expect_bytes(
                    bar,
                    (LoadQ ? sizeof(q_dst) : 0) +
                        cta2_fused_dense_mixed_dp_do_transfer_bytes<DoDpGL>() +
                        sizeof(do_dv_dst) + additional_expected_bytes
                );
            }
        }
        if constexpr (LoadQ) {
            tma::load_async<dim::ROW, cache_policy::NORMAL>(
                q_dst,
                q_src,
                q_tile_coord,
                SplitQTransaction ? *q_bar : bar
            );
        }
        cta2_fused_dense_load_mixed_dp_do_async(
            do_dp_dst,
            do_dp_src,
            do_dp_tile_coord,
            bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dv_dst,
            do_dv_src,
            do_dv_tile_coord,
            bar
        );
        tma::load_async<dim::ROW, cache_policy::NORMAL>(
            do_scale_dst,
            do_scale_src,
            coord<cta2_fused_dense_mxfp4_scale_tile>{
                do_scale_page,
                0,
                0,
                0
            },
            scale_bar
        );
    }
}

template <
    bool ArmTransaction,
    bool SplitQTransaction = false,
    bool LoadQ = true
>
__device__ __forceinline__ void
cta2_fused_dense_load_fp4_score_qdo_mixed_dv_elected(
    cta2_fused_dense_score_q_fp4_tile &q_dst,
    const cta2_fused_dense_score_q_fp4_gl &q_src,
    cta2_fused_dense_do_dp_fp8_tile &do_dp_dst,
    const cta2_fused_dense_do_dp_fp8_gl &do_dp_src,
    cta2_fused_dense_do_fp8_head_tile &do_dv_head_dst,
    const cta2_fused_dense_do_fp8_head_gl &do_dv_head_src,
    cta2_fused_dense_do_mxfp4_tile &do_dv_tail_dst,
    const cta2_fused_dense_do_mxfp4_gl &do_dv_tail_src,
    cta2_fused_dense_mxfp4_scale_tile &do_dv_scale_dst,
    const cta2_fused_dense_mxfp4_scale_tma_gl &do_dv_scale_src,
    int do_dv_scale_page,
    const coord<cta2_fused_dense_score_q_fp4_tile> &q_tile_coord,
    const coord<cta2_fused_dense_do_dp_fp8_tile> &do_dp_tile_coord,
    const coord<cta2_fused_dense_do_fp8_head_tile> &do_dv_head_coord,
    const coord<cta2_fused_dense_do_mxfp4_tile> &do_dv_tail_coord,
    semaphore &bar,
    semaphore &dv_tail_bar,
    uint32_t additional_expected_bytes = 0,
    semaphore *q_bar = nullptr
) {
    // The mixed three-command dV path uses a compile-time fixed dO exponent.
    // Its MXFP4 tail therefore reuses the already-resident fixed dP scale page;
    // do not move the separately-materialized dV scale page through TMA.
    (void)do_dv_scale_dst;
    (void)do_dv_scale_src;
    (void)do_dv_scale_page;
    if (laneid() == 0) {
        if constexpr (!TK_FA4_BWD_MIXED_DV_PADDED_DO_TAIL) {
            tma::expect_bytes(
                dv_tail_bar,
                sizeof(do_dv_tail_dst)
            );
        }
        if constexpr (ArmTransaction) {
            if constexpr (SplitQTransaction) {
                if constexpr (LoadQ) {
                    tma::expect_bytes(
                        *q_bar,
                        sizeof(q_dst) + additional_expected_bytes
                    );
                } else if (additional_expected_bytes != 0) {
                    tma::expect_bytes(*q_bar, additional_expected_bytes);
                }
                tma::expect_bytes(
                    bar,
                    sizeof(do_dp_dst) + sizeof(do_dv_head_dst)
                );
            } else {
                tma::expect_bytes(
                    bar,
                    (LoadQ ? sizeof(q_dst) : 0) + sizeof(do_dp_dst) +
                        sizeof(do_dv_head_dst) + additional_expected_bytes
                );
            }
        }
        if constexpr (LoadQ) {
            tma::load_async<dim::ROW, cache_policy::NORMAL>(
                q_dst,
                q_src,
                q_tile_coord,
                SplitQTransaction ? *q_bar : bar
            );
        }
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dp_dst,
            do_dp_src,
            do_dp_tile_coord,
            bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            do_dv_head_dst,
            do_dv_head_src,
            do_dv_head_coord,
            bar
        );
        if constexpr (!TK_FA4_BWD_MIXED_DV_PADDED_DO_TAIL) {
            tma::load_async<dim::ROW, cache_policy::NORMAL>(
                do_dv_tail_dst,
                do_dv_tail_src,
                do_dv_tail_coord,
                dv_tail_bar
            );
        }
    }
}

