__device__ __forceinline__ int
cta2_fused_dense_mxfp4_scale_page_index(
    int batch_idx,
    int q_tile_idx,
    int head_idx,
    int q_tile_count,
    int head_count
) {
    return (batch_idx * q_tile_count + q_tile_idx) * head_count + head_idx;
}

template <bool ArmTransaction>
__device__ __forceinline__ void
cta2_fused_dense_load_fp4_score_qdo_elected_pair(
    cta2_fused_dense_score_q_fp4_tile &q_dst,
    const cta2_fused_dense_score_q_fp4_gl &q_src,
    cta2_fused_dense_do_tile &do_dst,
    const cta2_fused_dense_do_gl &do_src,
    const coord<cta2_fused_dense_score_q_fp4_tile> &q_tile_coord,
    const coord<cta2_fused_dense_do_tile> &do_tile_coord,
    semaphore &bar,
    uint32_t additional_expected_bytes = 0
) {
    const uint64_t q_tma = reinterpret_cast<uint64_t>(
        q_src.template get_tma<
            cta2_fused_dense_score_q_fp4_tile,
            dim::ROW
        >()
    );
    const uint64_t do_tma = reinterpret_cast<uint64_t>(
        do_src.template get_tma<cta2_fused_dense_do_tile, dim::DEPTH>()
    );
    const uint32_t q_smem = static_cast<uint32_t>(
        __cvta_generic_to_shared(&q_dst)
    );
    const uint32_t do_smem = static_cast<uint32_t>(
        __cvta_generic_to_shared(&do_dst)
    );
    const uint32_t bar_smem = static_cast<uint32_t>(
        __cvta_generic_to_shared(&bar)
    );
    const int4 q_tma_coord = ::kittens::tma::detail::tma_coords<
        cta2_fused_dense_score_q_fp4_tile,
        dim::ROW
    >(q_tile_coord.template unit_coord<dim::ROW, 3>());
    const int4 do_tma_coord = ::kittens::tma::detail::tma_coords<
        cta2_fused_dense_do_tile,
        dim::DEPTH
    >(do_tile_coord.template unit_coord<dim::DEPTH, 3>());

    if constexpr (ArmTransaction) {
        const uint32_t expected_bytes =
            sizeof(cta2_fused_dense_score_q_fp4_tile) +
            sizeof(cta2_fused_dense_do_tile) +
            additional_expected_bytes;
        asm volatile(
            "{\n"
            ".reg .pred leader;\n"
            "elect.sync _|leader, -1;\n"
            "@leader mbarrier.arrive.expect_tx.shared::cta.b64 "
            "_, [%4], %13;\n"
            "@leader cp.async.bulk.tensor.5d.shared::cluster.global.tile."
            "mbarrier::complete_tx::bytes "
            "[%0], [%1, {0, %5, %6, %7, %8}], [%4];\n"
            "@leader cp.async.bulk.tensor.5d.shared::cluster.global.tile."
            "mbarrier::complete_tx::bytes "
            "[%2], [%3, {0, %9, %10, %11, %12}], [%4];\n"
            "}\n"
            :
            : "r"(q_smem),
              "l"(q_tma),
              "r"(do_smem),
              "l"(do_tma),
              "r"(bar_smem),
              "r"(q_tma_coord.x),
              "r"(q_tma_coord.y),
              "r"(q_tma_coord.z),
              "r"(q_tma_coord.w),
              "r"(do_tma_coord.x),
              "r"(do_tma_coord.y),
              "r"(do_tma_coord.z),
              "r"(do_tma_coord.w),
              "r"(expected_bytes)
            : "memory"
        );
    } else {
        asm volatile(
            "{\n"
            ".reg .pred leader;\n"
            "elect.sync _|leader, -1;\n"
            "@leader cp.async.bulk.tensor.5d.shared::cluster.global.tile."
            "mbarrier::complete_tx::bytes "
            "[%0], [%1, {0, %5, %6, %7, %8}], [%4];\n"
            "@leader cp.async.bulk.tensor.5d.shared::cluster.global.tile."
            "mbarrier::complete_tx::bytes "
            "[%2], [%3, {0, %9, %10, %11, %12}], [%4];\n"
            "}\n"
            :
            : "r"(q_smem),
              "l"(q_tma),
              "r"(do_smem),
              "l"(do_tma),
              "r"(bar_smem),
              "r"(q_tma_coord.x),
              "r"(q_tma_coord.y),
              "r"(q_tma_coord.z),
              "r"(q_tma_coord.w),
              "r"(do_tma_coord.x),
              "r"(do_tma_coord.y),
              "r"(do_tma_coord.z),
              "r"(do_tma_coord.w)
            : "memory"
        );
    }
}

