template <typename KGL>
__device__ __forceinline__ void
cta2_fused_dense_load_score_k_fp8_v_fp8_elected(
    cta2_fused_dense_score_k_fp8_tile &k_dst,
    const KGL &k_src,
    const coord<cta2_fused_dense_score_k_fp8_tile> &k_tile_coord,
    cta2_fused_dense_v_fp8_tile &v_dst,
    const cta2_fused_dense_v_fp8_gl &v_src,
    const coord<cta2_fused_dense_v_fp8_tile> &v_tile_coord,
    semaphore &bar
) {
    if (laneid() == 0) {
        tma::expect_bytes(bar, sizeof(k_dst) + sizeof(v_dst));
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            k_dst,
            k_src,
            k_tile_coord,
            bar
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            v_dst,
            v_src,
            v_tile_coord,
            bar
        );
    }
}

