using cta2_fused_dense_p_tile = st_bf<128, 128>;
using cta2_fused_dense_ds_tile = st_bf<128, 128>;
using cta2_fused_dense_ds_fp8_tile = st_fp8e4m3<128, 128>;
using cta2_fused_dense_ds_fp4_tile = st_fp8e4m3<128, 128>;
using cta2_fused_dense_q_t0_tile = st_bf<64, 128>;
using cta2_fused_dense_q_t1_tile = st_bf<32, 128>;
using cta2_fused_dense_q_t_wide_tile = st_bf<96, 128>;
using cta2_fused_dense_dq_a_tile = st_bf<256, 64>;
using cta2_fused_dense_dq_b_tile = st_bf<256, 96>;
// E4M3 supports a transpose-major A descriptor, so retain V382's physical
// [key, query-half] dS layout and issue dQ as dS^T K.  This avoids
// materializing a second, explicitly transposed copy of quantized dS.
using cta2_fused_dense_dq_a_fp8_tile = st_fp8e4m3<256, 64>;
using cta2_fused_dense_dq_exchange_fp8_tile = st_fp8e4m3<128, 64>;
// Keep dS in [key, query-half] form and pair it with row-major E2M1 K.  The
// mixed descriptor transposes both physical operands, avoiding an explicit dS
// transpose in the producer warps.
using cta2_fused_dense_dq_a_fp4_tile = st_fp8e4m3<256, 64>;
using cta2_fused_dense_dq_exchange_fp4_tile = st_fp8e4m3<128, 64>;
// True block-scaled dS uses compact E2M1 in both physical orientations.
// dK sees [K128, packed-Q128]; dQ sees [Q64, packed-K256] per CTA and
// receives one [Q64, packed-K128] half from its peer.
using cta2_fused_dense_dk_ds_mxfp4_tile = st_fp4e2m1_2<128, 64>;
// Force a 64-byte swizzle so the two packed-K128 halves are contiguous raw
// storage blocks.  That makes the peer half byte-compatible with the
// 64x64 exchange tile and preserves the existing one-shot cluster bulk copy.
using cta2_fused_dense_dq_a_mxfp4_tile =
    st_fp4e2m1_2<64, 128, true, 64>;
using cta2_fused_dense_dq_exchange_mxfp4_tile = st_fp4e2m1_2<64, 64>;
// Transpose-major dQ keeps M64 as the packed minor axis and K256 as the
// physical row axis.  Its two aligned K128 halves are byte-contiguous, so a
// peer bulk copy can gather the full reduction operand without transposing
// any E2M1 nibbles.
using cta2_fused_dense_dq_a_mxfp4_transpose_tile =
    st_fp4e2m1_2<128, 64, true, 64>;
using cta2_fused_dense_dq_exchange_mxfp4_transpose_tile =
    st_fp4e2m1_2<64, 64, true, 64>;

#if TK_FA4_BWD_PURE_MXFP4_ALIGNED_MXF8F6F4_DQ
using cta2_fused_dense_dq_a_mxfp4_active_tile =
    cta2_fused_dense_dq_a_fp4_tile;
using cta2_fused_dense_dq_exchange_mxfp4_active_tile =
    cta2_fused_dense_dq_exchange_fp4_tile;
using cta2_fused_dense_dq_k_mxfp4_active_tile =
    cta2_fused_dense_dq_b_fp4_tile;
#else
using cta2_fused_dense_dq_a_mxfp4_active_tile =
    cta2_fused_dense_dq_a_mxfp4_tile;
using cta2_fused_dense_dq_exchange_mxfp4_active_tile =
    cta2_fused_dense_dq_exchange_mxfp4_tile;
using cta2_fused_dense_dq_k_mxfp4_active_tile =
    cta2_fused_dense_dq_k_mxfp4_tile;
#endif

static_assert(
    sizeof(cta2_fused_dense_dq_a_mxfp4_transpose_tile) ==
        sizeof(cta2_fused_dense_dq_a_mxfp4_tile)
);
static_assert(
    sizeof(cta2_fused_dense_dq_exchange_mxfp4_transpose_tile) ==
        sizeof(cta2_fused_dense_dq_exchange_mxfp4_tile)
);

static_assert(
    sizeof(cta2_fused_dense_dq_b_fp8_tile) +
            sizeof(cta2_fused_dense_ds_fp8_tile) +
            sizeof(cta2_fused_dense_dq_exchange_fp8_tile) <=
        sizeof(cta2_fused_dense_dq_b_tile)
);

static_assert(
    sizeof(cta2_fused_dense_dq_b_fp4_tile) +
            sizeof(cta2_fused_dense_ds_fp4_tile) +
            sizeof(cta2_fused_dense_dq_exchange_fp4_tile) <=
        sizeof(cta2_fused_dense_dq_b_tile)
);

static_assert(
    sizeof(cta2_fused_dense_dq_k_mxfp4_active_tile) +
            sizeof(cta2_fused_dense_dk_ds_mxfp4_tile) +
            sizeof(cta2_fused_dense_dq_exchange_mxfp4_active_tile) +
            4 * sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_dq_b_tile)
);
static_assert(
    sizeof(cta2_fused_dense_dq_k_mxfp4_active_tile) +
            sizeof(cta2_fused_dense_dk_ds_mxfp4_tile) +
            sizeof(cta2_fused_dense_dq_exchange_mxfp4_active_tile) +
            8 * sizeof(cta2_fused_dense_nvfp4_scale_tile) <=
        sizeof(cta2_fused_dense_dq_b_tile)
);

template <typename Storage>
__device__ __forceinline__ cta2_fused_dense_ds_fp8_tile &
cta2_fused_dense_fp8_ds_stage(Storage &storage) {
    // The FP8 dQ B operand occupies only the first half of the BF16-sized
    // dq_b allocation.  Its aligned tail is large enough for dS and remains
    // live-safe while persistent BF16 V stays in storage.ds.
    auto *base = reinterpret_cast<unsigned char *>(&storage.dq_b);
    return *reinterpret_cast<cta2_fused_dense_ds_fp8_tile *>(
        base + sizeof(cta2_fused_dense_dq_b_fp8_tile)
    );
}

