template <int Page, typename Storage>
__device__ __forceinline__ cta2_fused_dense_nvfp4_scale_tile &
cta2_fused_dense_nvfp4_ds_scale_stage(Storage &storage) {
    // NVFP4 consumes one 512-byte scale page per K64.  The eight transient
    // pages are, in order: dK dS low/high K64, dQ source-CTA 0 low/high,
    // dQ source-CTA 1 low/high, and compact-Q/K unit low/high.  They reuse
    // the MXFP4 scale staging region and otherwise-idle tail of dq_b.
    static_assert(Page >= 0 && Page < 8);
    auto *base = reinterpret_cast<unsigned char *>(&storage.dq_b);
    return *reinterpret_cast<cta2_fused_dense_nvfp4_scale_tile *>(
        base + sizeof(cta2_fused_dense_dq_k_mxfp4_active_tile) +
            sizeof(cta2_fused_dense_dk_ds_mxfp4_tile) +
            sizeof(cta2_fused_dense_dq_exchange_mxfp4_active_tile) +
            Page * sizeof(cta2_fused_dense_nvfp4_scale_tile)
    );
}

