template <typename G, typename Storage>
__device__ __forceinline__ void cta2_fused_dense_load_q_nvfp4_scales(
    Storage &storage,
    const G &g,
    int batch_idx,
    int head_idx,
    int,
    int q_tile_idx,
    semaphore &ready
) {
    const int k64_blocks = g.seq_len / 64;
    const int page_base =
        ((batch_idx * static_cast<int>(gridDim.y) + head_idx) * 2 *
             k64_blocks) +
        2 * q_tile_idx;
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<6>(storage),
        g.q_dk_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{page_base, 0, 0, 0},
        ready
    );
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<7>(storage),
        g.q_dk_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{page_base + 1, 0, 0, 0},
        ready
    );
}

