template <typename G, typename Storage>
__device__ __forceinline__ void cta2_fused_dense_load_k_nvfp4_scales(
    Storage &storage,
    const G &g,
    int batch_idx,
    int head_idx,
    int owner_idx,
    int reduction_half,
    semaphore &ready
) {
    const int k64_blocks = g.seq_len / 64;
    const int k64_base = 4 * owner_idx + 2 * reduction_half;
    const int head_page_base =
        ((batch_idx * static_cast<int>(gridDim.y) + head_idx) * 2) *
            k64_blocks +
        k64_base;
    const int tail_page_base = head_page_base + k64_blocks;
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<0>(storage),
        g.k_dq_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{
            head_page_base,
            0,
            0,
            0
        },
        ready
    );
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<1>(storage),
        g.k_dq_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{
            head_page_base + 1,
            0,
            0,
            0
        },
        ready
    );
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<6>(storage),
        g.k_dq_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{
            tail_page_base,
            0,
            0,
            0
        },
        ready
    );
    tma::load_async<dim::ROW, cache_policy::NORMAL>(
        cta2_fused_dense_nvfp4_ds_scale_stage<7>(storage),
        g.k_dq_nvfp4_scale,
        coord<cta2_fused_dense_nvfp4_scale_tile>{
            tail_page_base + 1,
            0,
            0,
            0
        },
        ready
    );
}

template <int PageCount, int ReaderWarpCount = 4, typename ScaleGl>
__device__ __forceinline__ void
cta2_fused_dense_publish_nvfp4_scale_pages_direct_tmem(
    uint32_t dst_addr,
    const ScaleGl &src,
    int page_base
) {
    static_assert(PageCount == 2 || PageCount == 4);
    static_assert(ReaderWarpCount == 2 || ReaderWarpCount == 4);
    const int lane = warp::laneid();
    #pragma unroll
    for (int page = 0; page < PageCount; ++page) {
        #pragma unroll
        for (
            int reader_warp = 0;
            reader_warp < ReaderWarpCount;
            ++reader_warp
        ) {
            // Prepared scale pages are lane-major: one packed word holds the
            // four K16 scale bytes for this 32-row N tile.  The N128 head
            // needs four x1 stores; an N64 tail consumes only the first two.
            const int offset =
                (page_base + page) * 512 + lane * 16 + reader_warp * 4;
            const uint32_t packed =
                *reinterpret_cast<const uint32_t *>(src.raw_ptr + offset);
            const uint32_t tmem_addr =
                dst_addr + static_cast<uint32_t>(page * 4 + reader_warp);
            asm volatile(
                "tcgen05.st.sync.aligned.32x32b.x1.b32 [%0], {%1};"
                :: "r"(tmem_addr), "r"(packed)
                : "memory"
            );
        }
    }
    asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
}

template <int K64Count, typename ScaleGl>
__device__ __forceinline__ void
cta2_fused_dense_publish_nvfp4_n192_scale_atlas_direct_tmem(
    uint32_t dst_addr,
    const ScaleGl &src,
    int head_page_base,
    int tail_page_base
) {
    static_assert(K64Count == 2 || K64Count == 4);
    const int lane = warp::laneid();
    #pragma unroll
    for (int k64 = 0; k64 < K64Count; ++k64) {
        // The 2-CTA N192 scale transport is padded to N256: four N32 groups
        // from the N128 head page followed by a four-column tail page, whose
        // final two groups are ignored by the N192 instruction.
        #pragma unroll
        for (int reader_warp = 0; reader_warp < 4; ++reader_warp) {
            const int offset =
                (head_page_base + k64) * 512 +
                lane * 16 + reader_warp * 4;
            const uint32_t packed =
                *reinterpret_cast<const uint32_t *>(src.raw_ptr + offset);
            const uint32_t tmem_addr =
                dst_addr + static_cast<uint32_t>(k64 * 8 + reader_warp);
            asm volatile(
                "tcgen05.st.sync.aligned.32x32b.x1.b32 [%0], {%1};"
                :: "r"(tmem_addr), "r"(packed)
                : "memory"
            );
        }
        #pragma unroll
        for (int reader_warp = 0; reader_warp < 2; ++reader_warp) {
            const int offset =
                (tail_page_base + k64) * 512 +
                lane * 16 + reader_warp * 4;
            const uint32_t packed =
                *reinterpret_cast<const uint32_t *>(src.raw_ptr + offset);
            const uint32_t tmem_addr =
                dst_addr + static_cast<uint32_t>(
                    k64 * 8 + 4 + reader_warp
                );
            asm volatile(
                "tcgen05.st.sync.aligned.32x32b.x1.b32 [%0], {%1};"
                :: "r"(tmem_addr), "r"(packed)
                : "memory"
            );
        }
    }
    asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
}

#endif

__device__ __forceinline__ void
cta2_fused_dense_load_scaled_dq_k(
    cta2_fused_dense_dq_b_tile &dst,
    const cta2_fused_dense_k_gl &src,
    const coord<cta2_fused_dense_dq_b_tile> &tile_coord,
    float scale
) {
    constexpr int kGroupThreads = 8 * WARP_THREADS;
    constexpr int kElementsPerVector =
        sizeof(float4) / sizeof(bf16);
    constexpr int kVectorsPerRow =
        cta2_fused_dense_dq_b_tile::cols / kElementsPerVector;
    constexpr int kVectorCalls =
        (
            cta2_fused_dense_dq_b_tile::rows *
                cta2_fused_dense_dq_b_tile::cols +
            kGroupThreads * kElementsPerVector - 1
        ) /
        (kGroupThreads * kElementsPerVector);

    const auto unit_coord =
        tile_coord.template unit_coord<dim::DEPTH, 3>();
    bf16 *src_ptr = reinterpret_cast<bf16 *>(&src[unit_coord]);
    const int row_stride = src.template stride<dim::DEPTH>();
    const uint32_t dst_ptr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    const int group_lane = threadIdx.x % kGroupThreads;
    const bf16_2 scale_pair =
        __floats2bfloat162_rn(scale, scale);

    #pragma unroll
    for (int call = 0; call < kVectorCalls; ++call) {
        const int load_idx = call * kGroupThreads + group_lane;
        const int row = load_idx / kVectorsPerRow;
        const int col =
            (load_idx * kElementsPerVector) %
            cta2_fused_dense_dq_b_tile::cols;
        float4 payload;
        move<float4>::ldg(
            payload,
            reinterpret_cast<float4 *>(
                &src_ptr[row * row_stride + col]
            )
        );
        bf16_2 *pairs = reinterpret_cast<bf16_2 *>(&payload);
        #pragma unroll
        for (int pair = 0; pair < 4; ++pair) {
            pairs[pair] = __hmul2(pairs[pair], scale_pair);
        }
        move<float4>::sts(
            cta2_fused_dense_dq_b_tile::idx(
                dst_ptr,
                {row, col}
            ),
            payload
        );
    }
}

