template <ducks::tt::all TM, ducks::rt::all RT>
__device__ __forceinline__ void cta2_role_split_store_fp8_tmem_warp(
    TM &dst,
    const RT &src,
    int row_subtile
) {
    // TK's generic register-to-TMEM helper currently has no 8-bit store
    // branch.  Emit the native packed 16-row store used by the forward FP8
    // probability path instead of silently dropping these writes.
    static_assert(std::is_same_v<typename TM::T, fp8e4m3>);
    static_assert(std::is_same_v<typename RT::T, fp8e4m3>);
    static_assert(RT::rows == 16 && RT::cols == TM::cols);
    const uint32_t row_base =
        dst.addr + (static_cast<uint32_t>(row_subtile * 16) << 16);
    #pragma unroll
    for (int tile_col = 0; tile_col < RT::width; ++tile_col) {
        const uint32_t address = row_base + tile_col * 8;
        asm volatile(
            "tcgen05.st.sync.aligned.16x128b.x2.b32 "
            "[%0], {%1, %2, %3, %4};\n"
            :: "r"(address),
               "r"(*reinterpret_cast<const uint32_t *>(
                   &src.tiles[0][tile_col].data[0]
               )),
               "r"(*reinterpret_cast<const uint32_t *>(
                   &src.tiles[0][tile_col].data[1]
               )),
               "r"(*reinterpret_cast<const uint32_t *>(
                   &src.tiles[0][tile_col].data[2]
               )),
               "r"(*reinterpret_cast<const uint32_t *>(
                   &src.tiles[0][tile_col].data[3]
               ))
            : "memory"
        );
    }
}
