    sizeof(cta2_fused_dense_q_fp4_transposed_wide_tile) <=
        sizeof(cta2_fused_dense_q_operand_storage)
);
static_assert(
    sizeof(cta2_fused_dense_score_q_fp4_tile) <=
        sizeof(cta2_fused_dense_q_operand_storage)
);
static_assert(
    sizeof(cta2_fused_dense_score_k_fp4_tile) <=
        sizeof(cta2_fused_dense_k_tile)
);
constexpr size_t kCta2FusedDenseEarlyCompactScoreQOffset =
    sizeof(cta2_fused_dense_score_q_fp8_tile);
constexpr size_t kCta2FusedDenseEarlyCompactScoreKOffset =
    sizeof(cta2_fused_dense_score_k_fp8_tile);
constexpr size_t kCta2FusedDenseEarlyCompactScoreScaleOffset =
    (kCta2FusedDenseEarlyCompactScoreKOffset +
     sizeof(cta2_fused_dense_score_k_fp4_tile) + 15) & ~size_t(15);
static_assert(
    kCta2FusedDenseEarlyCompactScoreQOffset +
            sizeof(cta2_fused_dense_score_q_fp4_tile) <=
        sizeof(cta2_fused_dense_q_operand_storage)
);
static_assert(
    kCta2FusedDenseEarlyCompactScoreScaleOffset +
            sizeof(cta2_fused_dense_score_scale_fp4_tile) <=
        sizeof(cta2_fused_dense_k_tile)
);
constexpr size_t kCta2FusedDenseFp4ScoreScaleOffset =
    sizeof(cta2_fused_dense_score_k_fp4_tile);
constexpr size_t kCta2FusedDenseFp4ScoreScaleBarrierOffset =
    (kCta2FusedDenseFp4ScoreScaleOffset +
     sizeof(cta2_fused_dense_score_scale_fp4_tile) + 15) & ~size_t(15);
constexpr size_t kCta2FusedDenseMxFp4PScaleOffset =
    (kCta2FusedDenseFp4ScoreScaleBarrierOffset +
     sizeof(semaphore) + 15) & ~size_t(15);
constexpr size_t kCta2FusedDenseNvFp4PSharedOffset =
    (kCta2FusedDenseMxFp4PScaleOffset +
     sizeof(cta2_fused_dense_mxfp4_scale_tile) + 1023) & ~size_t(1023);
constexpr size_t kCta2FusedDenseMxFp4DoScaleOffset =
    (kCta2FusedDenseNvFp4PSharedOffset +
     sizeof(cta2_fused_dense_p_nvfp4_tile) + 15) & ~size_t(15);
static_assert(
    kCta2FusedDenseFp4ScoreScaleBarrierOffset + sizeof(semaphore) <=
        sizeof(cta2_fused_dense_k_tile)
);
static_assert(
    kCta2FusedDenseMxFp4PScaleOffset +
            sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_k_tile)
);
static_assert(
    kCta2FusedDenseNvFp4PSharedOffset +
            sizeof(cta2_fused_dense_p_nvfp4_tile) <=
        sizeof(cta2_fused_dense_k_tile)
);
static_assert(
    kCta2FusedDenseMxFp4DoScaleOffset +
            sizeof(cta2_fused_dense_mxfp4_scale_tile) <=
        sizeof(cta2_fused_dense_k_tile)
);

__device__ __forceinline__ cta2_fused_dense_score_q_fp4_tile &
cta2_fused_dense_early_compact_score_q_smem(
    cta2_fused_dense_q_operand_storage &storage
) {
    return *reinterpret_cast<cta2_fused_dense_score_q_fp4_tile *>(
        reinterpret_cast<uint8_t *>(&storage) +
        kCta2FusedDenseEarlyCompactScoreQOffset
    );
}

