        "@leader tcgen05.mma.cta_group::2.kind::f16 "
            "[%2], %0, %1, 0x10200490, 1;\n\t"
        "add.u64 %0, %0, 0x2;\n\t"
        "add.u64 %1, %1, 0x2;\n\t"
        "@leader tcgen05.mma.cta_group::2.kind::f16 "
            "[%2], %0, %1, 0x10200490, 1;\n\t"
        "@leader tcgen05.commit.cta_group::2."
            "mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 "
            "[%3], %4;\n\t"
        "}\n"
        : "+l"(a_base_desc),
          "+l"(b_base_desc)
        : "r"(d_addr),
          "r"(commit_address),
          "h"(uint16_t{0b11})
        : "memory"
    );
}

template <int Accumulate = 0, ducks::tt::all D,
          ducks::st_descriptor::input A,
          ducks::st_descriptor::input B>
__device__ __forceinline__ void cta2_fused_dense_mm2_ab_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::cols;
    using input_type = typename A::T;
    using output_type = typename D::T;
    constexpr int kReductionDimension =
        ::kittens::reduction_dimension<input_type>;
    static_assert(
        kK == B::rows && kK % kReductionDimension == 0
    );
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);
    static_assert(std::is_same_v<input_type, typename B::T>);
    const uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::N,
            transpose::T,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<
        input_type,
        Accumulate,
        kCtaGroup
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (
        int chunk = 1;
        chunk < kK / kReductionDimension;
        ++chunk
    ) {
        ::kittens::detail::tcgen05::template st_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk),
            b_desc.chunk_descriptor(chunk),
            instruction
        );
    }
}

template <ducks::tt::all D, ducks::st_descriptor::input A,
          ducks::st_descriptor::input B>
__device__ __forceinline__ void
cta2_fused_dense_mm2_ab_no_fence_runtime_accumulate(
    D &d,
    const A &a,
    const B &b,
    bool accumulate
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::cols;
    static_assert(kK == B::rows && kK % 16 == 0);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    using input_type = typename A::T;
    using output_type = typename D::T;
    static_assert(std::is_same_v<input_type, typename B::T>);
    static_assert(std::is_same_v<input_type, bf16>);
    const uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::N,
            transpose::T,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    const uint64_t first_a = a_desc.chunk_descriptor(0);
    const uint64_t first_b = b_desc.chunk_descriptor(0);
    const uint32_t accumulate_value = accumulate ? 1u : 0u;
    asm volatile(
        "{\n\t"
        ".reg .pred accumulate_pred;\n\t"
        "setp.ne.u32 accumulate_pred, %4, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::f16 "
        "[%0], %1, %2, %3, accumulate_pred;\n\t"
        "}\n"
        :: "r"(d.addr),
           "l"(first_a),
           "l"(first_b),
           "r"(instruction),
           "r"(accumulate_value)
        : "memory"
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / 16; ++chunk) {
        ::kittens::detail::tcgen05::template st_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk),
            b_desc.chunk_descriptor(chunk),
            instruction
        );
    }
}

template <ducks::tt::all D, ducks::tt::all A,
          ducks::st_descriptor::input B>
__device__ __forceinline__ void
cta2_fused_dense_tmem_a_mm2_ab_no_fence_runtime_accumulate(
    D &d,
    const A &a,
    const B &b,
    bool accumulate
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::cols;
    static_assert(kK == B::rows && kK % 16 == 0);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    using input_type = typename A::T;
    using output_type = typename D::T;
    static_assert(std::is_same_v<input_type, typename B::T>);
    static_assert(std::is_same_v<input_type, bf16>);
    const uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::N,
            transpose::T,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    const uint32_t first_a = a.template chunk_addr<transpose::N>(0);
    const uint64_t first_b = b_desc.chunk_descriptor(0);
    const uint32_t accumulate_value = accumulate ? 1u : 0u;
    asm volatile(
        "{\n\t"
        ".reg .pred accumulate_pred;\n\t"
        "setp.ne.u32 accumulate_pred, %4, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::f16 "
        "[%0], [%1], %2, %3, accumulate_pred;\n\t"
        "}\n"
        :: "r"(d.addr),
           "r"(first_a),
           "l"(first_b),
           "r"(instruction),
           "r"(accumulate_value)
        : "memory"
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / 16; ++chunk) {
        ::kittens::detail::tcgen05::template tt_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a.template chunk_addr<transpose::N>(chunk),
            b_desc.chunk_descriptor(chunk),
            instruction
        );
    }
}

template <
    int Accumulate,
    ducks::tt::all D,
    ducks::tt::all A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_tmem_a_fp8_mm2_ab_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    // Dense E4M3 P x dO follows the forward FP8-PV route: four K32 raw
    // F8F6F4 issues replace eight BF16 K16 issues, with P already resident in
    // TMEM and the completed dO tile repacked in shared memory.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::cols;
    using input_type = fp8e4m3;
    using output_type = typename D::T;
    constexpr int kReductionDimension =
        ::kittens::reduction_dimension<input_type>;
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(std::is_same_v<typename A::T, input_type>);
    static_assert(std::is_same_v<typename B::T, input_type>);
    static_assert(kK == B::rows && kK % kReductionDimension == 0);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::N,
            transpose::T,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    ::kittens::detail::tcgen05::template tt_st<
        input_type,
        Accumulate,
        kCtaGroup
    >(
        d.addr,
        a.template chunk_addr<transpose::N>(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / kReductionDimension; ++chunk) {
        // TK's generic MN-major descriptor advances one 16-row tile per
        // chunk.  Dense FP8 MMA consumes K32, so advance two such tiles;
        // otherwise adjacent commands overlap sixteen dO rows and never
        // reach the final forty-eight rows of the reduction operand.
        ::kittens::detail::tcgen05::template tt_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a.template chunk_addr<transpose::N>(chunk),
            b_desc.chunk_descriptor(2 * chunk),
            instruction
        );
    }
}

template <
    int Accumulate,
    ducks::tt::all D,
    ducks::tt::all SA,
    ducks::tt::all SB,
    ducks::st::all BFP4
>
__device__ __forceinline__ void
cta2_fused_dense_tmem_a_mixed_fp8_mxfp4_mm2_ab_no_fence(
    D &d,
    const cta2_fused_dense_p_fp8_tt &a_fp8,
    const cta2_fused_dense_do_fp8_head_tile &b_fp8,
    const cta2_fused_dense_p_mxfp4_tt &a_fp4_tail,
    const BFP4 &b_fp4,
    const SA &a_scale,
    const SB &b_scale
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = cta2_fused_dense_p_fp8_tt::rows * kCtaGroup;
    constexpr int kN = cta2_fused_dense_do_fp8_head_tile::cols *
        kCtaGroup;
    using output_type = typename D::T;
    using fp8_type = fp8e4m3;
    using fp4_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(std::is_same_v<typename SA::T, scale_type>);
    static_assert(std::is_same_v<typename SB::T, scale_type>);
    static_assert(kM == 256 && kN == 128);

    constexpr uint32_t fp8_instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            fp8_type,
            kM,
            kN,
            transpose::N,
            transpose::T,
            false
        >();
    constexpr uint32_t fp4_instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            fp4_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >();
    ::kittens::st_descriptor<
        cta2_fused_dense_do_fp8_head_tile,
        transpose::T
    > b_fp8_desc(b_fp8);
    ::kittens::detail::tcgen05::template tt_st<
        fp8_type,
        Accumulate,
        kCtaGroup
    >(
        d.addr,
        a_fp8.template chunk_addr<transpose::N>(0),
        b_fp8_desc.chunk_descriptor(0),
        fp8_instruction
    );
    ::kittens::detail::tcgen05::template tt_st<
        fp8_type,
        1,
        kCtaGroup
    >(
        d.addr,
        a_fp8.template chunk_addr<transpose::N>(1),
        b_fp8_desc.chunk_descriptor(2),
        fp8_instruction
    );
#if TK_FA4_BWD_MIXED_DV_ISSUE_MXFP4_TAIL
    if constexpr (
        std::is_same_v<
            std::remove_cv_t<BFP4>,
            cta2_fused_dense_do_dp_mixed_fp4_tile
        >
    ) {
        // Offset the descriptor base to byte 96 of every legal 128-byte
        // row.  MN-major interprets the query-major padding as KxN, which is
        // the transpose-equivalent of the old feature-major NxK tail.
        const auto *base = reinterpret_cast<const unsigned char *>(&b_fp4);
        const auto &padded_tail = *reinterpret_cast<const BFP4 *>(
            base + 96
        );
        ::kittens::st_descriptor<BFP4, transpose::T> b_fp4_desc(
            padded_tail
        );
        asm volatile(
            "{.reg .pred p;\n\t"
            "setp.ne.b32 p, 1, 0;\n\t"
            "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
            "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
            :: "r"(d.addr),
               "r"(a_fp4_tail.addr),
               "l"(b_fp4_desc.chunk_descriptor(0)),
               "r"(fp4_instruction2),
               "r"(a_scale.addr),
               "r"(b_scale.addr)
            : "memory"
        );
    } else {
        static_assert(
            std::is_same_v<
                std::remove_cv_t<BFP4>,
                cta2_fused_dense_do_mxfp4_tile
            >
        );
        ::kittens::st_descriptor<BFP4, 0> b_fp4_desc(b_fp4);
        asm volatile(
            "{.reg .pred p;\n\t"
            "setp.ne.b32 p, 1, 0;\n\t"
            "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
            "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
            :: "r"(d.addr),
               "r"(a_fp4_tail.addr),
               "l"(b_fp4_desc.chunk_descriptor(1)),
               "r"(fp4_instruction2),
               "r"(a_scale.addr),
               "r"(b_scale.addr)
            : "memory"
        );
    }
#endif
}

template <
    ducks::tt::all D,
    ducks::tt::all A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_tmem_a_mxfp4_mm2_ab_no_fence(
    D &d,
    const A &a,
    const B &b,
    const cta2_fused_dense_score_scale_fp4_tt &unit_scale,
    bool accumulate
) {
    using input_type = fp4e2m1_2;
    using scale_type = fp8e4m3;
    using output_type = typename D::T;
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    static_assert(std::is_same_v<typename A::T, fp4e2m1_2>);
    static_assert(std::is_same_v<typename B::T, fp4e2m1_2>);
    static_assert(A::rows == 128 && A::cols == 64);
    static_assert(B::rows == 64 && B::cols == 64);
    static_assert(kM == 256 && kN == 128);

    constexpr uint32_t kInstruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >();
    constexpr uint32_t kInstruction1 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >();
    ::kittens::st_descriptor<B, 0> b_desc(b);
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.ne.b32 p, %6, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::4X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d.addr),
           "r"(a.addr),
           "l"(b_desc.chunk_descriptor(0)),
           "r"(kInstruction0),
           "r"(unit_scale.addr),
           "r"(unit_scale.addr),
           "r"(static_cast<int>(accumulate))
        : "memory"
    );
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.ne.b32 p, 1, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::4X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d.addr),
           "r"(a.addr + 8),
           "l"(b_desc.chunk_descriptor(1)),
           "r"(kInstruction1),
           "r"(unit_scale.addr),
           "r"(unit_scale.addr)
        : "memory"
    );
}

template <
    int Accumulate,
    ducks::tt::all D,
    ducks::tt::all A,
    ducks::st_descriptor::input B,
    ducks::tt::all SA,
    ducks::tt::all SB
>
__device__ __forceinline__ void
cta2_fused_dense_tmem_a_mxfp4_scaled_mm2_ab_no_fence(
    D &d,
    const A &a,
    const B &b,
    const SA &a_scale,
    const SB &b_scale
) {
    // Keep the dynamically quantized P operand in TMEM, as the retained FP8
    // path does, while dO remains descriptor-backed in shared memory.  Each
    // K64 issue consumes two K32 E8M0 blocks via SFIDs 0 and 2.
    using input_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    using output_type = typename D::T;
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(std::is_same_v<typename A::T, input_type>);
    static_assert(std::is_same_v<typename B::T, input_type>);
    static_assert(std::is_same_v<typename SA::T, scale_type>);
    static_assert(std::is_same_v<typename SB::T, scale_type>);
    static_assert(A::rows == 128 && A::cols == 64);
    static_assert(B::rows == 64 && B::cols == 64);
    static_assert(kM == 256 && kN == 128);

    constexpr uint32_t kInstruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >();
    constexpr uint32_t kInstruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >();
    ::kittens::st_descriptor<B, 0> b_desc(b);
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.eq.u32 p, 1, %6;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d.addr),
           "r"(a.addr),
           "l"(b_desc.chunk_descriptor(0)),
           "r"(kInstruction0),
           "r"(a_scale.addr),
           "r"(b_scale.addr),
           "n"(Accumulate)
        : "memory"
    );
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.ne.b32 p, 1, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d.addr),
           "r"(a.addr + 8),
           "l"(b_desc.chunk_descriptor(1)),
           "r"(kInstruction2),
           "r"(a_scale.addr),
           "r"(b_scale.addr)
        : "memory"
    );
}

template <ducks::tt::all D, ducks::st_descriptor::input A,
          ducks::st_descriptor::input B>
__device__ __forceinline__ void cta2_fused_dense_mm2_atb_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::cols * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::rows;
    using input_type = typename A::T;
    using output_type = typename D::T;
    constexpr int kReductionDimension =
        ::kittens::reduction_dimension<input_type>;
    constexpr int kDescriptorChunkScale = kReductionDimension / 16;
    static_assert(
        kReductionDimension % 16 == 0 && kDescriptorChunkScale >= 1
    );
    static_assert(
        kK == B::rows && kK % kReductionDimension == 0
    );
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);
    static_assert(std::is_same_v<input_type, typename B::T>);
    const uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::T,
            transpose::T,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::T
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<input_type, 0, kCtaGroup>(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (
        int chunk = 1;
        chunk < kK / kReductionDimension;
        ++chunk
    ) {
        ::kittens::detail::tcgen05::template st_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk * kDescriptorChunkScale),
            b_desc.chunk_descriptor(chunk * kDescriptorChunkScale),
            instruction
        );
    }
}

template <
    int Accumulate = 0,
    bool IssueAllChunks = true,
    int LogicalN = 0,
    int BRowOffset = 0,
    int MaxChunks = 0,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B,
    ducks::tt::all SA,
    ducks::tt::all SB
>
__device__ __forceinline__ void
cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
    D &d,
    const A &a,
    const B &b,
    const SA &a_scale,
    const SB &b_scale
) {
    // Packed E2M1 plus unit E4M3 block scales selects NVFP4 K64.  D=192 is
    // therefore three issues rather than the six issues required by raw
    // F8F6F4's aligned-E2M1 K32 layout.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = LogicalN == 0
        ? B::rows * kCtaGroup
        : LogicalN;
    constexpr int kK = A::cols * 2;
    constexpr int kAvailableChunks = kK / 64;
    constexpr int kIssueChunks = MaxChunks == 0
        ? kAvailableChunks
        : MaxChunks;
    using input_type = fp4e2m1_2;
    using scale_type = fp8e4m3;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, input_type>);
    static_assert(std::is_same_v<typename B::T, input_type>);
    static_assert(std::is_same_v<typename SA::T, scale_type>);
    static_assert(std::is_same_v<typename SB::T, scale_type>);
    static_assert(kK == B::cols * 2 && kK % 64 == 0);
    static_assert(kIssueChunks >= 1 && kIssueChunks <= kAvailableChunks);
    static_assert(
        kM == D::rows * kCtaGroup && kN == D::cols &&
        BRowOffset >= 0 &&
        BRowOffset + kN / kCtaGroup <= B::rows
    );

    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);
    if constexpr (BRowOffset != 0) {
        // Select an N fragment without narrowing the descriptor type: K-major
        // chunk stepping must retain the parent tile's physical row count.
        b_desc.base_desc += ::kittens::detail::matrix_descriptor_encode(
            BRowOffset * B::swizzle_bytes
        );
    }

    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        Accumulate,
        kCtaGroup,
        16
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        a_scale.addr,
        b_scale.addr,
        instruction
    );
    if constexpr (IssueAllChunks) {
        #pragma unroll
        for (int chunk = 1; chunk < kIssueChunks; ++chunk) {
            ::kittens::detail::tcgen05::template st_st<
                input_type,
                scale_type,
                1,
                kCtaGroup,
                16
            >(
                d.addr,
                a_desc.chunk_descriptor(chunk),
                b_desc.chunk_descriptor(chunk),
                a_scale.addr,
                b_scale.addr,
                instruction
            );
        }
    }
}

template <
    int Accumulate = 0,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B,
    ducks::tt::all SA,
    ducks::tt::all SB
>
__device__ __forceinline__ void
cta2_fused_dense_mxfp4_scaled_mm2_abt_no_fence(
    D &d,
    const A &a,
    const B &b,
    const SA &a_scale,
    const SB &b_scale
) {
    // Match the forward MXFP4 K128 path exactly: each K64 instruction sees
    // two K32 E8M0 blocks, selected by scale-factor IDs 0 and 2.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    constexpr int kK = A::cols * 2;
    using input_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, input_type>);
    static_assert(std::is_same_v<typename B::T, input_type>);
    static_assert(std::is_same_v<typename SA::T, scale_type>);
    static_assert(std::is_same_v<typename SB::T, scale_type>);
    static_assert(kK == 128 && kK == B::cols * 2);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t instruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >();
    constexpr uint32_t instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        Accumulate,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        a_scale.addr,
        b_scale.addr,
        instruction0
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(1),
        b_desc.chunk_descriptor(1),
        a_scale.addr,
        b_scale.addr,
        instruction2
    );
}

template <int Accumulate, int M, int N>
__device__ __forceinline__ void
cta2_fused_dense_mxfp4_scaled_k128_desc_no_fence(
    uint32_t d_addr,
    uint64_t a_desc0,
    uint64_t a_desc1,
    uint64_t b_desc0,
    uint64_t b_desc1,
    uint32_t a_scale_addr,
    uint32_t b_scale_addr
) {
    // N192 scale-factor B is padded as two independent N128 atoms.  Issue
    // instruction-sized N128/N64 slices so every call consumes one aligned
    // 512-byte A page and one aligned 512-byte B page.  This also lets dQ
    // reduce K256 as two K128 calls without placing a UTCCP destination at
    // an illegal in-page offset.
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(M == 128 || M == 256);
    static_assert(N == 64 || N == 128 || N == 192 || N == 256);
    using input_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    constexpr int kCtaGroup = 2;
    constexpr uint32_t instruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            0
        >();
    constexpr uint32_t instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            2
        >();
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        Accumulate,
        kCtaGroup,
        32
    >(
        d_addr,
        a_desc0,
        b_desc0,
        a_scale_addr,
        b_scale_addr,
        instruction0
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        32
    >(
        d_addr,
        a_desc1,
        b_desc1,
        a_scale_addr,
        b_scale_addr,
        instruction2
    );
}

template <
    int Accumulate,
    int M,
    int N,
    bool ReuseAScalePage = false,
    bool ReuseBScalePage = false
>
__device__ __forceinline__ void
cta2_fused_dense_nvfp4_scaled_k128_desc_no_fence(
    uint32_t d_addr,
    uint64_t a_desc0,
    uint64_t a_desc1,
    uint64_t b_desc0,
    uint64_t b_desc1,
    uint32_t a_scale_addr,
    uint32_t b_scale_addr
) {
    // Both issues use SFID 0.  Every rank-local scale page reserves four
    // columns per K64, including the padded N96 half of a group-2 N192 B
    // operand.
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(M == 128 || M == 256);
    static_assert(N == 64 || N == 128 || N == 192 || N == 256);
    using input_type = fp4e2m1_2;
    using scale_type = fp8e4m3;
    constexpr int kCtaGroup = 2;
    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            0
        >();
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        Accumulate,
        kCtaGroup,
        16
    >(
        d_addr,
        a_desc0,
        b_desc0,
        a_scale_addr,
        b_scale_addr,
        instruction
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        16
    >(
        d_addr,
        a_desc1,
        b_desc1,
        a_scale_addr + (ReuseAScalePage ? 0 : 4),
        b_scale_addr + (ReuseBScalePage ? 0 : 4),
        instruction
    );
}

template <
    int Accumulate = 0,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_mxf8f6f4_e2m1_scaled_k256_atb_no_fence(
    D &d,
    const A &a,
    const B &b,
    uint32_t a_scale0_addr,
    uint32_t a_scale1_addr,
    uint32_t b_scale_addr
) {
    // Both operands use the F8F6F4 aligned E2M1 byte-container layout.  The
    // native dS payload is physically [K256, M64] in each CTA and K is
    // [K256, N96], so MN-major descriptors produce dS^T K directly.  Four
    // K32 issues consume each exact dS scale page; SFIDs 0..3 select the four
    // K32 scale records within that page.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::cols * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::rows;
    using opcode_input_type = fp8e4m3;
    using scale_type = fp8e8m0;
    using output_type = typename D::T;
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(std::is_same_v<typename A::T, fp8e4m3>);
    static_assert(std::is_same_v<typename B::T, fp8e4m3>);
    static_assert(kM == 128 && kN == 192 && kK == 256);
    static_assert(kK == B::rows);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t kE2m1Format = 0b101u;
    constexpr uint32_t kAlignedE2m1Transpose =
        (kE2m1Format << 7) |
        (kE2m1Format << 10) |
        (1u << 15) |
        (1u << 16);
    constexpr uint32_t instruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            opcode_input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >() | kAlignedE2m1Transpose;
    constexpr uint32_t instruction1 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            opcode_input_type,
            scale_type,
            kM,
            kN,
            false,
            1
        >() | kAlignedE2m1Transpose;
    constexpr uint32_t instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            opcode_input_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >() | kAlignedE2m1Transpose;
    constexpr uint32_t instruction3 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            opcode_input_type,
            scale_type,
            kM,
            kN,
            false,
            3
        >() | kAlignedE2m1Transpose;
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::T
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

#define TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(CHUNK, ACC, SCALE, INSTRUCTION) \
    ::kittens::detail::tcgen05::template st_st<                    \
        opcode_input_type,                                         \
        scale_type,                                                \
        ACC,                                                       \
        kCtaGroup,                                                 \
        32                                                         \
    >(                                                             \
        d.addr,                                                    \
        a_desc.chunk_descriptor(CHUNK),                           \
        b_desc.chunk_descriptor(CHUNK),                           \
        (SCALE) | ((static_cast<uint32_t>(CHUNK) & 3u) << 30),    \
        b_scale_addr |                                             \
            ((static_cast<uint32_t>(CHUNK) & 3u) << 30),          \
        INSTRUCTION                                                \
    )
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(0, Accumulate, a_scale0_addr, instruction0);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(1, 1, a_scale0_addr, instruction1);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(2, 1, a_scale0_addr, instruction2);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(3, 1, a_scale0_addr, instruction3);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(4, 1, a_scale1_addr, instruction0);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(5, 1, a_scale1_addr, instruction1);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(6, 1, a_scale1_addr, instruction2);
    TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ(7, 1, a_scale1_addr, instruction3);
#undef TK_FA4_BWD_ISSUE_ALIGNED_MX_DQ
}

template <int Accumulate, int M, int N>
__device__ __forceinline__ void
cta2_fused_dense_mxfp4_scaled_k128_tmem_a_desc_no_fence(
    uint32_t d_addr,
    uint32_t a_tmem_addr,
    uint64_t b_desc0,
    uint64_t b_desc1,
    uint32_t a_scale_addr,
    uint32_t b_scale_addr
) {
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(M == 256);
    static_assert(N == 64 || N == 128 || N == 192);
    using input_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    constexpr uint32_t instruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            0
        >();
    constexpr uint32_t instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            2
        >();
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.eq.u32 p, 1, %6;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d_addr),
           "r"(a_tmem_addr),
           "l"(b_desc0),
           "r"(instruction0),
           "r"(a_scale_addr),
           "r"(b_scale_addr),
           "n"(Accumulate)
        : "memory"
    );
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.ne.b32 p, 1, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::2X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d_addr),
           "r"(a_tmem_addr + 8),
           "l"(b_desc1),
           "r"(instruction2),
           "r"(a_scale_addr),
           "r"(b_scale_addr)
        : "memory"
    );
}

template <
    int Accumulate,
    int M,
    int N,
    bool ReuseAScalePage = false,
    bool ReuseBScalePage = false
>
__device__ __forceinline__ void
cta2_fused_dense_nvfp4_scaled_k128_tmem_a_desc_no_fence(
    uint32_t d_addr,
    uint32_t a_tmem_addr,
    uint64_t b_desc0,
    uint64_t b_desc1,
    uint32_t a_scale_addr,
    uint32_t b_scale_addr
) {
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(M == 256);
    static_assert(N == 64 || N == 128 || N == 192);
    using input_type = fp4e2m1_2;
    using scale_type = fp8e4m3;
    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            float,
            input_type,
            scale_type,
            M,
            N,
            false,
            0
        >();
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.eq.u32 p, 1, %6;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::4X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d_addr),
           "r"(a_tmem_addr),
           "l"(b_desc0),
           "r"(instruction),
           "r"(a_scale_addr),
           "r"(b_scale_addr),
           "n"(Accumulate)
        : "memory"
    );
    asm volatile(
        "{.reg .pred p;\n\t"
        "setp.ne.b32 p, 1, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::mxf4nvf4.block_scale."
        "scale_vec::4X [%0], [%1], %2, %3, [%4], [%5], p;}\n"
        :: "r"(d_addr),
           "r"(a_tmem_addr + 8),
           "l"(b_desc1),
           "r"(instruction),
           "r"(a_scale_addr + (ReuseAScalePage ? 0 : 4)),
           "r"(b_scale_addr + (ReuseBScalePage ? 0 : 4))
        : "memory"
    );
}

template <
    int Accumulate = 0,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B,
    ducks::tt::all SA,
    ducks::tt::all SB
>
__device__ __forceinline__ void
cta2_fused_dense_mxfp4_scaled_k256_mm2_abt_no_fence(
    D &d,
    const A &a,
    const B &b,
    const SA &a_scale,
    const SB &b_scale
) {
    // Match TK's generic MXFP4 K256 coordinate mapping.  SFIDs 0/2 select
    // the two K32 blocks inside each K64 issue pair.  Chunks 2/3 then advance
    // the logical scale coordinates by M/32/CTA and N/32 rather than treating
    // the second A page as a new instruction base.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    constexpr int kK = A::cols * 2;
    using input_type = fp4e2m1_2;
    using scale_type = fp8e8m0;
    using output_type = typename D::T;
    static_assert(Accumulate == 0 || Accumulate == 1);
    static_assert(std::is_same_v<typename A::T, input_type>);
    static_assert(std::is_same_v<typename B::T, input_type>);
    static_assert(std::is_same_v<typename SA::T, scale_type>);
    static_assert(std::is_same_v<typename SB::T, scale_type>);
    static_assert(kK == 256 && kK == B::cols * 2);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);
    constexpr int kAScaleK128Offset = kM / 32 / kCtaGroup;
    constexpr int kBScaleK128Offset = kN / 32;

    constexpr uint32_t instruction0 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            0
        >();
    constexpr uint32_t instruction2 =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            scale_type,
            kM,
            kN,
            false,
            2
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        Accumulate,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        a_scale.addr,
        b_scale.addr,
        instruction0
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(1),
        b_desc.chunk_descriptor(1),
        a_scale.addr,
        b_scale.addr,
        instruction2
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(2),
        b_desc.chunk_descriptor(2),
        a_scale.addr + kAScaleK128Offset,
        b_scale.addr + kBScaleK128Offset,
        instruction0
    );
    ::kittens::detail::tcgen05::template st_st<
        input_type,
        scale_type,
        1,
        kCtaGroup,
        32
    >(
        d.addr,
        a_desc.chunk_descriptor(3),
        b_desc.chunk_descriptor(3),
        a_scale.addr + kAScaleK128Offset,
        b_scale.addr + kBScaleK128Offset,
        instruction2
    );
}

template <
    int LogicalN = 0,
    int BColumnOffset = 0,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_fp4_score_mm2_ab_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    // Raw F8F6F4 consumes CUDA's aligned E2M1 byte-container layout.  Keep
    // the physical shared types byte-sized while selecting E2M1 for both
    // operands in the instruction descriptor.  D=192 lowers to six K32
    // issues without any scale movement.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = LogicalN == 0
        ? B::cols * kCtaGroup
        : LogicalN;
    constexpr int kK = A::cols;
    constexpr int kReductionDimension = 32;
    constexpr int kDescriptorChunkScale = kReductionDimension / 16;
    using input_type = fp4e2m1_2;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, fp8e4m3>);
    static_assert(std::is_same_v<typename B::T, fp8e4m3>);
    static_assert(kK == B::rows && kK % kReductionDimension == 0);
    static_assert(
        kM == D::rows * kCtaGroup && kN == D::cols &&
        BColumnOffset >= 0 &&
        BColumnOffset + kN / kCtaGroup <= B::cols &&
        (BColumnOffset * static_cast<int>(sizeof(typename B::T))) % 16 == 0
    );

    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            input_type,
            kM,
            kN,
            transpose::N,
            transpose::N,
            false
        >();
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);
    if constexpr (BColumnOffset != 0) {
        // Preserve the parent tile's K stride while selecting a later N
        // fragment.  st_subtile descriptors derive their stride from the
        // narrowed type, which is not the physical 192-row score-Q layout.
        b_desc.base_desc += ::kittens::detail::matrix_descriptor_encode(
            BColumnOffset * sizeof(typename B::T)
        );
    }

    ::kittens::detail::tcgen05::template st_st<
        input_type,
        0,
        kCtaGroup
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / kReductionDimension; ++chunk) {
        ::kittens::detail::tcgen05::template st_st<
            input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk * kDescriptorChunkScale),
            b_desc.chunk_descriptor(chunk * kDescriptorChunkScale),
            instruction
        );
    }
}

template <
    bool Accumulate,
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_mixed_fp8_fp4_mm2_abt_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    // A is dense E4M3 dS.  B is E2M1 Q/K stored in CUDA's aligned-U4
    // byte-container layout.  F8F6F4 permits independent input formats, but
    // TK's generic wrapper currently requires A and B to share a C++ type, so
    // form the independent B-format field here.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    constexpr int kK = A::cols;
    using a_input_type = fp8e4m3;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, fp8e4m3>);
    static_assert(std::is_same_v<typename B::T, fp8e4m3>);
    static_assert(kK == B::cols && kK % 32 == 0);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t kE2m1Format = 0b101u;
    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            a_input_type,
            kM,
            kN,
            transpose::N,
            transpose::N,
            false
        >() |
        (kE2m1Format << 10);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<
        a_input_type,
        Accumulate ? 1 : 0,
        kCtaGroup
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / 32; ++chunk) {
        ::kittens::detail::tcgen05::template st_st<
            a_input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk),
            b_desc.chunk_descriptor(chunk),
            instruction
        );
    }
}

template <
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_mixed_fp8_fp4_mm2_abt_split_no_fence(
    D &d,
    const A &a0,
    const A &a1,
    const B &b,
    bool accumulate
) {
    // The two dS halves share one logical K=128 reduction.  Build the Q
    // descriptor once and use a runtime predicate only on the first MMA;
    // issuing three generic helpers would rebuild descriptors and transfer
    // them to uniform registers for every half.
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::rows * kCtaGroup;
    constexpr int kN = B::rows * kCtaGroup;
    using a_input_type = fp8e4m3;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, fp8e4m3>);
    static_assert(std::is_same_v<typename B::T, fp8e4m3>);
    static_assert(2 * A::cols == B::cols && A::cols == 64);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t kE2m1Format = 0b101u;
    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            a_input_type,
            kM,
            kN,
            transpose::N,
            transpose::N,
            false
        >() |
        (kE2m1Format << 10);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a0_desc(a0);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::N
    > a1_desc(a1);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::N
    > b_desc(b);
    const uint32_t accumulate_value = accumulate ? 1u : 0u;
    asm volatile(
        "{\n\t"
        ".reg .pred accumulate_pred;\n\t"
        "setp.ne.u32 accumulate_pred, %4, 0;\n\t"
        "tcgen05.mma.cta_group::2.kind::f8f6f4 "
        "[%0], %1, %2, %3, accumulate_pred;\n\t"
        "}\n"
        :: "r"(d.addr),
           "l"(a0_desc.chunk_descriptor(0)),
           "l"(b_desc.chunk_descriptor(0)),
           "r"(instruction),
           "r"(accumulate_value)
        : "memory"
    );
    ::kittens::detail::tcgen05::template st_st<
        a_input_type,
        1,
        kCtaGroup
    >(
        d.addr,
        a0_desc.chunk_descriptor(1),
        b_desc.chunk_descriptor(1),
        instruction
    );
    ::kittens::detail::tcgen05::template st_st<
        a_input_type,
        1,
        kCtaGroup
    >(
        d.addr,
        a1_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(2),
        instruction
    );
    ::kittens::detail::tcgen05::template st_st<
        a_input_type,
        1,
        kCtaGroup
    >(
        d.addr,
        a1_desc.chunk_descriptor(1),
        b_desc.chunk_descriptor(3),
        instruction
    );
}

template <
    ducks::tt::all D,
    ducks::st_descriptor::input A,
    ducks::st_descriptor::input B
>
__device__ __forceinline__ void
cta2_fused_dense_mixed_fp8_fp4_mm2_atb_no_fence(
    D &d,
    const A &a,
    const B &b
) {
    constexpr int kCtaGroup = 2;
    constexpr int kM = A::cols * kCtaGroup;
    constexpr int kN = B::cols * kCtaGroup;
    constexpr int kK = A::rows;
    using a_input_type = fp8e4m3;
    using output_type = typename D::T;
    static_assert(std::is_same_v<typename A::T, fp8e4m3>);
    static_assert(std::is_same_v<typename B::T, fp8e4m3>);
    static_assert(kK == B::rows && kK % 32 == 0);
    static_assert(kM == D::rows * kCtaGroup && kN == D::cols);

    constexpr uint32_t kE2m1Format = 0b101u;
    constexpr uint32_t instruction =
        ::kittens::detail::tcgen05::instruction_descriptor<
            output_type,
            a_input_type,
            kM,
            kN,
            transpose::T,
            transpose::T,
            false
        >() |
        (kE2m1Format << 10);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<A>,
        transpose::T
    > a_desc(a);
    ::kittens::st_descriptor<
        ducks::st_descriptor::detail::get_st<B>,
        transpose::T
    > b_desc(b);

    ::kittens::detail::tcgen05::template st_st<
        a_input_type,
        0,
        kCtaGroup
    >(
        d.addr,
        a_desc.chunk_descriptor(0),
        b_desc.chunk_descriptor(0),
        instruction
    );
    #pragma unroll
    for (int chunk = 1; chunk < kK / 32; ++chunk) {
        ::kittens::detail::tcgen05::template st_st<
            a_input_type,
            1,
            kCtaGroup
        >(
            d.addr,
            a_desc.chunk_descriptor(chunk * 2),
            b_desc.chunk_descriptor(chunk * 2),
            instruction
        );
    }
}

__device__ __forceinline__ void cta2_role_split_load_q_transposed(
    cta2_fused_dense_main_phase_storage &main,
    cta2_fused_dense_qdo_exchange_storage &exchange,
    int logical_warp,
    int cta_rank,
    rt_bf<64, 16> &q0_transposed,
    rt_bf<32, 16> &q1_transposed
) {
    rt_bf<16, 64> q0;
    rt_bf<16, 32> q1;
    const int source_row = logical_warp & 3;
    if ((logical_warp >> 2) == cta_rank) {
        auto q0_source = main.q.q.template subtile<16, 64>(
            {source_row, cta_rank}
        );
        auto q1_source = main.q.q.template subtile<16, 32>(
            {source_row, 4 + cta_rank}
        );
        warp::load(q0, q0_source);
        warp::load(q1, q1_source);
    } else {
        auto q0_source = exchange.q0.template subtile<16, 64>(
            {source_row, 0}
        );
        auto q1_source = exchange.q1.template subtile<16, 32>(
            {source_row, cta_rank}
        );
        warp::load(q0, q0_source);
        warp::load(q1, q1_source);
    }
    warp::transpose_sep(q0_transposed, q0);
    warp::transpose_sep(q1_transposed, q1);
}

template <int Rows>
__device__ __forceinline__ void cta2_role_split_store_q_transposed_wide(
    cta2_fused_dense_q_t_wide_tile &dst,
    const rt_bf<Rows, 16> &src,
    int row_tile_offset,
    int col_tile
) {
    static_assert(Rows % 16 == 0);
    #pragma unroll
    for (int row_tile = 0; row_tile < Rows / 16; ++row_tile) {
        rt_bf<16, 16> fragment;
        fragment.tiles[0][0] = src.tiles[row_tile][0];
        auto dst_fragment = dst.template subtile<16, 16>({
            row_tile_offset + row_tile,
            col_tile
        });
        warp::store(dst_fragment, fragment);
    }
}

__device__ __forceinline__ void cta2_role_split_load_q_transposed_wide(
    cta2_fused_dense_main_phase_storage &main,
    cta2_fused_dense_qdo_exchange_storage &exchange,
    int logical_warp,
    int cta_rank,
    rt_bf<32, 16> &q0_transposed,
    rt_bf<32, 16> &q1_transposed,
    rt_bf<32, 16> &q2_transposed
) {
    rt_bf<16, 32> q0;
    rt_bf<16, 32> q1;
    rt_bf<16, 32> q2;
    const int source_row = logical_warp & 3;
    if ((logical_warp >> 2) == cta_rank) {
        auto q0_source = main.q.q.template subtile<16, 32>({
            source_row,
            cta_rank * 3
        });
        auto q1_source = main.q.q.template subtile<16, 32>({
            source_row,
            cta_rank * 3 + 1
        });
        auto q2_source = main.q.q.template subtile<16, 32>({
            source_row,
            cta_rank * 3 + 2
        });
        warp::load(q0, q0_source);
        warp::load(q1, q1_source);
        warp::load(q2, q2_source);
    } else if (cta_rank == 0) {
        auto q0_source = exchange.q0.template subtile<16, 32>({
            source_row,
            0
        });
        auto q1_source = exchange.q0.template subtile<16, 32>({
            source_row,
            1
        });
        auto q2_source = exchange.q1.template subtile<16, 32>({
            source_row,
            0
        });
        warp::load(q0, q0_source);
        warp::load(q1, q1_source);
        warp::load(q2, q2_source);
    } else {
        auto q0_source = exchange.q0.template subtile<16, 32>({
            source_row,
            1
        });
        auto q1_source = exchange.q1.template subtile<16, 32>({
            source_row,
            0
        });
        auto q2_source = exchange.q1.template subtile<16, 32>({
            source_row,
            1
        });
        warp::load(q0, q0_source);
        warp::load(q1, q1_source);
        warp::load(q2, q2_source);
    }
    warp::transpose_sep(q0_transposed, q0);
    warp::transpose_sep(q1_transposed, q1);
    warp::transpose_sep(q2_transposed, q2);
}

template <
    bool CacheLse,
    bool UseTmemDs,
    bool OverlapDsExchange,
    bool OverlapQWithDp,
    bool UseTmemP = false,
    bool OverlapDoWithDp = false,
    bool UseDpOperandReadyMbar = false,
    bool UseDqOperandReadyMbar = false,
    bool OverlapDvWithDs = false,
    bool PipelineNextScore = false,
    bool PreloadDqA = false,
    bool UseScoreOperandReadyMbar = false,
    bool UseDsWarpMulticastMbar = false
>
__global__ __launch_bounds__(256, 1)
void main_kernel_causal_cta2_fused_dense(
    const __grid_constant__ cta2_fused_dense_globals g
) {
    static_assert(
        !OverlapDvWithDs || (UseTmemP && OverlapDoWithDp),
        "early dV issue requires TMEM P and the normalized dO operand"
    );
    static_assert(
        !PipelineNextScore || UseDqOperandReadyMbar,
        "score lookahead requires the validated dQ-ready route"
    );
    static_assert(
        !PreloadDqA || OverlapDsExchange,
        "dQ-A preload requires the peer dS exchange"
    );
    static_assert(
        !UseDsWarpMulticastMbar || (UseTmemDs && OverlapDsExchange),
        "multicast dS readiness requires TMEM dS and the peer exchange"
    );
    __shared__ alignas(1024) cta2_fused_dense_shared_storage<CacheLse> storage;
    __shared__ alignas(16) semaphore score_done;
    __shared__ alignas(16) semaphore dp_done;
    __shared__ alignas(16) semaphore dkdv_done;
    __shared__ alignas(16) semaphore kv_load_done;
    __shared__ alignas(16) semaphore qdo_load_done;
    __shared__ alignas(16) semaphore qdo_prefetch_done;
    __shared__ alignas(16) semaphore qdo_exchange_done;
    __shared__ alignas(16) semaphore dq_exchange_done;
    __shared__ alignas(16) semaphore k_exchange_done;
    __shared__ alignas(16) semaphore dq_done;
    __shared__ alignas(16) semaphore dp_operands_ready;
    __shared__ alignas(16) semaphore dq_operands_ready;
    __shared__ alignas(16) semaphore score_lookahead_ready;
    __shared__ alignas(16) semaphore score_operands_ready;
    __shared__ alignas(16) semaphore ds_warp_multicast_ready;

    const int warp = warpid();
    const int cta_rank = cluster_ctarank();
    const int batch_idx = static_cast<int>(blockIdx.z);
    const int head_idx = static_cast<int>(blockIdx.y);
    const int owner_pair_idx = static_cast<int>(clusterIdx().x);
    const int q_tile_count = g.seq_len / 128;
    const int owner_count = q_tile_count / 2;
    const int output_subtile = 2 * (warp % 4) + warp / 4;

    if (threadIdx.x == 0) {
        g.k.template prefetch_tma<cta2_fused_dense_k_tile, dim::DEPTH>();
        g.q.template prefetch_tma<cta2_fused_dense_q_tile, dim::DEPTH>();
        g.q.template prefetch_tma<
            cta2_fused_dense_q0_exchange_tile,
            dim::DEPTH
        >();
        g.v.template prefetch_tma<cta2_fused_dense_v_tile, dim::DEPTH>();
        g.dout.template prefetch_tma<cta2_fused_dense_do_tile, dim::DEPTH>();
        g.dout.template prefetch_tma<
            cta2_fused_dense_do_exchange_tile,
            dim::DEPTH
        >();
        g.dq.template prefetch_tma<cta2_fused_dense_dq_stage, dim::DEPTH>();
        init_semaphore(score_done, 0, 1);
        init_semaphore(dp_done, 0, 1);
        init_semaphore(dkdv_done, 0, 1);
        init_semaphore(kv_load_done, 0, 1);
        init_semaphore(qdo_load_done, 0, 1);
        init_semaphore(qdo_prefetch_done, 0, 1);
        init_semaphore(qdo_exchange_done, 0, 1);
        init_semaphore(dq_exchange_done, 0, 1);
        init_semaphore(k_exchange_done, 0, 1);
        init_semaphore(dq_done, 0, 1);
        if constexpr (UseDpOperandReadyMbar) {
            init_semaphore(dp_operands_ready, 0, 2);
        }
        if constexpr (UseDqOperandReadyMbar) {
            init_semaphore(dq_operands_ready, 0, 2);
        }
        if constexpr (PipelineNextScore) {
            init_semaphore(score_lookahead_ready, 0, 10);
        }
        if constexpr (UseScoreOperandReadyMbar) {
            init_semaphore(score_operands_ready, 0, 2);
        }
        if constexpr (UseDsWarpMulticastMbar) {
            init_semaphore(ds_warp_multicast_ready, 0, 16);
        }
    }
    __syncthreads();
    everyone::tma::cluster::sync();

    tensor_allocator<1, 2> tm_alloc{};
    cta2_fused_dense_attn_tt dk_main_tmem =
        tm_alloc.template allocate<cta2_fused_dense_attn_tt>(0);
    cta2_fused_dense_dk_tail_tt dk_tail_tmem =
        tm_alloc.template allocate<cta2_fused_dense_dk_tail_tt>(128);
    cta2_fused_dense_attn_tt dv_tmem =
        tm_alloc.template allocate<cta2_fused_dense_attn_tt>(192);
    cta2_fused_dense_attn_tt score_dp_tmem =
        tm_alloc.template allocate<cta2_fused_dense_attn_tt>(320);
    cta2_fused_dense_ds_tt ds_tmem =
        tm_alloc.template allocate<cta2_fused_dense_ds_tt>(320);
    cta2_fused_dense_ds_tt p_tmem =
        tm_alloc.template allocate<cta2_fused_dense_ds_tt>(448);
    cta2_fused_dense_dq_tt dq_tmem =
        tm_alloc.template allocate<cta2_fused_dense_dq_tt>(0, 320);
    int score_lookahead_count = 0;

    #pragma unroll
    for (int owner_pass = 0; owner_pass < 2; ++owner_pass) {
    const int owner_idx = owner_pass == 0
        ? owner_pair_idx
        : owner_count - 1 - owner_pair_idx;
    const int owner_phase = owner_pass & 1;
    const int first_dense_q_tile = 2 * owner_idx + 1;
    rt_bf<16, kB300VDim> v_persistent;

    bool first_accumulation = true;
    int iteration = 0;
    if (threadIdx.x == 0) {
        tma::expect_bytes(
            kv_load_done,
            sizeof(storage.k) + sizeof(storage.ds)
        );
        coord<cta2_fused_dense_k_tile> k_tile_idx = {
            batch_idx,
            owner_idx * 2 + cta_rank,
            head_idx,
            0
        };
        coord<cta2_fused_dense_v_tile> v_tile_idx = {
            batch_idx,
            owner_idx * 2 + cta_rank,
            head_idx,
            0
        };
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            storage.k,
            g.k,
            k_tile_idx,
            kv_load_done
        );
        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
            storage.ds,
            g.v,
            v_tile_idx,
            kv_load_done
        );
    }
    wait(kv_load_done, owner_phase);
    __syncthreads();
    {
        auto v_source = storage.ds.template subtile<16, kB300VDim>(
            {warp, 0}
        );
        warp::load(v_persistent, v_source);
    }
    __syncthreads();
    everyone::tma::cluster::sync();

    {
        rt_bf<16, 96> k_local;
        rt_bf<16, 96> k_peer;
        auto k_local_smem =
            storage.k.template subtile<16, 96>({warp, cta_rank});
        auto k_peer_smem =
            storage.k.template subtile<16, 96>({warp, cta_rank ^ 1});
        warp::load(k_local, k_local_smem);
        warp::load(k_peer, k_peer_smem);
        auto b_local_smem =
            storage.dq_b.template subtile<16, 96>(
                {cta_rank * 8 + warp, 0}
            );
        auto k_exchange_smem =
            storage.phase.dq.operands.exchange.k.template subtile<16, 96>(
                {warp, 0}
            );
        warp::store(b_local_smem, k_local);
        warp::store(k_exchange_smem, k_peer);
    }
    __syncthreads();
    everyone::tma::cluster::sync();

    if (threadIdx.x == 0) {
        const int peer_rank = cta_rank ^ 1;
        constexpr int kChunkElements = 128 * 32;
        ::kittens::tma::cluster::expect_bytes(
            k_exchange_done,
            sizeof(storage.phase.dq.operands.exchange.k),
            peer_rank
        );
        #pragma unroll
        for (int chunk = 0; chunk < 3; ++chunk) {
            void *destination = reinterpret_cast<void *>(
                &storage.dq_b.data[
                    chunk * 2 * kChunkElements +
                    cta_rank * kChunkElements
                ]
            );
            void *source = reinterpret_cast<void *>(
                &storage.phase.dq.operands.exchange.k.data[
                    chunk * kChunkElements
                ]
            );
            ::kittens::tma::cluster::store_async(
                destination,
                source,
                kChunkElements * sizeof(bf16),
                peer_rank,
                k_exchange_done
            );
        }
    }
    ::kittens::tma::cluster::wait(k_exchange_done, owner_phase);
    __syncthreads();
    everyone::tma::cluster::sync();

    for (
        int q_tile_idx = first_dense_q_tile;
        q_tile_idx < q_tile_count;
        ++q_tile_idx, ++iteration
    ) {
        auto &main = storage.phase.main;
        auto &qdo_exchange = storage.qdo_phase.qdo;
        const int local_phase = iteration & 1;
        const int phase = (iteration + owner_phase) & 1;

        if (iteration == 0) {
            if (threadIdx.x == 0) {
                tma::expect_bytes(
                    qdo_load_done,
                    sizeof(main.q.q) + sizeof(main.dout) +
                        sizeof(storage.stats)
                );
                coord<cta2_fused_dense_q_tile> q_tile_coord = {
                    batch_idx,
                    q_tile_idx * 2 + cta_rank,
                    head_idx,
                    0
                };
                coord<cta2_fused_dense_do_tile> do_tile_coord = {
                    batch_idx,
                    q_tile_idx * 2 + cta_rank,
                    head_idx,
                    0
                };
                tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                    main.q.q,
                    g.q,
                    q_tile_coord,
                    qdo_load_done
                );
                tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                    main.dout,
                    g.dout,
                    do_tile_coord,
                    qdo_load_done
                );
                cta2_fused_dense_load_stats<CacheLse>(
                    g,
                    storage.stats,
                    qdo_load_done,
                    batch_idx,
                    q_tile_idx,
                    head_idx
                );
                cta2_fused_dense_load_peer_qdo(
                    g,
                    qdo_exchange,
                    qdo_exchange_done,
                    batch_idx,
                    q_tile_idx,
                    head_idx,
                    cta_rank
                );
            }
            wait(qdo_load_done, owner_phase);
        } else {
            wait(qdo_prefetch_done, local_phase ^ 1);
            if (warp < 4) {
                auto &next_q =
                    storage.phase.dq.operands.exchange.next_q;
                rt_bf<16, kB300QKDim> q_reg;
                auto q_source = next_q.template subtile<16, kB300QKDim>(
                    {warp, 0}
                );
                auto q_destination =
                    main.q.q.template subtile<16, kB300QKDim>({warp, 0});
                warp::load(q_reg, q_source);
                warp::store(q_destination, q_reg);

                rt_bf<16, kB300VDim> do_reg;
                auto &next_dout =
                    *reinterpret_cast<cta2_fused_dense_do_tile *>(
                        &storage.ds
                    );
                auto do_source =
                    next_dout.template subtile<16, kB300VDim>({warp, 0});
                auto do_destination =
                    main.dout.template subtile<16, kB300VDim>({warp, 0});
                warp::load(do_reg, do_source);
                warp::store(do_destination, do_reg);
            }
            if (threadIdx.x == 0) {
                cta2_fused_dense_load_peer_qdo(
                    g,
                    qdo_exchange,
                    qdo_exchange_done,
                    batch_idx,
                    q_tile_idx,
                    head_idx,
                    cta_rank
                );
            }
        }
        __syncthreads();
        if constexpr (UseScoreOperandReadyMbar) {
            if ((!PipelineNextScore || iteration == 0) && threadIdx.x == 0) {
                ::kittens::tma::cluster::arrive(score_operands_ready, 0);
            }
        } else {
            everyone::tma::cluster::sync();
        }

        if constexpr (PipelineNextScore) {
            if (iteration == 0 && cta_rank == 0) {
                if constexpr (UseScoreOperandReadyMbar) {
                    if (threadIdx.x == 0) {
                        wait(score_operands_ready, owner_phase);
                    }
                }
                group<8>::mm2_ABt(score_dp_tmem, storage.k, main.q.q);
                if (threadIdx.x == 0) {
                    cta2_fused_dense_commit(score_done);
                }
            }
        } else {
            if (cta_rank == 0) {
                if constexpr (UseScoreOperandReadyMbar) {
                    if (threadIdx.x == 0) {
                        wait(score_operands_ready, phase);
                    }
                }
                group<8>::mm2_ABt(score_dp_tmem, storage.k, main.q.q);
                if (threadIdx.x == 0) {
                    cta2_fused_dense_commit(score_done);
                }
            }
        }
        wait(score_done, phase);

        cta2_fused_dense_attn_bf_reg p_bf;
        {
            cta2_fused_dense_attn_reg p_reg;
            cta2_fused_dense_stats_vec lse_vec;
            group<8>::load_async(p_reg, score_dp_tmem);
            if constexpr (CacheLse) {
                warp::load(lse_vec, storage.stats.lse_log2);
            } else {
                warp::load(
                    lse_vec,
                    g.lse_log2,
                    {batch_idx, head_idx, 0, q_tile_idx}
                );
            }
            tensor_load_wait();
            warp::mul(p_reg, p_reg, g.scale_log2e);
            warp::sub_col(p_reg, p_reg, lse_vec);
            warp::exp2(p_reg, p_reg);
            if (q_tile_idx == first_dense_q_tile && cta_rank == 1) {
                // The frontier owns rank 1's diagonal half. Rank 0 alone owns
                // this K128-by-Q128 cross-half tile.
                warp::zero(p_reg);
            }
            warp::copy(p_bf, p_reg);
            if constexpr (UseTmemP) {
                group<8>::store_async(p_tmem, p_bf);
                tensor_store_wait();
            } else {
                auto p_smem =
                    main.p.p.template subtile<16, 128>({output_subtile, 0});
                warp::store(p_smem, p_bf);
            }
            auto v_smem = storage.ds.template subtile<16, kB300VDim>(
                {warp, 0}
            );
            warp::store(v_smem, v_persistent);
        }
        __syncthreads();
        if constexpr (UseDpOperandReadyMbar) {
            if (threadIdx.x == 0) {
                ::kittens::tma::cluster::arrive(dp_operands_ready, 0);
            }
        } else {
            everyone::tma::cluster::sync();
        }

        if constexpr (UseDpOperandReadyMbar) {
            if (cta_rank == 0 && threadIdx.x == 0) {
                wait(dp_operands_ready, phase);
                group<8>::mm2_ABt(score_dp_tmem, storage.ds, main.dout);
                cta2_fused_dense_commit(dp_done);
            }
        } else if (cta_rank == 0) {
            group<8>::mm2_ABt(score_dp_tmem, storage.ds, main.dout);
            if (threadIdx.x == 0) {
                cta2_fused_dense_commit(dp_done);
            }
        }
        if constexpr (OverlapQWithDp) {
            wait(qdo_exchange_done, phase);
            cta2_fused_dense_prepare_q_operand<
                UseTmemDs,
                UseTmemP && OverlapDoWithDp
            >(
                main,
                qdo_exchange,
                warp,
                cta_rank
            );
        }
        wait(dp_done, phase);

        if constexpr (OverlapDvWithDs) {
            if (cta_rank == 0) {
                auto &do_normal =
                    *reinterpret_cast<st_bf<128, 64> *>(&main.p.p);
                if (first_accumulation) {
                    group<8>::mm2_AB(dv_tmem, p_tmem, do_normal);
                } else {
                    group<8>::mma2_AB(dv_tmem, p_tmem, do_normal);
                }
            }
        }

        {
            cta2_fused_dense_attn_reg dp_reg;
            cta2_fused_dense_stats_vec dpsum_vec;
            group<8>::load_async(dp_reg, score_dp_tmem);
            warp::load(dpsum_vec, storage.stats.dpsum);
            tensor_load_wait();
            warp::sub_col(dp_reg, dp_reg, dpsum_vec);
            cta2_fused_dense_attn_reg ds_reg;
            warp::copy(ds_reg, p_bf);
            warp::mul(ds_reg, ds_reg, dp_reg);
            warp::mul(ds_reg, ds_reg, g.scale);
            cta2_fused_dense_attn_bf_reg ds_bf;
            warp::copy(ds_bf, ds_reg);
            if constexpr (UseTmemDs) {
                group<8>::store_async(ds_tmem, ds_bf);
                tensor_store_wait();
            }
            auto ds_smem = storage.ds.template subtile<16, 128>(
                {output_subtile, 0}
            );
            warp::store(ds_smem, ds_bf);
        }
        if constexpr (UseDsWarpMulticastMbar) {
            __syncwarp();
            if (laneid() == 0) {
                ::kittens::tma::cluster::arrive(
                    ds_warp_multicast_ready,
                    0
                );
                ::kittens::tma::cluster::arrive(
                    ds_warp_multicast_ready,
                    1
                );
            }
            ::kittens::tma::cluster::wait(
                ds_warp_multicast_ready,
                phase
            );
        } else {
            __syncthreads();
            everyone::tma::cluster::sync();
        }

        if constexpr (!OverlapQWithDp) {
            wait(qdo_exchange_done, phase);
            cta2_fused_dense_prepare_q_operand<
                UseTmemDs,
                UseTmemP && OverlapDoWithDp
            >(
                main,
                qdo_exchange,
                warp,
                cta_rank
            );
        }
        if constexpr (UseTmemP && !OverlapDoWithDp) {
            rt_bf<16, 64> do_half;
            const int source_row = warp & 3;
            if ((warp >> 2) == cta_rank) {
                auto do_source = main.dout.template subtile<16, 64>(
                    {source_row, cta_rank}
                );
                warp::load(do_half, do_source);
            } else {
                auto do_source = qdo_exchange.dout.template subtile<16, 64>(
                    {source_row, 0}
                );
                warp::load(do_half, do_source);
            }
            __syncthreads();
            auto &do_normal =
                *reinterpret_cast<st_bf<128, 64> *>(&main.dout);
            auto do_destination =
                do_normal.template subtile<16, 64>({warp, 0});
            warp::store(do_destination, do_half);
        } else if constexpr (!UseTmemP) {
            rt_bf<16, 64> do_half;
            rt_bf<64, 16> do_transposed;
            const int source_row = warp & 3;
            if ((warp >> 2) == cta_rank) {
                auto do_source = main.dout.template subtile<16, 64>(
                    {source_row, cta_rank}
                );
                warp::load(do_half, do_source);
            } else {
                auto do_source = qdo_exchange.dout.template subtile<16, 64>(
                    {source_row, 0}
                );
                warp::load(do_half, do_source);
            }
            warp::transpose_sep(do_transposed, do_half);
            __syncthreads();
            auto do_smem = main.dout.template subtile<64, 16>({0, warp});
            warp::store(do_smem, do_transposed);
        }
        if constexpr (!UseTmemP || !OverlapDoWithDp) {
            __syncthreads();
            everyone::tma::cluster::sync();
        }

        if constexpr (OverlapDsExchange) {
            if (threadIdx.x == 0) {
                const int peer_rank = cta_rank ^ 1;
                constexpr int kDsHalfElements = 128 * 64;
                ::kittens::tma::cluster::expect_bytes(
                    dq_exchange_done,
                    sizeof(storage.qdo_phase.ds),
                    peer_rank
                );
                ::kittens::tma::cluster::store_async(
                    reinterpret_cast<void *>(&storage.qdo_phase.ds),
                    reinterpret_cast<void *>(
                        &storage.ds.data[peer_rank * kDsHalfElements]
                    ),
                    sizeof(storage.qdo_phase.ds),
                    peer_rank,
                    dq_exchange_done
                );
            }
        }

        if (cta_rank == 0) {
            if (first_accumulation) {
                if constexpr (!OverlapDvWithDs) {
                    if constexpr (UseTmemP) {
                        auto &do_normal = OverlapDoWithDp
                            ? *reinterpret_cast<st_bf<128, 64> *>(&main.p.p)
                            : *reinterpret_cast<st_bf<128, 64> *>(&main.dout);
                        group<8>::mm2_AB(dv_tmem, p_tmem, do_normal);
                    } else {
                        group<8>::mm2_ABt(dv_tmem, main.p.p, main.dout);
                    }
                }
                if constexpr (UseTmemDs) {
                    group<8>::mm2_AB(
                        dk_main_tmem,
                        ds_tmem,
                        main.q.normal.q0
                    );
                    group<8>::mm2_AB(
                        dk_tail_tmem,
                        ds_tmem,
                        main.q.normal.q1
                    );
                } else {
                    group<8>::mm2_ABt(
                        dk_main_tmem,
                        storage.ds,
                        main.q.transposed.q0
                    );
                    group<8>::mm2_ABt(
                        dk_tail_tmem,
                        storage.ds,
                        main.q.transposed.q1
                    );
                }
            } else {
                if constexpr (!OverlapDvWithDs) {
                    if constexpr (UseTmemP) {
                        auto &do_normal = OverlapDoWithDp
                            ? *reinterpret_cast<st_bf<128, 64> *>(&main.p.p)
                            : *reinterpret_cast<st_bf<128, 64> *>(&main.dout);
                        group<8>::mma2_AB(dv_tmem, p_tmem, do_normal);
                    } else {
                        group<8>::mma2_ABt(dv_tmem, main.p.p, main.dout);
                    }
                }
                if constexpr (UseTmemDs) {
                    group<8>::mma2_AB(
                        dk_main_tmem,
                        ds_tmem,
                        main.q.normal.q0
                    );
                    group<8>::mma2_AB(
                        dk_tail_tmem,
                        ds_tmem,
                        main.q.normal.q1
                    );
                } else {
                    group<8>::mma2_ABt(
                        dk_main_tmem,
                        storage.ds,
                        main.q.transposed.q0
                    );
                    group<8>::mma2_ABt(
                        dk_tail_tmem,
                        storage.ds,
                        main.q.transposed.q1
                    );
                }
            }
            if (threadIdx.x == 0) {
                cta2_fused_dense_commit(dkdv_done);
            }
        }

        rt_bf<16, 64> dq_a_local_preload;
        rt_bf<16, 64> dq_a_peer_preload;
        if constexpr (PreloadDqA) {
            auto ds_local_smem =
                storage.ds.template subtile<16, 64>({warp, cta_rank});
            warp::load(dq_a_local_preload, ds_local_smem);
            ::kittens::tma::cluster::wait(dq_exchange_done, phase);
            auto ds_peer_smem =
                storage.qdo_phase.ds.template subtile<16, 64>({warp, 0});
            warp::load(dq_a_peer_preload, ds_peer_smem);
        }
        wait(dkdv_done, phase);

        auto &dq_operands = storage.phase.dq.operands;
        if constexpr (PreloadDqA) {
            auto a_local_smem =
                dq_operands.a.template subtile<16, 64>(
                    {cta_rank * 8 + warp, 0}
                );
            warp::store(a_local_smem, dq_a_local_preload);
            const int peer_rank = cta_rank ^ 1;
            auto a_peer_smem =
                dq_operands.a.template subtile<16, 64>(
                    {peer_rank * 8 + warp, 0}
                );
            warp::store(a_peer_smem, dq_a_peer_preload);
        } else {
            rt_bf<16, 64> ds_local;
            auto ds_local_smem =
                storage.ds.template subtile<16, 64>({warp, cta_rank});
            warp::load(ds_local, ds_local_smem);
            auto a_local_smem =
                dq_operands.a.template subtile<16, 64>(
                    {cta_rank * 8 + warp, 0}
                );
            warp::store(a_local_smem, ds_local);
        }

        if constexpr (!PreloadDqA) {
            if constexpr (OverlapDsExchange) {
                ::kittens::tma::cluster::wait(dq_exchange_done, phase);
                rt_bf<16, 64> ds_peer;
                auto ds_peer_smem =
                    storage.qdo_phase.ds.template subtile<16, 64>({warp, 0});
                warp::load(ds_peer, ds_peer_smem);
                const int peer_rank = cta_rank ^ 1;
                auto a_peer_smem =
                    dq_operands.a.template subtile<16, 64>(
                        {peer_rank * 8 + warp, 0}
                    );
                warp::store(a_peer_smem, ds_peer);
            } else {
                if (threadIdx.x == 0) {
                    const int peer_rank = cta_rank ^ 1;
                    constexpr int kDsHalfElements = 128 * 64;
                    void *destination = reinterpret_cast<void *>(
                        &dq_operands.a.data[cta_rank * 128 * 64]
                    );
                    ::kittens::tma::cluster::expect_bytes(
                        dq_exchange_done,
                        sizeof(dq_operands.exchange.ds),
                        peer_rank
                    );
                    ::kittens::tma::cluster::store_async(
                        destination,
                        reinterpret_cast<void *>(
                            &storage.ds.data[peer_rank * kDsHalfElements]
                        ),
                        sizeof(dq_operands.exchange.ds),
                        peer_rank,
                        dq_exchange_done
                    );
                }
                ::kittens::tma::cluster::wait(dq_exchange_done, phase);
            }
        }
        __syncthreads();
        if constexpr (UseDqOperandReadyMbar) {
            if (threadIdx.x == 0) {
                ::kittens::tma::cluster::arrive(dq_operands_ready, 0);
            }
        } else {
            everyone::tma::cluster::sync();
        }

        if constexpr (UseDqOperandReadyMbar) {
            if (cta_rank == 0 && threadIdx.x == 0) {
                wait(dq_operands_ready, phase);
                group<8>::mm2_AtB(
                    dq_tmem,
                    dq_operands.a,
                    storage.dq_b
                );
                cta2_fused_dense_commit(dq_done);
            }
        } else if (cta_rank == 0) {
            group<8>::mm2_AtB(dq_tmem, dq_operands.a, storage.dq_b);
            if (threadIdx.x == 0) {
                cta2_fused_dense_commit(dq_done);
            }
        }
        wait(dq_done, phase);

        cta2_fused_dense_prefetch_next_qdo<CacheLse>(
            g,
            storage,
            qdo_prefetch_done,
            batch_idx,
            q_tile_idx,
            q_tile_count,
            head_idx,
            cta_rank
        );

        const bool has_next_q_tile = q_tile_idx + 1 < q_tile_count;
        if constexpr (PipelineNextScore) {
            if (has_next_q_tile && threadIdx.x == 128) {
                wait(qdo_prefetch_done, local_phase);
                ::kittens::tma::cluster::arrive(score_lookahead_ready, 0);
            }
        }

        if (warp < 4) {
            auto &dq_reduce = storage.phase.dq.reduce;
            const int row_half = warp & 1;
            const int col_half = warp >> 1;
            const int q_row_block =
                q_tile_idx * 4 + cta_rank * 2 + row_half;
            const uint32_t physical_row = static_cast<uint32_t>(warp * 32);
            #pragma unroll 1
            for (int chunk = 0; chunk < 3; ++chunk) {
                uint32_t values[32];
                cta2_fused_dense_load_tmem_x32(
                    values,
                    dq_tmem.addr + (physical_row << 16) + chunk * 32
                );
                if constexpr (PipelineNextScore) {
                    if (
                        has_next_q_tile && chunk == 2 &&
                        (threadIdx.x & 31) == 0
                    ) {
                        ::kittens::tma::cluster::arrive(
                            score_lookahead_ready,
                            0
                        );
                    }
                }
                if (chunk >= 2) {
                    warp::tma::store_async_wait<1>();
                }
                auto &stage = dq_reduce.stage[chunk & 1][warp];
                #pragma unroll
                for (int col = 0; col < 32; col += 4) {
                    *reinterpret_cast<float4 *>(&stage[{laneid(), col}]) =
                        make_float4(
                            __uint_as_float(values[col + 0]),
                            __uint_as_float(values[col + 1]),
                            __uint_as_float(values[col + 2]),
                            __uint_as_float(values[col + 3])
                        );
                }
                __syncwarp();
                warp::tma::store_add_async<dim::DEPTH, cache_policy::NORMAL>(
                    g.dq,
                    stage,
                    {
                        batch_idx,
                        q_row_block,
                        head_idx,
                        col_half * 3 + chunk
                    }
                );
            }
            warp::tma::store_async_wait();
        }
        if constexpr (PipelineNextScore) {
            if (
                has_next_q_tile && cta_rank == 0 && threadIdx.x == 128
            ) {
                wait(score_lookahead_ready, score_lookahead_count & 1);
                auto &next_q = storage.phase.dq.operands.exchange.next_q;
                ::kittens::mm2<transpose::N, transpose::T>(
                    score_dp_tmem,
                    storage.k,
                    next_q
                );
                cta2_fused_dense_commit(score_done);
            }
            if (has_next_q_tile) {
                ++score_lookahead_count;
            }
        }
        __syncthreads();
        everyone::tma::cluster::sync();
        first_accumulation = false;
    }

    const int kv_depth_tile = owner_idx * 16 + cta_rank * 8 + output_subtile;
    if (first_dense_q_tile < q_tile_count) {
        cta2_fused_dense_attn_reg dk_main;
        cta2_fused_dense_dk_tail_reg dk_tail;
        cta2_fused_dense_attn_reg dv_reg;
        group<8>::load_async(dk_main, dk_main_tmem);
        group<8>::load_async(dk_tail, dk_tail_tmem);
        group<8>::load_async(dv_reg, dv_tmem);
        tensor_load_wait();
        warp::store<dim::DEPTH>(
            g.dk,
            dk_main,
            {batch_idx, kv_depth_tile, head_idx, 0}
        );
        warp::store<dim::DEPTH>(
            g.dk,
            dk_tail,
            {batch_idx, kv_depth_tile, head_idx, 2}
        );
        warp::store<dim::DEPTH>(
            g.dv,
            dv_reg,
            {batch_idx, kv_depth_tile, head_idx, 0}
        );
    } else {
        cta2_fused_dense_attn_reg dk_main;
        cta2_fused_dense_dk_tail_reg dk_tail;
        cta2_fused_dense_attn_reg dv_reg;
        warp::zero(dk_main);
        warp::zero(dk_tail);
        warp::zero(dv_reg);
        warp::store<dim::DEPTH>(
            g.dk,
            dk_main,
            {batch_idx, kv_depth_tile, head_idx, 0}
        );
        warp::store<dim::DEPTH>(
            g.dk,
            dk_tail,
            {batch_idx, kv_depth_tile, head_idx, 2}
        );
        warp::store<dim::DEPTH>(
            g.dv,
            dv_reg,
            {batch_idx, kv_depth_tile, head_idx, 0}
        );
    }
    __syncthreads();
    everyone::tma::cluster::sync();
    }
}

__device__ __forceinline__ void cta2_role_split_select_ds_half(
    rt_bf<16, 64> &dst,
    const cta2_fused_dense_attn_bf_reg &src,
    int half
) {
    if (half == 0) {
        #pragma unroll
        for (int col = 0; col < dst.width; ++col) {
            dst.tiles[0][col] = src.tiles[0][col];
        }
    } else {
        #pragma unroll
        for (int col = 0; col < dst.width; ++col) {
            dst.tiles[0][col] = src.tiles[0][dst.width + col];
        }
    }
}

template <ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_store_ds_x32_stage(
    ST &dst,
    const uint32_t (&src)[16],
    int row_base,
    int col_base
) {
    static_assert(ST::cols == 64);
    static_assert(std::is_same_v<typename ST::dtype, bf16>);
    const int row = row_base + laneid();
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    #pragma unroll
    for (int packed = 0; packed < 16; packed += 4) {
        const uint32_t address = dst.idx(
            shared_addr,
            {row, col_base + 2 * packed}
        );
        asm volatile(
            "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
            ::
              "r"(address),
              "r"(src[packed + 0]),
              "r"(src[packed + 1]),
              "r"(src[packed + 2]),
              "r"(src[packed + 3])
            : "memory"
        );
    }
}

template <int Half, ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_store_ds_half_direct(
    ST &dst,
    const cta2_fused_dense_attn_bf_reg &src
) {
    static_assert(Half == 0 || Half == 1);
    static_assert(ST::cols == 64);
    using U = typename ST::dtype;
    using U2 = base_types::packing<U>::packed_type;
    static_assert(std::is_same_v<U2, typename cta2_fused_dense_attn_bf_reg::dtype>);

    const int lane = laneid();
    const int row = lane % 16;
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    #pragma unroll
    for (int tile_col = 0; tile_col < 4; ++tile_col) {
        const int col = tile_col * 16 + (lane / 16) * 8;
        const auto &tile = src.tiles[0][Half * 4 + tile_col];
        U2 value0 = tile.data[0];
        U2 value1 = tile.data[1];
        U2 value2 = tile.data[2];
        U2 value3 = tile.data[3];
        move<U2>::stsm4(
            dst.idx(shared_addr, {row, col}),
            value0,
            value1,
            value2,
            value3
        );
    }
}

template <uint32_t ExponentDelta = kCta2DenseFp8DsBf16PairDelta>
__device__ __forceinline__ uint16_t
cta2_role_split_convert_scaled_bf16_pair_to_fp8(const bf16_2 &values);

template <uint32_t ExponentDelta = kCta2DenseFp8DsBf16PairDelta>
__device__ __forceinline__ uint32_t
cta2_role_split_convert_scaled_bf16_pairs_to_fp8x4(
    const bf16_2 &values0,
    const bf16_2 &values1
);

template <uint32_t ExponentDelta = kCta2DenseFp8DsF32Delta>
__device__ __forceinline__ uint16_t
cta2_role_split_convert_scaled_f32_pair_to_fp8(const float2 &values) {
    const uint32_t source0 = std::bit_cast<uint32_t>(values.x);
    const uint32_t source1 = std::bit_cast<uint32_t>(values.y);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b32 scaled0;\n"
        ".reg .b32 scaled1;\n"
        ".reg .b16 result;\n"
        "add.u32 scaled0, %1, %3;\n"
        "add.u32 scaled1, %2, %3;\n"
        "cvt.rn.satfinite.e4m3x2.f32 result, scaled1, scaled0;\n"
        "cvt.u32.u16 %0, result;\n"
        "}\n"
        : "=r"(packed)
        : "r"(source0), "r"(source1),
          "n"(ExponentDelta)
    );
    return static_cast<uint16_t>(packed);
}

__device__ __forceinline__ uint16_t
cta2_role_split_convert_f32_pair_to_fp8(const float2 &values) {
    const uint32_t source0 = std::bit_cast<uint32_t>(values.x);
    const uint32_t source1 = std::bit_cast<uint32_t>(values.y);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b16 result;\n"
        "cvt.rn.satfinite.e4m3x2.f32 result, %2, %1;\n"
        "cvt.u32.u16 %0, result;\n"
        "}\n"
        : "=r"(packed)
        : "r"(source0), "r"(source1)
    );
    return static_cast<uint16_t>(packed);
}

template <
    int Rows,
    int Cols,
    uint32_t ExponentDelta = kCta2DenseFp8DsF32Delta
>
__device__ __forceinline__ void cta2_role_split_convert_ds_f32_to_fp8(
    rt_fp8e4m3<Rows, Cols> &dst,
    const rt_fl<Rows, Cols> &src,
    float scale
) {
    // Quantize directly from the FP32 dS producer.  Converting both source
    // adoption pairs before the lane exchange preserves the exact TK output
    // ownership while avoiding the intermediate FP32->BF16 pack and the
    // BF16->FP32 reconstruction in the E4M3 converter.
    (void)scale;
    const int lane = laneid();
    #pragma unroll
    for (int tile_row = 0; tile_row < dst.height; ++tile_row) {
        #pragma unroll
        for (int tile_col = 0; tile_col < dst.width; ++tile_col) {
            #pragma unroll
            for (int packed = 0; packed < dst.packed_per_tile; ++packed) {
                const auto &source = src.tiles[tile_row][
                    2 * tile_col + packed / 2
                ];
                const int source_index = packed & 1;
                const uint32_t converted_lo =
                    cta2_role_split_convert_scaled_f32_pair_to_fp8<
                        ExponentDelta
                    >(
                        source.data[source_index + 0]
                    );
                const uint32_t converted_hi =
                    cta2_role_split_convert_scaled_f32_pair_to_fp8<
                        ExponentDelta
                    >(
                        source.data[source_index + 2]
                    );
                const uint32_t adoption0 = (lane & 1) == 0
                    ? converted_lo
                    : converted_hi;
                const uint32_t adoption1 = (lane & 1) == 0
                    ? converted_hi
                    : converted_lo;

                const int high_columns = (lane >> 1) & 1;
                const int source_pair =
                    (lane & ~3) + 2 * (lane & 1);
                const int source_lane0 = source_pair + high_columns;
                const int source_lane1 =
                    source_pair + 1 - high_columns;
                const uint32_t shuffled0 = __shfl_sync(
                    MASK_ALL,
                    adoption0,
                    source_lane0
                );
                const uint32_t shuffled1 = __shfl_sync(
                    MASK_ALL,
                    adoption1,
                    source_lane1
                );
                uint32_t converted;
                asm volatile(
                    "prmt.b32 %0, %1, %2, 0x5410;\n"
                    : "=r"(converted)
                    : "r"(shuffled0), "r"(shuffled1)
                );
                uint32_t ordered;
                asm volatile(
                    "shf.r.wrap.b32 %0, %1, %1, %2;\n"
                    : "=r"(ordered)
                    : "r"(converted), "r"(high_columns * 16)
                );
                dst.tiles[tile_row][tile_col].data[packed] =
                    std::bit_cast<fp8e4m3_4>(ordered);
            }
        }
    }
}

template <uint32_t ExponentDelta>
__device__ __forceinline__ void
cta2_role_split_convert_p_f32_half_to_fp8(
    cta2_fused_dense_attn_half_fp8_reg &dst,
    const cta2_fused_dense_attn_half_reg &src
) {
    // FP32 register tiles distribute each 16-column row across a four-lane
    // quartet, whereas the packed FP8 TMEM store needs one four-byte word per
    // lane.  Preserve the proven adoption/exchange mapping, but select the
    // final halfword order directly in PRMT.  The selector is invariant for
    // the lane, replacing every packed word's variable halfword rotate with
    // one value hoisted outside the unrolled loops.
    const int lane = laneid();
    const int high_columns = (lane >> 1) & 1;
    const int source_pair = (lane & ~3) + 2 * (lane & 1);
    const int source_lane0 = source_pair + high_columns;
    const int source_lane1 = source_pair + 1 - high_columns;
    const uint32_t prmt_selector = high_columns ? 0x1054u : 0x5410u;
    #pragma unroll
    for (int tile_col = 0; tile_col < dst.width; ++tile_col) {
        #pragma unroll
        for (int packed = 0; packed < dst.packed_per_tile; ++packed) {
            const auto &source = src.tiles[0][
                2 * tile_col + packed / 2
            ];
            const int source_index = packed & 1;
            const uint32_t converted_lo =
                cta2_role_split_convert_scaled_f32_pair_to_fp8<
                    ExponentDelta
                >(source.data[source_index + 0]);
            const uint32_t converted_hi =
                cta2_role_split_convert_scaled_f32_pair_to_fp8<
                    ExponentDelta
                >(source.data[source_index + 2]);
            const uint32_t adoption0 = (lane & 1) == 0
                ? converted_lo
                : converted_hi;
            const uint32_t adoption1 = (lane & 1) == 0
                ? converted_hi
                : converted_lo;
            const uint32_t shuffled0 = __shfl_sync(
                MASK_ALL,
                adoption0,
                source_lane0
            );
            const uint32_t shuffled1 = __shfl_sync(
                MASK_ALL,
                adoption1,
                source_lane1
            );
            uint32_t converted;
            asm volatile(
                "prmt.b32 %0, %1, %2, %3;\n"
                : "=r"(converted)
                : "r"(shuffled0), "r"(shuffled1), "r"(prmt_selector)
            );
            dst.tiles[0][tile_col].data[packed] =
                std::bit_cast<fp8e4m3_4>(converted);
        }
    }
}

template <
    int Rows,
    int Cols,
    uint32_t ExponentDelta = kCta2DenseFp8DsBf16PairDelta
>
__device__ __forceinline__ void cta2_role_split_convert_ds_bf16_to_fp8(
    rt_fp8e4m3<Rows, Cols> &dst,
    const rt_bf<Rows, Cols> &src,
    float scale
) {
    // Convert the two packed BF16 values per register directly to E4M3.  The
    // exponent adjustment folds the fixed dS quantization scale into the
    // conversion, avoiding a separate floating-point multiply.
    (void)scale;
    const int lane = laneid();
    #pragma unroll
    for (int tile_row = 0; tile_row < dst.height; ++tile_row) {
        #pragma unroll
        for (int tile_col = 0; tile_col < dst.width; ++tile_col) {
            #pragma unroll
            for (int packed = 0; packed < dst.packed_per_tile; ++packed) {
                const auto &source = src.tiles[tile_row][
                    2 * tile_col + packed / 2
                ];
                const int source_index = packed & 1;
                bf16_2 adoption0;
                bf16_2 adoption1;
                if ((lane & 1) == 0) {
                    adoption0 = source.data[source_index + 0];
                    adoption1 = source.data[source_index + 2];
                } else {
                    adoption0 = source.data[source_index + 2];
                    adoption1 = source.data[source_index + 0];
                }

                // Preserve the exact TK FP8 ownership mapping, but choose the
                // source order arithmetically.  High-column consumers fetch
                // the two adoption registers in reverse order; a single
                // halfword rotate below restores logical column order instead
                // of selecting both 32-bit operands a second time.
                const int high_columns = (lane >> 1) & 1;
                const int source_pair =
                    (lane & ~3) + 2 * (lane & 1);
                const int source_lane0 = source_pair + high_columns;
                const int source_lane1 =
                    source_pair + 1 - high_columns;
                const bf16_2 shuffled0 = packed_shfl_sync(
                    MASK_ALL,
                    adoption0,
                    source_lane0
                );
                const bf16_2 shuffled1 = packed_shfl_sync(
                    MASK_ALL,
                    adoption1,
                    source_lane1
                );
                const uint32_t converted =
                    cta2_role_split_convert_scaled_bf16_pairs_to_fp8x4<
                        ExponentDelta
                    >(
                        shuffled0,
                        shuffled1
                    );
                uint32_t ordered;
                asm volatile(
                    "shf.r.wrap.b32 %0, %1, %1, %2;\n"
                    : "=r"(ordered)
                    : "r"(converted), "r"(high_columns * 16)
                );
                dst.tiles[tile_row][tile_col].data[packed] =
                    std::bit_cast<fp8e4m3_4>(ordered);
            }
        }
    }
}

template <uint32_t ExponentDelta>
__device__ __forceinline__ uint32_t
cta2_role_split_convert_scaled_bf16_pairs_to_fp8x4(
    const bf16_2 &values0,
    const bf16_2 &values1
) {
    const uint32_t source0 =
        *reinterpret_cast<const uint32_t *>(&values0);
    const uint32_t source1 =
        *reinterpret_cast<const uint32_t *>(&values1);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b32 scaled0;\n"
        ".reg .b32 scaled1;\n"
        ".reg .b32 value00;\n"
        ".reg .b32 value01;\n"
        ".reg .b32 value10;\n"
        ".reg .b32 value11;\n"
        ".reg .b16 result0;\n"
        ".reg .b16 result1;\n"
        "add.u32 scaled0, %1, %3;\n"
        "add.u32 scaled1, %2, %3;\n"
        "shl.b32 value00, scaled0, 16;\n"
        "and.b32 value01, scaled0, 0xffff0000;\n"
        "shl.b32 value10, scaled1, 16;\n"
        "and.b32 value11, scaled1, 0xffff0000;\n"
        "cvt.rn.satfinite.e4m3x2.f32 result0, value01, value00;\n"
        "cvt.rn.satfinite.e4m3x2.f32 result1, value11, value10;\n"
        "mov.b32 %0, {result0, result1};\n"
        "}\n"
        : "=r"(packed)
        : "r"(source0), "r"(source1),
          "n"(ExponentDelta)
    );
    return packed;
}

template <uint32_t ExponentDelta>
__device__ __forceinline__ uint16_t
cta2_role_split_convert_scaled_bf16_pair_to_fp8(const bf16_2 &values) {
    const uint32_t source =
        *reinterpret_cast<const uint32_t *>(&values);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b32 scaled;\n"
        ".reg .b32 value0;\n"
        ".reg .b32 value1;\n"
        ".reg .b16 result;\n"
        "add.u32 scaled, %1, %2;\n"
        "shl.b32 value0, scaled, 16;\n"
        "and.b32 value1, scaled, 0xffff0000;\n"
        "cvt.rn.satfinite.e4m3x2.f32 result, value1, value0;\n"
        "cvt.u32.u16 %0, result;\n"
        "}\n"
        : "=r"(packed)
        : "r"(source), "n"(ExponentDelta)
    );
    return static_cast<uint16_t>(packed);
}

template <int Words>
__device__ __forceinline__ void cta2_role_split_store_fp8_tmem_x32(
    uint32_t dst_addr,
    const uint32_t (&src)[Words]
) {
    static_assert(Words >= 8);
    asm volatile(
        "tcgen05.st.sync.aligned.32x32b.x8.b32 [%0], "
        "{%1, %2, %3, %4, %5, %6, %7, %8};\n"
        :: "r"(dst_addr),
           "r"(src[0]), "r"(src[1]), "r"(src[2]), "r"(src[3]),
           "r"(src[4]), "r"(src[5]), "r"(src[6]), "r"(src[7])
        : "memory"
    );
}

__device__ __forceinline__ uint32_t
cta2_role_split_convert_f32_pair_to_half2(
    const float2 &values
) {
    const uint32_t source0 = std::bit_cast<uint32_t>(values.x);
    const uint32_t source1 = std::bit_cast<uint32_t>(values.y);
    uint32_t packed;
    asm volatile(
        "{\n"
        "cvt.rn.f16x2.f32 %0, %2, %1;\n"
        "}\n"
        : "=r"(packed)
        : "r"(source0), "r"(source1)
    );
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_center_f32x2_to_half2(
    uint32_t value0,
    uint32_t value1,
    float center0,
    float center1
) {
    const uint32_t center0_bits = std::bit_cast<uint32_t>(center0);
    const uint32_t center1_bits = std::bit_cast<uint32_t>(center1);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b64 values, centers, centered;\n"
        ".reg .b32 centered0, centered1;\n"
        "mov.b64 values, {%1, %2};\n"
        "mov.b64 centers, {%3, %4};\n"
        "sub.f32x2 centered, values, centers;\n"
        "mov.b64 {centered0, centered1}, centered;\n"
        "cvt.rn.f16x2.f32 %0, centered1, centered0;\n"
        "}\n"
        : "=r"(packed)
        : "r"(value0), "r"(value1),
          "r"(center0_bits), "r"(center1_bits)
    );
    return packed;
}

__device__ __forceinline__ void
cta2_role_split_unpack_fp8x4_to_half2(
    uint32_t &lo,
    uint32_t &hi,
    uint32_t packed
) {
    asm volatile(
        "{\n"
        ".reg .b16 packed_lo;\n"
        ".reg .b16 packed_hi;\n"
        "mov.b32 {packed_lo, packed_hi}, %2;\n"
        "cvt.rn.f16x2.e4m3x2 %0, packed_lo;\n"
        "cvt.rn.f16x2.e4m3x2 %1, packed_hi;\n"
        "}\n"
        : "=r"(lo), "=r"(hi)
        : "r"(packed)
    );
}

__device__ __forceinline__ uint16_t
cta2_role_split_convert_half2_to_fp8(const half_2 &values) {
    const uint32_t source =
        *reinterpret_cast<const uint32_t *>(&values);
    uint16_t packed;
    asm volatile(
        "cvt.rn.satfinite.e4m3x2.f16x2 %0, %1;\n"
        : "=h"(packed)
        : "r"(source)
    );
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_convert_half2_pair_to_fp8x4(
    const half_2 &values0,
    const half_2 &values1
) {
    const uint32_t source0 =
        *reinterpret_cast<const uint32_t *>(&values0);
    const uint32_t source1 =
        *reinterpret_cast<const uint32_t *>(&values1);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b16 packed0, packed1;\n"
        "cvt.rn.satfinite.e4m3x2.f16x2 packed0, %1;\n"
        "cvt.rn.satfinite.e4m3x2.f16x2 packed1, %2;\n"
        "mov.b32 %0, {packed0, packed1};\n"
        "}\n"
        : "=r"(packed)
        : "r"(source0), "r"(source1)
    );
    return packed;
}

template <uint32_t HalfPairDelta>
__device__ __forceinline__ uint16_t
cta2_role_split_convert_scaled_half2_to_fp8(const half_2 &values) {
    const uint32_t source =
        *reinterpret_cast<const uint32_t *>(&values);
    // Scale both half lanes independently.  Applying the power-of-two shift
    // after the half2 product preserves normal-value rounding while replacing
    // the two scalar FP32 exponent adjustments used before the product with a
    // single packed add.
    const uint32_t scaled = __vadd2(source, HalfPairDelta);
    uint16_t packed;
    asm volatile(
        "cvt.rn.satfinite.e4m3x2.f16x2 %0, %1;\n"
        : "=h"(packed)
        : "r"(scaled)
    );
    return packed;
}

template <uint32_t ExponentDelta>
__device__ __forceinline__ void
cta2_role_split_store_scaled_bf16_p_fp8_tmem_x32(
    uint32_t dst_addr,
    const uint32_t (&src)[16]
) {
    // The native x32 score fragment gives each lane one complete physical
    // row.  Pack adjacent BF16 probability pairs directly into eight E4M3
    // words, avoiding the quartet exchange required by rt_fl<16, 128>.
    uint32_t packed[8];
    #pragma unroll
    for (int word = 0; word < 8; ++word) {
        const bf16_2 values0 = *reinterpret_cast<const bf16_2 *>(
            &src[2 * word + 0]
        );
        const bf16_2 values1 = *reinterpret_cast<const bf16_2 *>(
            &src[2 * word + 1]
        );
        packed[word] =
            cta2_role_split_convert_scaled_bf16_pairs_to_fp8x4<
                ExponentDelta
            >(values0, values1);
    }
    cta2_role_split_store_fp8_tmem_x32(dst_addr, packed);
}

template <uint32_t ExponentDelta>
__device__ __forceinline__ void
cta2_role_split_make_ds_x32_stage_fp8(
    uint32_t (&p_ds)[16],
    const uint32_t (&dp_words)[32],
    const float (&dpsum)[32]
) {
    // Retain P as BF16 for the dS product, then overwrite the dead prefix of
    // the fragment with four E4M3 dS values per word.  The write cursor always
    // trails the unread P cursor, so this needs no second register array.
    #pragma unroll
    for (int word = 0; word < 8; ++word) {
        const uint32_t p_word0 = p_ds[2 * word + 0];
        const uint32_t p_word1 = p_ds[2 * word + 1];
        const float2 p0{
            __uint_as_float(p_word0 << 16),
            __uint_as_float(p_word0 & 0xffff0000u)
        };
        const float2 p1{
            __uint_as_float(p_word1 << 16),
            __uint_as_float(p_word1 & 0xffff0000u)
        };
        const int element = 4 * word;
        const float2 dp0{
            __uint_as_float(dp_words[element + 0]),
            __uint_as_float(dp_words[element + 1])
        };
        const float2 dp1{
            __uint_as_float(dp_words[element + 2]),
            __uint_as_float(dp_words[element + 3])
        };
        const float2 dpsum0{
            dpsum[element + 0],
            dpsum[element + 1]
        };
        const float2 dpsum1{
            dpsum[element + 2],
            dpsum[element + 3]
        };
        const float2 centered0 =
            base_ops::sub::op<float2>(dp0, dpsum0);
        const float2 centered1 =
            base_ops::sub::op<float2>(dp1, dpsum1);
        const float2 ds0 = base_ops::mul::op<float2>(p0, centered0);
        const float2 ds1 = base_ops::mul::op<float2>(p1, centered1);
        const uint32_t packed0 =
            cta2_role_split_convert_scaled_f32_pair_to_fp8<
                ExponentDelta
            >(ds0);
        const uint32_t packed1 =
            cta2_role_split_convert_scaled_f32_pair_to_fp8<
                ExponentDelta
            >(ds1);
        p_ds[word] = packed0 | (packed1 << 16);
    }
}

template <bool DpScaled16 = false, bool ApplyMxFp4Correction = false>
__device__ __forceinline__ void
cta2_role_split_make_ds_x32_stage_reuse_p_fp8(
    uint32_t (&p_ds)[16],
    const uint32_t (&dp_words)[32],
    const float (&dpsum)[32]
) {
    // P is already the E4M3 value consumed by dV, scaled by 2^8.  Reuse
    // those exact bits for dS instead of retaining a second BF16 copy.  The
    // centered dP conversion folds in the remaining 2^4 of the dS scale, so
    // the half2 product is already in the final 2^12 output scale.
    #pragma unroll
    for (int word = 0; word < 8; ++word) {
        uint32_t p_half0_bits;
        uint32_t p_half1_bits;
        cta2_role_split_unpack_fp8x4_to_half2(
            p_half0_bits,
            p_half1_bits,
            p_ds[word]
        );
        const half_2 p_half0 =
            *reinterpret_cast<const half_2 *>(&p_half0_bits);
        const half_2 p_half1 =
            *reinterpret_cast<const half_2 *>(&p_half1_bits);
        const int element = 4 * word;
        const float2 dp0{
            __uint_as_float(dp_words[element + 0]),
            __uint_as_float(dp_words[element + 1])
        };
        const float2 dp1{
            __uint_as_float(dp_words[element + 2]),
            __uint_as_float(dp_words[element + 3])
        };
        const float2 dpsum0{
            dpsum[element + 0],
            dpsum[element + 1]
        };
        const float2 dpsum1{
            dpsum[element + 2],
            dpsum[element + 3]
        };
        float2 centered0;
        float2 centered1;
        if constexpr (ApplyMxFp4Correction) {
            // MXFP4 MMA accumulators carry the format's standard 36x
            // reconstruction factor.  Fuse its reciprocal into centering
            // so the pure-FP4 dP path never materializes a corrected tile.
            constexpr float kMxFp4Correction = 1.0f / 36.0f;
            centered0 = {
                fmaf(dp0.x, kMxFp4Correction, -dpsum0.x),
                fmaf(dp0.y, kMxFp4Correction, -dpsum0.y)
            };
            centered1 = {
                fmaf(dp1.x, kMxFp4Correction, -dpsum1.x),
                fmaf(dp1.y, kMxFp4Correction, -dpsum1.y)
            };
        } else {
            centered0 = base_ops::sub::op<float2>(dp0, dpsum0);
            centered1 = base_ops::sub::op<float2>(dp1, dpsum1);
        }
        const uint32_t centered_half0_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered0);
        const uint32_t centered_half1_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered1);
        const half_2 centered_half0 =
            *reinterpret_cast<const half_2 *>(&centered_half0_bits);
        const half_2 centered_half1 =
            *reinterpret_cast<const half_2 *>(&centered_half1_bits);
        const half_2 ds_half0 = __hmul2(p_half0, centered_half0);
        const half_2 ds_half1 = __hmul2(p_half1, centered_half1);
        // The FP8-dP path scales both dP operands by 2^2 and stores dPsum
        // with the resulting 2^4 scale.  Together with P's existing 2^8
        // scale, the half2 product is already in the final 2^12 dS scale.
        // The control path still applies its packed 2^4 post-product shift.
        const uint32_t packed0 = DpScaled16
            ? cta2_role_split_convert_half2_to_fp8(ds_half0)
            : cta2_role_split_convert_scaled_half2_to_fp8<
                  kCta2DenseFp8ReuseDsHalfPairDelta
              >(ds_half0);
        const uint32_t packed1 = DpScaled16
            ? cta2_role_split_convert_half2_to_fp8(ds_half1)
            : cta2_role_split_convert_scaled_half2_to_fp8<
                  kCta2DenseFp8ReuseDsHalfPairDelta
              >(ds_half1);
        p_ds[word] = packed0 | (packed1 << 16);
    }
}

__device__ __forceinline__ void
cta2_role_split_preunpack_p_fp8_x32_stage(uint32_t (&p)[16]) {
    #pragma unroll
    for (int word = 7; word >= 6; --word) {
        uint32_t p_half0_bits;
        uint32_t p_half1_bits;
        cta2_role_split_unpack_fp8x4_to_half2(
            p_half0_bits,
            p_half1_bits,
            p[word]
        );
        p[2 * word + 0] = p_half0_bits;
        p[2 * word + 1] = p_half1_bits;
    }
}

template <bool DpScaled16 = false, bool PPreunpacked = false>
__device__ __forceinline__ void
cta2_role_split_make_ds_x32_stage_reuse_p_fp8_half_dpsum(
    uint32_t (&p_ds)[16],
    const uint32_t (&dp_words)[32],
    const uint32_t (&dpsum_half_words)[16]
) {
    #pragma unroll
    for (int word = 0; word < 8; ++word) {
        uint32_t p_half0_bits;
        uint32_t p_half1_bits;
        if constexpr (PPreunpacked) {
            if (word >= 6) {
                p_half0_bits = p_ds[2 * word + 0];
                p_half1_bits = p_ds[2 * word + 1];
            } else {
                cta2_role_split_unpack_fp8x4_to_half2(
                    p_half0_bits,
                    p_half1_bits,
                    p_ds[word]
                );
            }
        } else {
            cta2_role_split_unpack_fp8x4_to_half2(
                p_half0_bits,
                p_half1_bits,
                p_ds[word]
            );
        }
        const half_2 p_half0 =
            *reinterpret_cast<const half_2 *>(&p_half0_bits);
        const half_2 p_half1 =
            *reinterpret_cast<const half_2 *>(&p_half1_bits);
        const int element = 4 * word;
        const float2 dp0{
            __uint_as_float(dp_words[element + 0]),
            __uint_as_float(dp_words[element + 1])
        };
        const float2 dp1{
            __uint_as_float(dp_words[element + 2]),
            __uint_as_float(dp_words[element + 3])
        };
        const uint32_t dp_half0_bits =
            cta2_role_split_convert_f32_pair_to_half2(dp0);
        const uint32_t dp_half1_bits =
            cta2_role_split_convert_f32_pair_to_half2(dp1);
        const half_2 dp_half0 =
            *reinterpret_cast<const half_2 *>(&dp_half0_bits);
        const half_2 dp_half1 =
            *reinterpret_cast<const half_2 *>(&dp_half1_bits);
        const half_2 dpsum_half0 = *reinterpret_cast<const half_2 *>(
            &dpsum_half_words[2 * word + 0]
        );
        const half_2 dpsum_half1 = *reinterpret_cast<const half_2 *>(
            &dpsum_half_words[2 * word + 1]
        );
        const half_2 centered_half0 =
            base_ops::sub::op<half_2>(dp_half0, dpsum_half0);
        const half_2 centered_half1 =
            base_ops::sub::op<half_2>(dp_half1, dpsum_half1);
        const half_2 ds_half0 = __hmul2(p_half0, centered_half0);
        const half_2 ds_half1 = __hmul2(p_half1, centered_half1);
        if constexpr (DpScaled16) {
            p_ds[word] = cta2_role_split_convert_half2_pair_to_fp8x4(
                ds_half0,
                ds_half1
            );
        } else {
            const uint32_t packed0 =
                cta2_role_split_convert_scaled_half2_to_fp8<
                    kCta2DenseFp8ReuseDsHalfPairDelta
                >(ds_half0);
            const uint32_t packed1 =
                cta2_role_split_convert_scaled_half2_to_fp8<
                    kCta2DenseFp8ReuseDsHalfPairDelta
                >(ds_half1);
            p_ds[word] = packed0 | (packed1 << 16);
        }
    }
}

__device__ __forceinline__ void
cta2_role_split_unpack_mxfp4x8_to_half2(
    uint32_t (&dst)[4],
    uint32_t packed
) {
    asm volatile(
        "{\n"
        ".reg .b8 byte0, byte1, byte2, byte3;\n"
        "mov.b32 {byte0, byte1, byte2, byte3}, %4;\n"
        "cvt.rn.f16x2.e2m1x2 %0, byte0;\n"
        "cvt.rn.f16x2.e2m1x2 %1, byte1;\n"
        "cvt.rn.f16x2.e2m1x2 %2, byte2;\n"
        "cvt.rn.f16x2.e2m1x2 %3, byte3;\n"
        "}\n"
        : "=r"(dst[0]), "=r"(dst[1]), "=r"(dst[2]), "=r"(dst[3])
        : "r"(packed)
    );
}

template <bool DpScaled16 = false>
__device__ __forceinline__ void
cta2_role_split_make_ds_x32_stage_reuse_p_mxfp4_half_dpsum(
    uint32_t (&p_ds)[16],
    const uint32_t (&dp_words)[32],
    const uint32_t (&dpsum_half_words)[16]
) {
    const uint8_t p_e8m0 = static_cast<uint8_t>(p_ds[15]);
    // The forward-log pack normalizes P by 2^(129-e).  Reconstruct P*2^8,
    // matching the retained FP8 dS path, with the inverse exponent e+6.
    const float p_scale = p_e8m0 == 0
        ? 0.0f
        : __uint_as_float(
              (static_cast<uint32_t>(p_e8m0) + 6u) << 23
          );
    const half_2 p_scale_half2 = __float2half2_rn(p_scale);
    #pragma unroll
    for (int fp4_word = 3; fp4_word >= 0; --fp4_word) {
        uint32_t p_half_bits[4];
        cta2_role_split_unpack_mxfp4x8_to_half2(
            p_half_bits,
            p_ds[fp4_word]
        );
        #pragma unroll
        for (int pair = 0; pair < 2; ++pair) {
            const int output_word = 2 * fp4_word + pair;
            const int element = 4 * output_word;
            const half_2 p_half0 = __hmul2(
                *reinterpret_cast<const half_2 *>(
                    &p_half_bits[2 * pair + 0]
                ),
                p_scale_half2
            );
            const half_2 p_half1 = __hmul2(
                *reinterpret_cast<const half_2 *>(
                    &p_half_bits[2 * pair + 1]
                ),
                p_scale_half2
            );
            const float2 dp0{
                __uint_as_float(dp_words[element + 0]),
                __uint_as_float(dp_words[element + 1])
            };
            const float2 dp1{
                __uint_as_float(dp_words[element + 2]),
                __uint_as_float(dp_words[element + 3])
            };
            const uint32_t dp_half0_bits =
                cta2_role_split_convert_f32_pair_to_half2(dp0);
            const uint32_t dp_half1_bits =
                cta2_role_split_convert_f32_pair_to_half2(dp1);
            const half_2 dp_half0 =
                *reinterpret_cast<const half_2 *>(&dp_half0_bits);
            const half_2 dp_half1 =
                *reinterpret_cast<const half_2 *>(&dp_half1_bits);
            const half_2 dpsum_half0 =
                *reinterpret_cast<const half_2 *>(
                    &dpsum_half_words[2 * output_word + 0]
                );
            const half_2 dpsum_half1 =
                *reinterpret_cast<const half_2 *>(
                    &dpsum_half_words[2 * output_word + 1]
                );
            const half_2 ds_half0 = __hmul2(
                p_half0,
                base_ops::sub::op<half_2>(dp_half0, dpsum_half0)
            );
            const half_2 ds_half1 = __hmul2(
                p_half1,
                base_ops::sub::op<half_2>(dp_half1, dpsum_half1)
            );
            if constexpr (DpScaled16) {
                p_ds[output_word] =
                    cta2_role_split_convert_half2_pair_to_fp8x4(
                        ds_half0,
                        ds_half1
                    );
            } else {
                const uint32_t packed0 =
                    cta2_role_split_convert_scaled_half2_to_fp8<
                        kCta2DenseFp8ReuseDsHalfPairDelta
                    >(ds_half0);
                const uint32_t packed1 =
                    cta2_role_split_convert_scaled_half2_to_fp8<
                        kCta2DenseFp8ReuseDsHalfPairDelta
                    >(ds_half1);
                p_ds[output_word] = packed0 | (packed1 << 16);
            }
        }
    }
}

template <ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_store_fp8_x32_stage(
    ST &dst,
    const uint32_t (&src)[16],
    int row_base,
    int col_base
) {
    static_assert(std::is_same_v<typename ST::dtype, fp8e4m3>);
    const int row = row_base + laneid();
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    #pragma unroll
    for (int word = 0; word < 8; word += 4) {
        const uint32_t address = dst.idx(
            shared_addr,
            {row, col_base + 4 * word}
        );
        asm volatile(
            "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
            :: "r"(address),
               "r"(src[word + 0]), "r"(src[word + 1]),
               "r"(src[word + 2]), "r"(src[word + 3])
            : "memory"
        );
    }
}

template <int CtaRank>
__device__ __forceinline__ void
cta2_role_split_store_fp8_halves_for_dq_direct(
    cta2_fused_dense_dq_a_fp8_tile &dq_a,
    cta2_fused_dense_dq_exchange_fp8_tile &exchange,
    const rt_fp8e4m3<16, 128> &ds,
    int output_subtile
) {
    // Publish both query halves from the converted register fragment.  This
    // follows the forward FP4 path's direct register-to-consumer publication:
    // dK still receives the complete dS tile, while dQ avoids reloading that
    // just-written tile from shared memory solely to split its two halves.
    static_assert(
        cta2_fused_dense_dq_a_fp8_tile::cols == 64 &&
        cta2_fused_dense_dq_exchange_fp8_tile::cols == 64
    );
    static_assert(CtaRank == 0 || CtaRank == 1);
    const int lane = laneid();
    const int local_row =
        CtaRank * 128 + output_subtile * 16 + lane % 16;
    const int exchange_row = output_subtile * 16 + lane % 16;
    const uint32_t local_shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dq_a.data[0])
    );
    const uint32_t exchange_shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&exchange.data[0])
    );
    #pragma unroll
    for (int tile_col = 0; tile_col < 2; ++tile_col) {
        const int destination_col =
            tile_col * 32 + (lane / 16) * 16;
        const auto &local_tile = ds.tiles[0][CtaRank * 2 + tile_col];
        auto local_value0 = local_tile.data[0];
        auto local_value1 = local_tile.data[1];
        auto local_value2 = local_tile.data[2];
        auto local_value3 = local_tile.data[3];
        move<decltype(local_value0)>::stsm4(
            dq_a.idx(local_shared_addr, {local_row, destination_col}),
            local_value0,
            local_value1,
            local_value2,
            local_value3
        );

        const auto &peer_tile =
            ds.tiles[0][(CtaRank ^ 1) * 2 + tile_col];
        auto peer_value0 = peer_tile.data[0];
        auto peer_value1 = peer_tile.data[1];
        auto peer_value2 = peer_tile.data[2];
        auto peer_value3 = peer_tile.data[3];
        move<decltype(peer_value0)>::stsm4(
            exchange.idx(
                exchange_shared_addr,
                {exchange_row, destination_col}
            ),
            peer_value0,
            peer_value1,
            peer_value2,
            peer_value3
        );
    }
}

template <ducks::st::all ST, ducks::rt::all RT>
__device__ __forceinline__ void cta2_role_split_store_fp8_direct(
    ST &dst,
    const RT &src
) {
    static_assert(ST::rows == RT::rows);
    static_assert(ST::cols == RT::cols);
    static_assert(std::is_same_v<typename ST::dtype, fp8e4m3>);
    static_assert(std::is_same_v<typename RT::T, fp8e4m3>);
    using U2 = typename RT::dtype;

    // group<1>::store includes the physical warp id in its row coordinate.
    // These role-split destinations are already 16-row subtiles, so use the
    // producer-local row directly, as the established BF16 helper does.
    const int lane = laneid();
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    #pragma unroll
    for (int tile_row = 0; tile_row < src.height; ++tile_row) {
        const int row = tile_row * 16 + lane % 16;
        #pragma unroll
        for (int tile_col = 0; tile_col < src.width; ++tile_col) {
            const int col = tile_col * 32 + (lane / 16) * 16;
            const auto &tile = src.tiles[tile_row][tile_col];
            U2 value0 = tile.data[0];
            U2 value1 = tile.data[1];
            U2 value2 = tile.data[2];
            U2 value3 = tile.data[3];
            move<U2>::stsm4(
                dst.idx(shared_addr, {row, col}),
                value0,
                value1,
                value2,
                value3
            );
        }
    }
}

template <ducks::rt::all RT, ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_load_bf16_direct(
    RT &dst,
    const ST &src
) {
    static_assert(ST::rows == RT::rows);
    static_assert(ST::cols == RT::cols);
    static_assert(std::is_same_v<typename ST::dtype, bf16>);
    static_assert(std::is_same_v<typename RT::T, bf16>);
    using U2 = typename RT::dtype;

    const int lane = laneid();
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&src.data[0])
    );
    #pragma unroll
    for (int tile_row = 0; tile_row < dst.height; ++tile_row) {
        const int row = tile_row * 16 + lane % 16;
        #pragma unroll
        for (int tile_col = 0; tile_col < dst.width; ++tile_col) {
            const int col = tile_col * 16 + (lane / 16) * 8;
            auto &tile = dst.tiles[tile_row][tile_col];
            move<U2>::ldsm4(
                tile.data[0],
                tile.data[1],
                tile.data[2],
                tile.data[3],
                src.idx(shared_addr, {row, col})
            );
        }
    }
}

__device__ __forceinline__ void
cta2_role_split_transpose_fp8_ds_for_dq(
    cta2_fused_dense_dq_a_fp8_tile &dq_a,
    cta2_fused_dense_dq_exchange_fp8_tile &dq_exchange,
    const cta2_fused_dense_ds_fp8_tile &ds,
    int output_subtile,
    int cta_rank
) {
    // Each producer warp owns sixteen key rows of dS.  Materialize the
    // physical ABt operand as [query-half, key-pair]: the local query half is
    // written directly, while the peer query half is staged for one bulk
    // cluster copy.  This keeps the group::2 FP8 MMA on the same proven
    // physical-B layout used by TK's FP8 GEMMs.
    constexpr int kQueriesPerCta = 64;
    constexpr int kKeysPerCta = 128;
    constexpr int kElementsPerWarp = 16 * kQueriesPerCta;
    const int lane = laneid();
    const int source_row_base = output_subtile * 16;
    const int local_query_base = cta_rank * kQueriesPerCta;
    const int peer_query_base = (cta_rank ^ 1) * kQueriesPerCta;
    const int destination_key_base = cta_rank * kKeysPerCta;

    #pragma unroll
    for (int linear = lane; linear < kElementsPerWarp; linear += 32) {
        const int source_row = source_row_base + linear / kQueriesPerCta;
        const int query = linear % kQueriesPerCta;
        dq_a[{query, destination_key_base + source_row}] =
            ds[{source_row, local_query_base + query}];
        dq_exchange[{query, source_row}] =
            ds[{source_row, peer_query_base + query}];
    }
}

template <ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_store_ds_stage_direct(
    ST &dst,
    const cta2_fused_dense_attn_half_bf_reg &src
) {
    static_assert(ST::cols == 64);
    using U = typename ST::dtype;
    using U2 = base_types::packing<U>::packed_type;
    static_assert(
        std::is_same_v<
            U2,
            typename cta2_fused_dense_attn_half_bf_reg::dtype
        >
    );

    const int lane = laneid();
    const int row = lane % 16;
    const uint32_t shared_addr = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    #pragma unroll
    for (int tile_col = 0; tile_col < 4; ++tile_col) {
        const int col = tile_col * 16 + (lane / 16) * 8;
        const auto &tile = src.tiles[0][tile_col];
        U2 value0 = tile.data[0];
        U2 value1 = tile.data[1];
        U2 value2 = tile.data[2];
        U2 value3 = tile.data[3];
        move<U2>::stsm4(
            dst.idx(shared_addr, {row, col}),
            value0,
            value1,
            value2,
            value3
        );
    }
}

template <int Half, ducks::st::all ST>
__device__ __forceinline__ void cta2_role_split_store_ds_half_remote_async(
    ST &dst,
    const cta2_fused_dense_attn_bf_reg &src,
    int peer_rank,
    semaphore &completion
) {
    static_assert(Half == 0 || Half == 1);
    static_assert(ST::rows == 16 && ST::cols == 64);
    using U = typename ST::dtype;
    using U2 = base_types::packing<U>::packed_type;
    static_assert(
        std::is_same_v<U2, typename cta2_fused_dense_attn_bf_reg::dtype>
    );

    const int lane = laneid();
    const int quad_lane = lane & 3;
    const int quad_base = lane & ~3;
    const int row = lane >> 2;
    const uint32_t local_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    const uint32_t local_completion = static_cast<uint32_t>(
        __cvta_generic_to_shared(&completion)
    );
    uint32_t remote_completion;
    asm volatile(
        "mapa.shared::cluster.u32 %0, %1, %2;\n"
        : "=r"(remote_completion)
        : "r"(local_completion), "r"(peer_rank)
    );

    #pragma unroll
    for (int tile_col = 0; tile_col < 4; ++tile_col) {
        const auto &tile = src.tiles[0][Half * 4 + tile_col];
        #pragma unroll
        for (int fragment = 0; fragment < 4; ++fragment) {
            const uint32_t word = *reinterpret_cast<const uint32_t *>(
                &tile.data[fragment]
            );
            const uint32_t word0 = __shfl_sync(
                0xffffffff,
                word,
                quad_base + 0
            );
            const uint32_t word1 = __shfl_sync(
                0xffffffff,
                word,
                quad_base + 1
            );
            const uint32_t word2 = __shfl_sync(
                0xffffffff,
                word,
                quad_base + 2
            );
            const uint32_t word3 = __shfl_sync(
                0xffffffff,
                word,
                quad_base + 3
            );
            if (quad_lane == 0) {
                const int dst_row = row + (fragment & 1) * 8;
                const int dst_col = tile_col * 16 + (fragment >> 1) * 8;
                const uint32_t local_destination = dst.idx(
                    local_base,
                    {dst_row, dst_col}
                );
                uint32_t remote_destination;
                asm volatile(
                    "mapa.shared::cluster.u32 %0, %1, %2;\n"
                    : "=r"(remote_destination)
                    : "r"(local_destination), "r"(peer_rank)
                );
                asm volatile(
                    "st.async.weak.shared::cluster.mbarrier::complete_tx::bytes.v4.b32 "
                    "[%0], {%1, %2, %3, %4}, [%5];\n"
                    :
                    : "r"(remote_destination),
                      "r"(word0),
                      "r"(word1),
                      "r"(word2),
                      "r"(word3),
                      "r"(remote_completion)
                    : "memory"
                );
            }
        }
    }
}

__device__ __forceinline__ void
cta2_role_split_store_peer_bulk_after_cta_fence(
    void *destination,
    void *source,
    uint32_t size_bytes,
    int peer_rank,
    semaphore &completion
) {
    const uint32_t destination_shared =
        static_cast<uint32_t>(__cvta_generic_to_shared(destination));
    const uint32_t source_shared =
        static_cast<uint32_t>(__cvta_generic_to_shared(source));
    const uint32_t completion_shared =
        static_cast<uint32_t>(__cvta_generic_to_shared(&completion));
    uint32_t remote_destination;
    uint32_t remote_completion;
    asm volatile(
        "mapa.shared::cluster.u32 %0, %1, %2;\n"
        : "=r"(remote_destination)
        : "r"(destination_shared), "r"(peer_rank)
    );
    asm volatile(
        "mapa.shared::cluster.u32 %0, %1, %2;\n"
        : "=r"(remote_completion)
        : "r"(completion_shared), "r"(peer_rank)
    );
    asm volatile(
        "cp.async.bulk.shared::cluster.shared::cta.mbarrier::complete_tx::bytes "
        "[%0], [%1], %2, [%3];\n"
        :
        : "r"(remote_destination),
          "r"(source_shared),
          "r"(size_bytes),
          "r"(remote_completion)
        : "memory"
    );
}

#ifndef TK_FA4_BWD_EXP2_ALU_DEGREE
#define TK_FA4_BWD_EXP2_ALU_DEGREE 0
#endif

// Packed-ALU exp2 ported from the retained forward pipeline.  Backward
// converts P to E4M3 immediately, so the degree-2 approximation is evaluated
// at the same pair granularity as the subsequent quantizer and avoids
// serializing every score pair through MUFU.
__device__ __forceinline__ float2
cta2_role_split_exp2_approx_pair(float2 values) {
#if TK_FA4_BWD_EXP2_ALU_DEGREE == 0
    float2 result;
    asm volatile(
        "ex2.approx.ftz.f32 %0, %2;\n\t"
        "ex2.approx.ftz.f32 %1, %3;"
        : "=f"(result.x), "=f"(result.y)
        : "f"(values.x), "f"(values.y)
    );
    return result;
#elif TK_FA4_BWD_EXP2_ALU_DEGREE == 2
    uint32_t result_x;
    uint32_t result_y;
    asm volatile(
        "{\n\t"
        ".reg .f32 f1, f2, f3, f4, f5, f6;\n\t"
        ".reg .b64 l1, l2, l3, l4, l5, l7, l8, l9, l10;\n\t"
        ".reg .s32 r1, r2, r3, r4, r5, r6, r7, r8;\n\t"
        "max.ftz.f32 f1, %2, 0fC2FE0000;\n\t"
        "max.ftz.f32 f2, %3, 0fC2FE0000;\n\t"
        "mov.b64 l1, {f1, f2};\n\t"
        "mov.f32 f3, 0f4B400000;\n\t"
        "mov.b64 l2, {f3, f3};\n\t"
        "add.rm.ftz.f32x2 l7, l1, l2;\n\t"
        "sub.rn.ftz.f32x2 l8, l7, l2;\n\t"
        "sub.rn.ftz.f32x2 l9, l1, l8;\n\t"
        "mov.f32 f6, 0f3EA903CA;\n\t"
        "mov.b64 l5, {f6, f6};\n\t"
        "mov.f32 f5, 0f3F2A70E4;\n\t"
        "mov.b64 l4, {f5, f5};\n\t"
        "mov.f32 f4, 0f3F800000;\n\t"
        "mov.b64 l3, {f4, f4};\n\t"
        "fma.rn.ftz.f32x2 l10, l9, l5, l4;\n\t"
        "fma.rn.ftz.f32x2 l10, l10, l9, l3;\n\t"
        "mov.b64 {r1, r2}, l7;\n\t"
        "mov.b64 {r3, r4}, l10;\n\t"
        "shl.b32 r5, r1, 23;\n\t"
        "add.s32 r7, r5, r3;\n\t"
        "shl.b32 r6, r2, 23;\n\t"
        "add.s32 r8, r6, r4;\n\t"
        "mov.b32 %0, r7;\n\t"
        "mov.b32 %1, r8;\n\t"
        "}\n"
        : "=r"(result_x), "=r"(result_y)
        : "f"(values.x), "f"(values.y)
    );
    return {__uint_as_float(result_x), __uint_as_float(result_y)};
#else
#error "TK_FA4_BWD_EXP2_ALU_DEGREE must be 0 or 2"
#endif
}

__device__ __forceinline__ float cta2_role_split_exp2_approx(float value) {
    float result;
    asm volatile(
        "ex2.approx.ftz.f32 %0, %1;"
        : "=f"(result)
        : "f"(value)
    );
    return result;
}

__device__ __forceinline__ float cta2_role_split_max3_f32(
    float a,
    float b,
    float c
) {
    float result;
    asm volatile(
        "{max.f32 %0, %1, %2, %3;}"
        : "=f"(result)
        : "f"(a), "f"(b), "f"(c)
    );
    return result;
}

__device__ __forceinline__ uint8_t
cta2_role_split_float_to_e8m0_rte(float value) {
    const uint32_t bits = __float_as_uint(value);
    const uint32_t exponent = (bits >> 23) & 0xffu;
    if (!(value > 1e-38f) || exponent == 0xffu) {
        return 0;
    }
    uint32_t rounded = exponent;
    const uint32_t mantissa = bits & 0x7fffffu;
    constexpr uint32_t kHalf = 1u << 22;
    if ((mantissa > kHalf ||
         (mantissa == kHalf && (rounded & 1u))) &&
        rounded < 0xfeu) {
        ++rounded;
    }
    return static_cast<uint8_t>(rounded);
}

__device__ __forceinline__ uint8_t
cta2_role_split_half_abs_bits_to_e8m0_rte(uint32_t bits) {
#if TK_FA4_BWD_PURE_MXFP4_NORMAL_HALF_E8M0_FASTPATH
    const uint32_t rounded_exponent =
        ((bits + 0x1ffu + ((bits >> 10) & 1u)) >> 10) + 112u;
    return static_cast<uint8_t>(rounded_exponent);
#else
    // Positive finite IEEE-half bit patterns preserve numeric ordering.  The
    // E8M0 rounding boundary inside each binade is exactly 1.5, so the half
    // mantissa can be rounded directly without widening the tile maximum to
    // FP32.  Keep the subnormal case exact as well; it is uncommon here but
    // costs only one leading-bit search per 32x32 tile.
    const uint32_t exponent = (bits >> 10) & 0x1fu;
    const uint32_t mantissa = bits & 0x3ffu;
    if (exponent == 0x1fu || (exponent == 0 && mantissa == 0)) {
        return 0;
    }
    if (exponent != 0) {
        uint32_t rounded = exponent + 112u;
        constexpr uint32_t kHalf = 1u << 9;
        if ((mantissa > kHalf ||
             (mantissa == kHalf && (rounded & 1u))) &&
            rounded < 0xfeu) {
            ++rounded;
        }
        return static_cast<uint8_t>(rounded);
    }

    const uint32_t leading_bit = 31u - static_cast<uint32_t>(__clz(mantissa));
    uint32_t rounded = leading_bit + 103u;
    const uint32_t binade = 1u << leading_bit;
    const uint32_t remainder = mantissa - binade;
    const uint32_t midpoint = binade >> 1;
    if (remainder > midpoint ||
        (leading_bit != 0 && remainder == midpoint && (rounded & 1u))) {
        ++rounded;
    }
    return static_cast<uint8_t>(rounded);
#endif
}

__device__ __forceinline__ uint8_t
cta2_role_split_log2_to_e8m0_rte(float log2_value) {
    // P <= 1, so a finite log2(P) cannot overflow E8M0.  Clamp only to
    // keep the floor conversion defined for -inf, then select zero for the
    // original non-finite/underflow inputs.  This keeps scale selection
    // branchless in the repeated N32 producer.
    const uint32_t bits = __float_as_uint(log2_value);
    const bool finite = (bits & 0x7f800000u) != 0x7f800000u;
    const bool in_range = log2_value >= -126.0f;
    const float bounded_log2 = fmaxf(log2_value, -126.0f);
    const int floor_log2 = __float2int_rd(bounded_log2);
    const int exponent = floor_log2 + 127;
    const float fraction =
        bounded_log2 - static_cast<float>(floor_log2);
    constexpr float kLog2OnePointFive = 0.5849625007211562f;
    const bool round_up =
        fraction > kLog2OnePointFive ||
        (fraction == kLog2OnePointFive && (exponent & 1));
    const int rounded_exponent = exponent + static_cast<int>(round_up);
    // This helper is used for a softmax-probability operand.  Quantized QK
    // can overshoot the BF16 LSE slightly, but a probability scale must never
    // exceed one.  Besides avoiding needless range loss, the bound prevents
    // a corrupted/stale positive log value from becoming an enormous E8M0
    // multiplier in dV.
    return static_cast<uint8_t>(
        finite && in_range ? min(rounded_exponent, 127) : 0
    );
}

__device__ __forceinline__ float
cta2_role_split_e8m0_quant_multiplier(uint8_t e8m0) {
    return e8m0 == 0
        ? 0.0f
        : 6.0f * __uint_as_float(
              static_cast<uint32_t>(254 - e8m0) << 23
          );
}

__device__ __forceinline__ float
cta2_role_split_e8m0_quant_multiplier_pow2(uint8_t e8m0) {
    // Normalize the block maximum to 4 instead of the E2M1 endpoint 6.
    // Two such operands give the MMA a power-of-two reconstruction factor
    // of 16, which can be folded into dPsum and the existing dS scale instead
    // of paying a per-element 1/36 correction in the dense kernel.
    return e8m0 == 0
        ? 0.0f
        : 4.0f * __uint_as_float(
              static_cast<uint32_t>(254 - e8m0) << 23
          );
}

__device__ __forceinline__ uint32_t
cta2_role_split_e8m0_quant_multiplier_pow2_half2(uint8_t e8m0) {
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_HALF2_SCALE_BITS
    const uint32_t half_bits = e8m0 == 0
        ? 0
        : (144u - static_cast<uint32_t>(e8m0)) << 10;
    return half_bits | (half_bits << 16);
#else
    const float multiplier =
        cta2_role_split_e8m0_quant_multiplier_pow2(e8m0);
    const half_2 multiplier_half2 =
        __float2half2_rn(multiplier);
    return *reinterpret_cast<const uint32_t *>(&multiplier_half2);
#endif
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_e2m1_8(
    float v0,
    float v1,
    float v2,
    float v3,
    float v4,
    float v5,
    float v6,
    float v7
) {
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b8 byte0;\n"
        ".reg .b8 byte1;\n"
        ".reg .b8 byte2;\n"
        ".reg .b8 byte3;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte0, %2, %1;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte1, %4, %3;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte2, %6, %5;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte3, %8, %7;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "f"(v0), "f"(v1), "f"(v2), "f"(v3),
          "f"(v4), "f"(v5), "f"(v6), "f"(v7)
    );
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_half2_e2m1_8(
    uint32_t h01,
    uint32_t h23,
    uint32_t h45,
    uint32_t h67,
#if TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
    uint32_t multiplier_half2
#else
    float multiplier
#endif
) {
    // Match the forward packer's x2 ILP: widen eight retained half values,
    // scale four pairs at a time, and feed the native E2M1 converters without
    // materializing eight independent C++ float multiply expressions.
    uint32_t packed;
#if TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
    asm volatile(
        "{\n"
        ".reg .b32 scaled01, scaled23, scaled45, scaled67;\n"
        "mul.rn.f16x2 scaled01, %1, %5;\n"
        "mul.rn.f16x2 scaled23, %2, %5;\n"
        "mul.rn.f16x2 scaled45, %3, %5;\n"
        "mul.rn.f16x2 scaled67, %4, %5;\n"
        ".reg .b8 byte0, byte1, byte2, byte3;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte0, scaled01;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte1, scaled23;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte2, scaled45;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte3, scaled67;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "r"(h01), "r"(h23), "r"(h45), "r"(h67),
          "r"(multiplier_half2)
    );
#elif TK_FA4_BWD_PURE_MXFP4_RS_X4_PACK
    asm volatile(
        "{\n"
        ".reg .b16 h0, h1, h2, h3, h4, h5, h6, h7;\n"
        "mov.b32 {h0, h1}, %1;\n"
        "mov.b32 {h2, h3}, %2;\n"
        "mov.b32 {h4, h5}, %3;\n"
        "mov.b32 {h6, h7}, %4;\n"
        ".reg .f32 v0, v1, v2, v3, v4, v5, v6, v7;\n"
        "cvt.f32.f16 v0, h0;\n"
        "cvt.f32.f16 v1, h1;\n"
        "cvt.f32.f16 v2, h2;\n"
        "cvt.f32.f16 v3, h3;\n"
        "cvt.f32.f16 v4, h4;\n"
        "cvt.f32.f16 v5, h5;\n"
        "cvt.f32.f16 v6, h6;\n"
        "cvt.f32.f16 v7, h7;\n"
        ".reg .b64 scale2, v01, v23, v45, v67;\n"
        "mov.b64 scale2, {%5, %5};\n"
        "mov.b64 v01, {v0, v1};\n"
        "mov.b64 v23, {v2, v3};\n"
        "mov.b64 v45, {v4, v5};\n"
        "mov.b64 v67, {v6, v7};\n"
        "mul.f32x2 v01, v01, scale2;\n"
        "mul.f32x2 v23, v23, scale2;\n"
        "mul.f32x2 v45, v45, scale2;\n"
        "mul.f32x2 v67, v67, scale2;\n"
        "mov.b64 {v1, v0}, v01;\n"
        "mov.b64 {v3, v2}, v23;\n"
        "mov.b64 {v5, v4}, v45;\n"
        "mov.b64 {v7, v6}, v67;\n"
        ".reg .b16 quartet0, quartet1;\n"
        "cvt.rs.satfinite.e2m1x4.f32 quartet0, {v2, v3, v0, v1}, %1;\n"
        "cvt.rs.satfinite.e2m1x4.f32 quartet1, {v6, v7, v4, v5}, %3;\n"
        "mov.b32 %0, {quartet0, quartet1};\n"
        "}\n"
        : "=r"(packed)
        : "r"(h01), "r"(h23), "r"(h45), "r"(h67),
          "f"(multiplier)
    );
#else
    asm volatile(
        "{\n"
        ".reg .b16 h0, h1, h2, h3, h4, h5, h6, h7;\n"
        "mov.b32 {h0, h1}, %1;\n"
        "mov.b32 {h2, h3}, %2;\n"
        "mov.b32 {h4, h5}, %3;\n"
        "mov.b32 {h6, h7}, %4;\n"
        ".reg .f32 v0, v1, v2, v3, v4, v5, v6, v7;\n"
        "cvt.f32.f16 v0, h0;\n"
        "cvt.f32.f16 v1, h1;\n"
        "cvt.f32.f16 v2, h2;\n"
        "cvt.f32.f16 v3, h3;\n"
        "cvt.f32.f16 v4, h4;\n"
        "cvt.f32.f16 v5, h5;\n"
        "cvt.f32.f16 v6, h6;\n"
        "cvt.f32.f16 v7, h7;\n"
        ".reg .b64 scale2, v01, v23, v45, v67;\n"
        "mov.b64 scale2, {%5, %5};\n"
        "mov.b64 v01, {v0, v1};\n"
        "mov.b64 v23, {v2, v3};\n"
        "mov.b64 v45, {v4, v5};\n"
        "mov.b64 v67, {v6, v7};\n"
        "mul.f32x2 v01, v01, scale2;\n"
        "mul.f32x2 v23, v23, scale2;\n"
        "mul.f32x2 v45, v45, scale2;\n"
        "mul.f32x2 v67, v67, scale2;\n"
        "mov.b64 {v0, v1}, v01;\n"
        "mov.b64 {v2, v3}, v23;\n"
        "mov.b64 {v4, v5}, v45;\n"
        "mov.b64 {v6, v7}, v67;\n"
        ".reg .b8 byte0, byte1, byte2, byte3;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte0, v1, v0;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte1, v3, v2;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte2, v5, v4;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte3, v7, v6;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "r"(h01), "r"(h23), "r"(h45), "r"(h67),
          "f"(multiplier)
    );
#endif
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_normalized_half2_e2m1_8(
    uint32_t h01,
    uint32_t h23,
    uint32_t h45,
    uint32_t h67
) {
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b8 byte0, byte1, byte2, byte3;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte0, %1;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte1, %2;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte2, %3;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte3, %4;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "r"(h01), "r"(h23), "r"(h45), "r"(h67)
    );
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_half2_e2m1_8_exponent_delta(
    uint32_t h01,
    uint32_t h23,
    uint32_t h45,
    uint32_t h67,
    uint32_t pair_delta
) {
    const uint32_t scaled01 = __vadd2(h01, pair_delta);
    const uint32_t scaled23 = __vadd2(h23, pair_delta);
    const uint32_t scaled45 = __vadd2(h45, pair_delta);
    const uint32_t scaled67 = __vadd2(h67, pair_delta);
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b8 byte0, byte1, byte2, byte3;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte0, %1;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte1, %2;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte2, %3;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte3, %4;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "r"(scaled01), "r"(scaled23), "r"(scaled45), "r"(scaled67)
    );
    return packed;
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_half2_e2m1_8_exponent_scale(
    uint32_t h01,
    uint32_t h23,
    uint32_t h45,
    uint32_t h67,
    uint8_t source_e8m0
) {
    // Scaling the block maximum to four requires 2^(129-source_e8m0).
    // A packed exponent add is conversion-equivalent to the half2 multiply
    // for normal inputs when that delta is 0..12.  In the same range, any
    // zero/subnormal artifact remains strictly below the E2M1 0.25 midpoint.
    const int exponent_delta = 129 - static_cast<int>(source_e8m0);
#if TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
    const uint32_t half_delta = static_cast<uint16_t>(
        exponent_delta * (1 << 10)
    );
    return cta2_role_split_pack_half2_e2m1_8_exponent_delta(
        h01,
        h23,
        h45,
        h67,
        half_delta * 0x00010001u
    );
#else
    if (source_e8m0 >= 117 && source_e8m0 <= 129) {
        const uint32_t half_delta = static_cast<uint16_t>(
            exponent_delta * (1 << 10)
        );
        const uint32_t pair_delta = half_delta * 0x00010001u;
        return cta2_role_split_pack_half2_e2m1_8_exponent_delta(
            h01,
            h23,
            h45,
            h67,
            pair_delta
        );
    }
#if TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
    return cta2_role_split_pack_half2_e2m1_8(
        h01,
        h23,
        h45,
        h67,
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(source_e8m0)
    );
#else
    return cta2_role_split_pack_half2_e2m1_8(
        h01,
        h23,
        h45,
        h67,
        cta2_role_split_e8m0_quant_multiplier_pow2(source_e8m0)
    );
#endif
#endif
}

__device__ __forceinline__ void
cta2_role_split_pack_half2_e2m1_8_dual(
    uint32_t &packed0,
    uint32_t &packed1,
    uint32_t h01_0,
    uint32_t h23_0,
    uint32_t h45_0,
    uint32_t h67_0,
    float multiplier0,
    uint32_t h01_1,
    uint32_t h23_1,
    uint32_t h45_1,
    uint32_t h67_1,
    float multiplier1
) {
    // Process four values from each block at a time.  The second group then
    // overwrites the same eight FP32 temporaries after the first four E2M1
    // nibbles have been captured, bounding live state close to the single-
    // block converter while alternating independent conversion chains.
    asm volatile(
        "{\n"
        ".reg .b16 h00, h01, h02, h03;\n"
        ".reg .b16 h10, h11, h12, h13;\n"
        ".reg .f32 v00, v01, v02, v03;\n"
        ".reg .f32 v10, v11, v12, v13;\n"
        ".reg .b64 scale20, scale21, v0a, v0b, v1a, v1b;\n"
        ".reg .b8 byte00, byte01, byte02, byte03;\n"
        ".reg .b8 byte10, byte11, byte12, byte13;\n"
        "mov.b64 scale20, {%6, %6};\n"
        "mov.b64 scale21, {%11, %11};\n"

        "mov.b32 {h00, h01}, %2;\n"
        "mov.b32 {h02, h03}, %3;\n"
        "mov.b32 {h10, h11}, %7;\n"
        "mov.b32 {h12, h13}, %8;\n"
        "cvt.f32.f16 v00, h00;\n"
        "cvt.f32.f16 v10, h10;\n"
        "cvt.f32.f16 v01, h01;\n"
        "cvt.f32.f16 v11, h11;\n"
        "cvt.f32.f16 v02, h02;\n"
        "cvt.f32.f16 v12, h12;\n"
        "cvt.f32.f16 v03, h03;\n"
        "cvt.f32.f16 v13, h13;\n"
        "mov.b64 v0a, {v00, v01};\n"
        "mov.b64 v1a, {v10, v11};\n"
        "mov.b64 v0b, {v02, v03};\n"
        "mov.b64 v1b, {v12, v13};\n"
        "mul.f32x2 v0a, v0a, scale20;\n"
        "mul.f32x2 v1a, v1a, scale21;\n"
        "mul.f32x2 v0b, v0b, scale20;\n"
        "mul.f32x2 v1b, v1b, scale21;\n"
        "mov.b64 {v00, v01}, v0a;\n"
        "mov.b64 {v10, v11}, v1a;\n"
        "mov.b64 {v02, v03}, v0b;\n"
        "mov.b64 {v12, v13}, v1b;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte00, v01, v00;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte10, v11, v10;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte01, v03, v02;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte11, v13, v12;\n"

        "mov.b32 {h00, h01}, %4;\n"
        "mov.b32 {h02, h03}, %5;\n"
        "mov.b32 {h10, h11}, %9;\n"
        "mov.b32 {h12, h13}, %10;\n"
        "cvt.f32.f16 v00, h00;\n"
        "cvt.f32.f16 v10, h10;\n"
        "cvt.f32.f16 v01, h01;\n"
        "cvt.f32.f16 v11, h11;\n"
        "cvt.f32.f16 v02, h02;\n"
        "cvt.f32.f16 v12, h12;\n"
        "cvt.f32.f16 v03, h03;\n"
        "cvt.f32.f16 v13, h13;\n"
        "mov.b64 v0a, {v00, v01};\n"
        "mov.b64 v1a, {v10, v11};\n"
        "mov.b64 v0b, {v02, v03};\n"
        "mov.b64 v1b, {v12, v13};\n"
        "mul.f32x2 v0a, v0a, scale20;\n"
        "mul.f32x2 v1a, v1a, scale21;\n"
        "mul.f32x2 v0b, v0b, scale20;\n"
        "mul.f32x2 v1b, v1b, scale21;\n"
        "mov.b64 {v00, v01}, v0a;\n"
        "mov.b64 {v10, v11}, v1a;\n"
        "mov.b64 {v02, v03}, v0b;\n"
        "mov.b64 {v12, v13}, v1b;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte02, v01, v00;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte12, v11, v10;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte03, v03, v02;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte13, v13, v12;\n"
        "mov.b32 %0, {byte00, byte01, byte02, byte03};\n"
        "mov.b32 %1, {byte10, byte11, byte12, byte13};\n"
        "}\n"
        : "=r"(packed0), "=r"(packed1)
        : "r"(h01_0), "r"(h23_0), "r"(h45_0), "r"(h67_0),
          "f"(multiplier0),
          "r"(h01_1), "r"(h23_1), "r"(h45_1), "r"(h67_1),
          "f"(multiplier1)
    );
}

__device__ __forceinline__ void
cta2_role_split_pack_half2_e2m1_8_dual_direct(
    uint32_t &packed0,
    uint32_t &packed1,
    uint32_t h01_0,
    uint32_t h23_0,
    uint32_t h45_0,
    uint32_t h67_0,
    uint32_t multiplier_half2_0,
    uint32_t h01_1,
    uint32_t h23_1,
    uint32_t h45_1,
    uint32_t h67_1,
    uint32_t multiplier_half2_1
) {
    // Keep only one scaled half2 pair from each independent N32 stage live.
    // Alternating the stages puts useful work between dependent HMUL2 and
    // F16->E2M1 instructions while preserving exactly the same RN conversion.
    asm volatile(
        "{\n"
        ".reg .b32 scaled0, scaled1;\n"
        ".reg .b8 byte00, byte01, byte02, byte03;\n"
        ".reg .b8 byte10, byte11, byte12, byte13;\n"
        "mul.rn.f16x2 scaled0, %2, %6;\n"
        "mul.rn.f16x2 scaled1, %7, %11;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte00, scaled0;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte10, scaled1;\n"
        "mul.rn.f16x2 scaled0, %3, %6;\n"
        "mul.rn.f16x2 scaled1, %8, %11;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte01, scaled0;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte11, scaled1;\n"
        "mul.rn.f16x2 scaled0, %4, %6;\n"
        "mul.rn.f16x2 scaled1, %9, %11;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte02, scaled0;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte12, scaled1;\n"
        "mul.rn.f16x2 scaled0, %5, %6;\n"
        "mul.rn.f16x2 scaled1, %10, %11;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte03, scaled0;\n"
        "cvt.rn.satfinite.e2m1x2.f16x2 byte13, scaled1;\n"
        "mov.b32 %0, {byte00, byte01, byte02, byte03};\n"
        "mov.b32 %1, {byte10, byte11, byte12, byte13};\n"
        "}\n"
        : "=r"(packed0), "=r"(packed1)
        : "r"(h01_0), "r"(h23_0), "r"(h45_0), "r"(h67_0),
          "r"(multiplier_half2_0),
          "r"(h01_1), "r"(h23_1), "r"(h45_1), "r"(h67_1),
          "r"(multiplier_half2_1)
    );
}

__device__ __forceinline__ uint32_t
cta2_role_split_pack_e2m1_8_pow2(
    uint32_t v0,
    uint32_t v1,
    uint32_t v2,
    uint32_t v3,
    uint32_t v4,
    uint32_t v5,
    uint32_t v6,
    uint32_t v7,
    uint32_t exponent_delta
) {
    uint32_t packed;
    asm volatile(
        "{\n"
        ".reg .b32 scaled0;\n"
        ".reg .b32 scaled1;\n"
        ".reg .b32 scaled2;\n"
        ".reg .b32 scaled3;\n"
        ".reg .b32 scaled4;\n"
        ".reg .b32 scaled5;\n"
        ".reg .b32 scaled6;\n"
        ".reg .b32 scaled7;\n"
        ".reg .b8 byte0;\n"
        ".reg .b8 byte1;\n"
        ".reg .b8 byte2;\n"
        ".reg .b8 byte3;\n"
        "add.u32 scaled0, %1, %9;\n"
        "add.u32 scaled1, %2, %9;\n"
        "add.u32 scaled2, %3, %9;\n"
        "add.u32 scaled3, %4, %9;\n"
        "add.u32 scaled4, %5, %9;\n"
        "add.u32 scaled5, %6, %9;\n"
        "add.u32 scaled6, %7, %9;\n"
        "add.u32 scaled7, %8, %9;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte0, scaled1, scaled0;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte1, scaled3, scaled2;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte2, scaled5, scaled4;\n"
        "cvt.rn.satfinite.e2m1x2.f32 byte3, scaled7, scaled6;\n"
        "mov.b32 %0, {byte0, byte1, byte2, byte3};\n"
        "}\n"
        : "=r"(packed)
        : "r"(v0), "r"(v1), "r"(v2), "r"(v3),
          "r"(v4), "r"(v5), "r"(v6), "r"(v7),
          "r"(exponent_delta)
    );
    return packed;
}

__device__ __forceinline__ void
cta2_role_split_make_native_x32_ds_stage_mxfp4(
    uint32_t (&p_ds)[16],
    const uint32_t (&dp_words)[32],
    const float (&dpsum)[32],
    uint32_t (&packed_ds)[4],
    uint32_t &published_e8m0
) {
    // The retained native-x32 path already holds P*2^8 as E4M3 and receives
    // the power-of-two MXFP4 dP accumulator/dPsum at 2^4.  Form dS*2^12 in
    // half2, choose one scale for the complete 32x32 tile, and reuse that
    // exact payload when transposing dS for dQ.  A tile-wide scale is required
    // for a lossless code transpose: row-varying scales would change meaning
    // when the packed nibbles become reduction-axis values.
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_AMAX
    // dS is already rounded to half2 before it is retained for FP4 packing.
    // Reduce those exact retained values with packed half instructions, then
    // widen only the final pair for the cross-lane reduction.  This follows
    // the forward/GEMM quantizers and avoids expanding four half values to
    // FP32 on every loop iteration solely to compute their maximum.
    half_2 block_amax2 = __float2half2_rn(0.0f);
#else
    float block_amax = 0.0f;
#endif
    #pragma unroll
    for (int word = 7; word >= 0; --word) {
        uint32_t p_half0_bits;
        uint32_t p_half1_bits;
        cta2_role_split_unpack_fp8x4_to_half2(
            p_half0_bits,
            p_half1_bits,
            p_ds[word]
        );
        const half_2 p_half0 =
            *reinterpret_cast<const half_2 *>(&p_half0_bits);
        const half_2 p_half1 =
            *reinterpret_cast<const half_2 *>(&p_half1_bits);
        const int element = 4 * word;
#if TK_FA4_BWD_PURE_MXFP4_PACKED_F32X2_CENTERING
        const uint32_t centered_half0_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words[element + 0],
                dp_words[element + 1],
                dpsum[element + 0],
                dpsum[element + 1]
            );
        const uint32_t centered_half1_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words[element + 2],
                dp_words[element + 3],
                dpsum[element + 2],
                dpsum[element + 3]
            );
#else
        const float2 centered0{
            __uint_as_float(dp_words[element + 0]) - dpsum[element + 0],
            __uint_as_float(dp_words[element + 1]) - dpsum[element + 1]
        };
        const float2 centered1{
            __uint_as_float(dp_words[element + 2]) - dpsum[element + 2],
            __uint_as_float(dp_words[element + 3]) - dpsum[element + 3]
        };
        const uint32_t centered_half0_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered0);
        const uint32_t centered_half1_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered1);
#endif
        const half_2 centered_half0 =
            *reinterpret_cast<const half_2 *>(&centered_half0_bits);
        const half_2 centered_half1 =
            *reinterpret_cast<const half_2 *>(&centered_half1_bits);
        const half_2 ds_half0 = __hmul2(p_half0, centered_half0);
        const half_2 ds_half1 = __hmul2(p_half1, centered_half1);
        p_ds[2 * word + 0] =
            *reinterpret_cast<const uint32_t *>(&ds_half0);
        p_ds[2 * word + 1] =
            *reinterpret_cast<const uint32_t *>(&ds_half1);
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_AMAX
        block_amax2 = __hmax2(block_amax2, __habs2(ds_half0));
        block_amax2 = __hmax2(block_amax2, __habs2(ds_half1));
#else
        const float2 ds0 =
            base_types::convertor<float2, half_2>::convert(ds_half0);
        const float2 ds1 =
            base_types::convertor<float2, half_2>::convert(ds_half1);
        block_amax = fmaxf(
            block_amax,
            fmaxf(
                fmaxf(fabsf(ds0.x), fabsf(ds0.y)),
                fmaxf(fabsf(ds1.x), fabsf(ds1.y))
            )
        );
#endif
    }
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_AMAX
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_E8M0 || \
    TK_FA4_BWD_PURE_MXFP4_REDUX_HALF_AMAX
    const uint32_t block_amax2_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2);
    const uint32_t block_amax_lo = block_amax2_bits & 0xffffu;
    const uint32_t block_amax_hi = block_amax2_bits >> 16;
    uint32_t block_amax_half =
        block_amax_lo > block_amax_hi ? block_amax_lo : block_amax_hi;
#if TK_FA4_BWD_PURE_MXFP4_REDUX_HALF_AMAX
    block_amax_half = __reduce_max_sync(0xffffffffu, block_amax_half);
#else
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        const uint32_t peer = __shfl_xor_sync(
            0xffffffff,
            block_amax_half,
            offset
        );
        block_amax_half =
            block_amax_half > peer ? block_amax_half : peer;
    }
#endif
    const uint8_t source_e8m0 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(block_amax_half);
#else
    const float2 block_amax_pair =
        base_types::convertor<float2, half_2>::convert(block_amax2);
    float block_amax = fmaxf(block_amax_pair.x, block_amax_pair.y);
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        block_amax = fmaxf(
            block_amax,
            __shfl_xor_sync(0xffffffff, block_amax, offset)
        );
    }
    const uint8_t source_e8m0 =
        cta2_role_split_float_to_e8m0_rte(block_amax);
#endif
#else
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        block_amax = fmaxf(
            block_amax,
            __shfl_xor_sync(0xffffffff, block_amax, offset)
        );
    }
    const uint8_t source_e8m0 =
        cta2_role_split_float_to_e8m0_rte(block_amax);
#endif
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
#if TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
    const uint32_t exponent_pair_delta = static_cast<uint16_t>(
        (129 - static_cast<int>(source_e8m0)) * (1 << 10)
    ) * 0x00010001u;
#endif
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
    const uint32_t multiplier_half2 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(source_e8m0);
#else
    const float multiplier =
        cta2_role_split_e8m0_quant_multiplier_pow2(source_e8m0);
#endif
    #pragma unroll
    for (int word = 0; word < 4; ++word) {
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF2_CVT
        packed_ds[word] =
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_delta(
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_scale(
#else
            cta2_role_split_pack_half2_e2m1_8(
#endif
            p_ds[4 * word + 0],
            p_ds[4 * word + 1],
            p_ds[4 * word + 2],
            p_ds[4 * word + 3],
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            exponent_pair_delta
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            source_e8m0
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
            multiplier_half2
#else
            multiplier
#endif
        );
#else
        const half_2 h0 = *reinterpret_cast<const half_2 *>(
            &p_ds[4 * word + 0]
        );
        const half_2 h1 = *reinterpret_cast<const half_2 *>(
            &p_ds[4 * word + 1]
        );
        const half_2 h2 = *reinterpret_cast<const half_2 *>(
            &p_ds[4 * word + 2]
        );
        const half_2 h3 = *reinterpret_cast<const half_2 *>(
            &p_ds[4 * word + 3]
        );
        const float2 v0 =
            base_types::convertor<float2, half_2>::convert(h0);
        const float2 v1 =
            base_types::convertor<float2, half_2>::convert(h1);
        const float2 v2 =
            base_types::convertor<float2, half_2>::convert(h2);
        const float2 v3 =
            base_types::convertor<float2, half_2>::convert(h3);
        packed_ds[word] = cta2_role_split_pack_e2m1_8(
            v0.x * multiplier,
            v0.y * multiplier,
            v1.x * multiplier,
            v1.y * multiplier,
            v2.x * multiplier,
            v2.y * multiplier,
            v3.x * multiplier,
            v3.y * multiplier
        );
#endif
    }
    // Normalization maps the block maximum to four.  Lowering the published
    // E8M0 exponent by two cancels that factor, so the MMA reconstructs the
    // original dS*2^12 value before multiplying compact Q/K.
    published_e8m0 = source_e8m0 > 2 ? source_e8m0 - 2 : 0;
}

__device__ __forceinline__ void
cta2_role_split_make_native_x32_ds_stage_mxfp4_dual(
    uint32_t (&p_ds0)[16],
    const uint32_t (&dp_words0)[32],
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
    const float *dpsum0,
#else
    const float (&dpsum0)[32],
#endif
    uint32_t (&p_ds1)[16],
    const uint32_t (&dp_words1)[32],
    const float *dpsum1,
#if TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P
    uint8_t predicted_source_e8m0_0,
    uint8_t predicted_source_e8m0_1,
#endif
    uint32_t (&packed_ds0)[4],
    uint32_t &published_e8m0_0,
    uint32_t (&packed_ds1)[4],
    uint32_t &published_e8m0_1
) {
    static_assert(TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_AMAX);
    static_assert(TK_FA4_BWD_PURE_MXFP4_PACKED_HALF2_CVT);
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
    static_assert(TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P);
    static_assert(!TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY);
#endif
#if TK_FA4_BWD_PURE_MXFP4_STREAMING_DS_SCALE_BOUNDARY
    static_assert(TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P);
    static_assert(TK_FA4_BWD_PURE_MXFP4_SHARED_DUAL_DS_SCALE);
    static_assert(!TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY);
    // Positive half bit patterns preserve magnitude order.  The E8M0
    // round-to-nearest transition is 1.5*2^e; decrementing the integer
    // threshold for odd exponents folds the ties-to-even case into one
    // packed unsigned-greater-than comparison.
    uint32_t ds_scale_boundary_mask = 0;
    uint32_t ds_scale_boundary_half = predicted_source_e8m0_0 == 0
        ? 0xffffu
        : ((static_cast<uint32_t>(predicted_source_e8m0_0) - 112u) << 10) |
              0x200u;
    ds_scale_boundary_half -=
        static_cast<uint32_t>(predicted_source_e8m0_0 & 1u);
    const uint32_t ds_scale_boundary_pair =
        ds_scale_boundary_half * 0x00010001u;
#endif
#if TK_FA4_BWD_PURE_NVFP4_DS && \
    !TK_FA4_BWD_PURE_NVFP4_DS_REUSE_MX_PREDICTED_SCALE
    half_2 nv_amax2_00 = __float2half2_rn(0.0f);
    half_2 nv_amax2_01 = __float2half2_rn(0.0f);
    half_2 nv_amax2_10 = __float2half2_rn(0.0f);
    half_2 nv_amax2_11 = __float2half2_rn(0.0f);
#endif
#if !TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P || \
    TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY
    half_2 block_amax2_0 = __float2half2_rn(0.0f);
    half_2 block_amax2_1 = __float2half2_rn(0.0f);
#endif
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
    const uint32_t dpsum0_ptr = static_cast<uint32_t>(
        __cvta_generic_to_shared(dpsum0)
    );
#endif
    const uint32_t dpsum1_ptr = static_cast<uint32_t>(
        __cvta_generic_to_shared(dpsum1)
    );
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
    const int exponent_delta0 = predicted_source_e8m0_0 == 0
        ? 0
        : 129 - static_cast<int>(predicted_source_e8m0_0);
    const int exponent_delta1 = predicted_source_e8m0_1 == 0
        ? 0
        : 129 - static_cast<int>(predicted_source_e8m0_1);
    const uint32_t half_delta0 = static_cast<uint16_t>(
        exponent_delta0 * (1 << 10)
    );
    const uint32_t half_delta1 = static_cast<uint16_t>(
        exponent_delta1 * (1 << 10)
    );
    const uint32_t pair_delta0 = half_delta0 * 0x00010001u;
    const uint32_t pair_delta1 = half_delta1 * 0x00010001u;
#endif

    #pragma unroll
    for (int word = 7; word >= 0; --word) {
        const int element = 4 * word;
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
        float4 dpsum0_values;
        move<float4>::lds(
            dpsum0_values,
            dpsum0_ptr + static_cast<uint32_t>(element * sizeof(float))
        );
#endif
        float4 dpsum1_values;
        // Issue the independent stage-1 load before forming stage 0.  Its
        // shared-memory dependency can then mature under stage-0 arithmetic.
        move<float4>::lds(
            dpsum1_values,
            dpsum1_ptr + static_cast<uint32_t>(element * sizeof(float))
        );

        uint32_t p0_half0_bits;
        uint32_t p0_half1_bits;
        cta2_role_split_unpack_fp8x4_to_half2(
            p0_half0_bits,
            p0_half1_bits,
            p_ds0[word]
        );
        const half_2 p0_half0 =
            *reinterpret_cast<const half_2 *>(&p0_half0_bits);
        const half_2 p0_half1 =
            *reinterpret_cast<const half_2 *>(&p0_half1_bits);
#if TK_FA4_BWD_PURE_MXFP4_PACKED_F32X2_CENTERING
        const uint32_t centered0_half0_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words0[element + 0],
                dp_words0[element + 1],
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
                dpsum0_values.x,
                dpsum0_values.y
#else
                dpsum0[element + 0],
                dpsum0[element + 1]
#endif
            );
        const uint32_t centered0_half1_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words0[element + 2],
                dp_words0[element + 3],
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
                dpsum0_values.z,
                dpsum0_values.w
#else
                dpsum0[element + 2],
                dpsum0[element + 3]
#endif
            );
#else
        const float2 centered0_0{
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
            __uint_as_float(dp_words0[element + 0]) - dpsum0_values.x,
            __uint_as_float(dp_words0[element + 1]) - dpsum0_values.y
#else
            __uint_as_float(dp_words0[element + 0]) - dpsum0[element + 0],
            __uint_as_float(dp_words0[element + 1]) - dpsum0[element + 1]
#endif
        };
        const float2 centered0_1{
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
            __uint_as_float(dp_words0[element + 2]) - dpsum0_values.z,
            __uint_as_float(dp_words0[element + 3]) - dpsum0_values.w
#else
            __uint_as_float(dp_words0[element + 2]) - dpsum0[element + 2],
            __uint_as_float(dp_words0[element + 3]) - dpsum0[element + 3]
#endif
        };
        const uint32_t centered0_half0_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered0_0);
        const uint32_t centered0_half1_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered0_1);
#endif
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
        const uint32_t normalized_centered0_half0_bits =
            __vadd2(centered0_half0_bits, pair_delta0);
        const uint32_t normalized_centered0_half1_bits =
            __vadd2(centered0_half1_bits, pair_delta0);
#else
        const uint32_t normalized_centered0_half0_bits =
            centered0_half0_bits;
        const uint32_t normalized_centered0_half1_bits =
            centered0_half1_bits;
#endif
        const half_2 centered0_half0 = *reinterpret_cast<const half_2 *>(
            &normalized_centered0_half0_bits
        );
        const half_2 centered0_half1 = *reinterpret_cast<const half_2 *>(
            &normalized_centered0_half1_bits
        );
        const half_2 ds0_half0 = __hmul2(p0_half0, centered0_half0);
        const half_2 ds0_half1 = __hmul2(p0_half1, centered0_half1);
        p_ds0[2 * word + 0] =
            *reinterpret_cast<const uint32_t *>(&ds0_half0);
        p_ds0[2 * word + 1] =
            *reinterpret_cast<const uint32_t *>(&ds0_half1);
#if TK_FA4_BWD_PURE_NVFP4_DS && \
    !TK_FA4_BWD_PURE_NVFP4_DS_REUSE_MX_PREDICTED_SCALE
        const half_2 ds0_word_amax = __hmax2(
            __habs2(ds0_half0),
            __habs2(ds0_half1)
        );
        if (word < 4) {
            nv_amax2_00 = __hmax2(nv_amax2_00, ds0_word_amax);
        } else {
            nv_amax2_01 = __hmax2(nv_amax2_01, ds0_word_amax);
        }
#endif
#if TK_FA4_BWD_PURE_MXFP4_STREAMING_DS_SCALE_BOUNDARY
        const uint32_t ds0_absmax2 = __vmaxu2(
            p_ds0[2 * word + 0] & 0x7fff7fffu,
            p_ds0[2 * word + 1] & 0x7fff7fffu
        );
        ds_scale_boundary_mask |= __vcmpgtu2(
            ds0_absmax2,
            ds_scale_boundary_pair
        );
#endif
#if !TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P || \
    TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY
#if TK_FA4_BWD_PURE_MXFP4_SAMPLED_DUAL_DS_AMAX
        block_amax2_0 = __hmax2(
            block_amax2_0,
            __habs2((word & 1) ? ds0_half1 : ds0_half0)
        );
#else
        block_amax2_0 = __hmax2(block_amax2_0, __habs2(ds0_half0));
        block_amax2_0 = __hmax2(block_amax2_0, __habs2(ds0_half1));
#endif
#endif

        uint32_t p1_half0_bits;
        uint32_t p1_half1_bits;
        cta2_role_split_unpack_fp8x4_to_half2(
            p1_half0_bits,
            p1_half1_bits,
            p_ds1[word]
        );
        const half_2 p1_half0 =
            *reinterpret_cast<const half_2 *>(&p1_half0_bits);
        const half_2 p1_half1 =
            *reinterpret_cast<const half_2 *>(&p1_half1_bits);
#if TK_FA4_BWD_PURE_MXFP4_PACKED_F32X2_CENTERING
        const uint32_t centered1_half0_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words1[element + 0],
                dp_words1[element + 1],
                dpsum1_values.x,
                dpsum1_values.y
            );
        const uint32_t centered1_half1_bits =
            cta2_role_split_center_f32x2_to_half2(
                dp_words1[element + 2],
                dp_words1[element + 3],
                dpsum1_values.z,
                dpsum1_values.w
            );
#else
        const float2 centered1_0{
            __uint_as_float(dp_words1[element + 0]) - dpsum1_values.x,
            __uint_as_float(dp_words1[element + 1]) - dpsum1_values.y
        };
        const float2 centered1_1{
            __uint_as_float(dp_words1[element + 2]) - dpsum1_values.z,
            __uint_as_float(dp_words1[element + 3]) - dpsum1_values.w
        };
        const uint32_t centered1_half0_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered1_0);
        const uint32_t centered1_half1_bits =
            cta2_role_split_convert_f32_pair_to_half2(centered1_1);
#endif
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
        const uint32_t normalized_centered1_half0_bits =
            __vadd2(centered1_half0_bits, pair_delta1);
        const uint32_t normalized_centered1_half1_bits =
            __vadd2(centered1_half1_bits, pair_delta1);
#else
        const uint32_t normalized_centered1_half0_bits =
            centered1_half0_bits;
        const uint32_t normalized_centered1_half1_bits =
            centered1_half1_bits;
#endif
        const half_2 centered1_half0 = *reinterpret_cast<const half_2 *>(
            &normalized_centered1_half0_bits
        );
        const half_2 centered1_half1 = *reinterpret_cast<const half_2 *>(
            &normalized_centered1_half1_bits
        );
        const half_2 ds1_half0 = __hmul2(p1_half0, centered1_half0);
        const half_2 ds1_half1 = __hmul2(p1_half1, centered1_half1);
        p_ds1[2 * word + 0] =
            *reinterpret_cast<const uint32_t *>(&ds1_half0);
        p_ds1[2 * word + 1] =
            *reinterpret_cast<const uint32_t *>(&ds1_half1);
#if TK_FA4_BWD_PURE_NVFP4_DS && \
    !TK_FA4_BWD_PURE_NVFP4_DS_REUSE_MX_PREDICTED_SCALE
        const half_2 ds1_word_amax = __hmax2(
            __habs2(ds1_half0),
            __habs2(ds1_half1)
        );
        if (word < 4) {
            nv_amax2_10 = __hmax2(nv_amax2_10, ds1_word_amax);
        } else {
            nv_amax2_11 = __hmax2(nv_amax2_11, ds1_word_amax);
        }
#endif
#if TK_FA4_BWD_PURE_MXFP4_STREAMING_DS_SCALE_BOUNDARY
        const uint32_t ds1_absmax2 = __vmaxu2(
            p_ds1[2 * word + 0] & 0x7fff7fffu,
            p_ds1[2 * word + 1] & 0x7fff7fffu
        );
        ds_scale_boundary_mask |= __vcmpgtu2(
            ds1_absmax2,
            ds_scale_boundary_pair
        );
#endif
#if !TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P || \
    TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY
#if TK_FA4_BWD_PURE_MXFP4_SAMPLED_DUAL_DS_AMAX
        block_amax2_1 = __hmax2(
            block_amax2_1,
            __habs2((word & 1) ? ds1_half0 : ds1_half1)
        );
#else
        block_amax2_1 = __hmax2(block_amax2_1, __habs2(ds1_half0));
        block_amax2_1 = __hmax2(block_amax2_1, __habs2(ds1_half1));
#endif
#endif
    }

#if TK_FA4_BWD_PURE_NVFP4_DS
#if TK_FA4_BWD_PURE_NVFP4_DS_REUSE_MX_PREDICTED_SCALE
    static_assert(TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P);
    static_assert(TK_FA4_BWD_PURE_MXFP4_SHARED_DUAL_DS_SCALE);
    static_assert(TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 >= 2);
    static_assert(TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 <= 5);

    // MX normalizes a block maximum S to four and publishes S/4.  NV's
    // output correction divides by G, so publishing S*G/4 produces the same
    // reconstructed dS.  S is a power of two; its E4M3 byte therefore comes
    // directly from the E8M0 exponent without a floating conversion or a
    // reciprocal.  G>=8 also keeps the observed S=2^-10 floor representable.
    constexpr int kNvPredictedScaleExponentShift =
        TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 - 2;
    auto encode_predicted_power2_e4m3 = [](uint8_t source_e8m0) {
        if (source_e8m0 == 0) {
            return static_cast<uint32_t>(0);
        }
        const int exponent =
            static_cast<int>(source_e8m0) - 127 +
            kNvPredictedScaleExponentShift;
        if (exponent < -9) {
            return static_cast<uint32_t>(0);
        }
        if (exponent < -6) {
            return 1u << (exponent + 9);
        }
        if (exponent <= 8) {
            return static_cast<uint32_t>((exponent + 7) << 3);
        }
        return static_cast<uint32_t>(0x7eu);
    };
    const uint32_t predicted_scale0 =
        encode_predicted_power2_e4m3(predicted_source_e8m0_0);
    const uint32_t predicted_scale1 =
        encode_predicted_power2_e4m3(predicted_source_e8m0_1);
    published_e8m0_0 = predicted_scale0 * 0x0101u;
    published_e8m0_1 = predicted_scale1 * 0x0101u;

#if TK_FA4_BWD_PURE_NVFP4_DS_PREDICTED_EXPONENT_PACK
    const uint32_t exponent_pair_delta0 = static_cast<uint16_t>(
        (129 - static_cast<int>(predicted_source_e8m0_0)) * (1 << 10)
    ) * 0x00010001u;
    const uint32_t exponent_pair_delta1 = static_cast<uint16_t>(
        (129 - static_cast<int>(predicted_source_e8m0_1)) * (1 << 10)
    ) * 0x00010001u;
#else
    const uint32_t multiplier0_bits =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            predicted_source_e8m0_0
        );
    const uint32_t multiplier1_bits =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            predicted_source_e8m0_1
        );
#endif
    #pragma unroll
    for (int word = 0; word < 4; ++word) {
        packed_ds0[word] =
#if TK_FA4_BWD_PURE_NVFP4_DS_PREDICTED_EXPONENT_PACK
            predicted_source_e8m0_0 == 0
                ? 0
                : cta2_role_split_pack_half2_e2m1_8_exponent_delta(
#else
            cta2_role_split_pack_half2_e2m1_8(
#endif
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
#if TK_FA4_BWD_PURE_NVFP4_DS_PREDICTED_EXPONENT_PACK
            exponent_pair_delta0
#else
            multiplier0_bits
#endif
        );
        packed_ds1[word] =
#if TK_FA4_BWD_PURE_NVFP4_DS_PREDICTED_EXPONENT_PACK
            predicted_source_e8m0_1 == 0
                ? 0
                : cta2_role_split_pack_half2_e2m1_8_exponent_delta(
#else
            cta2_role_split_pack_half2_e2m1_8(
#endif
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
#if TK_FA4_BWD_PURE_NVFP4_DS_PREDICTED_EXPONENT_PACK
            exponent_pair_delta1
#else
            multiplier1_bits
#endif
        );
    }
#else
    const uint32_t nv_amax2_00_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_00);
    uint32_t nv_amax_half00 = max(
        nv_amax2_00_bits & 0xffffu,
        nv_amax2_00_bits >> 16
    );
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 1
    const uint32_t nv_amax2_01_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_01);
    const uint32_t nv_amax2_10_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_10);
    const uint32_t nv_amax2_11_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_11);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_01_bits & 0xffffu);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_01_bits >> 16);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_10_bits & 0xffffu);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_10_bits >> 16);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_11_bits & 0xffffu);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_11_bits >> 16);
    nv_amax_half00 = __reduce_max_sync(0xffffffffu, nv_amax_half00);
    const uint32_t nv_amax_half01 = nv_amax_half00;
    const uint32_t nv_amax_half10 = nv_amax_half00;
    const uint32_t nv_amax_half11 = nv_amax_half00;
#elif TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 2
    const uint32_t nv_amax2_01_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_01);
    const uint32_t nv_amax2_10_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_10);
    const uint32_t nv_amax2_11_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_11);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_01_bits & 0xffffu);
    nv_amax_half00 = max(nv_amax_half00, nv_amax2_01_bits >> 16);
    uint32_t nv_amax_half10 = max(
        nv_amax2_10_bits & 0xffffu,
        nv_amax2_10_bits >> 16
    );
    nv_amax_half10 = max(nv_amax_half10, nv_amax2_11_bits & 0xffffu);
    nv_amax_half10 = max(nv_amax_half10, nv_amax2_11_bits >> 16);
    nv_amax_half00 = __reduce_max_sync(0xffffffffu, nv_amax_half00);
    nv_amax_half10 = __reduce_max_sync(0xffffffffu, nv_amax_half10);
    const uint32_t nv_amax_half01 = nv_amax_half00;
    const uint32_t nv_amax_half11 = nv_amax_half10;
#else
    const uint32_t nv_amax2_01_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_01);
    const uint32_t nv_amax2_10_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_10);
    const uint32_t nv_amax2_11_bits =
        *reinterpret_cast<const uint32_t *>(&nv_amax2_11);
    uint32_t nv_amax_half01 = max(
        nv_amax2_01_bits & 0xffffu,
        nv_amax2_01_bits >> 16
    );
    uint32_t nv_amax_half10 = max(
        nv_amax2_10_bits & 0xffffu,
        nv_amax2_10_bits >> 16
    );
    uint32_t nv_amax_half11 = max(
        nv_amax2_11_bits & 0xffffu,
        nv_amax2_11_bits >> 16
    );
    nv_amax_half00 = __reduce_max_sync(0xffffffffu, nv_amax_half00);
    nv_amax_half01 = __reduce_max_sync(0xffffffffu, nv_amax_half01);
    nv_amax_half10 = __reduce_max_sync(0xffffffffu, nv_amax_half10);
    nv_amax_half11 = __reduce_max_sync(0xffffffffu, nv_amax_half11);
#endif

#if TK_FA4_BWD_PURE_NVFP4_DS_POWER2_LOCAL_SCALE
    static_assert(TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 >= 2);
    static_assert(TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 <= 5);
    const uint8_t local_source_e8m0_00 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(nv_amax_half00);
    const uint8_t local_source_e8m0_01 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(nv_amax_half01);
    const uint8_t local_source_e8m0_10 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(nv_amax_half10);
    const uint8_t local_source_e8m0_11 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(nv_amax_half11);
    constexpr int kNvLocalScaleExponentShift =
        TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2 - 2;
    auto encode_local_power2_e4m3 = [](uint8_t source_e8m0) {
        if (source_e8m0 == 0) {
            return static_cast<uint32_t>(0);
        }
        const int exponent =
            static_cast<int>(source_e8m0) - 127 +
            kNvLocalScaleExponentShift;
        if (exponent < -9) {
            return static_cast<uint32_t>(0);
        }
        if (exponent < -6) {
            return 1u << (exponent + 9);
        }
        if (exponent <= 8) {
            return static_cast<uint32_t>((exponent + 7) << 3);
        }
        return static_cast<uint32_t>(0x7eu);
    };
    const uint32_t local_scale00 =
        encode_local_power2_e4m3(local_source_e8m0_00);
    const uint32_t local_scale01 =
        encode_local_power2_e4m3(local_source_e8m0_01);
    const uint32_t local_scale10 =
        encode_local_power2_e4m3(local_source_e8m0_10);
    const uint32_t local_scale11 =
        encode_local_power2_e4m3(local_source_e8m0_11);
    published_e8m0_0 = local_scale00 | (local_scale01 << 8);
    published_e8m0_1 = local_scale10 | (local_scale11 << 8);

    const uint32_t local_multiplier00 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            local_source_e8m0_00
        );
    const uint32_t local_multiplier01 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            local_source_e8m0_01
        );
    const uint32_t local_multiplier10 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            local_source_e8m0_10
        );
    const uint32_t local_multiplier11 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(
            local_source_e8m0_11
        );
    #pragma unroll
    for (int word = 0; word < 4; ++word) {
        packed_ds0[word] = cta2_role_split_pack_half2_e2m1_8(
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
            word < 2 ? local_multiplier00 : local_multiplier01
        );
        packed_ds1[word] = cta2_role_split_pack_half2_e2m1_8(
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
            word < 2 ? local_multiplier10 : local_multiplier11
        );
    }
#else
    const uint32_t nv_amax_pair00 =
        nv_amax_half00 | (nv_amax_half00 << 16);
    const uint32_t nv_amax_pair01 =
        nv_amax_half01 | (nv_amax_half01 << 16);
    const uint32_t nv_amax_pair10 =
        nv_amax_half10 | (nv_amax_half10 << 16);
    const uint32_t nv_amax_pair11 =
        nv_amax_half11 | (nv_amax_half11 << 16);
    const float nv_amax00 =
        base_types::convertor<float2, half_2>::convert(
            *reinterpret_cast<const half_2 *>(&nv_amax_pair00)
        ).x;
    const float nv_amax01 =
        base_types::convertor<float2, half_2>::convert(
            *reinterpret_cast<const half_2 *>(&nv_amax_pair01)
        ).x;
    const float nv_amax10 =
        base_types::convertor<float2, half_2>::convert(
            *reinterpret_cast<const half_2 *>(&nv_amax_pair10)
        ).x;
    const float nv_amax11 =
        base_types::convertor<float2, half_2>::convert(
            *reinterpret_cast<const half_2 *>(&nv_amax_pair11)
        ).x;
    constexpr float kNvScaleEncode = static_cast<float>(
        1u << TK_FA4_BWD_PURE_NVFP4_DS_GLOBAL_SCALE_LOG2
    );
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 1
    const fp8e4m3 encoded_scale =
        base_types::convertor<fp8e4m3, float>::convert(
            nv_amax00 * (kNvScaleEncode / 6.0f)
        );
    const uint32_t encoded_scale_bits =
        static_cast<uint32_t>(std::bit_cast<uint8_t>(encoded_scale));
    const float rounded_scale =
        base_types::convertor<float, fp8e4m3>::convert(encoded_scale);
    const uint32_t published_scale_pair = encoded_scale_bits * 0x0101u;
    published_e8m0_0 = published_scale_pair;
    published_e8m0_1 = published_scale_pair;

    const half_2 multiplier = __float2half2_rn(
        rounded_scale > 0.0f ? kNvScaleEncode / rounded_scale : 0.0f
    );
    const uint32_t multiplier_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier);
    const uint32_t multiplier00_bits = multiplier_bits;
    const uint32_t multiplier01_bits = multiplier_bits;
    const uint32_t multiplier10_bits = multiplier_bits;
    const uint32_t multiplier11_bits = multiplier_bits;
#elif TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 2
    const fp8e4m3_2 encoded_scales =
        base_types::convertor<fp8e4m3_2, float2>::convert(
            make_float2(
                nv_amax00 * (kNvScaleEncode / 6.0f),
                nv_amax10 * (kNvScaleEncode / 6.0f)
            )
        );
    const uint32_t encoded_scale_bits =
        static_cast<uint32_t>(std::bit_cast<uint16_t>(encoded_scales));
    const float2 rounded_scales =
        base_types::convertor<float2, fp8e4m3_2>::convert(encoded_scales);
    uint32_t published_scale_pair0 =
        (encoded_scale_bits & 0xffu) * 0x0101u;
    uint32_t published_scale_pair1 =
        ((encoded_scale_bits >> 8) & 0xffu) * 0x0101u;
#if TK_FA4_BWD_PURE_NVFP4_DS_SWAP_K16_SCALE_BYTES
    // Each pair contains duplicate bytes, so the diagnostic swap is a no-op.
#endif
    published_e8m0_0 = published_scale_pair0;
    published_e8m0_1 = published_scale_pair1;

    const half_2 multiplier00 = __float2half2_rn(
        rounded_scales.x > 0.0f ? kNvScaleEncode / rounded_scales.x : 0.0f
    );
    const half_2 multiplier10 = __float2half2_rn(
        rounded_scales.y > 0.0f ? kNvScaleEncode / rounded_scales.y : 0.0f
    );
    const uint32_t multiplier00_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier00);
    const uint32_t multiplier01_bits = multiplier00_bits;
    const uint32_t multiplier10_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier10);
    const uint32_t multiplier11_bits = multiplier10_bits;
#else
    const fp8e4m3_4 encoded_scales =
        base_types::convertor<fp8e4m3_4, float4>::convert(
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 1
            make_float4(
                fmaxf(fmaxf(nv_amax00, nv_amax01),
                      fmaxf(nv_amax10, nv_amax11)) *
                    (kNvScaleEncode / 6.0f),
                fmaxf(fmaxf(nv_amax00, nv_amax01),
                      fmaxf(nv_amax10, nv_amax11)) *
                    (kNvScaleEncode / 6.0f),
                fmaxf(fmaxf(nv_amax00, nv_amax01),
                      fmaxf(nv_amax10, nv_amax11)) *
                    (kNvScaleEncode / 6.0f),
                fmaxf(fmaxf(nv_amax00, nv_amax01),
                      fmaxf(nv_amax10, nv_amax11)) *
                    (kNvScaleEncode / 6.0f)
            )
#elif TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION == 2
            make_float4(
                fmaxf(nv_amax00, nv_amax01) * (kNvScaleEncode / 6.0f),
                fmaxf(nv_amax00, nv_amax01) * (kNvScaleEncode / 6.0f),
                fmaxf(nv_amax10, nv_amax11) * (kNvScaleEncode / 6.0f),
                fmaxf(nv_amax10, nv_amax11) * (kNvScaleEncode / 6.0f)
            )
#else
            make_float4(
                nv_amax00 * (kNvScaleEncode / 6.0f),
                nv_amax01 * (kNvScaleEncode / 6.0f),
                nv_amax10 * (kNvScaleEncode / 6.0f),
                nv_amax11 * (kNvScaleEncode / 6.0f)
            )
#endif
        );
    const uint32_t encoded_scale_bits =
        std::bit_cast<uint32_t>(encoded_scales);
    const float4 rounded_scales =
        base_types::convertor<float4, fp8e4m3_4>::convert(encoded_scales);
    uint32_t published_scale_pair0 = encoded_scale_bits & 0xffffu;
    uint32_t published_scale_pair1 = encoded_scale_bits >> 16;
#if TK_FA4_BWD_PURE_NVFP4_DS_SWAP_K16_SCALE_BYTES
    published_scale_pair0 =
        ((published_scale_pair0 >> 8) | (published_scale_pair0 << 8)) &
        0xffffu;
    published_scale_pair1 =
        ((published_scale_pair1 >> 8) | (published_scale_pair1 << 8)) &
        0xffffu;
#endif
    published_e8m0_0 = published_scale_pair0;
    published_e8m0_1 = published_scale_pair1;

    const half_2 multiplier00 = __float2half2_rn(
        rounded_scales.x > 0.0f ? kNvScaleEncode / rounded_scales.x : 0.0f
    );
    const half_2 multiplier01 = __float2half2_rn(
        rounded_scales.y > 0.0f ? kNvScaleEncode / rounded_scales.y : 0.0f
    );
    const half_2 multiplier10 = __float2half2_rn(
        rounded_scales.z > 0.0f ? kNvScaleEncode / rounded_scales.z : 0.0f
    );
    const half_2 multiplier11 = __float2half2_rn(
        rounded_scales.w > 0.0f ? kNvScaleEncode / rounded_scales.w : 0.0f
    );
    const uint32_t multiplier00_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier00);
    const uint32_t multiplier01_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier01);
    const uint32_t multiplier10_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier10);
    const uint32_t multiplier11_bits =
        *reinterpret_cast<const uint32_t *>(&multiplier11);
#endif
    #pragma unroll
    for (int word = 0; word < 4; ++word) {
        packed_ds0[word] = cta2_role_split_pack_half2_e2m1_8(
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
            word < 2 ? multiplier00_bits : multiplier01_bits
        );
        packed_ds1[word] = cta2_role_split_pack_half2_e2m1_8(
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
            word < 2 ? multiplier10_bits : multiplier11_bits
        );
    }
#endif
#endif
#else
#if TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P
    uint8_t source_e8m0_0 = predicted_source_e8m0_0;
    uint8_t source_e8m0_1 = predicted_source_e8m0_1;
#if TK_FA4_BWD_PURE_MXFP4_STREAMING_DS_SCALE_BOUNDARY
    const uint32_t tile_round_up_mask = __reduce_or_sync(
        0xffffffffu,
        ds_scale_boundary_mask
    );
    const uint32_t tile_round_up = tile_round_up_mask != 0;
    source_e8m0_0 = static_cast<uint8_t>(
        min(
            static_cast<uint32_t>(source_e8m0_0) + tile_round_up,
            0xfeu
        )
    );
    source_e8m0_1 = source_e8m0_0;
#endif
#if TK_FA4_BWD_PURE_MXFP4_ADAPTIVE_DS_SCALE_BOUNDARY
    const uint32_t block_amax2_0_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2_0);
    const uint32_t block_amax2_1_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2_1);
    const uint32_t lane_amax_half0 = max(
        block_amax2_0_bits & 0xffffu,
        block_amax2_0_bits >> 16
    );
    const uint32_t lane_amax_half1 = max(
        block_amax2_1_bits & 0xffffu,
        block_amax2_1_bits >> 16
    );
    // The E8M0 boundary from exponent e to e+1 is exactly
    // 1.5 * 2^(e-127).  For this kernel's normal half range that value has
    // half exponent e-112 and mantissa 0x200.  Match the exact converter's
    // ties-to-even rule, then combine both stages' decisions in one vote.
    const uint32_t boundary_half0 = source_e8m0_0 == 0
        ? 0xffffffffu
        : ((static_cast<uint32_t>(source_e8m0_0) - 112u) << 10) |
              0x200u;
    const uint32_t boundary_half1 = source_e8m0_1 == 0
        ? 0xffffffffu
        : ((static_cast<uint32_t>(source_e8m0_1) - 112u) << 10) |
              0x200u;
    const uint32_t local_round_up0 =
        lane_amax_half0 > boundary_half0 ||
        (lane_amax_half0 == boundary_half0 && (source_e8m0_0 & 1u));
    const uint32_t local_round_up1 =
        lane_amax_half1 > boundary_half1 ||
        (lane_amax_half1 == boundary_half1 && (source_e8m0_1 & 1u));
    const uint32_t tile_round_up = __reduce_or_sync(
        0xffffffffu,
        local_round_up0 | (local_round_up1 << 1)
    );
    source_e8m0_0 = static_cast<uint8_t>(
        static_cast<uint32_t>(source_e8m0_0) + (tile_round_up & 1u)
    );
    source_e8m0_1 = static_cast<uint8_t>(
        static_cast<uint32_t>(source_e8m0_1) +
        ((tile_round_up >> 1) & 1u)
    );
#endif
#else
#if TK_FA4_BWD_PURE_MXFP4_SHARED_DUAL_DS_SCALE
#if TK_FA4_BWD_PURE_MXFP4_SAMPLED_DUAL_DS_AMAX
    const half_2 block_amax2 = __hmax2(block_amax2_0, block_amax2_1);
    const uint32_t block_amax2_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2);
#else
    const half_2 block_amax2 = __hmax2(block_amax2_0, block_amax2_1);
    const uint32_t block_amax2_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2);
#endif
    uint32_t block_amax_half = max(
        block_amax2_bits & 0xffffu,
        block_amax2_bits >> 16
    );
    block_amax_half = __reduce_max_sync(
        0xffffffffu,
        block_amax_half
    );
    const uint8_t sampled_source_e8m0 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(block_amax_half);
#if TK_FA4_BWD_PURE_MXFP4_SAMPLED_DUAL_DS_AMAX
    const uint8_t shared_source_e8m0 = static_cast<uint8_t>(
        min(
            static_cast<uint32_t>(sampled_source_e8m0) +
                TK_FA4_BWD_PURE_MXFP4_SAMPLED_DUAL_DS_AMAX_MARGIN,
            0xfeu
        )
    );
#else
    const uint8_t shared_source_e8m0 = sampled_source_e8m0;
#endif
    const uint8_t source_e8m0_0 = shared_source_e8m0;
    const uint8_t source_e8m0_1 = shared_source_e8m0;
#else
#if TK_FA4_BWD_PURE_MXFP4_PACKED_HALF_E8M0 || \
    TK_FA4_BWD_PURE_MXFP4_REDUX_HALF_AMAX
    const uint32_t block_amax2_0_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2_0);
    const uint32_t block_amax2_1_bits =
        *reinterpret_cast<const uint32_t *>(&block_amax2_1);
    uint32_t block_amax_half0 = max(
        block_amax2_0_bits & 0xffffu,
        block_amax2_0_bits >> 16
    );
    uint32_t block_amax_half1 = max(
        block_amax2_1_bits & 0xffffu,
        block_amax2_1_bits >> 16
    );
#if TK_FA4_BWD_PURE_MXFP4_REDUX_HALF_AMAX
    block_amax_half0 = __reduce_max_sync(0xffffffffu, block_amax_half0);
    block_amax_half1 = __reduce_max_sync(0xffffffffu, block_amax_half1);
#else
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        const uint32_t peer0 = __shfl_xor_sync(
            0xffffffff,
            block_amax_half0,
            offset
        );
        const uint32_t peer1 = __shfl_xor_sync(
            0xffffffff,
            block_amax_half1,
            offset
        );
        block_amax_half0 = max(block_amax_half0, peer0);
        block_amax_half1 = max(block_amax_half1, peer1);
    }
#endif
    const uint8_t source_e8m0_0 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(block_amax_half0);
    const uint8_t source_e8m0_1 =
        cta2_role_split_half_abs_bits_to_e8m0_rte(block_amax_half1);
#else
    const float2 block_amax_pair0 =
        base_types::convertor<float2, half_2>::convert(block_amax2_0);
    const float2 block_amax_pair1 =
        base_types::convertor<float2, half_2>::convert(block_amax2_1);
    float block_amax0 = fmaxf(block_amax_pair0.x, block_amax_pair0.y);
    float block_amax1 = fmaxf(block_amax_pair1.x, block_amax_pair1.y);
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        const float peer0 = __shfl_xor_sync(
            0xffffffff,
            block_amax0,
            offset
        );
        const float peer1 = __shfl_xor_sync(
            0xffffffff,
            block_amax1,
            offset
        );
        block_amax0 = fmaxf(block_amax0, peer0);
        block_amax1 = fmaxf(block_amax1, peer1);
    }
    const uint8_t source_e8m0_0 =
        cta2_role_split_float_to_e8m0_rte(block_amax0);
    const uint8_t source_e8m0_1 =
        cta2_role_split_float_to_e8m0_rte(block_amax1);
#endif
#endif
#endif
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
#if TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
    const uint32_t exponent_pair_delta0 = static_cast<uint16_t>(
        (129 - static_cast<int>(source_e8m0_0)) * (1 << 10)
    ) * 0x00010001u;
    const uint32_t exponent_pair_delta1 = static_cast<uint16_t>(
        (129 - static_cast<int>(source_e8m0_1)) * (1 << 10)
    ) * 0x00010001u;
#endif
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
    const uint32_t multiplier_half2_0 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(source_e8m0_0);
    const uint32_t multiplier_half2_1 =
        cta2_role_split_e8m0_quant_multiplier_pow2_half2(source_e8m0_1);
#else
    const float multiplier0 =
        cta2_role_split_e8m0_quant_multiplier_pow2(source_e8m0_0);
    const float multiplier1 =
        cta2_role_split_e8m0_quant_multiplier_pow2(source_e8m0_1);
#endif
    #pragma unroll
    for (int word = 0; word < 4; ++word) {
#if TK_FA4_BWD_PURE_MXFP4_FUSE_PREDICTED_DS_SCALE_INTO_CENTERED_DP
        packed_ds0[word] = cta2_role_split_pack_normalized_half2_e2m1_8(
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3]
        );
        packed_ds1[word] = cta2_role_split_pack_normalized_half2_e2m1_8(
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3]
        );
#else
#if TK_FA4_BWD_PURE_MXFP4_INTERLEAVED_DUAL_E2M1_PACK && \
    TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE && \
    !TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
        cta2_role_split_pack_half2_e2m1_8_dual_direct(
            packed_ds0[word],
            packed_ds1[word],
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
            multiplier_half2_0,
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
            multiplier_half2_1
        );
#elif TK_FA4_BWD_PURE_MXFP4_INTERLEAVED_DUAL_E2M1_PACK && \
    !TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
        cta2_role_split_pack_half2_e2m1_8_dual(
            packed_ds0[word],
            packed_ds1[word],
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
            multiplier0,
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
            multiplier1
        );
#else
        packed_ds0[word] =
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_delta(
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_scale(
#else
            cta2_role_split_pack_half2_e2m1_8(
#endif
            p_ds0[4 * word + 0],
            p_ds0[4 * word + 1],
            p_ds0[4 * word + 2],
            p_ds0[4 * word + 3],
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            exponent_pair_delta0
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            source_e8m0_0
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
            multiplier_half2_0
#else
            multiplier0
#endif
        );
        packed_ds1[word] =
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_delta(
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            cta2_role_split_pack_half2_e2m1_8_exponent_scale(
#else
            cta2_role_split_pack_half2_e2m1_8(
#endif
            p_ds1[4 * word + 0],
            p_ds1[4 * word + 1],
            p_ds1[4 * word + 2],
            p_ds1[4 * word + 3],
#if TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE && \
    TK_FA4_BWD_PURE_MXFP4_UNCHECKED_HALF2_EXPONENT_SCALE
            exponent_pair_delta1
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_EXPONENT_SCALE
            source_e8m0_1
#elif TK_FA4_BWD_PURE_MXFP4_HALF2_PRE_SCALE
            multiplier_half2_1
#else
            multiplier1
#endif
        );
#endif
#endif
    }
    published_e8m0_0 = source_e8m0_0 > 2 ? source_e8m0_0 - 2 : 0;
    published_e8m0_1 = source_e8m0_1 > 2 ? source_e8m0_1 - 2 : 0;
#endif
}

template <ducks::st::all Src, ducks::st::all Dst>
__device__ __forceinline__ void
cta2_role_split_transpose_mxfp4_x32(
    Dst &dst,
    const Src &src,
    int src_row_base,
    int src_logical_col_base,
    int dst_row_base,
    int dst_logical_col_base
) {
    static_assert(std::is_same_v<typename Src::dtype, fp4e2m1_2>);
    static_assert(std::is_same_v<typename Dst::dtype, fp4e2m1_2>);
    const uint32_t src_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&src.data[0])
    );
    const uint32_t dst_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );
    const int query_in_block = laneid();
    const int src_packed_col =
        (src_logical_col_base + query_in_block) / 2;
    const int nibble_shift = (query_in_block & 1) * 4;
    uint32_t words[4] = {0, 0, 0, 0};
    #pragma unroll
    for (int packed_key = 0; packed_key < 16; ++packed_key) {
        uint32_t row0_byte;
        uint32_t row1_byte;
        const uint32_t row0_address = src.idx(
            src_base,
            {src_row_base + 2 * packed_key + 0, src_packed_col}
        );
        const uint32_t row1_address = src.idx(
            src_base,
            {src_row_base + 2 * packed_key + 1, src_packed_col}
        );
        asm volatile(
            "ld.shared.u8 %0, [%2];\n"
            "ld.shared.u8 %1, [%3];\n"
            : "=r"(row0_byte), "=r"(row1_byte)
            : "r"(row0_address), "r"(row1_address)
            : "memory"
        );
        const uint32_t packed =
            ((row0_byte >> nibble_shift) & 0x0fu) |
            (((row1_byte >> nibble_shift) & 0x0fu) << 4);
        words[packed_key >> 2] |= packed << (8 * (packed_key & 3));
    }
    const uint32_t dst_address = dst.idx(
        dst_base,
        {
            dst_row_base + query_in_block,
            dst_logical_col_base / 2
        }
    );
    asm volatile(
        "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
        :: "r"(dst_address),
           "r"(words[0]), "r"(words[1]),
           "r"(words[2]), "r"(words[3])
        : "memory"
    );
}

__device__ __forceinline__ uint32_t
cta2_role_split_transpose_mxfp4_8x8_nibbles(uint32_t value) {
    const int lane_in_eight = laneid() & 7;
    uint32_t peer = __shfl_xor_sync(0xffffffff, value, 1, 8);
    value = (lane_in_eight & 1)
        ? (value & 0xf0f0f0f0u) | ((peer & 0xf0f0f0f0u) >> 4)
        : (value & 0x0f0f0f0fu) | ((peer & 0x0f0f0f0fu) << 4);
    peer = __shfl_xor_sync(0xffffffff, value, 2, 8);
    value = (lane_in_eight & 2)
        ? (value & 0xff00ff00u) | ((peer & 0xff00ff00u) >> 8)
        : (value & 0x00ff00ffu) | ((peer & 0x00ff00ffu) << 8);
    peer = __shfl_xor_sync(0xffffffff, value, 4, 8);
    return (lane_in_eight & 4)
        ? (value & 0xffff0000u) | ((peer & 0xffff0000u) >> 16)
        : (value & 0x0000ffffu) | ((peer & 0x0000ffffu) << 16);
}

__device__ __forceinline__ void
cta2_role_split_transpose_mxfp4_8x8_nibbles_dual(
    uint32_t &local,
    uint32_t &peer_value
) {
    const int lane_in_eight = laneid() & 7;
    uint32_t local_exchange =
        __shfl_xor_sync(0xffffffff, local, 1, 8);
    uint32_t peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 1, 8);
    local = (lane_in_eight & 1)
        ? (local & 0xf0f0f0f0u) |
              ((local_exchange & 0xf0f0f0f0u) >> 4)
        : (local & 0x0f0f0f0fu) |
              ((local_exchange & 0x0f0f0f0fu) << 4);
    peer_value = (lane_in_eight & 1)
        ? (peer_value & 0xf0f0f0f0u) |
              ((peer_exchange & 0xf0f0f0f0u) >> 4)
        : (peer_value & 0x0f0f0f0fu) |
              ((peer_exchange & 0x0f0f0f0fu) << 4);

    local_exchange = __shfl_xor_sync(0xffffffff, local, 2, 8);
    peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 2, 8);
    local = (lane_in_eight & 2)
        ? (local & 0xff00ff00u) |
              ((local_exchange & 0xff00ff00u) >> 8)
        : (local & 0x00ff00ffu) |
              ((local_exchange & 0x00ff00ffu) << 8);
    peer_value = (lane_in_eight & 2)
        ? (peer_value & 0xff00ff00u) |
              ((peer_exchange & 0xff00ff00u) >> 8)
        : (peer_value & 0x00ff00ffu) |
              ((peer_exchange & 0x00ff00ffu) << 8);

    local_exchange = __shfl_xor_sync(0xffffffff, local, 4, 8);
    peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 4, 8);
    local = (lane_in_eight & 4)
        ? (local & 0xffff0000u) |
              ((local_exchange & 0xffff0000u) >> 16)
        : (local & 0x0000ffffu) |
              ((local_exchange & 0x0000ffffu) << 16);
    peer_value = (lane_in_eight & 4)
        ? (peer_value & 0xffff0000u) |
              ((peer_exchange & 0xffff0000u) >> 16)
        : (peer_value & 0x0000ffffu) |
              ((peer_exchange & 0x0000ffffu) << 16);
}

__device__ __forceinline__ void
cta2_role_split_transpose_mxfp4_8x8_nibbles_dual_prmt(
    uint32_t &local,
    uint32_t &peer_value,
    uint32_t nibble_shift,
    uint32_t nibble_keep_mask,
    uint32_t byte_selector,
    uint32_t half_selector
) {
    uint32_t local_exchange =
        __shfl_xor_sync(0xffffffff, local, 1, 8);
    uint32_t peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 1, 8);
    const uint32_t local_rotated = __funnelshift_r(
        local_exchange,
        local_exchange,
        nibble_shift
    );
    const uint32_t peer_rotated = __funnelshift_r(
        peer_exchange,
        peer_exchange,
        nibble_shift
    );
    local = (local & nibble_keep_mask) |
        (local_rotated & ~nibble_keep_mask);
    peer_value = (peer_value & nibble_keep_mask) |
        (peer_rotated & ~nibble_keep_mask);

    local_exchange = __shfl_xor_sync(0xffffffff, local, 2, 8);
    peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 2, 8);
    local = __byte_perm(local, local_exchange, byte_selector);
    peer_value = __byte_perm(peer_value, peer_exchange, byte_selector);

    local_exchange = __shfl_xor_sync(0xffffffff, local, 4, 8);
    peer_exchange =
        __shfl_xor_sync(0xffffffff, peer_value, 4, 8);
    local = __byte_perm(local, local_exchange, half_selector);
    peer_value = __byte_perm(peer_value, peer_exchange, half_selector);
}

template <int Delta>
__device__ __forceinline__ uint32_t
cta2_role_split_shfl_xor_width4(uint32_t value) {
    static_assert(Delta == 1 || Delta == 2);
    uint32_t result;
    asm volatile(
        "shfl.sync.bfly.b32 %0, %1, %2, 0x1c1f, 0xffffffff;\n"
        : "=r"(result)
        : "r"(value), "n"(Delta)
    );
    return result;
}

template <ducks::st::all LocalDst, ducks::st::all PeerDst>
__device__ __forceinline__ void
cta2_role_split_transpose_mxfp4_x32_quartered_registers_dual(
    LocalDst &local_dst,
    PeerDst &peer_dst,
    const uint32_t (&stage0_native_words)[4],
    const uint32_t (&stage1_native_words)[4],
    bool stage0_is_local,
    int dst_row_base,
    int local_dst_logical_col_base,
    int peer_dst_logical_col_base
) {
    static_assert(std::is_same_v<typename LocalDst::dtype, fp4e2m1_2>);
    static_assert(std::is_same_v<typename PeerDst::dtype, fp4e2m1_2>);
    const int lane = laneid();
    uint32_t local_words[4];
    uint32_t peer_words[4];

#if TK_FA4_BWD_PURE_MXFP4_SKIP_QUARTER_TRANSPOSE_CEILING
    const uint32_t local_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&local_dst.data[0])
    );
    const uint32_t peer_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&peer_dst.data[0])
    );
    const uint32_t local_address = local_dst.idx(
        local_base,
        {dst_row_base + lane, local_dst_logical_col_base / 2}
    );
    const uint32_t peer_address = peer_dst.idx(
        peer_base,
        {dst_row_base + lane, peer_dst_logical_col_base / 2}
    );
    const uint32_t stage0_address =
        stage0_is_local ? local_address : peer_address;
    const uint32_t stage1_address =
        stage0_is_local ? peer_address : local_address;
    asm volatile(
        "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
        "st.shared.v4.b32 [%5], {%6, %7, %8, %9};\n"
        :: "r"(stage0_address),
           "r"(stage0_native_words[0]), "r"(stage0_native_words[1]),
           "r"(stage0_native_words[2]), "r"(stage0_native_words[3]),
           "r"(stage1_address),
           "r"(stage1_native_words[0]), "r"(stage1_native_words[1]),
           "r"(stage1_native_words[2]), "r"(stage1_native_words[3])
        : "memory"
    );
#elif TK_FA4_BWD_PURE_MXFP4_B8_STMATRIX_TRANSPOSE || \
      TK_FA4_BWD_PURE_MXFP4_B16_STMATRIX_TRANSPOSE
    const uint32_t nibble_shift = (lane & 1) ? 4u : 28u;
    const uint32_t nibble_keep_mask =
        (lane & 1) ? 0xf0f0f0f0u : 0x0f0f0f0fu;
#if TK_FA4_BWD_PURE_MXFP4_B8_STMATRIX_TRANSPOSE
    // Stage 1 exchanges K bit 0 with query bit 0 and forms four packed-byte
    // pairs.  The B8 matrix store already routes two more coordinate bits;
    // only the lane-bit-1 / halfword-bit exchange remains in registers.
    const uint32_t half_selector =
        (lane & 2) ? 0x3276u : 0x5410u;
    #pragma unroll
    for (int query_quarter = 0; query_quarter < 4; ++query_quarter) {
        uint32_t local = stage0_native_words[query_quarter];
        uint32_t peer_value = stage1_native_words[query_quarter];
        uint32_t local_exchange =
            cta2_role_split_shfl_xor_width4<1>(local);
        uint32_t peer_exchange =
            cta2_role_split_shfl_xor_width4<1>(peer_value);
        const uint32_t local_rotated = __funnelshift_r(
            local_exchange,
            local_exchange,
            nibble_shift
        );
        const uint32_t peer_rotated = __funnelshift_r(
            peer_exchange,
            peer_exchange,
            nibble_shift
        );
        local = (local & nibble_keep_mask) |
            (local_rotated & ~nibble_keep_mask);
        peer_value = (peer_value & nibble_keep_mask) |
            (peer_rotated & ~nibble_keep_mask);

        local_exchange = cta2_role_split_shfl_xor_width4<2>(local);
        peer_exchange = cta2_role_split_shfl_xor_width4<2>(peer_value);
        local_words[query_quarter] = __byte_perm(
            local,
            local_exchange,
            half_selector
        );
        peer_words[query_quarter] = __byte_perm(
            peer_value,
            peer_exchange,
            half_selector
        );
    }
#else
    const uint32_t byte0_selector =
        (lane & 1) ? 0x3715u : 0x6240u;
    // The B16 transpose consumes halfwords in source-lane order 0,2,1,3.
    // Fold that permutation into the second PRMT selector.
    const uint32_t byte1_selector =
        (lane & 2) ? 0x3726u : 0x5140u;

    // Keep each independent query quarter together, but encode the width-4
    // butterfly directly.  The intrinsic otherwise materializes a source-lane
    // index and lowers this fixed exchange to SHFL.IDX.
    #pragma unroll
    for (int query_quarter = 0; query_quarter < 4; ++query_quarter) {
        uint32_t local = stage0_native_words[query_quarter];
        uint32_t peer_value = stage1_native_words[query_quarter];
#if TK_FA4_BWD_PURE_MXFP4_QUARTER_TRANSPOSE_STAGES >= 1
        uint32_t local_exchange =
            cta2_role_split_shfl_xor_width4<1>(local);
        uint32_t peer_exchange =
            cta2_role_split_shfl_xor_width4<1>(peer_value);
        const uint32_t local_rotated = __funnelshift_r(
            local_exchange,
            local_exchange,
            nibble_shift
        );
        const uint32_t peer_rotated = __funnelshift_r(
            peer_exchange,
            peer_exchange,
            nibble_shift
        );
        local = (local & nibble_keep_mask) |
            (local_rotated & ~nibble_keep_mask);
        peer_value = (peer_value & nibble_keep_mask) |
            (peer_rotated & ~nibble_keep_mask);
#endif

#if TK_FA4_BWD_PURE_MXFP4_QUARTER_TRANSPOSE_STAGES >= 2
        local_exchange = cta2_role_split_shfl_xor_width4<1>(local);
        peer_exchange = cta2_role_split_shfl_xor_width4<1>(peer_value);
        local = __byte_perm(local, local_exchange, byte0_selector);
        peer_value = __byte_perm(
            peer_value,
            peer_exchange,
            byte0_selector
        );
#endif

#if TK_FA4_BWD_PURE_MXFP4_QUARTER_TRANSPOSE_STAGES >= 3
        local_exchange = cta2_role_split_shfl_xor_width4<2>(local);
        peer_exchange = cta2_role_split_shfl_xor_width4<2>(peer_value);
        local = __byte_perm(
            local,
            local_exchange,
            byte1_selector
        );
        peer_value = __byte_perm(
            peer_value,
            peer_exchange,
            byte1_selector
        );
#endif
        local_words[query_quarter] = local;
        peer_words[query_quarter] = peer_value;
    }
#endif

    const uint32_t local_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&local_dst.data[0])
    );
    const uint32_t peer_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&peer_dst.data[0])
    );
    // B8's source-column order reverses the two low query bits.  Redirect its
    // eight row addresses once per store instead of permuting every payload.
    const int matrix_store_lane =
#if TK_FA4_BWD_PURE_MXFP4_B8_STMATRIX_TRANSPOSE
        (lane & ~3) | ((lane & 1) << 1) | ((lane & 2) >> 1);
#else
        lane;
#endif
    const uint32_t local_address = local_dst.idx(
        local_base,
        {dst_row_base + matrix_store_lane, local_dst_logical_col_base / 2}
    );
    const uint32_t peer_address = peer_dst.idx(
        peer_base,
        {dst_row_base + matrix_store_lane, peer_dst_logical_col_base / 2}
    );
    const uint32_t stage0_address =
        stage0_is_local ? local_address : peer_address;
    const uint32_t stage1_address =
        stage0_is_local ? peer_address : local_address;
#if TK_FA4_BWD_PURE_MXFP4_B8_STMATRIX_TRANSPOSE
    asm volatile(
        "stmatrix.sync.aligned.m16n8.x4.trans.shared::cta.b8 "
        "[%0], {%1, %2, %3, %4};\n"
        "stmatrix.sync.aligned.m16n8.x4.trans.shared::cta.b8 "
        "[%5], {%6, %7, %8, %9};\n"
#else
    asm volatile(
        "stmatrix.sync.aligned.x4.trans.m8n8.shared.b16 "
        "[%0], {%1, %2, %3, %4};\n"
        "stmatrix.sync.aligned.x4.trans.m8n8.shared.b16 "
        "[%5], {%6, %7, %8, %9};\n"
#endif
        :: "r"(stage0_address),
           "r"(local_words[0]), "r"(local_words[1]),
           "r"(local_words[2]), "r"(local_words[3]),
           "r"(stage1_address),
           "r"(peer_words[0]), "r"(peer_words[1]),
           "r"(peer_words[2]), "r"(peer_words[3])
        : "memory"
    );
#else

    const int destination_quarter = lane >> 3;

#if TK_FA4_BWD_PURE_MXFP4_PRMT_8X8_TRANSPOSE
    const int lane_in_eight = lane & 7;
    const uint32_t nibble_shift =
        (lane_in_eight & 1) ? 4u : 28u;
    const uint32_t nibble_keep_mask =
        (lane_in_eight & 1) ? 0xf0f0f0f0u : 0x0f0f0f0fu;
    const uint32_t byte_selector =
        (lane_in_eight & 2) ? 0x3715u : 0x6240u;
    const uint32_t half_selector =
        (lane_in_eight & 4) ? 0x3276u : 0x5410u;
#endif

    #pragma unroll
    for (int query_quarter = 0; query_quarter < 4; ++query_quarter) {
        local_words[query_quarter] = stage0_native_words[query_quarter];
        peer_words[query_quarter] = stage1_native_words[query_quarter];
#if TK_FA4_BWD_PURE_MXFP4_PRMT_8X8_TRANSPOSE
        cta2_role_split_transpose_mxfp4_8x8_nibbles_dual_prmt(
            local_words[query_quarter],
            peer_words[query_quarter],
            nibble_shift,
            nibble_keep_mask,
            byte_selector,
            half_selector
        );
#else
        cta2_role_split_transpose_mxfp4_8x8_nibbles_dual(
            local_words[query_quarter],
            peer_words[query_quarter]
        );
#endif
    }

    const bool quarter_bit0 = (destination_quarter & 1) != 0;
    {
        const uint32_t local_exchange01 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit0 ? local_words[0] : local_words[1],
            8
        );
        const uint32_t peer_exchange01 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit0 ? peer_words[0] : peer_words[1],
            8
        );
        const uint32_t local_exchange23 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit0 ? local_words[2] : local_words[3],
            8
        );
        const uint32_t peer_exchange23 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit0 ? peer_words[2] : peer_words[3],
            8
        );
        if (quarter_bit0) {
            local_words[0] = local_exchange01;
            local_words[2] = local_exchange23;
            peer_words[0] = peer_exchange01;
            peer_words[2] = peer_exchange23;
        } else {
            local_words[1] = local_exchange01;
            local_words[3] = local_exchange23;
            peer_words[1] = peer_exchange01;
            peer_words[3] = peer_exchange23;
        }
    }

    const bool quarter_bit1 = (destination_quarter & 2) != 0;
    {
        const uint32_t local_exchange02 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit1 ? local_words[0] : local_words[2],
            16
        );
        const uint32_t peer_exchange02 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit1 ? peer_words[0] : peer_words[2],
            16
        );
        const uint32_t local_exchange13 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit1 ? local_words[1] : local_words[3],
            16
        );
        const uint32_t peer_exchange13 = __shfl_xor_sync(
            0xffffffff,
            quarter_bit1 ? peer_words[1] : peer_words[3],
            16
        );
        if (quarter_bit1) {
            local_words[0] = local_exchange02;
            local_words[1] = local_exchange13;
            peer_words[0] = peer_exchange02;
            peer_words[1] = peer_exchange13;
        } else {
            local_words[2] = local_exchange02;
            local_words[3] = local_exchange13;
            peer_words[2] = peer_exchange02;
            peer_words[3] = peer_exchange13;
        }
    }

    const uint32_t local_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&local_dst.data[0])
    );
    const uint32_t peer_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&peer_dst.data[0])
    );
    const uint32_t local_address = local_dst.idx(
        local_base,
        {dst_row_base + lane, local_dst_logical_col_base / 2}
    );
    const uint32_t peer_address = peer_dst.idx(
        peer_base,
        {dst_row_base + lane, peer_dst_logical_col_base / 2}
    );
    // The transpose is identical for both source stages.  Choose ownership at
    // the two store addresses instead of conditionally moving all eight words
    // into local/peer register arrays before the shuffle network.
    const uint32_t stage0_address =
        stage0_is_local ? local_address : peer_address;
    const uint32_t stage1_address =
        stage0_is_local ? peer_address : local_address;
    asm volatile(
        "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
        "st.shared.v4.b32 [%5], {%6, %7, %8, %9};\n"
        :: "r"(stage0_address),
           "r"(local_words[0]), "r"(local_words[1]),
           "r"(local_words[2]), "r"(local_words[3]),
           "r"(stage1_address),
           "r"(peer_words[0]), "r"(peer_words[1]),
           "r"(peer_words[2]), "r"(peer_words[3])
        : "memory"
    );
#endif
}

template <ducks::st::all Dst>
__device__ __forceinline__ void
cta2_role_split_transpose_mxfp4_x32_quartered_registers(
    Dst &dst,
    const uint32_t (&native_words)[4],
    int dst_row_base,
    int dst_logical_col_base
) {
    static_assert(std::is_same_v<typename Dst::dtype, fp4e2m1_2>);
    const int lane = laneid();
    const int destination_quarter = lane >> 3;
    const uint32_t dst_base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&dst.data[0])
    );

#if TK_FA4_BWD_PURE_MXFP4_BUTTERFLY_QUARTER_TRANSPOSE
    // First transpose the four independent 8x8 nibble blocks local to each
    // lane quarter.  At this point lane quarter K owns the vector
    // {block[K][Q0], ..., block[K][Q3]}.
    uint32_t words[4];
    #pragma unroll
    for (int query_quarter = 0; query_quarter < 4; ++query_quarter) {
        words[query_quarter] =
            cta2_role_split_transpose_mxfp4_8x8_nibbles(
                native_words[query_quarter]
            );
    }

    // Transpose that distributed 4x4 register matrix with a two-level
    // butterfly.  Selecting the source operand from the source lane quarter
    // lets one shuffle exchange each off-diagonal pair, so this needs four
    // cross-quarter shuffles rather than the old sixteen.  Each lane then
    // owns all four key-quarter words for its query quarter and stores once.
    const bool quarter_bit0 = (destination_quarter & 1) != 0;
    const uint32_t exchange01 = __shfl_xor_sync(
        0xffffffff,
        quarter_bit0 ? words[0] : words[1],
        8
    );
    const uint32_t exchange23 = __shfl_xor_sync(
        0xffffffff,
        quarter_bit0 ? words[2] : words[3],
        8
    );
    if (quarter_bit0) {
        words[0] = exchange01;
        words[2] = exchange23;
    } else {
        words[1] = exchange01;
        words[3] = exchange23;
    }

    const bool quarter_bit1 = (destination_quarter & 2) != 0;
    const uint32_t exchange02 = __shfl_xor_sync(
        0xffffffff,
        quarter_bit1 ? words[0] : words[2],
        16
    );
    const uint32_t exchange13 = __shfl_xor_sync(
        0xffffffff,
        quarter_bit1 ? words[1] : words[3],
        16
    );
    if (quarter_bit1) {
        words[0] = exchange02;
        words[1] = exchange13;
    } else {
        words[2] = exchange02;
        words[3] = exchange13;
    }

    const uint32_t dst_address = dst.idx(
        dst_base,
        {
            dst_row_base + lane,
            dst_logical_col_base / 2
        }
    );
    asm volatile(
        "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
        :: "r"(dst_address),
           "r"(words[0]), "r"(words[1]),
           "r"(words[2]), "r"(words[3])
        : "memory"
    );
#else
    const int lane_in_eight = lane & 7;
    // Treat the 32x32 nibble transpose as sixteen independent 8x8 blocks.
    // Only the destination eight-lane quarter stores each pass, so the
    // temporary dies before the next query quarter is opened.  This mirrors
    // the forward pass's quarter-retirement discipline without retaining a
    // full transposed register tile.
    #pragma unroll
    for (int query_quarter = 0; query_quarter < 4; ++query_quarter) {
        const uint32_t transposed =
            cta2_role_split_transpose_mxfp4_8x8_nibbles(
                native_words[query_quarter]
            );
        uint32_t key_quarter_words[4];
        #pragma unroll
        for (int key_quarter = 0; key_quarter < 4; ++key_quarter) {
            key_quarter_words[key_quarter] = __shfl_sync(
                0xffffffff,
                transposed,
                key_quarter * 8 + lane_in_eight
            );
        }
        if (destination_quarter == query_quarter) {
            const uint32_t dst_address = dst.idx(
                dst_base,
                {
                    dst_row_base + lane,
                    dst_logical_col_base / 2
                }
            );
            asm volatile(
                "st.shared.v4.b32 [%0], {%1, %2, %3, %4};\n"
                :: "r"(dst_address),
                   "r"(key_quarter_words[0]),
                   "r"(key_quarter_words[1]),
                   "r"(key_quarter_words[2]),
                   "r"(key_quarter_words[3])
                : "memory"
            );
        }
    }
#endif
}

__host__ __device__ __forceinline__ int
cta2_role_split_mxfp4_scale_swizzle_idx(int row, int k_block) {
    const int row_in_32 = row & 31;
    const int tile_in_block = (row >> 5) & 3;
    const int k_block_group = k_block >> 2;
    const int kb_in_block = k_block & 3;
    return k_block_group * 512 + row_in_32 * 16 +
        tile_in_block * 4 + kb_in_block;
}

template <typename ScaleTile>
__device__ __forceinline__ void
cta2_role_split_store_mxfp4_scale_byte(
    ScaleTile &scale,
    int row,
    int k_block,
    uint8_t e8m0
) {
    const uint32_t base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&reinterpret_cast<uint8_t &>(
            scale.data[0]
        ))
    );
    asm volatile(
        "st.shared.b8 [%0], %1;"
        :: "r"(base + cta2_role_split_mxfp4_scale_swizzle_idx(
                     row,
                     k_block
                 )),
           "r"(static_cast<uint32_t>(e8m0))
        : "memory"
    );
}

template <typename ScaleTile>
__device__ __forceinline__ uint32_t
cta2_role_split_load_mxfp4_scale_word(
    const ScaleTile &scale,
    int row
) {
    const uint32_t base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&reinterpret_cast<const uint8_t &>(
            scale.data[0]
        ))
    );
    uint32_t packed;
    asm volatile(
        "ld.shared.b32 %0, [%1];"
        : "=r"(packed)
        : "r"(base + cta2_role_split_mxfp4_scale_swizzle_idx(row, 0))
    );
    return packed;
}

__device__ __forceinline__ void
cta2_role_split_store_mxfp4_scale_tmem_x1(
    uint32_t page_addr,
    int reader_warp,
    uint32_t packed_scale
) {
    // Scale-factor pages use the special tcgen05 scale layout.  As in the
    // forward direct-P-scale path, the four 32-row reader warps select low
    // TMEM columns 0..3; they do not encode their row group in bits 16+.
    asm volatile(
        "tcgen05.st.sync.aligned.32x32b.x1.b32 [%0], {%1};"
        :: "r"(page_addr + static_cast<uint32_t>(reader_warp)),
           "r"(packed_scale)
        : "memory"
    );
}

__device__ __forceinline__ void
cta2_role_split_tmem_store_wait() {
    asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
}

template <typename ScaleTile>
__device__ __forceinline__ void
cta2_role_split_store_mxfp4_scale_byte_peer(
    ScaleTile &scale,
    int row,
    int k_block,
    uint8_t e8m0,
    int peer_rank
) {
    const uint32_t base = static_cast<uint32_t>(
        __cvta_generic_to_shared(&reinterpret_cast<uint8_t &>(
            scale.data[0]
        ))
    );
    const uint32_t local_address =
        base + cta2_role_split_mxfp4_scale_swizzle_idx(row, k_block);
    uint32_t peer_address;
    asm volatile(
        "mapa.shared::cluster.u32 %0, %1, %2;\n"
        : "=r"(peer_address)
        : "r"(local_address), "r"(peer_rank)
    );
    asm volatile(
        "st.shared::cluster.b8 [%0], %1;"
        :: "r"(peer_address), "r"(static_cast<uint32_t>(e8m0))
        : "memory"
    );
}

