        "tcgen05.st.sync.aligned.32x32b.x4.b32 "
        "[%0], {%1, %2, %3, %4};\n"
        :: "r"(dst_addr),
           "r"(words[0]), "r"(words[1]),
           "r"(words[2]), "r"(words[3])
        : "memory"
