) {
    static_assert(Half == 0 || Half == 1);
    auto &score_half = *reinterpret_cast<
        cta2_fused_dense_attn_half_reg *
    >(&score.tiles[0][Half * 4]);
    auto score_half_tmem =
        score_tmem.template subtile<cta2_fused_dense_attn_half_tt>(
