#if TK_FA4_BWD_PURE_MXFP4_REDUCER_SCORE_SCALE_COPY || \
    TK_FA4_BWD_HYBRID_REDUCER_SCORE_SCALE_COPY || \
    TK_FA4_BWD_FP8DPDV_REDUCER_SCORE_SCALE_COPY || \
