            auto *scale_words = reinterpret_cast<uint32_t *>(
                &score_scale.data[0]
            );
            auto &p_mxfp4_scale =
                cta2_fused_dense_mxfp4_p_scale_smem(storage.k);
            auto &do_mxfp4_scale =
                cta2_fused_dense_mxfp4_do_scale_smem(storage.k);
            auto *p_scale_words = reinterpret_cast<uint32_t *>(
                &p_mxfp4_scale.data[0]
