            auto *do_scale_words = reinterpret_cast<uint32_t *>(
                &do_mxfp4_scale.data[0]
            );
            auto &qk_unit_scale =
                cta2_fused_dense_mxfp4_qk_unit_scale_stage(storage);
            auto *qk_unit_scale_words = reinterpret_cast<uint32_t *>(
                &qk_unit_scale.data[0]
            );
            auto &dq_ds_scale0 =
                cta2_fused_dense_mxfp4_dsdq_scale_stage<0>(storage);
            auto &dq_ds_scale1 =
                cta2_fused_dense_mxfp4_dsdq_scale_stage<1>(storage);
            auto &dk_ds_scale =
                cta2_fused_dense_mxfp4_dsdk_scale_stage(storage);
            auto *dq_ds_scale0_words = reinterpret_cast<uint32_t *>(
