            auto *nv_scale_words1 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<1>(storage).data[0]
            );
            auto *nv_scale_words2 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<2>(storage).data[0]
            );
            auto *nv_scale_words3 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<3>(storage).data[0]
            );
            auto *nv_scale_words4 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<4>(storage).data[0]
            );
            auto *nv_scale_words5 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<5>(storage).data[0]
            );
            auto *nv_scale_words6 = reinterpret_cast<uint32_t *>(
                &cta2_fused_dense_nvfp4_ds_scale_stage<6>(storage).data[0]
