            #pragma unroll
            for (int word = lane; word < 128; word += 32) {
                scale_words[word] = score_scale_word;
                p_scale_words[word] = 0;
                do_scale_words[word] = 0;
                if constexpr (UsePureMxFp4DqDk) {
#if TK_FA4_BWD_PURE_NVFP4_DS
                    nv_scale_words0[word] = 0;
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION != 1
                    nv_scale_words1[word] = 0;
#endif
                    nv_scale_words2[word] = 0;
                    nv_scale_words3[word] = 0;
                    nv_scale_words4[word] = 0;
                    nv_scale_words5[word] = 0;
                    nv_scale_words6[word] = 0x38383838u;
