            auto *scale_words = reinterpret_cast<uint32_t *>(
                &score_scale.data[0]
            );
            #pragma unroll
            for (int word = lane; word < 128; word += 32) {
                scale_words[word] = 0x38383838u;
            }
            asm volatile(
                "fence.proxy.async.shared::cta;"
                ::: "memory"
            );
        }
    }
    if constexpr (UseFixedMixedDpScale && !ReuseScoreScaleForMixedDp) {
        if (physical_warp == 13) {
            auto &fixed_scale =
                cta2_fused_dense_mixed_dp_v_scale_stage(storage.ds);
            auto *fixed_scale_words = reinterpret_cast<uint32_t *>(
                &fixed_scale.data[0]
            );
            constexpr uint32_t kFixedScaleByte =
                TK_FA4_BWD_MIXED_DP_FIXED_SCALE_E8M0;
            constexpr uint32_t kFixedScaleWord =
                kFixedScaleByte * 0x01010101u;
            #pragma unroll
            for (int word = lane; word < 128; word += 32) {
