        UseStreamedMixedDpN64
            ? score_dp_tmem.addr + 64
            : score_unit_scale_tmem.addr
    );
    cta2_fused_dense_mxfp4_scale_tt score_as_mixed_dp_scale_tmem(
        score_unit_scale_tmem.addr
    );
    cta2_fused_dense_attn_half_tt streamed_dp_tmem(
        score_dp_tmem.addr + 128
    );
    cta2_fused_dense_ds_tt p_tmem =
        tm_alloc.template allocate<cta2_fused_dense_ds_tt>(
            SplitDqAliasLifetimeWithCuteTmemMap
                ? 320
                : (UseFusedTmemPAndDs ? 448 : 320)
        );
    cta2_fused_dense_p_fp8_tt p_fp8_tmem(p_tmem.addr);
    cta2_fused_dense_p_mxfp4_tt p_mxfp4_tmem(p_tmem.addr);
    cta2_fused_dense_p_mxfp4_tt p_mixed_dv_tail_tmem(
        p_tmem.addr + 16
    );
    cta2_fused_dense_score_scale_fp4_tt dv_unit_scale_tmem(p_tmem.addr);
    // MXFP4 P occupies only the first 16 columns, but the winning E4M3 P
    // representation occupies 32.  Mixed dP must therefore keep both scale
    // pages in the dead score tail at columns 32..63; placing the first page
    // at +16 overwrites half of the retained P before dV and dS consume it.
    cta2_fused_dense_mxfp4_scale_tt dv_p_scale_tmem(
        p_tmem.addr + (UseMixedFp8MxFp4Dp ? 32 : 16)
