    cta2_fused_dense_mxfp4_scale_tt ds_qk_scale0_tmem(p_tmem.addr + 48);
    cta2_fused_dense_mxfp4_scale_tt ds_qk_scale1_tmem(p_tmem.addr + 64);
    cta2_fused_dense_mxfp4_scale_tt qk_unit_scale_tmem(p_tmem.addr + 80);
    cta2_fused_dense_attn_tt dp_tmem =
        tm_alloc.template allocate<cta2_fused_dense_attn_tt>(384);
