    cta2_fused_dense_dq_tt dq_tmem =
        tm_alloc.template allocate<cta2_fused_dense_dq_tt>(
            0,
            UseCrossIterationN64Score
                ? 384
                : (UsePureMxFp4DqDk && TK_FA4_BWD_PURE_MXFP4_DQ_N256
                    ? 384
                    : (SplitDqAliasLifetimeWithCuteTmemMap ? 416 : 320))
