                ""
                : "+f"(cached_adaptive_dq_fragment_scale)
            );
        }
        if constexpr (UseDirectWinningScoreScaleTmem) {
            if (physical_warp == 0) {
                auto &score_scale =
                    cta2_fused_dense_fp4_score_scale_smem(storage.k);
                cached_direct_score_scale_word =
                    reinterpret_cast<const uint32_t *>(
                        &score_scale.data[0]
                    )[0];
                asm volatile(
                    ""
                    : "+r"(cached_direct_score_scale_word)
                );
            }
        }
        auto &dq_reduce = [&]() -> cta2_fused_dense_dq_reduce & {
            if constexpr (DirectNextQdoDuringDqDrain) {
                return *reinterpret_cast<cta2_fused_dense_dq_reduce *>(
                    &storage.phase.main.p
                );
            } else {
                return storage.phase.dq.reduce;
            }
        }();
        uint32_t hoisted_dq_stage_lane_pointer_even = 0;
        uint32_t hoisted_dq_stage_lane_pointer_odd = 0;
        if constexpr (HoistWinningDqStagePointers) {
            auto &stage_even = dq_reduce.stage[0][physical_warp];
            auto &stage_odd = dq_reduce.stage[1][physical_warp];
            hoisted_dq_stage_lane_pointer_even = static_cast<uint32_t>(
                __cvta_generic_to_shared(
                    stage_even.data +
                        lane * cta2_fused_dense_dq_stage::cols
                )
            );
            hoisted_dq_stage_lane_pointer_odd = static_cast<uint32_t>(
                __cvta_generic_to_shared(
                    stage_odd.data +
                        lane * cta2_fused_dense_dq_stage::cols
                )
            );
            hoisted_dq_stage_lane_pointer_even ^=
                (hoisted_dq_stage_lane_pointer_even & 0x380u) >> 3;
            hoisted_dq_stage_lane_pointer_odd ^=
                (hoisted_dq_stage_lane_pointer_odd & 0x380u) >> 3;
            asm volatile(
                ""
                : "+r"(hoisted_dq_stage_lane_pointer_even),
                  "+r"(hoisted_dq_stage_lane_pointer_odd)
            );
        }
        #pragma unroll 1
        for (
            int owner_pass = 0;
            owner_pass < (SingleOwnerCluster ? 1 : 2);
            ++owner_pass
        ) {
            const int owner_idx = SingleOwnerCluster
                ? owner_pair_idx
                : (owner_pass == 0
                    ? owner_pair_idx
                    : owner_count - 1 - owner_pair_idx);
            const int owner_phase = OwnerQWorkSplitId >= 0
                ? (owner_pass == 0
                    ? 0
                    : ((owner_count - owner_pair_idx) & 1))
                : (SingleOwnerCluster || IntegrateCausalFrontier
                    ? 0
                    : (owner_pass & 1));
            const int owner_once_phase =
                SingleOwnerCluster ? 0 : (owner_pass & 1);
            const int first_dense_q_tile =
                2 * owner_idx + (IntegrateCausalFrontier ? 0 : 1) +
                (OwnerQWorkSplitId < 0 ? 0 : OwnerQWorkSplitId);
            rt_bf<32, kB300VDim> v_persistent;
            if constexpr (!UseTmaVWithScoreK) {
                warp::load<dim::DEPTH>(
                    v_persistent,
                    g.v,
                    {
                        batch_idx,
                        owner_idx * 8 + cta_rank * 4 + physical_warp,
                        head_idx,
                        0
                    }
                );
            }
            if constexpr (PublishVOncePerOwner && !UseTmaVWithScoreK) {
                auto v_smem = storage.ds.template subtile<32, kB300VDim>(
                    {physical_warp, 0}
                );
                warp::store(v_smem, v_persistent);
                warp::arrive(v_local_ready);
                if (physical_warp == 0 && lane == 0) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        v_local_ready,
                        owner_once_phase
                    );
                }
            }
            int iteration = 0;
            int reducer_score_phase = owner_phase;
            for (
                int q_tile_idx = first_dense_q_tile;
                q_tile_idx < q_tile_count;
                q_tile_idx += q_tile_step, ++iteration
            ) {
                const int phase = CarryAllRolePhases
                    ? reducer_score_phase
                    : ((iteration + owner_phase) & 1);
                if constexpr (HoistReducerDpReadyBeforeScoreWait) {
                    if (physical_warp == 0 && lane == 0) {
                        ::kittens::tma::cluster::arrive(
                            dp_operands_ready,
                            0
                        );
                    }
                }
                if constexpr (!HoistReducerDpReadyBeforeScoreWait) {
                    if constexpr (UseComputeScoreFanout) {
                        if (physical_warp == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                score_done,
                                phase
                            );
                            if constexpr (!UseStatsWarpScoreFanout) {
                                if constexpr (UseX32TmemComputeLayout) {
                                    asm volatile(
                                        "bar.sync 5, 320;"
                                        ::: "memory"
                                    );
                                } else {
                                    asm volatile(
                                        "bar.sync 5, 288;"
                                        ::: "memory"
                                    );
                                }
                            }
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                score_done,
                                phase
                            );
                        }
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_done,
                            phase
                        );
                    }
                }
                auto &main = storage.phase.main;
                if constexpr (DirectTmaDkQ && !LoaderOwnedDkQ) {
                    if (physical_warp == 0) {
                        if constexpr (UseFp8DqDk) {
                            if (lane == 0) {
                                auto &q_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_q_fp8_transposed_wide_tile *
                                >(&main.q);
                                tma::expect_bytes(
                                    q_source_loaded,
                                    sizeof(q_fp8)
                                );
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    q_fp8,
                                    g.q_fp8,
                                    coord<
                                        cta2_fused_dense_q_fp8_transposed_wide_tile
                                    >{
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        q_tile_idx
                                    },
                                    q_source_loaded
                                );
                            }
                        } else if constexpr (UseFp4DqDk) {
                            if (lane == 0) {
                                if constexpr (UsePureMxFp4DqDk) {
                                    auto &q_mxfp4_tma = *reinterpret_cast<
                                        cta2_fused_dense_dk_q_mxfp4_tma_tile *
                                    >(&main.q);
                                    tma::expect_bytes(
                                        q_source_loaded,
                                        sizeof(q_mxfp4_tma)
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    !TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                                            + 2 * sizeof(
                                                cta2_fused_dense_nvfp4_scale_tile
                                            )
#endif
                                    );
                                    tma::load_async<
                                        dim::ROW,
                                        cache_policy::NORMAL
                                    >(
                                        q_mxfp4_tma,
                                        g.q_dk_mxfp4,
                                        coord<
                                            cta2_fused_dense_dk_q_mxfp4_tma_tile
                                        >{
                                            batch_idx,
                                            head_idx,
                                            cta_rank,
                                            q_tile_idx
                                        },
                                        q_source_loaded
                                    );
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    !TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                                    cta2_fused_dense_load_q_nvfp4_scales(
                                        storage,
                                        g,
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        q_tile_idx,
                                        q_source_loaded
                                    );
#endif
                                } else {
                                    auto &q_fp4 = *reinterpret_cast<
                                        cta2_fused_dense_q_fp4_transposed_wide_tile *
                                    >(&main.q);
                                    tma::expect_bytes(
                                        q_source_loaded,
                                        sizeof(q_fp4)
                                    );
                                    tma::load_async<
                                        dim::ROW,
                                        cache_policy::NORMAL
                                    >(
                                        q_fp4,
                                        g.q_fp4,
                                        coord<
                                            cta2_fused_dense_q_fp4_transposed_wide_tile
                                        >{
                                            batch_idx,
                                            head_idx,
                                            cta_rank,
                                            q_tile_idx
                                        },
                                        q_source_loaded
                                    );
                                }
                            }
                        } else if constexpr (UseWideDkN192) {
                            if constexpr (ElectedWideDkQTmaLoad) {
                                cta2_fused_dense_load_dk_q_wide_elected(
                                    main.q.normal_wide,
                                    g.q,
                                    coord<
                                        cta2_fused_dense_q_normal_wide_tile
                                    >{
                                        batch_idx,
                                        q_tile_idx,
                                        head_idx,
                                        cta_rank
                                    },
                                    q_source_loaded
                                );
                            } else if (lane == 0) {
                                tma::expect_bytes(
                                    q_source_loaded,
                                    sizeof(main.q.normal_wide)
                                );
                                tma::load_async<
                                    dim::DEPTH,
                                    cache_policy::NORMAL
                                >(
                                    main.q.normal_wide,
                                    g.q,
                                    coord<
                                        cta2_fused_dense_q_normal_wide_tile
                                    >{
                                        batch_idx,
                                        q_tile_idx,
                                        head_idx,
                                        cta_rank
                                    },
                                    q_source_loaded
                                );
                            }
                        } else if (lane == 0) {
                            tma::expect_bytes(
                                q_source_loaded,
                                sizeof(main.q.normal)
                            );
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                main.q.normal.q0,
                                g.q,
                                coord<cta2_fused_dense_q_normal0_tile>{
                                    batch_idx,
                                    q_tile_idx,
                                    head_idx,
                                    cta_rank
                                },
                                q_source_loaded
                            );
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                main.q.normal.q1,
                                g.q,
                                coord<cta2_fused_dense_q_normal1_tile>{
                                    batch_idx,
                                    q_tile_idx,
                                    head_idx,
                                    4 + cta_rank
                                },
                                q_source_loaded
                            );
                        }
                    }
                }
                if constexpr (
                    !PublishVOncePerOwner && !UseTmaVWithScoreK
                ) {
                    auto v_smem = storage.ds.template subtile<32, kB300VDim>(
                        {physical_warp, 0}
                    );
                    warp::store(v_smem, v_persistent);
                    warp::arrive(v_local_ready);
                }
                if constexpr (!HoistReducerDpReadyBeforeScoreWait) {
                    if (physical_warp == 0 && lane == 0) {
                        if constexpr (
                            !PublishVOncePerOwner && !UseTmaVWithScoreK
                        ) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                v_local_ready,
                                phase
                            );
                        }
                        ::kittens::tma::cluster::arrive(
                            dp_operands_ready,
                            0
                        );
                    }
                }
                auto &qdo_exchange = storage.qdo_phase.qdo;
                if constexpr (!DirectTmaDkQ) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        qdo_exchange_done,
                        phase
                    );
                    if constexpr (UseWideDkN192) {
                        rt_bf<32, 16> q0_transposed[2];
                        rt_bf<32, 16> q1_transposed[2];
                        rt_bf<32, 16> q2_transposed[2];
                        cta2_role_split_load_q_transposed_wide(
                            main,
                            qdo_exchange,
                            physical_warp,
                            cta_rank,
                            q0_transposed[0],
                            q1_transposed[0],
                            q2_transposed[0]
                        );
                        cta2_role_split_load_q_transposed_wide(
                            main,
                            qdo_exchange,
                            physical_warp + 4,
                            cta_rank,
                            q0_transposed[1],
                            q1_transposed[1],
                            q2_transposed[1]
                        );
                        warp::arrive(q_source_loaded);
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            q_source_loaded,
                            phase
                        );
                        #pragma unroll
                        for (int source = 0; source < 2; ++source) {
                            const int col_tile = physical_warp + 4 * source;
                            cta2_role_split_store_q_transposed_wide(
                                main.q.transposed_wide,
                                q0_transposed[source],
                                0,
                                col_tile
                            );
                            cta2_role_split_store_q_transposed_wide(
                                main.q.transposed_wide,
                                q1_transposed[source],
                                2,
                                col_tile
                            );
                            cta2_role_split_store_q_transposed_wide(
                                main.q.transposed_wide,
                                q2_transposed[source],
                                4,
                                col_tile
                            );
                        }
                    } else {
                        rt_bf<64, 16> q0_transposed_0;
                        rt_bf<64, 16> q0_transposed_1;
                        rt_bf<32, 16> q1_transposed_0;
                        rt_bf<32, 16> q1_transposed_1;
                        cta2_role_split_load_q_transposed(
                            main,
                            qdo_exchange,
                            physical_warp,
                            cta_rank,
                            q0_transposed_0,
                            q1_transposed_0
                        );
                        cta2_role_split_load_q_transposed(
                            main,
                            qdo_exchange,
                            physical_warp + 4,
                            cta_rank,
                            q0_transposed_1,
                            q1_transposed_1
                        );
                        warp::arrive(q_source_loaded);
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            q_source_loaded,
                            phase
                        );
                        auto q0_smem_0 =
                            main.q.transposed.q0.template subtile<64, 16>(
                                {0, physical_warp}
                            );
                        auto q0_smem_1 =
                            main.q.transposed.q0.template subtile<64, 16>(
                                {0, physical_warp + 4}
                            );
                        auto q1_smem_0 =
                            main.q.transposed.q1.template subtile<32, 16>(
                                {0, physical_warp}
                            );
                        auto q1_smem_1 =
                            main.q.transposed.q1.template subtile<32, 16>(
                                {0, physical_warp + 4}
                            );
                        warp::store(q0_smem_0, q0_transposed_0);
                        warp::store(q0_smem_1, q0_transposed_1);
                        warp::store(q1_smem_0, q1_transposed_0);
                        warp::store(q1_smem_1, q1_transposed_1);
                    }
                } else {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        q_source_loaded,
                        phase
                    );
                }
                asm volatile(
                    "fence.proxy.async.shared::cta;"
                    ::: "memory"
                );
                if constexpr (!UseAsyncDkReady) {
                    if constexpr (UseNamedDkdvLocalFanIn) {
                        asm volatile("bar.arrive 7, 384;" ::: "memory");
                    } else {
                        warp::arrive(dkdv_local_ready);
                    }
                }
                const int row_half = physical_warp & 1;
                int col_half = physical_warp >> 1;
                int q_row_block =
                    q_tile_idx * 4 + cta_rank * 2 + row_half;
                const uint32_t physical_row =
                    static_cast<uint32_t>(physical_warp * 32);
                uint32_t dq_stage_lane_pointer_even =
                    hoisted_dq_stage_lane_pointer_even;
                uint32_t dq_stage_lane_pointer_odd =
                    hoisted_dq_stage_lane_pointer_odd;
                uint32_t dq_row_address = 0;
                float dq_fragment_scale;
                if constexpr (UseReducerDqFanout) {
                    if (physical_warp == 0) {
                        if constexpr (UseEarlyWinningDqTmemWait) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_issued,
                                phase
                            );
                        } else if constexpr (SplitWinningDqN64First) {
                            if constexpr (ReverseSplitWinningDqIssue) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dq_done, phase);
                            } else {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dq_prefix_done, phase);
                            }
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_done,
                                phase
                            );
                        }
                    }
                    if constexpr (SplitWinningDqN64First) {
                        // Use a fully blocking first-completion fanout so
                        // barrier 6 is cleanly reusable for the second split.
                        asm volatile(
                            "bar.sync 6, 128;"
                            ::: "memory"
                        );
                    } else if constexpr (
                        UseReducerDqLeaderArrive && !SplitScoreQReady &&
                        !(UseWinningFp8DpDv &&
                          TK_FA4_BWD_FP8DPDV_UNIFORM_DQ_FANOUT)
                    ) {
                        if (physical_warp == 0) {
                            asm volatile(
                                "bar.arrive 6, 128;"
                                ::: "memory"
                            );
                        } else {
                            asm volatile(
                                "bar.sync 6, 128;"
                                ::: "memory"
                            );
                        }
                    } else {
                        // Split score-Q readiness makes the dQ producer short
                        // enough that the leader-arrive branch reconverges on
                        // the critical path.  Let all four reducer warps join
                        // the same blocking barrier after warp 0 observes the
                        // tensor completion; this removes the extra divergent
                        // fanout while preserving the single dq_done waiter.
                        asm volatile(
                            "bar.sync 6, 128;"
                            ::: "memory"
                        );
                    }
                } else {
                    if constexpr (SplitWinningDqN64First) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dq_prefix_done,
                            phase
                        );
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dq_done,
                            phase
                        );
                    }
                }
                if constexpr (UseLowpDqDk) {
                    if constexpr (UsePostScaleMixedDq) {
                        dq_fragment_scale = 1.0f;
                    } else if constexpr (UseAdaptiveQkScales) {
                        dq_fragment_scale =
                            cached_adaptive_dq_fragment_scale;
                    } else {
                        dq_fragment_scale = g.dq_output_scale;
                    }
                } else {
                    dq_fragment_scale =
                        UseSlicedFp32PForDs ? 1.0f : g.scale;
                }
                if constexpr (
                    CacheDqStageLanePointers &&
                    !HoistWinningDqStagePointers
                ) {
                    auto &stage_even = dq_reduce.stage[0][physical_warp];
                    auto &stage_odd = dq_reduce.stage[1][physical_warp];
                    dq_stage_lane_pointer_even = static_cast<uint32_t>(
                        __cvta_generic_to_shared(
                            stage_even.data +
                                lane * cta2_fused_dense_dq_stage::cols
                        )
                    );
                    dq_stage_lane_pointer_odd = static_cast<uint32_t>(
                        __cvta_generic_to_shared(
                            stage_odd.data +
                                lane * cta2_fused_dense_dq_stage::cols
                        )
                    );
                    // Each 32-float row is 128-byte aligned, so the 128-byte
                    // swizzle selector is constant across all eight float4
                    // stores.
                    dq_stage_lane_pointer_even ^=
                        (dq_stage_lane_pointer_even & 0x380u) >> 3;
                    dq_stage_lane_pointer_odd ^=
                        (dq_stage_lane_pointer_odd & 0x380u) >> 3;
                    asm volatile(
                        ""
                        : "+r"(dq_stage_lane_pointer_even),
                          "+r"(dq_stage_lane_pointer_odd)
                    );
                }
                if constexpr (SplitWinningDqN64First) {
                    static_assert(
                        UseLowpDqDk && UseBatchedDqTmemLoads &&
                        SplitDqTmemAndSharedHandoff &&
                        SplitDqAliasLifetimeWithCuteTmemMap
                    );
                    dq_row_address =
                        dq_tmem.addr + (physical_row << 16);
                    if constexpr (ReverseSplitWinningDqIssue) {
                        // N128 is the first legal issue.  Drain its two
                        // non-score fragments while the tensor warp computes
                        // the final N64 fragment in the score-aliased prefix.
                        uint32_t head_values0[32];
                        cta2_fused_dense_load_tmem_x32(
                            head_values0,
                            dq_row_address + 32
                        );
                        cta2_fused_dense_store_dq_chunk_cached_scaled<0>(
                            g,
                            dq_reduce.stage[0][physical_warp],
                            dq_stage_lane_pointer_even,
                            head_values0,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );
                        uint32_t head_values1[32];
                        cta2_fused_dense_load_tmem_x32(
                            head_values1,
                            dq_row_address + 64
                        );
                        cta2_fused_dense_store_dq_chunk_cached_scaled<1>(
                            g,
                            dq_reduce.stage[1][physical_warp],
                            dq_stage_lane_pointer_odd,
                            head_values1,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );

                        if (physical_warp == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_prefix_done,
                                phase
                            );
                        }
                        asm volatile(
                            "bar.sync 6, 128;"
                            ::: "memory"
                        );

                        uint32_t tail_values[32];
                        cta2_fused_dense_load_tmem_x32(
                            tail_values,
                            dq_row_address
                        );
                        // The final fragment is now in registers, so both the
                        // score alias and dP/dQ TMEM overlap may be reused.
                        warp::arrive(dq_reduce_done);
                        warp::arrive(p_tmem_ready);
                        // Head-0 is the oldest store; retire it before stage 0
                        // is reused for the final tail store.
                        warp::tma::store_async_wait<1>();
                        cta2_fused_dense_store_dq_chunk_cached_scaled<2>(
                            g,
                            dq_reduce.stage[0][physical_warp],
                            dq_stage_lane_pointer_even,
                            tail_values,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );
                        warp::tma::store_async_read_wait();
                        warp::arrive(dq_shared_read_done);
                        warp::tma::store_async_wait();
                    } else {
                        // The N64 instruction contains chunk 2 from each
                        // 96-feature datapath half in the score-aliased
                        // prefix.  This order is retained only as a disabled
                        // diagnostic: N128-after-N64 is not valid here.
                        uint32_t tail_values[32];
                        cta2_fused_dense_load_tmem_x32(
                            tail_values,
                            dq_row_address
                        );
                        cta2_fused_dense_store_dq_chunk_cached_scaled<2>(
                            g,
                            dq_reduce.stage[0][physical_warp],
                            dq_stage_lane_pointer_even,
                            tail_values,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );

                        if (physical_warp == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_done,
                                phase
                            );
                        }
                        asm volatile(
                            "bar.sync 6, 128;"
                            ::: "memory"
                        );

                        uint32_t head_values0[32];
                        uint32_t head_values1[32];
                        cta2_fused_dense_load_tmem_x32(
                            head_values0,
                            dq_row_address + 32
                        );
                        cta2_fused_dense_load_tmem_x32(
                            head_values1,
                            dq_row_address + 64
                        );
                        warp::arrive(dq_reduce_done);
                        warp::arrive(p_tmem_ready);
                        cta2_fused_dense_store_dq_chunk_cached_scaled<0>(
                            g,
                            dq_reduce.stage[1][physical_warp],
                            dq_stage_lane_pointer_odd,
                            head_values0,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );
                        warp::tma::store_async_wait<1>();
                        cta2_fused_dense_store_dq_chunk_cached_scaled<1>(
                            g,
                            dq_reduce.stage[0][physical_warp],
                            dq_stage_lane_pointer_even,
                            head_values1,
                            dq_fragment_scale,
                            batch_idx,
                            q_row_block,
                            head_idx,
                            col_half
                        );
                        warp::tma::store_async_read_wait();
                        warp::arrive(dq_shared_read_done);
                        warp::tma::store_async_wait();
                    }
                } else
#if TK_FA4_BWD_PURE_MXFP4_DQ_N256
                if constexpr (UsePureMxFp4DqDk) {
                    // Layout B (M128 + cta_group::2) assigns B[0:N/2] to
