                        cta2_fused_dense_dk_tail_tt
                    >(chunk * 64);
                    group<4>::load_async(output_chunk, dk_chunk);
                    tensor_load_wait();
                    if constexpr (UseLowpDqDk) {
                        if constexpr (UseAdaptiveQkScales) {
                            warp::mul(
                                output_chunk,
                                output_chunk,
                                g.adaptive_qk_scales[head_idx * 7 + 3]
                            );
                        } else {
                            warp::mul(
                                output_chunk,
                                output_chunk,
                                g.dk_output_scale
                            );
                        }
                    } else {
                        warp::mul(output_chunk, output_chunk, g.scale);
                    }
                    if constexpr (WideCoalescedBf16Store) {
                        cta2_fused_dense_store_bf16_coalesced_wide(
                            g.dk,
                            output_chunk,
                            batch_idx,
                            kv_tile,
                            head_idx,
                            chunk
                        );
                    } else if constexpr (CoalescedBf16Store) {
                        cta2_fused_dense_store_bf16_coalesced(
                            g.dk,
                            output_chunk,
                            batch_idx,
                            kv_tile,
                            head_idx,
                            chunk
                        );
                    } else {
                        group<4>::store<dim::DEPTH>(
                            g.dk,
                            output_chunk,
                            {batch_idx, kv_tile, head_idx, chunk}
                        );
                    }
                }
                {
                    rt_fl<32, 64> output_chunk;
                    if constexpr (ReverseDkTailTmemLoadIssue) {
                        auto dk_tail_warp_tmem =
                            dk_tail_tmem.template subtile<tt_fl<32, 64>>(
                                32 * warpid(),
                                0
                            );
                        auto dk_tail_hi =
                            dk_tail_warp_tmem.template subtile<tt_fl<16, 64>>(
                                16,
                                0
                            );
                        auto dk_tail_lo =
                            dk_tail_warp_tmem.template subtile<tt_fl<16, 64>>(
                                0,
                                0
                            );
                        auto &output_hi =
                            group<1>::subtile_inplace<16>(output_chunk, 1);
                        auto &output_lo =
                            group<1>::subtile_inplace<16>(output_chunk, 0);
                        group<1>::load_async(output_hi, dk_tail_hi);
                        group<1>::load_async(output_lo, dk_tail_lo);
                    } else {
                        group<4>::load_async(output_chunk, dk_tail_tmem);
                    }
                    tensor_load_wait();
                    if constexpr (UseLowpDqDk) {
                        if constexpr (UseAdaptiveQkScales) {
                            warp::mul(
                                output_chunk,
                                output_chunk,
                                g.adaptive_qk_scales[head_idx * 7 + 3]
                            );
                        } else {
                            warp::mul(
                                output_chunk,
                                output_chunk,
                                g.dk_output_scale
                            );
                        }
                    } else {
                        warp::mul(output_chunk, output_chunk, g.scale);
                    }
                    if constexpr (WideCoalescedBf16Store) {
                        cta2_fused_dense_store_bf16_coalesced_wide(
                            g.dk,
                            output_chunk,
                            batch_idx,
                            kv_tile,
                            head_idx,
                            2
                        );
                    } else if constexpr (CoalescedBf16Store) {
                        cta2_fused_dense_store_bf16_coalesced(
                            g.dk,
                            output_chunk,
                            batch_idx,
                            kv_tile,
                            head_idx,
                            2
                        );
                    } else {
                        group<4>::store<dim::DEPTH>(
                            g.dk,
                            output_chunk,
                            {batch_idx, kv_tile, head_idx, 2}
                        );
                    }
                }
                if constexpr (EnsureReducerOutputDrain) {
                    asm volatile("bar.sync 8, 128;" ::: "memory");
                }
                if (physical_warp == 0 && lane == 0) {
                    ::kittens::tma::cluster::arrive(
                        owner_output_loaded,
                        0
                    );
                }
            }
        }
        return;
    }

    if (is_compute) {
        asm volatile("setmaxnreg.inc.sync.aligned.u32 136;" ::: "memory");
        const int output_subtile =
            2 * (compute_warp % 4) + compute_warp / 4;
        uint32_t dv_operands_ready_cluster_address = 0;
        uint32_t dkdv_operands_ready_cluster_address = 0;
        if constexpr (
            CacheRoleClusterAddresses && !UseX32TmemComputeLayout
        ) {
            if (physical_warp == 4 && lane == 0) {
                dv_operands_ready_cluster_address =
                    cta2_fused_dense_map_cluster_semaphore(
                        dv_operands_ready,
                        0
                    );
                dkdv_operands_ready_cluster_address =
                    cta2_fused_dense_map_cluster_semaphore(
                        dkdv_operands_ready,
                        0
                    );
            }
        }
        int compute_stats_iteration = 0;
        bool have_previous_dq_shared_read = false;
        int previous_dq_shared_read_phase = 0;
        #pragma unroll 1
        for (
            int owner_pass = 0;
            owner_pass < (SingleOwnerCluster ? 1 : 2);
            ++owner_pass
        ) {
            const int owner_idx = SingleOwnerCluster
                ? owner_pair_idx
                : (owner_pass == 0
                    ? owner_pair_idx
                    : owner_count - 1 - owner_pair_idx);
            const int owner_phase = OwnerQWorkSplitId >= 0
                ? (owner_pass == 0
                    ? 0
                    : ((owner_count - owner_pair_idx) & 1))
                : (SingleOwnerCluster || IntegrateCausalFrontier
                    ? 0
                    : (owner_pass & 1));
            const int owner_once_phase =
                SingleOwnerCluster ? 0 : (owner_pass & 1);
            const int first_dense_q_tile =
                2 * owner_idx + (IntegrateCausalFrontier ? 0 : 1) +
                (OwnerQWorkSplitId < 0 ? 0 : OwnerQWorkSplitId);
            size_t carried_direct_stats_offset = 0;
            if constexpr (CarryDirectStatsOffset) {
                carried_direct_stats_offset =
                    (static_cast<size_t>(batch_idx) *
                            g.lse_log2.depth() +
                        head_idx) *
                        g.seq_len +
                    first_dense_q_tile * 128;
            }
            if constexpr (UseTmaScoreK) {
                if constexpr (ElectedScoreKTmaLoad) {
                    if (physical_warp == 4) {
                        if constexpr (UseFp8DqDk) {
                            auto &score_k_fp8 = *reinterpret_cast<
                                cta2_fused_dense_score_k_fp8_tile *
                            >(&storage.k);
                            coord<cta2_fused_dense_score_k_fp8_tile>
                                k_tile_coord = {
                                    batch_idx,
                                    owner_idx * 2 + cta_rank,
                                    head_idx,
                                    0
                            };
                            if constexpr (UseTmaVWithScoreK) {
                                if constexpr (UseFp8Dp) {
                                    auto &v_fp8 = *reinterpret_cast<
                                        cta2_fused_dense_v_fp8_tile *
                                    >(&storage.ds);
                                    cta2_fused_dense_load_score_k_fp8_v_fp8_elected(
                                        score_k_fp8,
                                        g.k_fp8,
                                        k_tile_coord,
                                        v_fp8,
                                        g.v_fp8,
                                        coord<cta2_fused_dense_v_fp8_tile>{
                                            batch_idx,
                                            owner_idx * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        k_local_ready
                                    );
                                } else {
                                    coord<cta2_fused_dense_v_tile>
                                        v_tile_coord = {
                                            batch_idx,
                                            owner_idx * 2 + cta_rank,
                                            head_idx,
                                            0
                                    };
                                    cta2_fused_dense_load_score_k_fp8_v_elected(
                                        score_k_fp8,
                                        g.k_fp8,
                                        k_tile_coord,
                                        storage.ds,
                                        g.v,
                                        v_tile_coord,
                                        k_local_ready
                                    );
                                }
                            } else {
                                cta2_fused_dense_load_score_k_fp8_elected(
                                    score_k_fp8,
                                    g.k_fp8,
                                    k_tile_coord,
                                    k_local_ready
                                );
                            }
                        } else if constexpr (UseFp4DqDk) {
                            if constexpr (UseNvFp4Score) {
                                auto &score_k_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_k_fp4_tile *
                                >(&storage.k);
                                if constexpr (UseTmaVWithScoreK) {
                                    if constexpr (UseMxFp4Dp) {
                                        auto &v_dp =
                                            cta2_fused_dense_mxfp4_dp_v_tma_stage(
                                                storage.ds
                                            );
                                        auto &v_dp_scale =
                                            cta2_fused_dense_mxfp4_dp_v_scale_stage(
                                                storage.ds
                                            );
                                        const int v_scale_page =
                                            cta2_fused_dense_mxfp4_scale_page_index(
                                                batch_idx,
                                                owner_idx * 2 + cta_rank,
                                                head_idx,
                                                q_tile_count,
                                                g.q.rows()
                                            );
                                        cta2_fused_dense_load_score_k_fp4_v_mxfp4_elected(
                                            score_k_fp4,
                                            g.score_k_fp4,
                                            coord<
                                                cta2_fused_dense_score_k_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                owner_idx * 2 + cta_rank,
                                                0
                                            },
                                            v_dp,
                                            g.v_dp_mxfp4,
                                            coord<
                                                cta2_fused_dense_v_dp_mxfp4_tma_tile
                                            >{
                                                batch_idx,
                                                owner_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            v_dp_scale,
                                            g.v_dp_mxfp4_scale,
                                            v_scale_page,
                                            k_local_ready
                                        );
                                    } else {
                                        auto &v_fp8 = *reinterpret_cast<
                                            cta2_fused_dense_v_fp8_tile *
                                        >(&storage.ds);
                                        if constexpr (
                                            UseMixedFp8MxFp4Dp &&
                                            !UseFixedMixedDpScale
                                        ) {
                                            auto &v_scale =
                                                cta2_fused_dense_mixed_dp_v_scale_stage(
                                                    storage.ds
                                                );
                                            const int v_scale_page =
                                                cta2_fused_dense_mxfp4_scale_page_index(
                                                    batch_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    head_idx,
                                                    q_tile_count,
                                                    g.q.rows()
                                                );
                                            cta2_fused_dense_load_score_k_fp4_v_mixed_dp_elected(
                                                score_k_fp4,
                                                g.score_k_fp4,
                                                coord<
                                                    cta2_fused_dense_score_k_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    0
                                                },
                                                v_fp8,
                                                g.v_fp8,
                                                coord<
                                                    cta2_fused_dense_v_fp8_tile
                                                >{
                                                    batch_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                v_scale,
                                                g.v_dp_mxfp4_scale,
                                                v_scale_page,
                                                k_local_ready
                                            );
                                        } else {
                                            cta2_fused_dense_load_score_k_fp4_v_fp8_elected(
                                                score_k_fp4,
                                                g.score_k_fp4,
                                                coord<
                                                    cta2_fused_dense_score_k_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    0
                                                },
                                                v_fp8,
                                                g.v_fp8,
                                                coord<
                                                    cta2_fused_dense_v_fp8_tile
                                                >{
                                                    batch_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                k_local_ready
                                            );
                                        }
                                    }
                                } else {
                                    cta2_fused_dense_load_score_k_fp4_elected(
                                        score_k_fp4,
                                        g.score_k_fp4,
                                        coord<
                                            cta2_fused_dense_score_k_fp4_tile
                                        >{
                                            batch_idx,
                                            head_idx,
                                            owner_idx * 2 + cta_rank,
                                            0
                                        },
                                        k_local_ready
                                    );
                                }
                            } else {
                                auto &score_k_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_k_fp8_tile *
                                >(&storage.k);
                                coord<cta2_fused_dense_score_k_fp8_tile>
                                    k_tile_coord = {
                                        batch_idx,
                                        owner_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                };
                                if constexpr (UseTmaVWithScoreK) {
                                    if constexpr (UseEarlyRawN96Score) {
                                        auto &v_fp8 = *reinterpret_cast<
                                            cta2_fused_dense_v_fp8_tile *
                                        >(&storage.ds);
                                        auto &score_k_compact =
                                            cta2_fused_dense_early_compact_score_k_smem(
                                                storage.k
                                            );
                                        if (lane == 0) {
                                            tma::expect_bytes(
                                                k_local_ready,
                                                sizeof(score_k_fp4) +
                                                    sizeof(score_k_compact) +
                                                    sizeof(v_fp8)
                                            );
                                            tma::load_async<
                                                dim::DEPTH,
                                                cache_policy::NORMAL
                                            >(
                                                score_k_fp4,
                                                g.k_fp4,
                                                k_tile_coord,
                                                k_local_ready
                                            );
                                            tma::load_async<
                                                dim::ROW,
                                                cache_policy::NORMAL
                                            >(
                                                score_k_compact,
                                                g.score_k_fp4,
                                                coord<
                                                    cta2_fused_dense_score_k_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    0
                                                },
                                                k_local_ready
                                            );
                                            tma::load_async<
                                                dim::DEPTH,
                                                cache_policy::NORMAL
                                            >(
                                                v_fp8,
                                                g.v_fp8,
                                                coord<
                                                    cta2_fused_dense_v_fp8_tile
                                                >{
                                                    batch_idx,
                                                    owner_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                k_local_ready
                                            );
                                        }
                                    } else {
                                        coord<cta2_fused_dense_v_tile>
                                            v_tile_coord = {
                                                batch_idx,
                                                owner_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                        };
                                        cta2_fused_dense_load_score_k_fp8_v_elected(
                                            score_k_fp4,
                                            g.k_fp4,
                                            k_tile_coord,
                                            storage.ds,
                                            g.v,
                                            v_tile_coord,
                                            k_local_ready
                                        );
                                    }
                                } else {
                                    cta2_fused_dense_load_score_k_fp8_elected(
                                        score_k_fp4,
                                        g.k_fp4,
                                        k_tile_coord,
                                        k_local_ready
                                    );
                                }
                            }
                        } else {
                            coord<cta2_fused_dense_k_tile> k_tile_coord = {
                                batch_idx,
                                owner_idx * 2 + cta_rank,
                                head_idx,
                                0
                            };
                            if constexpr (UseTmaVWithScoreK) {
                                coord<cta2_fused_dense_v_tile>
                                    v_tile_coord = {
                                        batch_idx,
                                        owner_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                };
                                cta2_fused_dense_load_score_k_v_elected(
                                    storage.k,
                                    g.k,
                                    k_tile_coord,
                                    storage.ds,
                                    g.v,
                                    v_tile_coord,
                                    k_local_ready
                                );
                            } else {
                                cta2_fused_dense_load_score_k_elected(
                                    storage.k,
                                    g.k,
                                    k_tile_coord,
                                    k_local_ready
                                );
                            }
                        }
                    }
                } else if (physical_warp == 4 && lane == 0) {
                    if constexpr (UseFp8DqDk) {
                        auto &score_k_fp8 = *reinterpret_cast<
                            cta2_fused_dense_score_k_fp8_tile *
                        >(&storage.k);
                        const uint32_t expected_bytes =
                            sizeof(score_k_fp8) +
                            (UseTmaVWithScoreK
                                ? (UseFp8Dp
                                    ? sizeof(cta2_fused_dense_v_fp8_tile)
                                    : sizeof(cta2_fused_dense_v_tile))
                                : 0);
                        tma::expect_bytes(k_local_ready, expected_bytes);
                        coord<cta2_fused_dense_score_k_fp8_tile>
                            k_tile_coord = {
                                batch_idx,
                                owner_idx * 2 + cta_rank,
                                head_idx,
                                0
                        };
                        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                            score_k_fp8,
                            g.k_fp8,
                            k_tile_coord,
                            k_local_ready
                        );
                        if constexpr (UseTmaVWithScoreK) {
                            if constexpr (UseFp8Dp) {
                                auto &v_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_v_fp8_tile *
                                >(&storage.ds);
                                tma::load_async<
                                    dim::DEPTH,
                                    cache_policy::NORMAL
                                >(
                                    v_fp8,
                                    g.v_fp8,
                                    coord<cta2_fused_dense_v_fp8_tile>{
                                        batch_idx,
                                        owner_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    k_local_ready
                                );
                            } else {
                                tma::load_async<
                                    dim::DEPTH,
                                    cache_policy::NORMAL
                                >(
                                    storage.ds,
                                    g.v,
                                    coord<cta2_fused_dense_v_tile>{
                                        batch_idx,
                                        owner_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    k_local_ready
                                );
                            }
                        }
                    } else if constexpr (UseFp4DqDk) {
                        auto &score_k_fp4 = *reinterpret_cast<
                            cta2_fused_dense_score_k_fp8_tile *
                        >(&storage.k);
                        const uint32_t expected_bytes =
                            sizeof(score_k_fp4) +
                            (UseTmaVWithScoreK
                                ? sizeof(cta2_fused_dense_v_tile)
                                : 0);
                        tma::expect_bytes(k_local_ready, expected_bytes);
                        coord<cta2_fused_dense_score_k_fp8_tile>
                            k_tile_coord = {
                                batch_idx,
                                owner_idx * 2 + cta_rank,
                                head_idx,
                                0
                        };
                        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                            score_k_fp4,
                            g.k_fp4,
                            k_tile_coord,
                            k_local_ready
                        );
                        if constexpr (UseTmaVWithScoreK) {
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                storage.ds,
                                g.v,
                                coord<cta2_fused_dense_v_tile>{
                                    batch_idx,
                                    owner_idx * 2 + cta_rank,
                                    head_idx,
                                    0
                                },
                                k_local_ready
                            );
                        }
                    } else {
                        tma::expect_bytes(k_local_ready, sizeof(storage.k));
                        coord<cta2_fused_dense_k_tile> k_tile_coord = {
                            batch_idx,
                            owner_idx * 2 + cta_rank,
                            head_idx,
                            0
                        };
                        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                            storage.k,
                            g.k,
                            k_tile_coord,
                            k_local_ready
                        );
                    }
                }
            } else {
                rt_bf<16, kB300QKDim> k_reg;
                warp::load<dim::DEPTH>(
                    k_reg,
                    g.k,
                    {
                        batch_idx,
                        owner_idx * 16 + cta_rank * 8 + compute_warp,
                        head_idx,
                        0
                    }
                );
                auto k_smem = storage.k.template subtile<16, kB300QKDim>(
                    {compute_warp, 0}
                );
                warp::store(k_smem, k_reg);
            }
            if constexpr (WideDqKGlobalToShared) {
                if constexpr (UseFp8DqDk) {
                    auto &dq_b_fp8 = *reinterpret_cast<
                        cta2_fused_dense_dq_b_fp8_tile *
                    >(&storage.dq_b);
                    group<8>::load<dim::DEPTH, true>(
                        dq_b_fp8,
                        g.k_fp8,
                        coord<cta2_fused_dense_dq_b_fp8_tile>{
                            batch_idx,
                            owner_idx,
                            head_idx,
                            cta_rank
                        }
                    );
                } else if constexpr (UseFp4DqDk) {
                    if constexpr (UsePureMxFp4DqDk) {
#if TK_FA4_BWD_PURE_MXFP4_ALIGNED_MXF8F6F4_DQ
                        auto &dq_k_mxfp4 = *reinterpret_cast<
                            cta2_fused_dense_dq_k_mxfp4_active_tile *
                        >(&storage.dq_b);
                        group<8>::load<dim::DEPTH, true>(
                            dq_k_mxfp4,
                            g.k_fp4,
                            coord<cta2_fused_dense_dq_k_mxfp4_active_tile>{
                                batch_idx,
                                owner_idx,
                                head_idx,
                                cta_rank
                            }
                        );
#else
                        auto &dq_k_mxfp4_tma = *reinterpret_cast<
                            cta2_fused_dense_dq_k_mxfp4_tma_tile *
                        >(&storage.dq_b);
                        group<8>::load<dim::ROW, true>(
                            dq_k_mxfp4_tma,
                            g.k_dq_mxfp4,
                            coord<cta2_fused_dense_dq_k_mxfp4_tma_tile>{
                                batch_idx,
                                head_idx,
                                cta_rank,
                                owner_idx
                            }
                        );
#endif
                    } else {
                        auto &dq_b_fp4 = *reinterpret_cast<
                            cta2_fused_dense_dq_b_fp4_tile *
                        >(&storage.dq_b);
                        group<8>::load<dim::DEPTH, true>(
                            dq_b_fp4,
                            g.k_fp4,
                            coord<cta2_fused_dense_dq_b_fp4_tile>{
                                batch_idx,
                                owner_idx,
                                head_idx,
                                cta_rank
                            }
                        );
                    }
                } else if constexpr (UseSlicedFp32PForDs) {
                    cta2_fused_dense_load_scaled_dq_k(
                        storage.dq_b,
                        g.k,
                        coord<cta2_fused_dense_dq_b_tile>{
                            batch_idx,
                            owner_idx,
                            head_idx,
                            cta_rank
                        },
                        g.scale
                    );
                } else {
                    group<8>::load<dim::DEPTH, true>(
                        storage.dq_b,
                        g.k,
                        coord<cta2_fused_dense_dq_b_tile>{
                            batch_idx,
                            owner_idx,
                            head_idx,
                            cta_rank
                        }
                    );
                }
            } else {
                rt_bf<32, 96> k_reg;
                warp::load<dim::DEPTH>(
                    k_reg,
                    g.k,
                    {
                        batch_idx,
                        owner_idx * 8 + compute_warp,
                        head_idx,
                        cta_rank
                    }
                );
                auto k_smem = storage.dq_b.template subtile<32, 96>(
                    {compute_warp, 0}
                );
                warp::store(k_smem, k_reg);
            }
            if constexpr (UseTmaScoreK) {
                if (physical_warp == 4) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        k_local_ready,
                        owner_once_phase
                    );
                }
            } else {
                asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
                warp::arrive(k_local_ready);
            }
            if (physical_warp == 4 && lane == 0) {
                if constexpr (!UseTmaScoreK) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        k_local_ready,
                        owner_once_phase
