            }

            int iteration = 0;
            int compute_phase = owner_phase;
            for (
                int q_tile_idx = first_dense_q_tile;
                q_tile_idx < q_tile_count;
                q_tile_idx += q_tile_step,
                ++iteration,
                ++compute_stats_iteration
