                auto &main = storage.phase.main;
                cta2_fused_dense_stats_vec lse_vec;
                float lse_x32_stage0[32];
                const int x32_column_group =
                    compute_warp < 4 ? 32 : 0;
                if constexpr (UseX32TmemComputeLayout) {
                } else if constexpr (UseLongSeqStatsCache) {
                    const size_t stats_offset =
                        CarryDirectStatsOffset
                            ? carried_direct_stats_offset
                            : (static_cast<size_t>(batch_idx) *
                                    g.lse_log2.depth() +
                                head_idx) *
                                    g.seq_len +
                                q_tile_idx * 128;
                    cta2_role_split_load_stats_global_direct(
                        lse_vec,
                        g.lse_log2.raw_ptr + stats_offset
                    );
                } else if constexpr (UseRoleStatsCache) {
                    if constexpr (!DeferFp4DpsumAfterScoreFanout) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            storage.stats_ready,
                            phase
                        );
                        if constexpr (PipelineLsePrefetch) {
                            auto &lse_stage = phase == 0
                                ? storage.stats.lse_log2
                                : storage.lse_log2_next;
                            if constexpr (UseDirectStatsLoads) {
                                cta2_role_split_load_stats_direct(
                                    lse_vec,
                                    lse_stage
                                );
                            } else {
                                warp::load(lse_vec, lse_stage);
                            }
                        } else {
                            warp::load(lse_vec, storage.stats.lse_log2);
                        }
                    }
                } else {
                    if constexpr (UseDirectStatsLoads) {
                        const size_t stats_offset =
                            CarryDirectStatsOffset
                                ? carried_direct_stats_offset
                                : (static_cast<size_t>(batch_idx) *
                                        g.lse_log2.depth() +
                                    head_idx) *
                                        g.seq_len +
                                    q_tile_idx * 128;
                        cta2_role_split_load_stats_global_direct(
                            lse_vec,
                            g.lse_log2.raw_ptr + stats_offset
                        );
                    } else {
                        warp::load(
                            lse_vec,
                            g.lse_log2,
                            {batch_idx, head_idx, 0, q_tile_idx}
                        );
                    }
                }
                uint32_t score_consumed_local_address = 0;
                uint32_t p_tmem_ready_address = 0;
                uint32_t dp_operands_ready_address = 0;
                int score_iteration_value = iteration;
                int score_iteration_threshold = 2;
                if constexpr (
                    UseLowpDp && PrecomputePostScoreFanoutAddresses
                ) {
                    // The FP8 dP/dV path has shortened the tensor producer
                    // enough that score fanout is exposed again.  Prepare the
                    // score-independent consumer addresses before joining the
                    // fanout, matching the forward pipeline's convention of
                    // doing descriptor work while the tensor result is in
                    // flight.
                    score_consumed_local_address =
                        static_cast<uint32_t>(
                            __cvta_generic_to_shared(&score_consumed_local)
                        );
                    if (compute_warp == 0) {
                        p_tmem_ready_address = static_cast<uint32_t>(
                            __cvta_generic_to_shared(&p_tmem_ready)
                        );
                        dp_operands_ready_address =
                            cta2_fused_dense_map_cluster_semaphore(
                                dp_operands_ready,
                                0
                            );
