                        ""
                        : "+r"(score_consumed_local_address),
                          "+r"(p_tmem_ready_address),
                          "+r"(dp_operands_ready_address)
                    );
                }
                if constexpr (
                    UseLowpDp && PrecomputeScoreIterationDeltaUnderFanout
                ) {
                    asm volatile(
                        "add.s32 %0, %1, -2;"
                        : "=r"(score_iteration_value)
                        : "r"(iteration)
                    );
                    score_iteration_threshold = 0;
                }
                if constexpr (UseFp4ComputeLeaderScoreFanout) {
                    if constexpr (
                        UseLowpDp &&
                        !(UsePureMxFp4DqDk &&
                          TK_FA4_BWD_PURE_MXFP4_LEADER_SCORE_FANOUT)
                    ) {
                        // The statistics warp normally publishes through two
                        // score leaders, which then fan the tensor completion
                        // out through named barrier 5.  With the shorter FP8
                        // dP producer that extra hop is exposed.  Join the
                        // already-early statistics publication once, then let
                        // every consumer observe score_done directly.
                        asm volatile("bar.sync 12, 288;" ::: "memory");
                        if constexpr (UseEarlyWinningScoreTmemWait) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                score_issued,
                                phase
                            );
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                score_done,
                                phase
                            );
                        }
                    } else if (compute_warp == 0 || compute_warp == 4) {
                        // The stats warp no longer participates in the score
                        // fanout barrier, so explicitly order its LSE publish
                        // before releasing either score-consumer leader.
                        asm volatile("bar.sync 12, 96;" ::: "memory");
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_done,
                            phase
                        );
                        asm volatile("bar.arrive 5, 256;" ::: "memory");
                    } else {
                        asm volatile("bar.sync 5, 256;" ::: "memory");
                    }
                } else if constexpr (UseComputeScoreFanout) {
                    if constexpr (UseX32TmemComputeLayout) {
                        asm volatile("bar.sync 5, 320;" ::: "memory");
                    } else {
                        asm volatile("bar.sync 5, 288;" ::: "memory");
                    }
                } else {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        score_done,
                        phase
                    );
                }
                cta2_fused_dense_attn_reg p_reg;
                if constexpr (
                    ShiftOverlappingScoreHalfBeforeDpRelease &&
                    !UseNativeX32Lowp
