                cta2_fused_dense_attn_bf_reg p_bf;
                cta2_fused_dense_quarter_stats_vec dpsum_quarter;
                uint32_t p_x32_stage0[16];
                uint32_t p_x32_stage1[16];
                uint32_t ds_mxfp4_stage0[4];
                uint32_t ds_mxfp4_stage1[4];
                uint32_t ds_mxfp4_scale0;
                uint32_t ds_mxfp4_scale1;
#if TK_FA4_BWD_PURE_MXFP4_FUSED_P_SCALE_PUBLICATION || \
    TK_FA4_BWD_MXFP4_PV_INTERLEAVED_KBLOCKS
                uint32_t p_mxfp4_e8m0_pair = 0;
#endif
#if TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P
                uint32_t predicted_ds_e8m0_pair = 0;
