                                score_scale_log2e
                            );
                            warp::sub_col(p_reg, p_reg, lse_vec);
                            if (causal_iteration == cta_rank) {
                                cta2_role_split_apply_diagonal_causal_mask(
                                    p_reg,
                                    output_subtile
                                );
                            }
                            if (causal_iteration < cta_rank) {
                                if constexpr (UseSlicedFp32PForDs) {
                                    warp::neg_infty(p_reg);
                                } else {
                                    warp::zero(p_bf);
                                }
                            } else {
                                if constexpr (FusedExp2Fragment4First) {
                                    cta2_role_split_exp2_approx_pack_bf16_fragment4_first<
                                        UseSlicedFp32PForDs
                                    >(
                                        p_bf,
                                        p_reg
                                    );
                                } else {
                                    cta2_role_split_exp2_approx_pack_bf16<
                                        UseSlicedFp32PForDs
                                    >(
                                        p_bf,
                                        p_reg
                                    );
                                }
                            }
                            if constexpr (InterleaveSteadyScoreExpPairs) {
                                cta2_role_split_store_p_sliced<false>(
                                    p_tmem,
                                    p_reg,
                                    p_bf,
                                    lse_vec
                                );
                                tensor_store_wait();
                            }
                        }
                    } else {
                        warp::mul(
                            p_reg,
                            p_reg,
                            score_scale_log2e
                        );
                        if constexpr (PeelCausalPrefix) {
                            if (iteration >= 2) {
                                warp::sub_col(p_reg, p_reg, lse_vec);
                                cta2_role_split_exp2_approx_pack_bf16<
                                    UseSlicedFp32PForDs
                                >(
                                    p_bf,
                                    p_reg
                                );
                            } else {
                                if (causal_iteration == cta_rank) {
                                    cta2_role_split_apply_diagonal_causal_mask(
                                        p_reg,
                                        output_subtile
                                    );
                                }
                                warp::sub_col(p_reg, p_reg, lse_vec);
                                if (causal_iteration < cta_rank) {
                                    if constexpr (UseSlicedFp32PForDs) {
                                        warp::neg_infty(p_reg);
                                    } else {
                                        warp::zero(p_bf);
                                    }
                                } else {
                                    cta2_role_split_exp2_approx_pack_bf16<
                                        UseSlicedFp32PForDs
                                    >(
                                        p_bf,
                                        p_reg
                                    );
                                }
                            }
                        } else {
                            if constexpr (UseIterationCausalMask) {
                                if (causal_iteration == cta_rank) {
                                    cta2_role_split_apply_diagonal_causal_mask(
                                        p_reg,
                                        output_subtile
                                    );
                                }
                            } else if constexpr (IntegrateCausalFrontier) {
                                const int kv_tile_idx =
                                    2 * owner_idx + cta_rank;
                                if (q_tile_idx == kv_tile_idx) {
                                    cta2_role_split_apply_diagonal_causal_mask(
                                        p_reg,
                                        output_subtile
                                    );
                                }
                            }
                            warp::sub_col(p_reg, p_reg, lse_vec);
                            if constexpr (UseFusedExp2Pack) {
                                if (iteration < cta_rank) {
                                    if constexpr (UseSlicedFp32PForDs) {
                                        warp::neg_infty(p_reg);
                                    } else {
                                        warp::zero(p_bf);
                                    }
                                } else {
                                    cta2_role_split_exp2_approx_pack_bf16<
                                        UseSlicedFp32PForDs
                                    >(
                                        p_bf,
                                        p_reg
                                    );
                                }
                            } else {
                                if constexpr (UseFastExp2) {
                                    cta2_role_split_exp2_approx(p_reg);
                                } else {
                                    warp::exp2(p_reg, p_reg);
                                }
                                if constexpr (UseIterationCausalMask) {
                                    if (causal_iteration < cta_rank) {
                                        warp::zero(p_reg);
                                    }
                                } else if constexpr (
                                    IntegrateCausalFrontier
                                ) {
                                    if (
                                        q_tile_idx <
                                        2 * owner_idx + cta_rank
                                    ) {
                                        warp::zero(p_reg);
                                    }
                                } else if (
                                    q_tile_idx == first_dense_q_tile &&
                                    cta_rank == 1
                                ) {
                                    warp::zero(p_reg);
                                }
                                warp::copy(p_bf, p_reg);
                            }
                        }
                    }
                    if constexpr (
                        !InterleaveSteadyScoreExpPairs &&
                        (UseFusedTmemPAndDs || !PreloadDpsum)
                    ) {
                        if constexpr (UseSlicedFp32PForDs) {
                            {
                                auto &p_bf_quarter = *reinterpret_cast<
                                    cta2_fused_dense_attn_quarter_bf_reg *
                                >(&p_bf.tiles[0][0]);
                                if constexpr (UseFp8Pv) {
                                    cta2_role_split_exp_p_fp32_quarter<0>(
                                        p_reg
                                    );
                                } else {
                                    cta2_role_split_pack_p_fp32_quarter<0>(
                                        p_reg,
                                        p_bf_quarter
                                    );
                                }
                            }
                            {
                                auto &p_bf_quarter = *reinterpret_cast<
                                    cta2_fused_dense_attn_quarter_bf_reg *
                                >(&p_bf.tiles[0][2]);
                                if constexpr (UseFp8Pv) {
                                    cta2_role_split_exp_p_fp32_quarter<1>(
                                        p_reg
                                    );
                                } else {
                                    cta2_role_split_pack_p_fp32_quarter<1>(
                                        p_reg,
                                        p_bf_quarter
                                    );
                                }
                            }
                            {
                                if constexpr (UseFp8Pv) {
                                    auto &p_fp32_half = *reinterpret_cast<
                                        cta2_fused_dense_attn_half_reg *
                                    >(&p_reg.tiles[0][0]);
                                    cta2_fused_dense_attn_half_fp8_reg
                                        p_fp8_half;
                                    cta2_role_split_convert_p_f32_half_to_fp8<
                                        kCta2DenseFp8PvPScaleF32Delta
                                    >(
                                        p_fp8_half,
                                        p_fp32_half
                                    );
                                    auto p_half_tmem =
                                        p_fp8_tmem.template subtile<
                                            cta2_fused_dense_p_fp8_half_tt
                                        >(0);
                                    cta2_role_split_store_fp8_tmem_warp(
                                        p_half_tmem,
                                        p_fp8_half,
                                        output_subtile
                                    );
                                } else {
                                    auto &p_bf_half = *reinterpret_cast<
                                        cta2_fused_dense_attn_half_bf_reg *
                                    >(&p_bf.tiles[0][0]);
                                    auto p_half_tmem =
                                        p_tmem.template subtile<
                                            cta2_fused_dense_ds_half_tt
                                        >(0);
                                    group<8>::store_async(
                                        p_half_tmem,
                                        p_bf_half
                                    );
                                }
                            }
                            if constexpr (
                                OverlapFirstDpsumQuarterWithSecondPStore
                            ) {
                                cta2_role_split_load_stats_direct_quarter<0>(
                                    dpsum_quarter,
                                    storage.stats.dpsum
                                );
                            }
                            {
                                auto &p_bf_quarter = *reinterpret_cast<
                                    cta2_fused_dense_attn_quarter_bf_reg *
                                >(&p_bf.tiles[0][4]);
                                if constexpr (UseFp8Pv) {
                                    cta2_role_split_exp_p_fp32_quarter<2>(
                                        p_reg
                                    );
                                } else {
                                    cta2_role_split_pack_p_fp32_quarter<2>(
                                        p_reg,
                                        p_bf_quarter
                                    );
                                }
                            }
                            {
                                auto &p_bf_quarter = *reinterpret_cast<
                                    cta2_fused_dense_attn_quarter_bf_reg *
                                >(&p_bf.tiles[0][6]);
                                if constexpr (UseFp8Pv) {
                                    cta2_role_split_exp_p_fp32_quarter<3>(
                                        p_reg
                                    );
                                } else {
                                    cta2_role_split_pack_p_fp32_quarter<3>(
                                        p_reg,
                                        p_bf_quarter
                                    );
                                }
                            }
                            {
                                if constexpr (UseFp8Pv) {
                                    auto &p_fp32_half = *reinterpret_cast<
                                        cta2_fused_dense_attn_half_reg *
                                    >(&p_reg.tiles[0][4]);
                                    cta2_fused_dense_attn_half_fp8_reg
                                        p_fp8_half;
                                    cta2_role_split_convert_p_f32_half_to_fp8<
                                        kCta2DenseFp8PvPScaleF32Delta
                                    >(
                                        p_fp8_half,
                                        p_fp32_half
                                    );
                                    auto p_half_tmem =
                                        p_fp8_tmem.template subtile<
                                            cta2_fused_dense_p_fp8_half_tt
                                        >(64);
                                    cta2_role_split_store_fp8_tmem_warp(
                                        p_half_tmem,
                                        p_fp8_half,
                                        output_subtile
                                    );
                                } else {
                                    auto &p_bf_half = *reinterpret_cast<
                                        cta2_fused_dense_attn_half_bf_reg *
                                    >(&p_bf.tiles[0][4]);
                                    auto p_half_tmem =
                                        p_tmem.template subtile<
                                            cta2_fused_dense_ds_half_tt
                                        >(64);
                                    group<8>::store_async(
                                        p_half_tmem,
                                        p_bf_half
                                    );
                                }
                            }
                        } else {
                            group<8>::store_async(p_tmem, p_bf);
                        }
                        tensor_store_wait();
                    }
                    if constexpr (!UseFusedTmemPAndDs) {
                        auto p_smem = main.p.p.template subtile<16, 128>(
                            {output_subtile, 0}
                        );
                        warp::store(p_smem, p_bf);
                    }
                }
                }

                cta2_fused_dense_stats_vec dpsum_vec;
                cta2_fused_dense_attn_half_reg dp_half;
                cta2_fused_dense_attn_quarter_reg dp_first_quarter;
                float *split_direct_dpsum_src = nullptr;
                float dpsum_x32_stage0[32];
                uint32_t dpsum_half_x32_stage0[16];
                if constexpr (PreloadDpsum) {
                    if constexpr (DeferFp4DpsumAfterScoreFanout) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            storage.stats_ready,
                            phase
                        );
                    }
                    if constexpr (
                        UseX32TmemComputeLayout || UseNativeX32Lowp
                    ) {
                        if constexpr (
                            !(UsePureMxFp4DqDk &&
                              TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM)
                        ) {
                            if constexpr (UseHalfDpsum) {
                                auto &dpsum_half = *reinterpret_cast<
                                    sv_hf<128> *
                                >(&storage.stats.dpsum);
                                cta2_role_split_load_half_stats_x32_stage_shared(
                                    dpsum_half_x32_stage0,
                                    dpsum_half.data + x32_column_group
                                );
                            } else {
                                cta2_role_split_load_stats_x32_stage_shared(
                                    dpsum_x32_stage0,
                                    storage.stats.dpsum.data +
                                        x32_column_group
                                );
                            }
                        }
                    } else if constexpr (UseLongSeqStatsCache) {
                        const int stats_stage =
                            compute_stats_iteration & 1;
                        auto &stats = stats_stage == 0
                            ? storage.stats
                            : storage.stats_next;
                        cta2_role_split_load_stats_direct(
                            dpsum_vec,
                            stats.dpsum
                        );
                    } else if constexpr (UseRoleStatsCache) {
                        if constexpr (UseDirectStatsLoads) {
                            if constexpr (UseSlicedFp32PForDs) {
                                if constexpr (
                                    !OverlapFirstDpsumQuarterWithSecondPStore
                                ) {
                                    cta2_role_split_load_stats_direct_quarter<0>(
                                        dpsum_quarter,
                                        storage.stats.dpsum
                                    );
                                }
                            } else {
                                cta2_role_split_load_stats_direct(
                                    dpsum_vec,
                                    storage.stats.dpsum
                                );
                            }
                        } else {
                            warp::load(dpsum_vec, storage.stats.dpsum);
                            warp::arrive(storage.stats_consumed);
                        }
                    } else {
                        if constexpr (UseDirectStatsLoads) {
                            const size_t stats_offset =
                                CarryDirectStatsOffset
                                    ? carried_direct_stats_offset
                                    : (static_cast<size_t>(batch_idx) *
                                            g.dpsum.depth() +
                                        head_idx) *
                                            g.seq_len +
                                        q_tile_idx * 128;
                            if constexpr (
                                SplitDirectDpsumAcrossDpDoneWait
                            ) {
                                split_direct_dpsum_src =
                                    g.dpsum.raw_ptr + stats_offset;
                                cta2_role_split_load_stats_global_direct_range<
                                    0,
                                    4
                                >(
                                    dpsum_vec,
                                    split_direct_dpsum_src
                                );
                            } else {
                                cta2_role_split_load_stats_global_direct(
                                    dpsum_vec,
                                    g.dpsum.raw_ptr + stats_offset
                                );
                            }
                        } else {
                            warp::load(
                                dpsum_vec,
                                g.dpsum,
                                {batch_idx, head_idx, 0, q_tile_idx}
                            );
                        }
                    }
                }
                if constexpr (
                    UseLowpDp && SplitDvDkReady && BulkDoDvStage
                ) {
                    // W12 issued dP before it can observe this credit.  Both
                    // dO layouts are immutable, so the same deterministic
                    // issue stream can enqueue dV immediately after dP while
                    // the compute warps wait for the dP result.
                    if constexpr (!UseMxFp4Dv) {
                        if (physical_warp == 4 && lane == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                native_x32_p_ready,
                                phase
                            );
                            ::kittens::tma::cluster::arrive(
                                dv_operands_ready,
                                0
                            );
                        }
                    }
                }
                if constexpr (PreunpackFirstWinningPStage) {
                    cta2_role_split_preunpack_p_fp8_x32_stage(
                        p_x32_stage0
                    );
                }
                if constexpr (!UseStreamedMixedDpN64) {
                    if constexpr (UseEarlyMixedDpTmemWait) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            do_ready,
                            phase
                        );
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dp_done,
                            phase
                        );
                    }
                }
                if constexpr (UseMxFp4Dv) {
                    // The fused preprocessing pass already emitted the
                    // forward-compatible payload and complete scale page.
                    // Their grouped load finished before dP could commit, so
                    // only the existing P-production dependency remains.
                    if (physical_warp == 4 && lane == 0) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            native_x32_p_ready,
                            phase
                        );
                        ::kittens::tma::cluster::arrive(
                            dv_operands_ready,
                            0
                        );
                    }
                }
                if constexpr (
                    UseFp8Pv && !UseLowpDp &&
                    SplitDvDkReady && BulkDoDvStage
                ) {
                    if (physical_warp == 4 && lane == 0) {
                        auto &do_fp8_stage =
                            cta2_fused_dense_fp8_do_stage(main.dout);
                        tma::expect_bytes(
                            do_source_loaded,
                            sizeof(do_fp8_stage)
                        );
                        tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                            do_fp8_stage,
                            g.dout_fp8,
                            coord<cta2_fused_dense_do_fp8_tile>{
                                batch_idx,
                                q_tile_idx,
                                head_idx,
                                cta_rank
                            },
                            do_source_loaded
                        );
                    }
                }
                if constexpr (
                    PipelineFirstDpQuarterLoads && !UseNativeX32Lowp
                ) {
                    cta2_role_split_issue_dp_fp32_quarter<0>(
                        dp_first_quarter,
                        active_dp_tmem
                    );
                } else if constexpr (
                    PreissueFirstDpHalfBeforeQdoWait &&
                    !UseNativeX32Lowp
                ) {
                    cta2_role_split_issue_dp_fp32_half<0>(
                        dp_half,
                        active_dp_tmem
                    );
                }
                if constexpr (
                    SplitDirectDpsumAcrossDpDoneWait &&
                    !UseX32TmemComputeLayout &&
                    !UseLongSeqStatsCache
                ) {
                    cta2_role_split_load_stats_global_direct_range<4, 8>(
                        dpsum_vec,
                        split_direct_dpsum_src
                    );
                }
                if constexpr (!PreloadDpsum) {
                    warp::load(
                        dpsum_vec,
                        g.dpsum,
                        {batch_idx, head_idx, 0, q_tile_idx}
                    );
                }
                if constexpr (SplitDvDkReady) {
                    if constexpr (BulkDoDvStage) {
                        if constexpr (UseLowpDp) {
                            // Publication happened before dp_done above.
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                qdo_exchange_done,
                                phase
                            );
                        }
                        if constexpr (UseLowpDp) {
                        } else if constexpr (!UseFp8Pv) {
                            if (physical_warp == 4 && lane == 0) {
                            constexpr uint32_t kHalfElements = 64 * 64;
                            constexpr uint32_t kHalfBytes =
                                kHalfElements * sizeof(bf16);
                            static_assert(
                                sizeof(cta2_fused_dense_do_exchange_tile) ==
                                    kHalfBytes
                            );
                            auto &do_normal =
                                *reinterpret_cast<st_bf<128, 64> *>(
                                    &main.dout
                                );
                            ::kittens::tma::cluster::expect_bytes(
                                do_source_loaded,
                                kHalfBytes,
                                cta_rank
                            );
                            cta2_role_split_store_peer_bulk_after_cta_fence(
                                reinterpret_cast<void *>(
                                    &do_normal.data[
                                        (cta_rank ^ 1) * kHalfElements
                                    ]
                                ),
                                reinterpret_cast<void *>(
                                    &storage.qdo_phase.qdo.dout
                                ),
                                kHalfBytes,
                                cta_rank,
                                do_source_loaded
                            );
                            if constexpr (
                                !RelayDoDvCompletionViaExchangeWarp
                            ) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    do_source_loaded,
                                    phase
                                );
                                if constexpr (UseX32TmemComputeLayout) {
                                    cta2_fused_dense_role_wait<
                                        TimeoutAllRoleWaits
                                    >(
                                        p_tmem_ready,
                                        phase
                                    );
                                }
                                if constexpr (SingleOwnerCluster) {
                                    ::kittens::tma::cluster::arrive(
                                        owner_output_loaded,
                                        0
                                    );
                                } else if constexpr (
                                    CacheRoleClusterAddresses &&
                                    !UseX32TmemComputeLayout
                                ) {
                                    cta2_fused_dense_cluster_arrive_mapped(
                                        dv_operands_ready_cluster_address
                                    );
                                } else {
                                    ::kittens::tma::cluster::arrive(
                                        dv_operands_ready,
                                        0
                                    );
                                }
                            }
                            }
                        } else if (physical_warp == 4 && lane == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                do_source_loaded,
                                phase
                            );
                            if constexpr (UseNativeX32Lowp) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    native_x32_p_ready,
                                    phase
                                );
                            } else if constexpr (
                                UseX32TmemComputeLayout
                            ) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    p_tmem_ready,
                                    phase
                                );
                            }
                            ::kittens::tma::cluster::arrive(
                                dv_operands_ready,
                                0
                            );
                        }
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            qdo_exchange_done,
                            phase
                        );
                        auto &qdo_exchange = storage.qdo_phase.qdo;
                        const int source_row = compute_warp & 3;
                        rt_bf<16, 64> do_half;
                        if constexpr (BranchlessDoSourceBaseSelect) {
                            auto local_source =
                                main.dout.template subtile<16, 64>(
                                    {source_row, cta_rank}
                                );
                            auto peer_source =
                                qdo_exchange.dout.template subtile<16, 64>(
                                    {source_row, 0}
                                );
                            cta2_role_split_load_do_half_branchless_base_select(
                                do_half,
                                local_source,
                                peer_source,
                                (compute_warp >> 2) == cta_rank
                            );
                        } else if constexpr (BranchlessDoSourceLoad) {
                            auto local_source =
                                main.dout.template subtile<16, 64>(
                                    {source_row, cta_rank}
                                );
                            auto peer_source =
                                qdo_exchange.dout.template subtile<16, 64>(
                                    {source_row, 0}
                                );
                            cta2_role_split_load_do_half_branchless(
                                do_half,
                                local_source,
                                peer_source,
                                (compute_warp >> 2) == cta_rank
                            );
                        } else if ((compute_warp >> 2) == cta_rank) {
                            auto do_source =
                                main.dout.template subtile<16, 64>(
                                    {source_row, cta_rank}
                                );
                            warp::load(do_half, do_source);
                        } else {
                            auto do_source =
                                qdo_exchange.dout.template subtile<16, 64>(
                                    {source_row, 0}
                                );
                            warp::load(do_half, do_source);
                        }
                        if constexpr (UseNamedDoSourceBarrier) {
                            asm volatile("bar.sync 4, 256;" ::: "memory");
                        } else {
                            warp::arrive(do_source_loaded);
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                do_source_loaded,
                                phase
                            );
                        }
                        auto &do_normal =
                            *reinterpret_cast<st_bf<128, 64> *>(
                                &main.dout
                            );
                        auto do_smem = do_normal.template subtile<16, 64>(
                            {compute_warp, 0}
                        );
                        warp::store(do_smem, do_half);
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        if constexpr (AsymmetricDvPublish) {
                            if (physical_warp == 4) {
                                asm volatile(
                                    "bar.sync 1, 256;"
                                    ::: "memory"
                                );
                            } else {
                                asm volatile(
                                    "bar.arrive 1, 256;"
                                    ::: "memory"
                                );
                            }
                            if (physical_warp == 4 && lane == 0) {
                                if constexpr (
                                    CacheRoleClusterAddresses &&
                                    !UseX32TmemComputeLayout
                                ) {
                                    cta2_fused_dense_cluster_arrive_mapped(
                                        dv_operands_ready_cluster_address
                                    );
                                } else {
                                    ::kittens::tma::cluster::arrive(
                                        dv_operands_ready,
                                        0
                                    );
                                }
                            }
                        } else {
                            asm volatile("bar.sync 1, 256;" ::: "memory");
                            if (physical_warp == 4 && lane == 0) {
                                if constexpr (SingleOwnerCluster) {
                                    ::kittens::tma::cluster::arrive(
                                        owner_output_loaded,
                                        0
                                    );
                                } else if constexpr (
                                    CacheRoleClusterAddresses &&
                                    !UseX32TmemComputeLayout
                                ) {
                                    cta2_fused_dense_cluster_arrive_mapped(
                                        dv_operands_ready_cluster_address
                                    );
                                } else {
                                    ::kittens::tma::cluster::arrive(
                                        dv_operands_ready,
                                        0
                                    );
                                }
                            }
                        }
                    }
                }
                rt_bf<16, 64> dq_a_local_preload;
                rt_bf<16, 64> dq_a_peer_preload;
                cta2_fused_dense_attn_bf_reg ds_bf;
                rt_fp8e4m3<16, 128> ds_lowp_reg;
                if constexpr (UseNativeX32Lowp) {
                    const uint32_t physical_row =
                        static_cast<uint32_t>(32 * (compute_warp & 3));
                    const uint32_t dp_row_address =
                        (UseStreamedMixedDpN64
                            ? streamed_dp_tmem.addr
                            : active_dp_tmem.addr) +
                        (physical_row << 16);
                    uint32_t dp_x32_stage0[32];
                    uint32_t dp_x32_stage1[32];
                    if constexpr (UseStreamedMixedDpN64) {
                        if (x32_column_group == 0) {
                            if (compute_warp == 4) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dp_head_done, phase);
                            }
                            // Reuse the cohort's post-load barrier as a
                            // leader-to-followers issue fanout.  Named
                            // barriers reset between the two rendezvous.
                            asm volatile(
                                "bar.sync 10, 128;"
                                ::: "memory"
                            );
                        } else {
                            // The streamed producer publishes the second
                            // global-N64 issue on dp_done.  do_ready is the
                            // early marker for the unsplit N128 path only.
                            if (compute_warp == 0) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dp_done, phase);
                            }
                            asm volatile(
                                "bar.sync 9, 128;"
                                ::: "memory"
                            );
                        }
                        cta2_fused_dense_load_tmem_x32(
                            dp_x32_stage0,
                            dp_row_address
                        );
                        cta2_fused_dense_load_tmem_x32(
                            dp_x32_stage1,
                            dp_row_address + 32
                        );
                    } else {
                        cta2_fused_dense_load_tmem_x32(
                            dp_x32_stage0,
                            dp_row_address + x32_column_group
                        );
                        cta2_fused_dense_load_tmem_x32(
                            dp_x32_stage1,
                            dp_row_address + x32_column_group + 64
