                    }
                    if constexpr (UseStreamedMixedDpN64) {
                        static_assert(
                            EnforceDpTmemConsumerRelease &&
                            SplitDpTmemConsumerRelease,
                            "streamed dP requires cohort-scoped TMEM release"
                        );
                        // All four cohort warps have now issued both LDTM
                        // operations.  Publish page reuse before waiting for
                        // the register results: the TMEM scoreboard preserves
                        // read-before-write ordering against the following
                        // N64 MMA, while tensor_load_wait remains the local
                        // value-readiness proof for dS construction.
                        if (compute_warp < 4) {
                            asm volatile(
                                "bar.sync 9, 128;"
                                ::: "memory"
