                        } else {
                            asm volatile(
                                "bar.sync 10, 128;"
                                ::: "memory"
                            );
                        }
                        if (compute_warp == 4 && lane == 0) {
                            ::kittens::tma::cluster::arrive(
                                dp_head_consumed,
                                0
