                    if constexpr (UsePureMxFp4DqDk) {
#if TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P
                        const uint8_t predicted_source_e8m0_0 =
                            static_cast<uint8_t>(
                                predicted_ds_e8m0_pair & 0xffu
                            );
                        const uint8_t predicted_source_e8m0_1 =
                            static_cast<uint8_t>(
                                (predicted_ds_e8m0_pair >> 8) & 0xffu
                            );
#endif
                        cta2_role_split_make_native_x32_ds_stage_mxfp4_dual(
                            p_x32_stage0,
                            dp_x32_stage0,
#if TK_FA4_BWD_PURE_MXFP4_STREAM_DUAL_DPSUM
                            storage.stats.dpsum.data + x32_column_group,
#else
                            dpsum_x32_stage0,
#endif
                            p_x32_stage1,
                            dp_x32_stage1,
                            storage.stats.dpsum.data +
                                x32_column_group + 64,
#if TK_FA4_BWD_PURE_MXFP4_PREDICT_DS_SCALE_FROM_P
                            predicted_source_e8m0_0,
                            predicted_source_e8m0_1,
