                            ds_mxfp4_stage0,
                            ds_mxfp4_scale0,
                            ds_mxfp4_stage1,
                            ds_mxfp4_scale1
                        );
                        warp::arrive(storage.stats_consumed);
                    } else
#endif
                    {
                        if constexpr (UsePureMxFp4DqDk) {
                            cta2_role_split_make_native_x32_ds_stage_mxfp4(
                                p_x32_stage0,
                                dp_x32_stage0,
