                                } else {
                                    asm volatile(
                                        "bar.sync 10, 128;"
                                        ::: "memory"
                                    );
                                }
                            }
                            if (
                                (compute_warp == 0 || compute_warp == 4) &&
                                lane == 0
                            ) {
                                ::kittens::tma::cluster::arrive(
                                    score_consumed,
                                    0
                                );
                            }
                        } else {
                            asm volatile("bar.sync 9, 256;" ::: "memory");
                            if (physical_warp == 4 && lane == 0) {
                                ::kittens::tma::cluster::arrive(
                                    score_consumed,
                                    0
                                );
                            }
                        }
                    }
                    warp::sub_col(dp_reg, dp_reg, dpsum_vec);
                    if constexpr (
                        UseDirectStatsLoads && UseRoleStatsCache &&
                        !UseLongSeqStatsCache
                    ) {
                        warp::arrive(storage.stats_consumed);
                    }
                    if constexpr (UsePackedBf16DsProduct) {
                        cta2_fused_dense_attn_bf_reg dp_bf;
                        warp::copy(dp_bf, dp_reg);
                        warp::mul(ds_bf, p_bf, dp_bf);
                    } else {
                        cta2_fused_dense_attn_reg ds_reg;
                        if constexpr (UseBitwisePExpansion) {
                            cta2_role_split_expand_bf16_bits(ds_reg, p_bf);
                        } else {
                            warp::copy(ds_reg, p_bf);
                        }
                        warp::mul(ds_reg, ds_reg, dp_reg);
                        warp::copy(ds_bf, ds_reg);
                    }
                    if constexpr (RetainDsExchange && !DirectDsHalfStore) {
                        if constexpr (RetainDsLocal) {
                            cta2_role_split_select_ds_half(
                                dq_a_local_preload,
                                ds_bf,
                                cta_rank
                            );
                        }
                        cta2_role_split_select_ds_half(
                            dq_a_peer_preload,
                            ds_bf,
                            cta_rank ^ 1
                        );
                    }
                    if constexpr (
                        !UseLowpDqDk &&
                        (UseFusedTmemPAndDs || !PreloadDpsum)
                    ) {
                        group<8>::store_async(ds_tmem, ds_bf);
                        tensor_store_wait();
                        tensor_before_thread_sync();
                    }
                    if constexpr (!UseFusedTmemPAndDs) {
                        auto ds_smem = storage.ds.template subtile<16, 128>(
                            {output_subtile, 0}
                        );
                        warp::store(ds_smem, ds_bf);
                    }
                }
                }
                if constexpr (UseLowpDqDk && SplitDqTmemAndSharedHandoff) {
                    // main.p remains the previous dQ shared operand until its
                    // TMEM consumer has taken the complete tile.
                    if (have_previous_dq_shared_read) {
                        if constexpr (DistributedDqSharedReadWait) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_shared_read_done,
                                previous_dq_shared_read_phase
                            );
                        } else {
                            if (physical_warp == 4) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    dq_shared_read_done,
                                    previous_dq_shared_read_phase
                                );
                            }
                            asm volatile(
                                "bar.sync 11, 256;"
                                ::: "memory"
                            );
                        }
                    }
                }
                if constexpr (
                    UseLowpDqDk &&
                    (UseX32TmemComputeLayout || UseNativeX32Lowp)
                ) {
                    static_assert(
                        UseFp8Pv,
                        "native x32 low-precision publication is specialized for FP8 P/dO"
                    );
                    const int row_base = 32 * (compute_warp & 3);
                    if constexpr (UsePureMxFp4DqDk) {
                        auto &dk_ds_mxfp4 =
                            cta2_fused_dense_mxfp4_dk_ds_stage(storage);
                        auto &dq_a_mxfp4 = *reinterpret_cast<
                            cta2_fused_dense_dq_a_mxfp4_active_tile *
                        >(&main.p.p);
                        auto &dq_exchange_mxfp4 =
                            cta2_fused_dense_mxfp4_dq_exchange_stage(
                                storage
                            );
                        auto &dk_ds_scale =
                            cta2_fused_dense_mxfp4_dsdk_scale_stage(storage);
                        auto &dq_ds_scale0 =
                            cta2_fused_dense_mxfp4_dsdq_scale_stage<0>(
                                storage
                            );
                        auto &dq_ds_scale1 =
                            cta2_fused_dense_mxfp4_dsdq_scale_stage<1>(
                                storage
                            );
                        const int first_q_block = x32_column_group / 32;
                        const int second_q_block = first_q_block + 2;

                        // dK consumes dS in its native [key, query] view.
                        // Keep the exact same packed codes for dQ and only
                        // transpose their nibble positions after all eight
                        // producers have published the complete dS tile.
#if !TK_FA4_BWD_PURE_MXFP4_QUARTER_DUAL_DS || \
    TK_FA4_BWD_PURE_MXFP4_TRANSPOSE_DESCRIPTOR_DQ
                        cta2_role_split_store_nvfp4_smem_x32(
                            dk_ds_mxfp4,
                            ds_mxfp4_stage0,
                            row_base,
                            x32_column_group
                        );
                        cta2_role_split_store_nvfp4_smem_x32(
                            dk_ds_mxfp4,
                            ds_mxfp4_stage1,
                            row_base,
                            x32_column_group + 64
                        );
#endif
#if TK_FA4_BWD_PURE_NVFP4_DS
                        auto &nv_dk_scale0 =
                            cta2_fused_dense_nvfp4_ds_scale_stage<0>(
                                storage
                            );
                        auto &nv_dk_scale1 =
                            cta2_fused_dense_nvfp4_ds_scale_stage<1>(
                                storage
                            );
                        const uint32_t own_nv_scales =
                            (ds_mxfp4_scale0 & 0xffffu) |
                            (ds_mxfp4_scale1 << 16);
                        // Lower warps own odd Q32 blocks; publish their two
                        // block-16 pairs once.  The matching upper warp then
                        // interleaves even/odd Q blocks into two legal K64
                        // scale records and writes one word per key row.
                        if (compute_warp < 4 && lane == 0) {
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            asm volatile(
                                "st.shared.b32 [%0], %1;"
                                :: "r"(
                                       scratch_base +
                                       static_cast<uint32_t>(
                                           compute_warp * 4
                                       )
                                   ),
                                   "r"(own_nv_scales)
                                : "memory"
                            );
                        }
                        asm volatile("bar.sync 3, 256;" ::: "memory");
                        if (compute_warp >= 4) {
                            const int reader_warp = compute_warp & 3;
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            uint32_t odd_nv_scales;
                            asm volatile(
                                "ld.shared.b32 %0, [%1];"
                                : "=r"(odd_nv_scales)
                                : "r"(
                                      scratch_base +
                                      static_cast<uint32_t>(
                                          reader_warp * 4
                                      )
                                  )
                                : "memory"
                            );
                            const uint32_t first_k64_scales = __byte_perm(
                                own_nv_scales,
                                odd_nv_scales,
                                0x5410
                            );
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION != 1
                            const uint32_t second_k64_scales = __byte_perm(
                                own_nv_scales,
                                odd_nv_scales,
                                0x7632
                            );
#endif
                            cta2_role_split_store_mxfp4_scale_word(
                                nv_dk_scale0,
                                row_base + lane,
                                first_k64_scales
                            );
#if TK_FA4_BWD_PURE_NVFP4_DS_SHARED_SCALE_CALIBRATION != 1
                            cta2_role_split_store_mxfp4_scale_word(
                                nv_dk_scale1,
                                row_base + lane,
                                second_k64_scales
                            );
#endif
                        }

                        // Transpose only the scale coordinates.  Within one
                        // 32x16 rectangle all key rows share a scale, so a
                        // dQ row duplicates its selected byte across the two
                        // key-K16 groups covered by this producer warp.
                        auto &nv_dq_source0_lo =
                            cta2_fused_dense_nvfp4_ds_scale_stage<2>(
                                storage
                            );
                        auto &nv_dq_source0_hi =
                            cta2_fused_dense_nvfp4_ds_scale_stage<3>(
                                storage
                            );
                        auto &nv_dq_source1_lo =
                            cta2_fused_dense_nvfp4_ds_scale_stage<4>(
                                storage
                            );
                        auto &nv_dq_source1_hi =
                            cta2_fused_dense_nvfp4_ds_scale_stage<5>(
                                storage
                            );
                        auto &nv_dq_source_lo = cta_rank == 0
                            ? nv_dq_source0_lo
                            : nv_dq_source1_lo;
                        auto &nv_dq_source_hi = cta_rank == 0
                            ? nv_dq_source0_hi
                            : nv_dq_source1_hi;
                        auto &nv_dq_source = (compute_warp & 3) < 2
                            ? nv_dq_source_lo
                            : nv_dq_source_hi;
                        const uint32_t local_nv_scale_pair = cta_rank == 0
                            ? ds_mxfp4_scale0
                            : ds_mxfp4_scale1;
                        const uint32_t peer_nv_scale_pair = cta_rank == 0
                            ? ds_mxfp4_scale1
                            : ds_mxfp4_scale0;
                        const int nv_query_half_shift = (lane >> 4) * 8;
                        const uint16_t local_nv_scale =
                            static_cast<uint16_t>(
                                (local_nv_scale_pair >>
                                 nv_query_half_shift) & 0xffu
                            ) * 0x0101u;
                        const uint16_t peer_nv_scale =
                            static_cast<uint16_t>(
                                (peer_nv_scale_pair >>
                                 nv_query_half_shift) & 0xffu
                            ) * 0x0101u;
                        const int nv_scale_row = first_q_block * 32 + lane;
                        const int nv_scale_k_block =
                            2 * ((compute_warp & 3) & 1);
                        cta2_role_split_store_nvfp4_scale_halfword(
                            nv_dq_source,
                            nv_scale_row,
                            nv_scale_k_block,
                            local_nv_scale
                        );
                        cta2_role_split_store_nvfp4_scale_halfword_peer(
                            nv_dq_source,
                            nv_scale_row,
                            nv_scale_k_block,
                            peer_nv_scale,
                            cta_rank ^ 1
                        );
#else
#if TK_FA4_BWD_PURE_MXFP4_FUSED_DK_SCALE_PUBLICATION
                        static_assert(
                            TK_FA4_BWD_PURE_MXFP4_QUARTER_DUAL_DS
                        );
                        static_assert(
                            TK_FA4_BWD_PURE_MXFP4_SHARED_DUAL_DS_SCALE
                        );
                        uint32_t packed_dk_scale = 0;
                        // The scale is warp-uniform.  Record one byte from
                        // each producer, ordered as lower q-half k0..k3 then
                        // upper q-half k0..k3.  This one mailbox feeds both
                        // dK's alternating Q-block word and dQ's packed
                        // source-key scale words.
                        if (lane == 0) {
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            asm volatile(
                                "st.shared.b8 [%0], %1;"
                                :: "r"(
                                       scratch_base +
                                       static_cast<uint32_t>(
                                           compute_warp
                                       )
                                   ),
                                   "r"(
                                       static_cast<uint32_t>(
                                           ds_mxfp4_scale0
                                       )
                                   )
                                : "memory"
                            );
                        }
#elif TK_FA4_BWD_PURE_MXFP4_PACKED_DK_SCALE_PUBLICATION
                        // Under quartered dS the shared native payload is
                        // retired in favor of its compact TMEM copy.  Reuse
                        // its first 256 bytes as four contiguous warp-pair
                        // mailboxes: lower warps contribute q-blocks 1/3,
                        // while upper warps retain q-blocks 0/2 in registers.
                        if (compute_warp < 4) {
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            const uint32_t pair =
                                static_cast<uint32_t>(ds_mxfp4_scale0) |
                                (static_cast<uint32_t>(ds_mxfp4_scale1) << 8);
                            asm volatile(
                                "st.shared.b16 [%0], %1;"
                                :: "r"(
                                       scratch_base +
                                       static_cast<uint32_t>(compute_warp * 64 +
                                                             lane * 2)
                                   ),
                                   "r"(pair)
                                : "memory"
                            );
                        }
#else
                        cta2_role_split_store_mxfp4_scale_byte(
                            dk_ds_scale,
                            row_base + lane,
                            first_q_block,
                            ds_mxfp4_scale0
                        );
                        cta2_role_split_store_mxfp4_scale_byte(
                            dk_ds_scale,
                            row_base + lane,
                            second_q_block,
                            ds_mxfp4_scale1
                        );
#endif
                        asm volatile("bar.sync 3, 256;" ::: "memory");

#if TK_FA4_BWD_PURE_MXFP4_FUSED_DK_SCALE_PUBLICATION
                        if (compute_warp >= 4) {
                            const int reader_warp = compute_warp & 3;
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            uint32_t odd_scale;
                            asm volatile(
                                "ld.shared.u8 %0, [%1];"
                                : "=r"(odd_scale)
                                : "r"(
                                      scratch_base +
                                      static_cast<uint32_t>(
                                          reader_warp
                                      )
                                  )
                                : "memory"
                            );
                            // PRMT 0x4040 selects [even.b0, odd.b0,
                            // even.b0, odd.b0], matching q-blocks 0..3.
                            asm volatile(
                                "prmt.b32 %0, %1, %2, 0x4040;"
                                : "=r"(packed_dk_scale)
                                : "r"(
                                      static_cast<uint32_t>(
                                          ds_mxfp4_scale0
                                      )
                                  ),
                                  "r"(odd_scale)
                            );
#if !(TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM & 1)
                            const uint32_t scale_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &reinterpret_cast<uint8_t &>(
                                            dk_ds_scale.data[0]
                                        )
                                    )
                                );
                            asm volatile(
                                "st.shared.b32 [%0], %1;"
                                :: "r"(
                                       scale_base +
                                       cta2_role_split_mxfp4_scale_swizzle_idx(
                                           row_base + lane,
                                           0
                                       )
                                   ),
                                   "r"(packed_dk_scale)
                                : "memory"
                            );
#endif
                        }
#elif TK_FA4_BWD_PURE_MXFP4_PACKED_DK_SCALE_PUBLICATION
                        if (compute_warp >= 4) {
                            const int reader_warp = compute_warp & 3;
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            uint32_t odd_blocks;
                            asm volatile(
                                "ld.shared.u16 %0, [%1];"
                                : "=r"(odd_blocks)
                                : "r"(
                                      scratch_base +
                                      static_cast<uint32_t>(reader_warp * 64 +
                                                            lane * 2)
                                  )
                                : "memory"
                            );
                            const uint32_t packed_scale =
                                static_cast<uint32_t>(ds_mxfp4_scale0) |
                                ((odd_blocks & 0xffu) << 8) |
                                (static_cast<uint32_t>(ds_mxfp4_scale1) << 16) |
                                ((odd_blocks & 0xff00u) << 16);
                            const uint32_t scale_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &reinterpret_cast<uint8_t &>(
                                            dk_ds_scale.data[0]
                                        )
                                    )
                                );
                            asm volatile(
                                "st.shared.b32 [%0], %1;"
                                :: "r"(
                                       scale_base +
                                       cta2_role_split_mxfp4_scale_swizzle_idx(
                                           row_base + lane,
                                           0
                                       )
                                   ),
                                   "r"(packed_scale)
                                : "memory"
                            );
                        }
#endif

#if TK_FA4_BWD_PURE_MXFP4_FUSED_DQ_SCALE_PUBLICATION
                        static_assert(
                            TK_FA4_BWD_PURE_MXFP4_FUSED_DK_SCALE_PUBLICATION
                        );
                        // Warp 0 publishes query rows 32..63 from the lower
                        // four mailbox bytes; warp 4 publishes rows 0..31
                        // from the upper four.  Every lane loads the same
                        // word (a hardware broadcast), then writes one row of
                        // the local page and its peer's matching source page.
                        if ((compute_warp & 3) == 0) {
                            const uint32_t scratch_base =
                                static_cast<uint32_t>(
                                    __cvta_generic_to_shared(
                                        &dk_ds_mxfp4.data[0]
                                    )
                                );
                            uint32_t packed_dq_scale;
                            asm volatile(
                                "ld.shared.b32 %0, [%1];"
                                : "=r"(packed_dq_scale)
                                : "r"(
                                      scratch_base +
                                      static_cast<uint32_t>(
                                          (compute_warp >> 2) * 4
                                      )
                                  )
                                : "memory"
                            );
                            auto &source_scale_page = cta_rank == 0
                                ? dq_ds_scale0
                                : dq_ds_scale1;
                            const int packed_scale_row =
                                first_q_block * 32 + lane;
                            cta2_role_split_store_mxfp4_scale_word(
                                source_scale_page,
                                packed_scale_row,
                                packed_dq_scale
                            );
                            cta2_role_split_store_mxfp4_scale_word_peer(
                                source_scale_page,
                                packed_scale_row,
                                packed_dq_scale,
                                cta_rank ^ 1
                            );
                        }
#endif
#endif

#if TK_FA4_BWD_PURE_MXFP4_QUARTER_DUAL_DS
                        // All dP readers have crossed the rendezvous, so its
                        // compact first sixteen columns can be retired and
                        // reused immediately.  dK consumes this native view;
                        // dQ receives a quarter-at-a-time register transpose
                        // below, avoiding the native shared round trip.
                        cta2_role_split_store_mxfp4_tmem_x32(
                            dk_ds_mxfp4_tmem.addr +
                                (static_cast<uint32_t>(row_base) << 16) +
                                x32_column_group / 8,
                            ds_mxfp4_stage0
                        );
                        cta2_role_split_store_mxfp4_tmem_x32(
                            dk_ds_mxfp4_tmem.addr +
                                (static_cast<uint32_t>(row_base) << 16) +
                                (x32_column_group + 64) / 8,
                            ds_mxfp4_stage1
                        );
#if TK_FA4_BWD_PURE_MXFP4_FUSED_DK_SCALE_PUBLICATION && \
    TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM & 1
                        if (compute_warp >= 4) {
                            const int reader_warp = compute_warp & 3;
                            cta2_role_split_store_mxfp4_scale_tmem_x1(
                                ds_qk_scale0_tmem.addr,
                                reader_warp,
                                packed_dk_scale
                            );
                        }
#endif
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM & 2
                        // A scale page's four low columns are one logical
                        // 128-row record.  Issue all four x1 fragments from
                        // one warp, matching the proven direct-dQ layout;
                        // distributing them across physical producer warps
                        // leaves an invalid page on Blackwell.
                        if (compute_warp == 4) {
                            #pragma unroll
                            for (
                                int reader_warp = 0;
                                reader_warp < 4;
                                ++reader_warp
                            ) {
                                cta2_role_split_store_mxfp4_scale_tmem_x1(
                                    qk_unit_scale_tmem.addr,
                                    reader_warp,
                                    0x7f7f7f7fu
                                );
                            }
                        }
#endif
#endif
#if !TK_FA4_BWD_PURE_MXFP4_DEFER_NATIVE_DS_TMEM_WAIT
                        cta2_role_split_tmem_store_wait();
#endif
#endif

#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM && \
    !TK_FA4_BWD_PURE_MXFP4_FUSED_DK_SCALE_PUBLICATION
                        // The lower four producer warps own q-blocks 0/2;
                        // after the existing dS rendezvous they can read the
                        // adjacent 0/1/2/3 scale bytes contributed by their
                        // paired upper warp in one instruction.  Publish the
                        // exact dS page and the fixed compact-Q page directly
                        // to TMEM, avoiding two 512-byte tcgen05.cp moves on
                        // the tensor warp's dK critical path.
                        if (compute_warp >= 4) {
                            const int reader_warp = compute_warp & 3;
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM & 1
                            const uint32_t packed_scale =
                                cta2_role_split_load_mxfp4_scale_word(
                                    dk_ds_scale,
                                    row_base + lane
                                );
                            cta2_role_split_store_mxfp4_scale_tmem_x1(
                                ds_qk_scale0_tmem.addr,
                                reader_warp,
                                packed_scale
                            );
#endif
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DK_SCALE_TMEM & 2
                            cta2_role_split_store_mxfp4_scale_tmem_x1(
                                qk_unit_scale_tmem.addr,
                                reader_warp,
                                0x7f7f7f7fu
                            );
#endif
                            cta2_role_split_tmem_store_wait();
                        }
#endif

#if TK_FA4_BWD_PURE_MXFP4_ASYNC_DK_READY
                        // Every producer has completed its native dS TMEM
                        // stores and exact scale publication here.  Arrival is
                        // nonblocking; warp 14 combines this local proof with
                        // compact-Q TMA completion and performs the one
                        // cluster arrival consumed by the tensor warp.
                        if constexpr (FenceDsBeforeDkdvReady) {
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                        }
                        warp::arrive(dkdv_local_ready);
#endif

#if TK_FA4_BWD_PURE_MXFP4_EARLY_DK_READY
                        // dK consumes only the native dS TMEM tile, its scale
                        // page, and the compact Q tile contributed by the
                        // loader warps.  None of the dQ transpose/publication
                        // work below is a dK dependency, so close the existing
                        // 12-warp fan-in here and let the tensor warp proceed.
                        if constexpr (FenceDsBeforeDkdvReady) {
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                        }
                        if constexpr (UseNamedDkdvLocalFanIn) {
                            if (physical_warp == 4) {
                                asm volatile(
                                    "bar.sync 7, 384;"
                                    ::: "memory"
                                );
                            } else {
                                asm volatile(
                                    "bar.arrive 7, 384;"
                                    ::: "memory"
                                );
                            }
                            if (physical_warp == 4 && lane == 0) {
                                if constexpr (
                                    CacheRoleClusterAddresses &&
                                    !UseX32TmemComputeLayout
                                ) {
                                    cta2_fused_dense_cluster_arrive_mapped(
                                        dkdv_operands_ready_cluster_address
                                    );
                                } else {
                                    ::kittens::tma::cluster::arrive(
                                        dkdv_operands_ready,
                                        0
                                    );
                                }
                            }
                        } else {
                            warp::arrive(dkdv_local_ready);
                            if (physical_warp == 4 && lane == 0) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dkdv_local_ready, phase);
                                if constexpr (
                                    CacheRoleClusterAddresses &&
                                    !UseX32TmemComputeLayout
                                ) {
                                    cta2_fused_dense_cluster_arrive_mapped(
                                        dkdv_operands_ready_cluster_address
                                    );
                                } else {
                                    ::kittens::tma::cluster::arrive(
                                        dkdv_operands_ready,
                                        0
                                    );
                                }
                            }
                        }
#endif

#if !TK_FA4_BWD_PURE_MXFP4_FUSED_DQ_SCALE_PUBLICATION
                        const uint8_t local_scale = cta_rank == 0
                            ? ds_mxfp4_scale0
                            : ds_mxfp4_scale1;
                        const uint8_t peer_scale = cta_rank == 0
                            ? ds_mxfp4_scale1
                            : ds_mxfp4_scale0;
#endif
                        const int query_row_base = first_q_block * 32;
                        const int source_key_col_base = cta_rank * 128;
#if TK_FA4_BWD_PURE_MXFP4_ALIGNED_MXF8F6F4_DQ
                        // Preserve native [key, query] order.  Rank 0 owns
                        // query rows 0:64 and rank 1 owns 64:128; each source
                        // keeps its destination half local and publishes the
                        // complementary half through the existing peer copy.
                        if (cta_rank == 0) {
                            cta2_role_split_store_aligned_e2m1_smem_x32(
                                dq_a_mxfp4,
                                ds_mxfp4_stage0,
                                row_base,
                                x32_column_group
                            );
                            cta2_role_split_store_aligned_e2m1_smem_x32(
                                dq_exchange_mxfp4,
                                ds_mxfp4_stage1,
                                row_base,
                                x32_column_group
                            );
                        } else {
                            cta2_role_split_store_aligned_e2m1_smem_x32(
                                dq_a_mxfp4,
                                ds_mxfp4_stage1,
                                128 + row_base,
                                x32_column_group
                            );
                            cta2_role_split_store_aligned_e2m1_smem_x32(
                                dq_exchange_mxfp4,
                                ds_mxfp4_stage0,
                                row_base,
                                x32_column_group
                            );
                        }
#elif TK_FA4_BWD_PURE_MXFP4_GATHERED_TRANSPOSE_DQ
                        auto &dq_a_mxfp4_transpose = *reinterpret_cast<
                            cta2_fused_dense_dq_a_mxfp4_transpose_tile *
                        >(&dq_a_mxfp4);
                        auto &dq_exchange_mxfp4_transpose =
                            *reinterpret_cast<
                                cta2_fused_dense_dq_exchange_mxfp4_transpose_tile *
                            >(&dq_exchange_mxfp4);
                        const auto &local_native_words = cta_rank == 0
                            ? ds_mxfp4_stage0
                            : ds_mxfp4_stage1;
                        const auto &peer_native_words = cta_rank == 0
                            ? ds_mxfp4_stage1
                            : ds_mxfp4_stage0;
                        // Each CTA retains the query half it owns as the M64
                        // minor axis and publishes the other half for its
                        // peer.  Source rank chooses the contiguous K128
                        // destination half during the existing bulk copy.
                        cta2_role_split_store_mxfp4_transpose_major_x32(
                            dq_a_mxfp4_transpose,
                            local_native_words,
                            cta_rank * 64 + row_base / 2,
                            x32_column_group
                        );
                        cta2_role_split_store_mxfp4_transpose_major_x32(
                            dq_exchange_mxfp4_transpose,
                            peer_native_words,
                            row_base / 2,
                            x32_column_group
                        );
#elif TK_FA4_BWD_PURE_MXFP4_QUARTER_DUAL_DS
#if TK_FA4_BWD_PURE_MXFP4_INTERLEAVED_DUAL_TRANSPOSE
                        cta2_role_split_transpose_mxfp4_x32_quartered_registers_dual(
                            dq_a_mxfp4,
                            dq_exchange_mxfp4,
                            ds_mxfp4_stage0,
                            ds_mxfp4_stage1,
                            cta_rank == 0,
                            query_row_base,
                            source_key_col_base + row_base,
                            row_base
                        );
#else
                        const auto &local_native_words = cta_rank == 0
                            ? ds_mxfp4_stage0
                            : ds_mxfp4_stage1;
                        const auto &peer_native_words = cta_rank == 0
                            ? ds_mxfp4_stage1
                            : ds_mxfp4_stage0;
                        cta2_role_split_transpose_mxfp4_x32_quartered_registers(
                            dq_a_mxfp4,
                            local_native_words,
                            query_row_base,
                            source_key_col_base + row_base
                        );
                        cta2_role_split_transpose_mxfp4_x32_quartered_registers(
                            dq_exchange_mxfp4,
                            peer_native_words,
                            query_row_base,
                            row_base
                        );
#endif
#else
                        cta2_role_split_transpose_mxfp4_x32(
                            dq_a_mxfp4,
                            dk_ds_mxfp4,
                            row_base,
                            cta_rank == 0
                                ? first_q_block * 32
                                : second_q_block * 32,
                            query_row_base,
