                        );
                        cta2_role_split_transpose_mxfp4_x32(
                            dq_exchange_mxfp4,
                            dk_ds_mxfp4,
                            row_base,
                            cta_rank == 0
                                ? second_q_block * 32
                                : first_q_block * 32,
                            query_row_base,
                            row_base
