                        // Page 0 describes source keys 0:128 (CTA 0) and
                        // page 1 describes source keys 128:256 (CTA 1).
                        // Each source publishes its local query half into
                        // its own CTA and the complementary query half into
                        // the peer, both in that destination CTA's local
                        // M64 row coordinates.
#if !TK_FA4_BWD_PURE_MXFP4_FUSED_DQ_SCALE_PUBLICATION
                        auto &source_scale_page = cta_rank == 0
                            ? dq_ds_scale0
                            : dq_ds_scale1;
                        const int packed_scale_row = query_row_base + lane;
                        cta2_role_split_store_mxfp4_scale_byte(
                            source_scale_page,
                            packed_scale_row,
                            compute_warp & 3,
                            local_scale
                        );
                        cta2_role_split_store_mxfp4_scale_byte_peer(
                            source_scale_page,
                            packed_scale_row,
                            compute_warp & 3,
                            peer_scale,
                            cta_rank ^ 1
