#endif
#if TK_FA4_BWD_PURE_MXFP4_QUARTER_DUAL_DS && \
    TK_FA4_BWD_PURE_MXFP4_DEFER_NATIVE_DS_TMEM_WAIT
                        cta2_role_split_tmem_store_wait();
#endif
                    } else {
                    auto &dq_a_fp4 = *reinterpret_cast<
                        cta2_fused_dense_dq_a_fp4_tile *
                    >(&main.p.p);
                    auto &dq_exchange_fp4 =
                        cta2_fused_dense_fp4_dq_exchange_stage(storage);
                    if constexpr (UseNativeX32Lowp) {
                        auto &ds_fp4 =
                            cta2_fused_dense_fp4_ds_stage(storage);
                        if constexpr (ReuseDqDsForDk) {
