                        } else {
                            cta2_role_split_store_fp8_x32_stage(
                                ds_fp4,
                                p_x32_stage0,
                                row_base,
                                x32_column_group
                            );
                            cta2_role_split_store_fp8_x32_stage(
                                ds_fp4,
                                p_x32_stage1,
                                row_base,
                                x32_column_group + 64
                            );
                        }
                    }
                    if constexpr (UseAsyncDkReady) {
                        // Native dS is complete here; dQ's local/peer views
                        // below are independent of dK and stay off its fan-in.
                        if constexpr (FenceDsBeforeDkdvReady) {
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                        }
                        warp::arrive(dkdv_local_ready);
                    }
                    if (cta_rank == 0) {
                        cta2_role_split_store_fp8_x32_stage(
                            dq_a_fp4,
                            p_x32_stage0,
                            row_base,
                            x32_column_group
                        );
                        cta2_role_split_store_fp8_x32_stage(
                            dq_exchange_fp4,
                            p_x32_stage1,
                            row_base,
                            x32_column_group
                        );
                    } else {
                        cta2_role_split_store_fp8_x32_stage(
                            dq_a_fp4,
                            p_x32_stage1,
                            128 + row_base,
                            x32_column_group
                        );
                        cta2_role_split_store_fp8_x32_stage(
                            dq_exchange_fp4,
                            p_x32_stage0,
                            row_base,
                            x32_column_group
                        );
                    }
                    }
                } else if constexpr (UseFp8DqDk) {
                    auto &ds_fp8 = cta2_fused_dense_fp8_ds_stage(storage);
                    auto ds_fp8_smem =
                        ds_fp8.template subtile<16, 128>(
                            {output_subtile, 0}
                        );
                    cta2_role_split_store_fp8_direct(
                        ds_fp8_smem,
                        ds_lowp_reg
                    );
                    auto &dq_a_fp8 = *reinterpret_cast<
                        cta2_fused_dense_dq_a_fp8_tile *
                    >(&main.p.p);
                    auto &dq_exchange_fp8 =
                        cta2_fused_dense_fp8_dq_exchange_stage(storage);
                    if (cta_rank == 0) {
                        cta2_role_split_store_fp8_halves_for_dq_direct<0>(
                            dq_a_fp8,
                            dq_exchange_fp8,
                            ds_lowp_reg,
                            output_subtile
