                    } else {
                        cta2_role_split_store_fp8_halves_for_dq_direct<1>(
                            dq_a_fp8,
                            dq_exchange_fp8,
                            ds_lowp_reg,
                            output_subtile
                        );
                    }
                } else if constexpr (UseFp4DqDk) {
                    auto &ds_fp4 = cta2_fused_dense_fp4_ds_stage(storage);
                    auto ds_fp4_smem =
                        ds_fp4.template subtile<16, 128>(
                            {output_subtile, 0}
                        );
                    cta2_role_split_store_fp8_direct(
                        ds_fp4_smem,
                        ds_lowp_reg
                    );
                    auto &dq_a_fp4 = *reinterpret_cast<
                        cta2_fused_dense_dq_a_fp4_tile *
                    >(&main.p.p);
                    auto &dq_exchange_fp4 =
                        cta2_fused_dense_fp4_dq_exchange_stage(storage);
                    if (cta_rank == 0) {
                        cta2_role_split_store_fp8_halves_for_dq_direct<0>(
                            dq_a_fp4,
                            dq_exchange_fp4,
                            ds_lowp_reg,
                            output_subtile
