                                    "bar.arrive 3, 256;"
                                    ::: "memory"
                                );
                            }
                        } else {
                            asm volatile("bar.sync 3, 256;" ::: "memory");
                        }
                        if (physical_warp == 4 && lane == 0) {
                            constexpr int kHalfElements = 64 * 128;
                            void *destination = reinterpret_cast<void *>(
                                &dq_a_fp8.data[
                                    cta_rank * kHalfElements
                                ]
