                                cta2_role_split_store_peer_bulk_after_cta_fence(
                                    destination,
                                    reinterpret_cast<void *>(
                                        &dq_exchange_mxfp4
                                    ),
                                    sizeof(dq_exchange_mxfp4),
                                    cta_rank ^ 1,
                                    dq_exchange_done
                                );
                            }
                            if constexpr (
                                UseNonblockingDqPublicationFollowers
                            ) {
                                if (physical_warp == 4) {
                                    warp::arrive(dq_local_ready);
                                }
                            } else {
                                warp::arrive(dq_local_ready);
                            }
                        } else {
                        auto &dq_a_fp4 = *reinterpret_cast<
                            cta2_fused_dense_dq_a_fp4_tile *
                        >(&main.p.p);
                        auto &dq_exchange_fp4 =
                            cta2_fused_dense_fp4_dq_exchange_stage(storage);
                        if (physical_warp == 4 && lane == 0) {
                            ::kittens::tma::cluster::expect_bytes(
                                dq_exchange_done,
                                sizeof(dq_exchange_fp4),
                                cta_rank ^ 1
                            );
