                        }
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        if constexpr (
                                UseNonblockingDqPublicationFollowers
                            ) {
                                if (physical_warp == 4) {
                                    asm volatile(
                                        "bar.sync 3, 256;"
                                        ::: "memory"
                                    );
                                } else {
                                    asm volatile(
                                        "bar.arrive 3, 256;"
                                        ::: "memory"
                                    );
                                }
                            } else {
                                asm volatile(
                                    "bar.sync 3, 256;"
                                    ::: "memory"
                                );
                            }
