                            RelayDoDvCompletionViaExchangeWarp &&
                            !UseFp8Pv &&
                            !OverlapDqPeerCopyWithDoDvCompletion
                        ) {
                            if (lane == 0) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    do_source_loaded,
                                    phase
                                );
                            }
                            __syncwarp();
                        }
                        if constexpr (
                            OverlapFinalDsTmemStoreWithPeerSharedStores
