                            tensor_before_thread_sync();
                        }
                    }
                    __syncwarp();
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    if constexpr (UseNonblockingDqPublicationFollowers) {
                        if (physical_warp == 4) {
                            asm volatile("bar.sync 3, 256;" ::: "memory");
                        } else {
                            asm volatile("bar.arrive 3, 256;" ::: "memory");
                        }
                    } else {
                        asm volatile("bar.sync 3, 256;" ::: "memory");
                    }
                    if (physical_warp == 4 && lane == 0) {
                        constexpr int kHalfElements = 128 * 64;
                        void *destination = reinterpret_cast<void *>(
                            &dq_a.data[cta_rank * kHalfElements]
                        );
                        cta2_role_split_store_peer_bulk_after_cta_fence(
                            destination,
                            reinterpret_cast<void *>(
                                &storage.qdo_phase.ds
                            ),
                            kHalfElements * sizeof(bf16),
                            cta_rank ^ 1,
                            dq_exchange_done
                        );
                    }
                    if constexpr (OverlapLocalDqStoreWithPeerCopy) {
                        auto a_local_smem =
                            dq_a.template subtile<16, 64>(
                                {cta_rank * 8 + output_subtile, 0}
                            );
                        if (cta_rank == 0) {
                            cta2_role_split_store_ds_half_direct<0>(
                                a_local_smem,
                                ds_bf
                            );
                        } else {
                            cta2_role_split_store_ds_half_direct<1>(
                                a_local_smem,
                                ds_bf
                            );
                        }
                        __syncwarp();
                    }
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    warp::arrive(dq_local_ready);
                    }
                }
                if constexpr (!SplitDvDkReady) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        qdo_exchange_done,
                        phase
                    );
                    auto &qdo_exchange = storage.qdo_phase.qdo;
                    const int source_row = compute_warp & 3;
                    rt_bf<16, 64> do_half;
                    if ((compute_warp >> 2) == cta_rank) {
                        auto do_source = main.dout.template subtile<16, 64>(
                            {source_row, cta_rank}
                        );
                        warp::load(do_half, do_source);
                    } else {
                        auto do_source =
                            qdo_exchange.dout.template subtile<16, 64>(
                                {source_row, 0}
                            );
                        warp::load(do_half, do_source);
                    }
                    if constexpr (UseNormalDoDv) {
                        warp::arrive(do_source_loaded);
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            do_source_loaded,
                            phase
                        );
                        auto &do_normal =
                            *reinterpret_cast<st_bf<128, 64> *>(
                                &main.dout
                            );
                        auto do_smem = do_normal.template subtile<16, 64>(
                            {compute_warp, 0}
                        );
                        warp::store(do_smem, do_half);
                    } else {
                        rt_bf<64, 16> do_transposed;
                        warp::transpose_sep(do_transposed, do_half);
                        warp::arrive(do_source_loaded);
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            do_source_loaded,
                            phase
                        );
                        auto do_smem = main.dout.template subtile<64, 16>(
                            {0, compute_warp}
                        );
                        warp::store(do_smem, do_transposed);
                    }
                }
                if constexpr (
                    !((UsePureMxFp4DqDk &&
                       TK_FA4_BWD_PURE_MXFP4_EARLY_DK_READY) ||
                      UseAsyncDkReady)
                ) {
                    if constexpr (FenceDsBeforeDkdvReady) {
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                    }
                    if constexpr (UseNamedDkdvLocalFanIn) {
                        if (physical_warp == 4) {
                            asm volatile("bar.sync 7, 384;" ::: "memory");
                        } else {
                            asm volatile("bar.arrive 7, 384;" ::: "memory");
                        }
                        if (physical_warp == 4 && lane == 0) {
                            if constexpr (
                                CacheRoleClusterAddresses &&
                                !UseX32TmemComputeLayout
                            ) {
                                cta2_fused_dense_cluster_arrive_mapped(
                                    dkdv_operands_ready_cluster_address
                                );
                            } else {
                                ::kittens::tma::cluster::arrive(
                                    dkdv_operands_ready,
                                    0
                                );
                            }
                        }
                    } else {
                        warp::arrive(dkdv_local_ready);
                        if (physical_warp == 4 && lane == 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dkdv_local_ready,
                                phase
                            );
                            if constexpr (
                                CacheRoleClusterAddresses &&
                                !UseX32TmemComputeLayout
                            ) {
                                cta2_fused_dense_cluster_arrive_mapped(
                                    dkdv_operands_ready_cluster_address
                                );
                            } else {
                                ::kittens::tma::cluster::arrive(
                                    dkdv_operands_ready,
                                    0
                                );
                            }
                        }
                    }
                }
                if constexpr (RetainDsLocal) {
                    // Both dS halves remain in their producer warp registers.
                } else if constexpr (RetainDsExchange) {
                    auto ds_local_smem =
                        storage.ds.template subtile<16, 64>(
                            {compute_warp, cta_rank}
                        );
                    warp::load(dq_a_local_preload, ds_local_smem);
                } else {
                    auto ds_local_smem =
                        storage.ds.template subtile<16, 64>(
                            {compute_warp, cta_rank}
                        );
                    auto ds_peer_smem =
                        storage.ds.template subtile<16, 64>(
                            {compute_warp, cta_rank ^ 1}
                        );
                    warp::load(dq_a_local_preload, ds_local_smem);
                    warp::load(dq_a_peer_preload, ds_peer_smem);
                }
                if constexpr (StageDqAfterDv) {
                    asm volatile("bar.sync 2, 256;" ::: "memory");
                }
                if constexpr (StageDqPeerBeforeDv) {
                    auto a_peer_smem =
                        storage.qdo_phase.ds.template subtile<16, 64>({
                            RetainDsExchange ? output_subtile : compute_warp,
                            0
                        });
                    warp::store(a_peer_smem, dq_a_peer_preload);
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    warp::arrive(dq_peer_ready);
                }
                cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                    dkdv_done,
                    phase
                );
                if constexpr (
                    !OverlapFusedDqAPublication &&
                    (DirectAsyncPeerDs || ProducerBulkPeerDs)
                ) {
                    if (physical_warp == 4 && lane == 0) {
                        ::kittens::tma::cluster::expect_bytes(
                            dq_exchange_done,
                            sizeof(storage.qdo_phase.ds),
                            cta_rank ^ 1
                        );
                    }
                    if constexpr (!UseFusedTmemPAndDs) {
                        asm volatile("bar.sync 3, 256;" ::: "memory");
                    }
                }

                if constexpr (!OverlapFusedDqAPublication) {
                    auto &dq_operands = storage.phase.dq.operands;
                    auto &dq_a = [&]() -> cta2_fused_dense_dq_a_tile & {
                        if constexpr (StageDqAfterDv) {
                            return *reinterpret_cast<
                                cta2_fused_dense_dq_a_tile *
                            >(&main.p.p);
                        } else {
                            return dq_operands.a;
                        }
                    }();
                    auto a_local_smem =
                        dq_a.template subtile<16, 64>(
                            {
                                cta_rank * 8 +
                                    (RetainDsLocal
                                        ? output_subtile
                                        : compute_warp),
                                0
                            }
                        );
                    if constexpr (DirectDsHalfStore) {
                        if (cta_rank == 0) {
                            cta2_role_split_store_ds_half_direct<0>(
                                a_local_smem,
                                ds_bf
                            );
                        } else {
                            cta2_role_split_store_ds_half_direct<1>(
                                a_local_smem,
                                ds_bf
                            );
                        }
                    } else {
                        warp::store(a_local_smem, dq_a_local_preload);
                    }
                    if constexpr (!StageDqPeerBeforeDv) {
                        if constexpr (DirectAsyncPeerDs) {
                            auto a_peer_smem = dq_a.template subtile<16, 64>(
                                {cta_rank * 8 + output_subtile, 0}
                            );
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                            if (cta_rank == 0) {
                                cta2_role_split_store_ds_half_remote_async<1>(
                                    a_peer_smem,
                                    ds_bf,
                                    1,
                                    dq_exchange_done
                                );
                            } else {
                                cta2_role_split_store_ds_half_remote_async<0>(
                                    a_peer_smem,
                                    ds_bf,
                                    0,
                                    dq_exchange_done
                                );
                            }
                        } else {
                            if constexpr (
                                !BulkPeerDsFromFullTile ||
                                UseFusedTmemPAndDs
                            ) {
                                auto a_peer_smem =
                                    storage.qdo_phase.ds.template
                                        subtile<16, 64>({
                                            RetainDsExchange
                                                ? output_subtile
                                                : compute_warp,
                                            0
                                        });
                                if constexpr (DirectDsHalfStore) {
                                    if (cta_rank == 0) {
                                        cta2_role_split_store_ds_half_direct<1>(
                                            a_peer_smem,
                                            ds_bf
                                        );
                                    } else {
                                        cta2_role_split_store_ds_half_direct<0>(
                                            a_peer_smem,
                                            ds_bf
                                        );
                                    }
                                } else {
                                    warp::store(
                                        a_peer_smem,
                                        dq_a_peer_preload
                                    );
                                }
                            }
                            if constexpr (ProducerBulkPeerDs) {
                                __syncwarp();
                                asm volatile(
                                    "fence.proxy.async.shared::cta;"
                                    ::: "memory"
                                );
                                if constexpr (UseFusedTmemPAndDs) {
                                    asm volatile(
                                        "bar.sync 3, 256;"
                                        ::: "memory"
                                    );
                                }
                                if constexpr (CoalescedPeerDsBulk) {
                                    if (physical_warp == 4 && lane == 0) {
                                        constexpr int kHalfElements =
                                            128 * 64;
                                        void *destination =
                                            reinterpret_cast<void *>(
                                                &dq_a.data[
                                                    cta_rank * kHalfElements
                                                ]
                                            );
                                        void *source;
                                        if constexpr (UseFusedTmemPAndDs) {
                                            source = reinterpret_cast<void *>(
                                                &storage.qdo_phase.ds
                                            );
                                        } else {
                                            source = reinterpret_cast<void *>(
                                                &storage.ds.data[
                                                    (cta_rank ^ 1) *
                                                        kHalfElements
                                                ]
                                            );
                                        }
                                        cta2_role_split_store_peer_bulk_after_cta_fence(
                                            destination,
                                            source,
                                            kHalfElements * sizeof(bf16),
                                            cta_rank ^ 1,
                                            dq_exchange_done
                                        );
                                    }
                                } else if (lane == 0) {
                                    constexpr int kChunkElements = 16 * 64;
                                    void *destination = reinterpret_cast<void *>(
                                        &dq_a.data[
                                            (cta_rank * 128 +
                                             output_subtile * 16) * 64
                                        ]
                                    );
                                    void *source;
                                    if constexpr (BulkPeerDsFromFullTile) {
                                        constexpr int kHalfElements =
                                            128 * 64;
                                        source = reinterpret_cast<void *>(
                                            &storage.ds.data[
                                                (cta_rank ^ 1) *
                                                    kHalfElements +
                                                output_subtile *
                                                    kChunkElements
                                            ]
                                        );
                                    } else {
                                        source = reinterpret_cast<void *>(
                                            &storage.qdo_phase.ds.data[
                                                output_subtile *
                                                    kChunkElements
                                            ]
                                        );
                                    }
                                    if constexpr (
                                        ProducerBulkPeerDsCtaFenceOnly
                                    ) {
                                        cta2_role_split_store_peer_bulk_after_cta_fence(
                                            destination,
                                            source,
                                            kChunkElements * sizeof(bf16),
                                            cta_rank ^ 1,
                                            dq_exchange_done
                                        );
                                    } else {
                                        ::kittens::tma::cluster::store_async(
                                            destination,
                                            source,
                                            kChunkElements * sizeof(bf16),
                                            cta_rank ^ 1,
                                            dq_exchange_done
                                        );
                                    }
                                }
                            }
                        }
                    }
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    warp::arrive(dq_local_ready);
                }
                if constexpr (CarryDirectStatsOffset) {
                    carried_direct_stats_offset += q_tile_step * 128;
                }
                if constexpr (SplitDqTmemAndSharedHandoff) {
                    have_previous_dq_shared_read = true;
                    previous_dq_shared_read_phase = phase;
                }
                if constexpr (CarryAllRolePhases) {
                    compute_phase ^= 1;
                }
            }
            if (first_dense_q_tile < q_tile_count) {
                const int iteration_count =
                    (q_tile_count - first_dense_q_tile + q_tile_step - 1) /
                    q_tile_step;
                const int last_phase =
                    (iteration_count - 1 + owner_phase) & 1;
                cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                    dq_done,
                    last_phase
                );
            }
        }
        return;
    }

    if (physical_warp == 12) {
        asm volatile("setmaxnreg.dec.sync.aligned.u32 104;" ::: "memory");
        if (cta_rank == 0 && lane == 0) {
            uint32_t score_done_commit_address = 0;
            uint32_t dp_done_commit_address = 0;
            uint32_t dkdv_done_commit_address = 0;
            uint32_t dk_done_commit_address = 0;
            uint32_t dq_done_commit_address = 0;
            if constexpr (CacheTensorCommitAddresses) {
                score_done_commit_address =
                    cta2_fused_dense_map_cluster_semaphore(score_done, 0);
                dp_done_commit_address =
                    cta2_fused_dense_map_cluster_semaphore(dp_done, 0);
                if constexpr (LateTensorCommitAddressSharedMask & 0x1) {
                    late_tensor_commit_address_scratch[0] =
                        cta2_fused_dense_map_cluster_semaphore(
                            dkdv_done,
                            0
                        );
                } else {
                    dkdv_done_commit_address =
                        cta2_fused_dense_map_cluster_semaphore(dkdv_done, 0);
                }
                if constexpr (PrefetchNextQdoAfterDkdv) {
                    if constexpr (
                        LateTensorCommitAddressSharedMask & 0x2
                    ) {
                        late_tensor_commit_address_scratch[1] =
                            cta2_fused_dense_map_cluster_semaphore(
                                dk_done,
                                0
                            );
                    } else {
                        dk_done_commit_address =
                            cta2_fused_dense_map_cluster_semaphore(
                                dk_done,
                                0
                            );
                    }
                }
                if constexpr (LateTensorCommitAddressSharedMask & 0x4) {
                    late_tensor_commit_address_scratch[2] =
                        cta2_fused_dense_map_cluster_semaphore(
                            dq_done,
                            0
                        );
                } else {
                    dq_done_commit_address =
                        cta2_fused_dense_map_cluster_semaphore(dq_done, 0);
                }
            }
            uint64_t compact_score_a_desc = 0;
            uint64_t compact_score_b_desc = 0;
            uint64_t compact_dp_a_desc = 0;
            uint64_t compact_dp_b_desc = 0;
            if constexpr (
                UsePureMxFp4DqDk &&
                TK_FA4_BWD_PURE_MXFP4_HOIST_SCORE_SCALE_TMEM
            ) {
                auto &score_scale =
                    cta2_fused_dense_fp4_score_scale_smem(storage.k);
                load_mxnv_scale_async<2>(
                    score_unit_scale_tmem,
                    score_scale
                );
                tensor_load_wait();
            }
            if constexpr (UseCompactScoreMma) {
                ::kittens::st_descriptor<
                    cta2_fused_dense_k_tile,
                    transpose::N
                > a_desc(storage.k);
                ::kittens::st_descriptor<
                    cta2_fused_dense_q_tile,
                    transpose::N
                > b_desc(storage.phase.main.q.q);
                compact_score_a_desc = a_desc.base_desc;
                compact_score_b_desc = b_desc.base_desc;
            }
            if constexpr (
                UseCompactDpMma &&
                (!BuildCompactDpDescriptorsAfterWait ||
                 CacheCompactDpDescriptorsInShared)
            ) {
                ::kittens::st_descriptor<
                    cta2_fused_dense_ds_tile,
                    transpose::N
                > a_desc(storage.ds);
                ::kittens::st_descriptor<
                    cta2_fused_dense_do_tile,
                    transpose::N
                > b_desc(storage.phase.main.dout);
                if constexpr (CacheCompactDpDescriptorsInShared) {
                    compact_dp_descriptor_scratch[0] = a_desc.base_desc;
                    compact_dp_descriptor_scratch[1] = b_desc.base_desc;
                } else {
                    compact_dp_a_desc = a_desc.base_desc;
                    compact_dp_b_desc = b_desc.base_desc;
                }
            }
            bool have_streamed_dv_tail = false;
            int streamed_dv_tail_phase = 0;
            #pragma unroll 1
            for (
                int owner_pass = 0;
                owner_pass < (SingleOwnerCluster ? 1 : 2);
                ++owner_pass
            ) {
                const int owner_idx = SingleOwnerCluster
                    ? owner_pair_idx
                    : (owner_pass == 0
                        ? owner_pair_idx
                        : owner_count - 1 - owner_pair_idx);
                const int owner_phase = OwnerQWorkSplitId >= 0
                    ? (owner_pass == 0
                        ? 0
                        : ((owner_count - owner_pair_idx) & 1))
                    : (SingleOwnerCluster || IntegrateCausalFrontier
                        ? 0
                        : (owner_pass & 1));
                const int owner_once_phase =
                    SingleOwnerCluster ? 0 : (owner_pass & 1);
            const int first_dense_q_tile =
                2 * owner_idx + (IntegrateCausalFrontier ? 0 : 1) +
                (OwnerQWorkSplitId < 0 ? 0 : OwnerQWorkSplitId);
                cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                    k_ready,
                    owner_once_phase
                );
                bool first_accumulation = true;
                int iteration = 0;
                int tensor_phase = owner_phase;
                for (
                    int q_tile_idx = first_dense_q_tile;
                    q_tile_idx < q_tile_count;
                q_tile_idx += q_tile_step, ++iteration
                ) {
                    const int phase = CarryAllRolePhases
                        ? tensor_phase
                        : ((iteration + owner_phase) & 1);
                    auto &main = storage.phase.main;
                    if constexpr (
                        UseNvFp4Score && PipelineScoreScaleTmem
                    ) {
                        if (iteration != 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                p_tmem_ready,
                                phase ^ 1
                            );
                            auto &score_scale =
                                cta2_fused_dense_fp4_score_scale_smem(
                                    storage.k
                                );
                            load_mxnv_scale_async<2>(
                                score_unit_scale_tmem,
                                score_scale
                            );
                        }
                    }
                    if constexpr (UseDoubleBufferedScoreQ) {
                        if constexpr (
                            TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                        ) {
                            if constexpr (UseLongSeqStatsCache) {
                                if (iteration == 0) {
                                    cta2_fused_dense_role_wait<
                                        TimeoutAllRoleWaits
                                    >(qdo_ready, phase);
                                }
                            }
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                score_q_scratch_ready[iteration & 1],
                                (iteration >> 1) & 1
                            );
                        } else {
                            if (iteration == 0) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(qdo_ready, phase);
                            } else {
                                const int score_q_epoch = iteration - 1;
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    score_q_scratch_ready[
                                        score_q_epoch & 1
                                    ],
                                    (score_q_epoch >> 1) & 1
                                );
                            }
                        }
                        if constexpr (
                            WaitDoubleBufferedScoreAliasRelease
                        ) {
                            // Q(i) can arrive in the exchange tail early, but
                            // score(i) still aliases the preceding dQ prefix
                            // in TMEM columns 416..447.  Keep the lightweight
                            // reducer-release gate while removing Q TMA from
                            // that dependency.
                            if (iteration != 0 || !SplitScoreQReady) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(qdo_ready, phase);
                            }
                        }
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            qdo_ready,
                            phase
                        );
                    }
                    if constexpr (UseCrossIterationScoreHead) {
                        if (iteration != 0) {
                            // Columns 320..383 hold the preceding P tile.
                            // dkdv_done is committed immediately after dV,
                            // so it is the earliest proof that score head may
                            // overwrite those columns without racing P reads.
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dkdv_done,
                                phase ^ 1
                            );
                        }
                    }
                    if constexpr (
                        UseNvFp4Score &&
                        ((UsePureMxFp4DqDk &&
                          TK_FA4_BWD_PURE_MXFP4_DIRECT_SCORE_SCALE_TMEM) ||
                         UseDirectWinningScoreScaleTmem)
                    ) {
                        if (iteration != 0) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                reducer_score_scale_safe,
                                phase ^ 1
                            );
                            tensor_after_thread_sync();
                        }
                    }
                    if constexpr (
                        UseNvFp4Score &&
                        !(UsePureMxFp4DqDk &&
                          TK_FA4_BWD_PURE_MXFP4_HOIST_SCORE_SCALE_TMEM)
                    ) {
                        auto &score_scale =
                            cta2_fused_dense_fp4_score_scale_smem(storage.k);
                        if constexpr (UseReducerScoreScaleCopy) {
                            if (iteration == 0) {
                                load_mxnv_scale_async<2>(
                                    score_unit_scale_tmem,
                                    score_scale
                                );
                                tensor_load_wait();
                            } else {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    cta2_fused_dense_fp4_score_scale_done(
                                        storage.k
                                    ),
                                    phase ^ 1
                                );
                            }
                        } else if constexpr (
                            (UsePureMxFp4DqDk &&
                             TK_FA4_BWD_PURE_MXFP4_DIRECT_SCORE_SCALE_TMEM) ||
                            UseDirectWinningScoreScaleTmem
                        ) {
                            if (iteration == 0) {
                                load_mxnv_scale_async<2>(
                                    score_unit_scale_tmem,
                                    score_scale
                                );
                                tensor_load_wait();
                            }
                        } else {
                            if constexpr (PreissueNextScoreHead) {
                                // QK(i)'s head captured this page at the end of
                                // iteration i-1.  dQ(i-1) then aliases it, so
                                // defer the reload for QK(i)'s tail until after
                                // score_alias_ready below.
                                if (iteration == 0) {
                                    load_mxnv_scale_async<2>(
                                        score_unit_scale_tmem,
                                        score_scale
                                    );
                                    tensor_load_wait();
                                }
                            } else {
                                if constexpr (PipelineScoreScaleTmem) {
                                    if (iteration == 0) {
                                        load_mxnv_scale_async<2>(
                                            score_unit_scale_tmem,
                                            score_scale
                                        );
                                    }
                                } else {
                                    load_mxnv_scale_async<2>(
                                        score_unit_scale_tmem,
                                        score_scale
                                    );
                                }
                                tensor_load_wait();
                            }
                        }
                    }
                    if constexpr (UseFp8DqDk) {
                        auto &score_k_fp8 = *reinterpret_cast<
                            cta2_fused_dense_score_k_fp8_tile *
                        >(&storage.k);
                        auto &score_q_fp8 = *reinterpret_cast<
                            cta2_fused_dense_score_q_fp8_tile *
                        >(&main.q);
                        cta2_fused_dense_mm2_ab_no_fence(
                            score_dp_tmem,
                            score_k_fp8,
                            score_q_fp8
                        );
                        cta2_fused_dense_commit_selected<
                            CacheTensorCommitAddresses
                        >(score_done, score_done_commit_address);
                    } else if constexpr (UseFp4DqDk) {
                        if constexpr (UseNvFp4Score) {
                            auto &score_k_fp4 = *reinterpret_cast<
                                cta2_fused_dense_score_k_fp4_tile *
                            >(&storage.k);
                            auto &score_q_fp4 = [&]()
                                -> cta2_fused_dense_score_q_fp4_tile & {
                                if constexpr (UseDoubleBufferedScoreQ) {
                                    if constexpr (
                                        TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ) {
                                        return cta2_fused_dense_route_score_q_scratch<
                                            UseScoreQScratchTail
                                        >(
                                            storage.qdo_phase,
                                            iteration & 1
                                        );
                                    } else if (iteration != 0) {
                                        return cta2_fused_dense_route_score_q_scratch<
                                            UseScoreQScratchTail
                                        >(
                                            storage.qdo_phase,
                                            (iteration - 1) & 1
                                        );
                                    }
                                }
                                return *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp4_tile *
                                >(&main.q);
                            }();
                            if constexpr (UseSplitN96Score) {
                                auto score_q_tail =
                                    score_q_fp4.template subtile<16, 96>(
                                        {3, 0}
                                    );
                                full_tt_fl<96> score_head_tmem(
                                    score_dp_tmem.addr
                                );
                                cta2_fused_dense_attn_quarter_tt
                                    score_tail_tmem(
                                        score_dp_tmem.addr + 96
                                    );
                                // Keep the parent N64 shared descriptor so K
                                // chunks retain their physical row stride;
                                // only the MMA instruction and D view are
                                // narrowed to the logical N96 prefix.
                                cta2_fused_dense_fp4_scaled_mm2_abt_no_fence<
                                    0,
                                    true,
                                    96
                                >(
                                    score_head_tmem,
                                    score_k_fp4,
                                    score_q_fp4,
                                    score_unit_scale_tmem,
                                    score_unit_scale_tmem
                                );
                                cta2_fused_dense_commit_selected<
                                    CacheTensorCommitAddresses
                                >(
                                    score_done,
                                    score_done_commit_address
                                );
                                cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
                                    score_tail_tmem,
                                    score_k_fp4,
                                    score_q_tail,
                                    score_unit_scale_tmem,
                                    score_unit_scale_tmem
                                );
                                cta2_fused_dense_commit(score_tail_done);
                            } else if constexpr (UseSplitN64Score) {
                                auto score_q_head =
                                    score_q_fp4.template subtile<32, 96>(
                                        {0, 0}
                                    );
                                auto score_q_tail =
                                    score_q_fp4.template subtile<32, 96>(
                                        {1, 0}
                                    );
                                cta2_fused_dense_attn_half_tt score_head_tmem(
                                    score_dp_tmem.addr
                                );
                                cta2_fused_dense_attn_half_tt score_tail_tmem(
                                    score_dp_tmem.addr + 64
                                );
                                if constexpr (PreissueNextScoreHead) {
                                    if (iteration == 0) {
                                        cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
                                            score_head_tmem,
                                            score_k_fp4,
                                            score_q_head,
                                            score_unit_scale_tmem,
                                            score_unit_scale_tmem
                                        );
                                        cta2_fused_dense_commit_selected<
                                            CacheTensorCommitAddresses
                                        >(
                                            score_done,
                                            score_done_commit_address
                                        );
                                    }
                                } else {
                                    cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
                                        score_head_tmem,
                                        score_k_fp4,
                                        score_q_head,
                                        score_unit_scale_tmem,
                                        score_unit_scale_tmem
                                    );
                                    cta2_fused_dense_commit_selected<
                                        CacheTensorCommitAddresses
                                    >(
                                        score_done,
                                        score_done_commit_address
                                    );
                                }
                                if constexpr (UseCrossIterationScoreHead) {
                                    // The head occupies TMEM columns 320..383
                                    // and can run alongside the preceding dQ.
                                    // Only the tail reaches dQ's 416..511
                                    // alias, so delay that issue until both
                                    // CTAs have drained their dQ reducers.
                                    cta2_fused_dense_role_wait<
                                        TimeoutAllRoleWaits
                                    >(score_alias_ready, phase);
                                }
                                if constexpr (PreissueNextScoreHead) {
                                    if (iteration != 0) {
                                        auto &score_scale =
                                            cta2_fused_dense_fp4_score_scale_smem(
                                                storage.k
                                            );
                                        load_mxnv_scale_async<2>(
                                            score_unit_scale_tmem,
                                            score_scale
                                        );
                                        tensor_load_wait();
                                    }
                                }
                                cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
                                    score_tail_tmem,
                                    score_k_fp4,
                                    score_q_tail,
                                    score_unit_scale_tmem,
                                    score_unit_scale_tmem
                                );
                                cta2_fused_dense_commit(score_tail_done);
                            } else {
                                if constexpr (UseTwoCommandScore) {
                                    cta2_fused_dense_fp4_scaled_mm2_abt_no_fence<
                                        0,
                                        true,
                                        0,
                                        0,
                                        2
                                    >(
                                        score_dp_tmem,
                                        score_k_fp4,
                                        score_q_fp4,
                                        score_unit_scale_tmem,
                                        score_unit_scale_tmem
                                    );
                                } else {
                                    cta2_fused_dense_fp4_scaled_mm2_abt_no_fence(
                                        score_dp_tmem,
                                        score_k_fp4,
                                        score_q_fp4,
                                        score_unit_scale_tmem,
                                        score_unit_scale_tmem
                                    );
                                }
                            }
                        } else {
                            auto &score_k_fp4 = *reinterpret_cast<
                                cta2_fused_dense_score_k_fp8_tile *
                            >(&storage.k);
                            auto &score_q_fp4 = *reinterpret_cast<
                                cta2_fused_dense_score_q_fp8_tile *
                            >(&main.q);
                            if constexpr (UseEarlyRawN96Score) {
                                full_tt_fl<96> score_head_tmem(
                                    score_dp_tmem.addr
                                );
                                cta2_fused_dense_attn_quarter_tt
                                    score_tail_tmem(
                                        score_dp_tmem.addr + 96
                                    );
                                cta2_fused_dense_fp4_score_mm2_ab_no_fence<
                                    96,
                                    0
                                >(
                                    score_head_tmem,
                                    score_k_fp4,
                                    score_q_fp4
                                );
                                cta2_fused_dense_commit_selected<
                                    CacheTensorCommitAddresses
                                >(
                                    score_done,
                                    score_done_commit_address
                                );
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(score_alias_ready, phase);
                                auto &score_scale =
                                    cta2_fused_dense_early_compact_score_scale_smem(
                                        storage.k
                                    );
                                auto &score_k_compact =
                                    cta2_fused_dense_early_compact_score_k_smem(
                                        storage.k
                                    );
                                auto &score_q_compact =
                                    cta2_fused_dense_early_compact_score_q_smem(
                                        main.q
                                    );
                                load_mxnv_scale_async<2>(
                                    score_unit_scale_tmem,
                                    score_scale
                                );
                                tensor_load_wait();
                                cta2_fused_dense_fp4_scaled_mm2_abt_no_fence<
                                    0,
                                    true,
                                    32,
                                    48
                                >(
                                    score_tail_tmem,
                                    score_k_compact,
                                    score_q_compact,
                                    score_unit_scale_tmem,
                                    score_unit_scale_tmem
                                );
                                cta2_fused_dense_commit(score_tail_done);
                            } else {
                                cta2_fused_dense_fp4_score_mm2_ab_no_fence(
                                    score_dp_tmem,
                                    score_k_fp4,
                                    score_q_fp4
                                );
                            }
                        }
                        if constexpr (!UseSplitScore) {
                            cta2_fused_dense_commit_selected<
                                CacheTensorCommitAddresses
                            >(score_done, score_done_commit_address);
                        }
                        if constexpr (UseEarlyWinningScoreTmemWait) {
                            ::kittens::tma::cluster::arrive(score_issued, 0);
                            ::kittens::tma::cluster::arrive(score_issued, 1);
                        }
                    } else if constexpr (UseCompactScoreMma) {
                        cta2_fused_dense_score_mma_commit_compact(
                            score_dp_tmem.addr,
                            compact_score_a_desc,
                            compact_score_b_desc,
                            score_done_commit_address
                        );
                    } else {
                        cta2_fused_dense_mm2_abt_no_fence(
                            score_dp_tmem,
                            storage.k,
                            main.q.q
                        );
                        cta2_fused_dense_commit_selected<
                            CacheTensorCommitAddresses
                        >(score_done, score_done_commit_address);
                    }
                    if constexpr (!MergeScoreDpReady) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_consumed,
                            phase
                        );
                    }
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dp_operands_ready,
                        phase
                    );
                    if constexpr (SplitScoreQReady) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            do_ready,
                            phase
                        );
                    }
                    if constexpr (
                        UseMixedFp8MxFp4Dp && !UseJointMixedDpScale
                    ) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            mixed_do_scale_ready,
                            phase
                        );
                    }
                    if constexpr (UseMxFp4Dp) {
                        auto &v_dp =
                            cta2_fused_dense_mxfp4_dp_v_stage(storage.ds);
                        auto &do_dp =
                            cta2_fused_dense_mxfp4_dp_do_stage(main.dout);
                        auto &v_dp_scale =
                            cta2_fused_dense_mxfp4_dp_v_scale_stage(
                                storage.ds
                            );
                        auto &do_dp_scale =
                            cta2_fused_dense_mxfp4_dp_do_scale_stage(
                                main.dout
                            );
                        // The score consumer has released the aliased P
                        // columns before dp_operands_ready.  Reuse the two
                        // exact-scale TMEM slots here, then overwrite them
                        // with P/dO scales for dV after dp_done.
                        load_mxnv_scale_async<2>(
                            dv_p_scale_tmem,
                            v_dp_scale
                        );
                        load_mxnv_scale_async<2>(
                            dv_do_scale_tmem,
                            do_dp_scale
                        );
                        tensor_load_wait();
                        cta2_fused_dense_mxfp4_scaled_mm2_abt_no_fence(
                            active_dp_tmem,
                            v_dp,
                            do_dp,
                            dv_p_scale_tmem,
                            dv_do_scale_tmem
                        );
                        cta2_fused_dense_commit_selected<
                            CacheTensorCommitAddresses
                        >(dp_done, dp_done_commit_address);
                    } else if constexpr (UseFp8Dp) {
                        auto &v_fp8 = *reinterpret_cast<
                            cta2_fused_dense_v_fp8_tile *
                        >(&storage.ds);
                        auto &do_dp =
                            cta2_fused_dense_fp8_dp_do_stage(main.dout);
                        if constexpr (UseMixedFp8MxFp4Dp) {
                            if constexpr (UseStreamedMixedDpN64) {
                                auto &fixed_scale = *reinterpret_cast<
                                    cta2_fused_dense_mxfp4_scale_tile *
                                >(
                                    &cta2_fused_dense_fp4_score_scale_smem(
                                        storage.k
                                    )
                                );
                                cta2_fused_dense_mixed_fp8_mxfp4_n64_mm2_abt_no_fence<
                                    0
                                >(
                                    streamed_dp_tmem,
                                    v_fp8,
                                    do_dp,
                                    score_as_mixed_dp_scale_tmem,
                                    score_as_mixed_dp_scale_tmem
                                );
                                load_mxnv_scale_async<2>(
                                    mixed_dp_score_scale_tmem,
                                    fixed_scale
                                );
                                ::kittens::tma::cluster::arrive(
                                    dp_head_done,
                                    0
                                );
                                ::kittens::tma::cluster::arrive(
                                    dp_head_done,
                                    1
                                );
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dp_head_consumed, phase);
                                tensor_load_wait();
                                cta2_fused_dense_mixed_fp8_mxfp4_n64_mm2_abt_no_fence<
                                    32
                                >(
                                    streamed_dp_tmem,
                                    v_fp8,
                                    do_dp,
                                    mixed_dp_score_scale_tmem,
                                    mixed_dp_score_scale_tmem
                                );
                            } else if constexpr (UseJointMixedDpScale) {
                                if constexpr (ReuseScoreScaleForMixedDp) {
                                    cta2_fused_dense_mixed_fp8_mxfp4_mm2_abt_no_fence<
                                        true
                                    >(
                                        active_dp_tmem,
                                        v_fp8,
                                        do_dp,
                                        mixed_dp_score_scale_tmem,
                                        mixed_dp_score_scale_tmem
                                    );
                                } else {
                                    if constexpr (
                                        !TK_FA4_BWD_MIXED_DP_STATIC_FP4_TAIL
                                    ) {
                                        auto &v_scale =
                                            cta2_fused_dense_mixed_dp_v_scale_stage(
                                                storage.ds
                                            );
                                        load_mxnv_scale_async<2>(
                                            dv_p_scale_tmem,
                                            v_scale
                                        );
                                        tensor_load_wait();
                                    }
                                    cta2_fused_dense_mixed_fp8_mxfp4_mm2_abt_no_fence(
                                        active_dp_tmem,
                                        v_fp8,
                                        do_dp,
                                        dv_p_scale_tmem,
                                        dv_p_scale_tmem
                                    );
                                }
                            } else {
                                auto &do_scale =
                                    cta2_fused_dense_mixed_dp_do_scale_stage(
                                        storage.ds
                                    );
                                auto &v_scale =
                                    cta2_fused_dense_mixed_dp_v_scale_stage(
                                        storage.ds
                                    );
                                load_mxnv_scale_async<2>(
                                    dv_p_scale_tmem,
                                    v_scale
                                );
                                load_mxnv_scale_async<2>(
                                    dv_do_scale_tmem,
                                    do_scale
                                );
                                tensor_load_wait();
                                cta2_fused_dense_mixed_fp8_mxfp4_mm2_abt_no_fence(
                                    active_dp_tmem,
                                    v_fp8,
                                    do_dp,
                                    dv_p_scale_tmem,
                                    dv_do_scale_tmem
                                );
                            }
                        } else {
                            cta2_fused_dense_fp8_mm2_abt_no_fence(
                                active_dp_tmem,
                                v_fp8,
                                do_dp
                            );
                        }
                        if constexpr (UseStreamedMixedDpN64) {
                            // The tail consumers immediately enqueue TMEM
                            // loads and execute tensor_load_wait, so dp_done
                            // can be the tail issue marker in this schedule.
                            // The later score_consumed fan-in is the reuse
                            // proof; a second completion barrier adds no
                            // safety and exposes the tail MMA latency.
                            ::kittens::tma::cluster::arrive(dp_done, 0);
                            ::kittens::tma::cluster::arrive(dp_done, 1);
                        } else {
                            cta2_fused_dense_commit_selected<
                                CacheTensorCommitAddresses
                            >(dp_done, dp_done_commit_address);
                        }
                        if constexpr (
                            UseEarlyMixedDpTmemWait &&
                            !UseStreamedMixedDpN64
                        ) {
                            ::kittens::tma::cluster::arrive(do_ready, 0);
                            ::kittens::tma::cluster::arrive(do_ready, 1);
                        }
                    } else if constexpr (UseCompactDpMma) {
                        uint64_t active_compact_dp_a_desc =
                            compact_dp_a_desc;
                        uint64_t active_compact_dp_b_desc =
                            compact_dp_b_desc;
                        if constexpr (
                            BuildCompactDpDescriptorsAfterWait
                        ) {
                            if constexpr (
                                CacheCompactDpDescriptorsInShared
                            ) {
                                active_compact_dp_a_desc =
                                    compact_dp_descriptor_scratch[0];
                                active_compact_dp_b_desc =
                                    compact_dp_descriptor_scratch[1];
                            } else {
                                ::kittens::st_descriptor<
                                    cta2_fused_dense_ds_tile,
                                    transpose::N
                                > a_desc(storage.ds);
                                ::kittens::st_descriptor<
                                    cta2_fused_dense_do_tile,
                                    transpose::N
                                > b_desc(main.dout);
                                active_compact_dp_a_desc = a_desc.base_desc;
                                active_compact_dp_b_desc = b_desc.base_desc;
                            }
                        }
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        cta2_fused_dense_dp_mma_commit_compact(
                            BuildCompactDpDescriptorsAfterWait
                                ? active_dp_tmem.addr
                                : score_dp_tmem.addr,
                            active_compact_dp_a_desc,
                            active_compact_dp_b_desc,
                            dp_done_commit_address
                        );
                    } else {
                        if constexpr (!PreloadDpsum) {
                            ::kittens::mm2_ABt(
                                dp_tmem,
                                storage.ds,
                                main.dout
                            );
                        } else {
                            ::kittens::mm2_ABt(
                                active_dp_tmem,
                                storage.ds,
                                main.dout
                            );
                        }
                        cta2_fused_dense_commit_selected<
                            CacheTensorCommitAddresses
                        >(dp_done, dp_done_commit_address);
                    }
                    if constexpr (SplitDvDkReady) {
                        if constexpr (SingleOwnerCluster && !UseFp8Pv) {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                owner_output_loaded,
                                phase
                            );
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dv_operands_ready,
                                phase
                            );
                        }
                        if constexpr (StreamDvTailBf16) {
                            if (have_streamed_dv_tail) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    dv_tail_consumed,
                                    streamed_dv_tail_phase
                                );
                            }
                        }
                        auto &do_normal =
                            *reinterpret_cast<st_bf<128, 64> *>(
                                &main.dout
                            );
                        if constexpr (UseFusedTmemPAndDs) {
                            if constexpr (UseMxFp4Dv) {
                                auto &do_nvfp4 = [&]()
                                    -> cta2_fused_dense_do_mxfp4_tile & {
                                    if constexpr (UseMxFp4Dp) {
                                        return cta2_fused_dense_mxfp4_dv_do_stage_pure(
                                            main.dout
                                        );
                                    } else {
                                        return cta2_fused_dense_mxfp4_dv_do_stage(
                                            main.dout
                                        );
                                    }
                                }();
                                auto &p_mxfp4_scale =
                                    cta2_fused_dense_mxfp4_p_scale_smem(
                                        storage.k
                                    );
                                auto &do_mxfp4_scale =
                                    cta2_fused_dense_mxfp4_do_scale_smem(
                                        storage.k
                                    );
                                load_mxnv_scale_async<2>(
                                    dv_p_scale_tmem,
                                    p_mxfp4_scale
                                );
                                load_mxnv_scale_async<2>(
                                    dv_do_scale_tmem,
                                    do_mxfp4_scale
                                );
                                tensor_load_wait();
                                if (first_accumulation) {
                                    cta2_fused_dense_tmem_a_mxfp4_scaled_mm2_ab_no_fence<
                                        0
                                    >(
                                        dv_tmem,
                                        p_mxfp4_tmem,
                                        do_nvfp4,
                                        dv_p_scale_tmem,
                                        dv_do_scale_tmem
                                    );
                                } else {
                                    cta2_fused_dense_tmem_a_mxfp4_scaled_mm2_ab_no_fence<
                                        1
                                    >(
                                        dv_tmem,
                                        p_mxfp4_tmem,
                                        do_nvfp4,
                                        dv_p_scale_tmem,
                                        dv_do_scale_tmem
                                    );
                                }
                            } else if constexpr (UseMixedFp8MxFp4Dv) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(
                                    mixed_do_scale_ready,
                                    phase
                                );
                                auto &do_fp8_head =
                                    cta2_fused_dense_mixed_dv_fp8_head_stage(
                                        main.dout
                                    );
#if TK_FA4_BWD_MIXED_DV_DIRECT_P_SCALE_TMEM
                                tensor_after_thread_sync();
#else
                                auto &p_mxfp4_scale =
                                    cta2_fused_dense_mxfp4_p_scale_smem(
                                        storage.k
                                    );
                                load_mxnv_scale_async<2>(
                                    dv_do_scale_tmem,
                                    p_mxfp4_scale
                                );
                                tensor_load_wait();
#endif
                                if (first_accumulation) {
                                    if constexpr (UsePaddedMixedDvTail) {
                                        cta2_fused_dense_tmem_a_mixed_fp8_mxfp4_mm2_ab_no_fence<
                                            0
                                        >(
                                            dv_tmem,
                                            p_fp8_tmem,
                                            do_fp8_head,
                                            p_mixed_dv_tail_tmem,
                                            cta2_fused_dense_mixed_dp_do_stage(
                                                main.dout
                                            ),
                                            dv_do_scale_tmem,
                                            dv_p_scale_tmem
                                        );
                                    } else {
                                        cta2_fused_dense_tmem_a_mixed_fp8_mxfp4_mm2_ab_no_fence<
                                            0
                                        >(
                                            dv_tmem,
                                            p_fp8_tmem,
                                            do_fp8_head,
                                            p_mixed_dv_tail_tmem,
                                            cta2_fused_dense_mixed_dv_mxfp4_tail_stage(
                                                main.dout
                                            ),
                                            dv_do_scale_tmem,
                                            dv_p_scale_tmem
                                        );
                                    }
                                } else {
                                    if constexpr (UsePaddedMixedDvTail) {
                                        cta2_fused_dense_tmem_a_mixed_fp8_mxfp4_mm2_ab_no_fence<
                                            1
                                        >(
                                            dv_tmem,
                                            p_fp8_tmem,
                                            do_fp8_head,
                                            p_mixed_dv_tail_tmem,
                                            cta2_fused_dense_mixed_dp_do_stage(
                                                main.dout
                                            ),
                                            dv_do_scale_tmem,
                                            dv_p_scale_tmem
                                        );
                                    } else {
                                        cta2_fused_dense_tmem_a_mixed_fp8_mxfp4_mm2_ab_no_fence<
                                            1
                                        >(
                                            dv_tmem,
                                            p_fp8_tmem,
                                            do_fp8_head,
                                            p_mixed_dv_tail_tmem,
                                            cta2_fused_dense_mixed_dv_mxfp4_tail_stage(
                                                main.dout
                                            ),
                                            dv_do_scale_tmem,
                                            dv_p_scale_tmem
