            const int owner_phase = OwnerQWorkSplitId >= 0
                ? (owner_pass == 0
                    ? 0
                    : ((owner_count - owner_pair_idx) & 1))
                : (SingleOwnerCluster || IntegrateCausalFrontier
                    ? 0
                    : (owner_pass & 1));
            const int owner_once_phase =
                SingleOwnerCluster ? 0 : (owner_pass & 1);
            const int first_dense_q_tile =
                2 * owner_idx + (IntegrateCausalFrontier ? 0 : 1) +
                (OwnerQWorkSplitId < 0 ? 0 : OwnerQWorkSplitId);
            auto &main = storage.phase.main;
            semaphore *current_qdo_done = &qdo_load_done;
            int current_qdo_phase = owner_once_phase;
            if constexpr (LoaderOwnedDkQ) {
                if (owner_pass == 0) {
                    if constexpr (UseFp8DqDk) {
                        auto &score_q_fp8 = *reinterpret_cast<
                            cta2_fused_dense_score_q_fp8_tile *
                        >(&main.q);
                        cta2_fused_dense_load_fp8_score_qdo_lowp_elected_pair<
                            true
                        >(
                            score_q_fp8,
                            g.q_fp8,
                            main.dout,
                            g.dout_dp_fp8,
                            g.dout_fp8,
                            coord<cta2_fused_dense_score_q_fp8_tile>{
                                batch_idx,
                                head_idx,
                                0,
                                first_dense_q_tile * 2 + cta_rank
                            },
                            batch_idx,
                            first_dense_q_tile,
                            head_idx,
                            cta_rank,
                            qdo_load_done,
                            UseLongSeqStatsCache
                                ? sizeof(sv_fl<128>)
                                : 0
                        );
                    } else if constexpr (UseFp4DqDk) {
                        auto &score_q_fp4 = *reinterpret_cast<
                            cta2_fused_dense_score_q_fp8_tile *
                        >(&main.q);
                        if constexpr (UseMxFp4Dp) {
                            auto &score_q_nvfp4 = *reinterpret_cast<
                                cta2_fused_dense_score_q_fp4_tile *
                            >(&main.q);
                            auto &do_dp =
                                cta2_fused_dense_mxfp4_dp_do_tma_stage(
                                    main.dout
                                );
                            auto &do_dv =
                                cta2_fused_dense_mxfp4_dv_do_stage_pure(
                                    main.dout
                                );
                            auto &do_dp_scale =
                                cta2_fused_dense_mxfp4_dp_do_scale_stage(
                                    main.dout
                                );
                            auto &do_dv_scale =
                                cta2_fused_dense_mxfp4_do_scale_smem(
                                    storage.k
                                );
                            const int dp_scale_page =
                                cta2_fused_dense_mxfp4_scale_page_index(
                                    batch_idx,
                                    first_dense_q_tile,
                                    head_idx,
                                    q_tile_count,
                                    g.q.rows()
                                );
                            const int dv_scale_page =
                                cta2_fused_dense_mxfp4_scale_page_index(
                                    batch_idx,
                                    first_dense_q_tile,
                                    head_idx,
                                    q_tile_count,
                                    g.q.rows()
                                );
                            cta2_fused_dense_load_fp4_score_qdo_pure_mxfp4_elected<
                                true,
                                SplitScoreQReady,
                                !(UseDoubleBufferedScoreQ &&
                                  TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q)
                            >(
                                score_q_nvfp4,
                                g.score_q_fp4,
                                do_dp,
                                g.dout_dp_mxfp4,
                                do_dv,
                                g.dout_mxfp4,
                                do_dp_scale,
                                g.dout_dp_mxfp4_scale,
                                dp_scale_page,
                                do_dv_scale,
                                g.dout_mxfp4_scale,
                                dv_scale_page,
                                coord<cta2_fused_dense_score_q_fp4_tile>{
                                    batch_idx,
                                    head_idx,
                                    first_dense_q_tile * 2 + cta_rank,
                                    0
                                },
                                coord<cta2_fused_dense_do_dp_mxfp4_tma_tile>{
                                    batch_idx,
                                    first_dense_q_tile * 2 + cta_rank,
                                    head_idx,
                                    0
                                },
                                coord<cta2_fused_dense_do_mxfp4_tile>{
                                    batch_idx,
                                    head_idx,
                                    cta_rank,
                                    first_dense_q_tile
                                },
                                SplitScoreQReady
                                    ? qdo_exchange_done
                                    : qdo_load_done,
                                UseLongSeqStatsCache
                                    ? sizeof(sv_fl<128>)
                                    : 0,
                                &qdo_load_done
                            );
                            if constexpr (
                                UseDoubleBufferedScoreQ &&
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q &&
                                !UseLongSeqStatsCache
                            ) {
                                warp::arrive(qdo_load_done);
                            }
                        } else if constexpr (UseFp8Dp) {
                            auto &score_q_nvfp4 = *reinterpret_cast<
                                cta2_fused_dense_score_q_fp4_tile *
                            >(&main.q);
                            auto &do_dp =
                                cta2_fused_dense_fp8_dp_do_stage(main.dout);
                            if constexpr (UseEarlyRawN96Score) {
                                auto &do_dv =
                                    cta2_fused_dense_fp8_dv_do_stage(
                                        main.dout
                                    );
                                auto &score_q_compact =
                                    cta2_fused_dense_early_compact_score_q_smem(
                                        main.q
                                    );
                                cta2_fused_dense_load_dual_fp4_score_qdo_dual_elected<
                                    true,
                                    SplitScoreQReady
                                >(
                                    score_q_fp4,
                                    g.q_fp4,
                                    score_q_compact,
                                    g.score_q_fp4,
                                    do_dp,
                                    g.dout_dp_fp8,
                                    do_dv,
                                    g.dout_fp8,
                                    coord<
                                        cta2_fused_dense_score_q_fp8_tile
                                    >{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        first_dense_q_tile * 2 + cta_rank
                                    },
                                    coord<
                                        cta2_fused_dense_score_q_fp4_tile
                                    >{
                                        batch_idx,
                                        head_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_dp_fp8_tile>{
                                        batch_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_fp8_tile>{
                                        batch_idx,
                                        first_dense_q_tile,
                                        head_idx,
                                        cta_rank
                                    },
                                    SplitScoreQReady
                                        ? qdo_exchange_done
                                        : qdo_load_done,
                                    UseLongSeqStatsCache
                                        ? sizeof(sv_fl<128>)
                                        : 0,
                                    &qdo_load_done
                                );
                            } else if constexpr (UseMxFp4Dv) {
                                auto &do_dv =
                                    cta2_fused_dense_mxfp4_dv_do_stage(
                                        main.dout
                                    );
                                auto &do_scale =
                                    cta2_fused_dense_mxfp4_do_scale_smem(
                                        storage.k
                                    );
                                const int scale_page =
                                    cta2_fused_dense_mxfp4_scale_page_index(
                                        batch_idx,
                                        first_dense_q_tile,
                                        head_idx,
                                        q_tile_count,
                                        g.q.rows()
                                    );
                                cta2_fused_dense_load_fp4_score_qdo_mxfp4_elected<
                                    true,
                                    SplitScoreQReady,
                                    !(UseDoubleBufferedScoreQ &&
                                      TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q)
                                >(
                                    score_q_nvfp4,
                                    g.score_q_fp4,
                                    do_dp,
                                    g.dout_dp_fp8,
                                    do_dv,
                                    g.dout_mxfp4,
                                    do_scale,
                                    g.dout_mxfp4_scale,
                                    scale_page,
                                    coord<cta2_fused_dense_score_q_fp4_tile>{
                                        batch_idx,
                                        head_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_dp_fp8_tile>{
                                        batch_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_mxfp4_tile>{
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        first_dense_q_tile
                                    },
                                    SplitScoreQReady
                                        ? qdo_exchange_done
                                        : qdo_load_done,
                                    UseLongSeqStatsCache
                                        ? sizeof(sv_fl<128>)
                                        : 0,
                                    &qdo_load_done
                                );
                                if constexpr (
                                    UseDoubleBufferedScoreQ &&
                                    TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q &&
                                    !UseLongSeqStatsCache
                                ) {
                                    warp::arrive(qdo_load_done);
                                }
                            } else if constexpr (UseMixedFp8MxFp4Dv) {
                                auto &do_dv_head =
                                    cta2_fused_dense_mixed_dv_fp8_head_stage(
                                        main.dout
                                    );
                                auto &do_dv_tail =
                                    cta2_fused_dense_mixed_dv_mxfp4_tail_stage(
                                        main.dout
                                    );
                                auto &do_dv_scale =
                                    cta2_fused_dense_mxfp4_do_scale_smem(
                                        storage.k
                                    );
                                const int scale_page =
                                    cta2_fused_dense_mxfp4_scale_page_index(
                                        batch_idx,
                                        first_dense_q_tile,
                                        head_idx,
                                        q_tile_count,
                                        g.q.rows()
                                    );
                                cta2_fused_dense_load_fp4_score_qdo_mixed_dv_elected<
                                    true,
                                    SplitScoreQReady,
                                    !(UseDoubleBufferedScoreQ &&
                                      TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q)
                                >(
                                    score_q_nvfp4,
                                    g.score_q_fp4,
                                    do_dp,
                                    g.dout_dp_fp8,
                                    do_dv_head,
                                    g.dout_fp8,
                                    do_dv_tail,
                                    g.dout_mxfp4,
                                    do_dv_scale,
                                    g.dout_mxfp4_scale,
                                    scale_page,
                                    coord<cta2_fused_dense_score_q_fp4_tile>{
                                        batch_idx,
                                        head_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_dp_fp8_tile>{
                                        batch_idx,
                                        first_dense_q_tile * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    coord<cta2_fused_dense_do_fp8_head_tile>{
                                        batch_idx,
                                        first_dense_q_tile * 2,
                                        head_idx,
                                        cta_rank
                                    },
                                    coord<cta2_fused_dense_do_mxfp4_tile>{
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        first_dense_q_tile
                                    },
                                    SplitScoreQReady
                                        ? qdo_exchange_done
                                        : qdo_load_done,
                                    mixed_do_scale_ready,
                                    UseLongSeqStatsCache
                                        ? sizeof(sv_fl<128>)
                                        : 0,
                                    &qdo_load_done
                                );
                                if constexpr (
                                    UseDoubleBufferedScoreQ &&
                                    TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q &&
                                    !UseLongSeqStatsCache
                                ) {
                                    warp::arrive(qdo_load_done);
                                }
                            } else {
                                auto &do_dv =
                                    cta2_fused_dense_fp8_dv_do_stage(
                                        main.dout
                                    );
                                if constexpr (
                                    UseMixedFp8MxFp4Dp &&
                                    !UseJointMixedDpScale
                                ) {
                                    auto &do_scale =
                                        cta2_fused_dense_mixed_dp_do_scale_stage(
                                            storage.ds
                                        );
                                    const int do_scale_page =
                                        cta2_fused_dense_mxfp4_scale_page_index(
                                            batch_idx,
                                            first_dense_q_tile,
                                            head_idx,
                                            q_tile_count,
                                            g.q.rows()
                                        );
                                    cta2_fused_dense_load_fp4_score_qdo_mixed_dp_elected<
                                        true,
                                        SplitScoreQReady,
                                        !(UseDoubleBufferedScoreQ &&
                                          TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q)
                                    >(
                                        score_q_nvfp4,
                                        g.score_q_fp4,
                                        do_dp,
                                        g.dout_dp_fp8,
                                        do_dv,
                                        g.dout_fp8,
                                        do_scale,
                                        g.dout_dp_mxfp4_scale,
                                        do_scale_page,
                                        coord<cta2_fused_dense_score_q_fp4_tile>{
                                            batch_idx,
                                            head_idx,
                                            first_dense_q_tile * 2 + cta_rank,
                                            0
                                        },
                                        coord<cta2_fused_dense_do_dp_fp8_tile>{
                                            batch_idx,
                                            first_dense_q_tile * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        coord<cta2_fused_dense_do_fp8_tile>{
                                            batch_idx,
                                            first_dense_q_tile,
                                            head_idx,
                                            cta_rank
                                        },
                                        SplitScoreQReady
                                            ? qdo_exchange_done
                                            : qdo_load_done,
                                        mixed_do_scale_ready,
                                        UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0,
                                        &qdo_load_done
                                    );
                                } else {
                                    cta2_fused_dense_load_fp4_score_qdo_dual_elected<
                                        true,
                                        SplitScoreQReady,
                                        !(UseDoubleBufferedScoreQ &&
                                          TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q)
                                    >(
                                        score_q_nvfp4,
                                        g.score_q_fp4,
                                        do_dp,
                                        g.dout_dp_fp8,
                                        do_dv,
                                        g.dout_fp8,
                                        coord<cta2_fused_dense_score_q_fp4_tile>{
                                            batch_idx,
                                            head_idx,
                                            first_dense_q_tile * 2 + cta_rank,
                                            0
                                        },
                                        coord<cta2_fused_dense_do_dp_fp8_tile>{
                                            batch_idx,
                                            first_dense_q_tile * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        coord<cta2_fused_dense_do_fp8_tile>{
                                            batch_idx,
                                            first_dense_q_tile,
                                            head_idx,
                                            cta_rank
                                        },
                                        SplitScoreQReady
                                            ? qdo_exchange_done
                                            : qdo_load_done,
                                        UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0,
                                        &qdo_load_done
                                    );
                                }
                                if constexpr (
                                    UseDoubleBufferedScoreQ &&
                                    TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q &&
                                    !UseLongSeqStatsCache
                                ) {
                                    warp::arrive(qdo_load_done);
                                }
                            }
                        } else {
                            cta2_fused_dense_load_fp8_score_qdo_elected_pair<
                                true
                            >(
                                score_q_fp4,
                                g.q_fp4,
                                main.dout,
                                g.dout,
                                coord<cta2_fused_dense_score_q_fp8_tile>{
                                    batch_idx,
                                    head_idx,
                                    0,
                                    first_dense_q_tile * 2 + cta_rank
                                },
                                coord<cta2_fused_dense_do_tile>{
                                    batch_idx,
                                    first_dense_q_tile * 2 + cta_rank,
                                    head_idx,
                                    0
                                },
                                qdo_load_done,
                                UseLongSeqStatsCache
                                    ? sizeof(sv_fl<128>)
                                    : 0
                            );
                        }
                    } else {
                        coord<cta2_fused_dense_q_tile> q_tile_coord = {
                            batch_idx,
                            first_dense_q_tile * 2 + cta_rank,
                            head_idx,
                            0
                        };
                        cta2_fused_dense_load_qdo_elected_pair(
                            main.q.q,
                            g.q,
                            main.dout,
                            g.dout,
                            q_tile_coord,
                            qdo_load_done,
                            UseLongSeqStatsCache
                                ? sizeof(sv_fl<128>)
                                : 0
                        );
                    }
                    if constexpr (UseLongSeqStatsCache) {
                        if (lane == 0) {
                            cta2_fused_dense_load_dpsum(
                                g,
                                storage.stats,
                                qdo_load_done,
                                batch_idx,
                                first_dense_q_tile,
                                head_idx
                            );
                        }
                    }
                }
            }
            int iteration = 0;
            int loader_phase = owner_phase;
            int loader_local_phase = OwnerQWorkSplitId >= 0
                ? (owner_pass == 0
                    ? 0
                    : ((owner_count - owner_pair_idx - 1) & 1))
                : (IntegrateCausalFrontier ? owner_pass : 0);
            for (
                int q_tile_idx = first_dense_q_tile;
                q_tile_idx < q_tile_count;
                q_tile_idx += q_tile_step,
                ++iteration,
                ++loader_stats_iteration
            ) {
                const int phase = CarryAllRolePhases
                    ? loader_phase
                    : ((iteration + owner_phase) & 1);
                const int local_phase = CarryAllRolePhases
                    ? loader_local_phase
                    : (OwnerQWorkSplitId >= 0
                        ? (iteration +
                           (owner_pass == 0
                                ? 0
                                : ((owner_count - owner_pair_idx - 1) & 1))) &
                            1
                        : (iteration +
                           (IntegrateCausalFrontier ? owner_pass : 0)) & 1);
                const bool has_next_q_tile =
                    q_tile_idx + q_tile_step < q_tile_count;
                if constexpr (UseCrossIterationScoreHead) {
                    if (iteration == 0 && lane == 0) {
                        // Seed phase zero before waiting to reuse the single
                        // scratch slot.  The first score has no preceding dQ
                        // alias, and delaying this arrival until the normal
                        // Q publication would form a tail/scratch cycle.
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        ::kittens::tma::cluster::arrive(
                            score_alias_ready,
                            0
                        );
                    }
                }
#if TK_FA4_BWD_PURE_MXFP4_EARLY_NEXT_SCORE_Q
                if constexpr (UseDoubleBufferedScoreQ) {
                    if (has_next_q_tile && lane == 0) {
                        if constexpr (UseScoreQScratchTail) {
                            if constexpr (UseCrossIterationN64Score) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(score_tail_done, phase);
                            } else {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(score_done, phase);
                            }
                        }
                        const int next_score_q_epoch = iteration + 1;
                        auto &next_score_q =
                            cta2_fused_dense_route_score_q_scratch<
                                UseScoreQScratchTail
                            >(
                                storage.qdo_phase,
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            );
                        tma::expect_bytes(
                            score_q_scratch_ready[
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            ],
                            sizeof(next_score_q)
                        );
                        tma::load_async<dim::ROW, cache_policy::NORMAL>(
                            next_score_q,
                            g.score_q_fp4,
                            coord<cta2_fused_dense_score_q_fp4_tile>{
                                batch_idx,
                                head_idx,
                                (q_tile_idx + q_tile_step) * 2 + cta_rank,
                                0
                            },
                            score_q_scratch_ready[
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            ]
                        );
                    }
                }
#endif
                if constexpr (UseLowpDp) {
                    // Both dO instruction layouts were loaded with qdo_ready;
                    // no BF16 peer relay is needed for dP or dV.
                } else if constexpr (ElectedPeerDoTmaLoad) {
                    if constexpr (PublishNextQdoAtDqAliasRelease) {
                        if (iteration == 0) {
                            cta2_fused_dense_load_peer_do_elected(
                                g,
                                storage.qdo_phase.qdo,
                                qdo_exchange_done,
                                batch_idx,
                                q_tile_idx,
                                head_idx,
                                cta_rank
                            );
                        }
                    } else {
                        cta2_fused_dense_load_peer_do_elected(
                            g,
                            storage.qdo_phase.qdo,
                            qdo_exchange_done,
                            batch_idx,
                            q_tile_idx,
                            head_idx,
                            cta_rank
                        );
                    }
                } else if (lane == 0) {
                    cta2_fused_dense_load_peer_qdo<
                        UseWideDkN192,
                        !DirectTmaDkQ
                    >(
                        g,
                        storage.qdo_phase.qdo,
                        qdo_exchange_done,
                        batch_idx,
                        q_tile_idx,
                        head_idx,
                        cta_rank
                    );
                }
                if constexpr (LoaderOwnedDkQ) {
                    if constexpr (PublishNextQdoAtDqAliasRelease) {
                        if (iteration == 0) {
                            cta2_fused_dense_role_wait<
                                TimeoutAllRoleWaits
                            >(
                                *current_qdo_done,
                                current_qdo_phase
                            );
                        }
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            *current_qdo_done,
                            current_qdo_phase
                        );
                    }
                } else if (iteration == 0) {
                    const bool issue_initial_qdo =
                        !PrefetchNextOwnerQdo || owner_pass == 0;
                    if (issue_initial_qdo) {
                        if constexpr (GroupQdoTmaLoads) {
                            if constexpr (UseFp8DqDk) {
                                auto &score_q_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                cta2_fused_dense_load_fp8_score_qdo_lowp_elected_pair<
                                    true
                                >(
                                    score_q_fp8,
                                    g.q_fp8,
                                    main.dout,
                                    g.dout_dp_fp8,
                                    g.dout_fp8,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        q_tile_idx * 2 + cta_rank
                                    },
                                    batch_idx,
                                    q_tile_idx,
                                    head_idx,
                                    cta_rank,
                                    qdo_load_done
                                );
                            } else if constexpr (UseFp4DqDk) {
                                auto &score_q_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                if constexpr (UseFp8Dp) {
                                    auto &score_q_nvfp4 = *reinterpret_cast<
                                        cta2_fused_dense_score_q_fp4_tile *
                                    >(&main.q);
                                    auto &do_dp =
                                        cta2_fused_dense_fp8_dp_do_stage(
                                            main.dout
                                        );
                                    if constexpr (UseEarlyRawN96Score) {
                                        auto &do_dv =
                                            cta2_fused_dense_fp8_dv_do_stage(
                                                main.dout
                                            );
                                        auto &score_q_compact =
                                            cta2_fused_dense_early_compact_score_q_smem(
                                                main.q
                                            );
                                        cta2_fused_dense_load_dual_fp4_score_qdo_dual_elected<
                                            true,
                                            false
                                        >(
                                            score_q_fp4,
                                            g.q_fp4,
                                            score_q_compact,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv,
                                            g.dout_fp8,
                                            coord<
                                                cta2_fused_dense_score_q_fp8_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                0,
                                                q_tile_idx * 2 + cta_rank
                                            },
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_fp8_tile
                                            >{
                                                batch_idx,
                                                q_tile_idx,
                                                head_idx,
                                                cta_rank
                                            },
                                            qdo_load_done
                                        );
                                    } else if constexpr (UseMxFp4Dv) {
                                        auto &do_dv =
                                            cta2_fused_dense_mxfp4_dv_do_stage(
                                                main.dout
                                            );
                                        auto &do_scale =
                                            cta2_fused_dense_mxfp4_do_scale_smem(
                                                storage.k
                                            );
                                        const int scale_page =
                                            cta2_fused_dense_mxfp4_scale_page_index(
                                                batch_idx,
                                                q_tile_idx,
                                                head_idx,
                                                q_tile_count,
                                                g.q.rows()
                                            );
                                        cta2_fused_dense_load_fp4_score_qdo_mxfp4_elected<
                                            true,
                                            false,
                                            !UseDoubleBufferedScoreQ
                                        >(
                                            score_q_nvfp4,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv,
                                            g.dout_mxfp4,
                                            do_scale,
                                            g.dout_mxfp4_scale,
                                            scale_page,
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_mxfp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                cta_rank,
                                                q_tile_idx
                                            },
                                            qdo_load_done
                                        );
                                    } else if constexpr (
                                        UseMixedFp8MxFp4Dv
                                    ) {
                                        auto &do_dv_head =
                                            cta2_fused_dense_mixed_dv_fp8_head_stage(
                                                main.dout
                                            );
                                        auto &do_dv_tail =
                                            cta2_fused_dense_mixed_dv_mxfp4_tail_stage(
                                                main.dout
                                            );
                                        auto &do_dv_scale =
                                            cta2_fused_dense_mxfp4_do_scale_smem(
                                                storage.k
                                            );
                                        const int scale_page =
                                            cta2_fused_dense_mxfp4_scale_page_index(
                                                batch_idx,
                                                q_tile_idx,
                                                head_idx,
                                                q_tile_count,
                                                g.q.rows()
                                            );
                                        cta2_fused_dense_load_fp4_score_qdo_mixed_dv_elected<
                                            true,
                                            false,
                                            !UseDoubleBufferedScoreQ
                                        >(
                                            score_q_nvfp4,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv_head,
                                            g.dout_fp8,
                                            do_dv_tail,
                                            g.dout_mxfp4,
                                            do_dv_scale,
                                            g.dout_mxfp4_scale,
                                            scale_page,
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_fp8_head_tile
                                            >{
                                                batch_idx,
                                                q_tile_idx * 2,
                                                head_idx,
                                                cta_rank
                                            },
                                            coord<
                                                cta2_fused_dense_do_mxfp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                cta_rank,
                                                q_tile_idx
                                            },
                                            qdo_load_done,
                                            mixed_do_scale_ready
                                        );
                                    } else {
                                        auto &do_dv =
                                            cta2_fused_dense_fp8_dv_do_stage(
                                                main.dout
                                            );
                                        if constexpr (
                                            UseMixedFp8MxFp4Dp &&
                                            !UseJointMixedDpScale
                                        ) {
                                            auto &do_scale =
                                                cta2_fused_dense_mixed_dp_do_scale_stage(
                                                    storage.ds
                                                );
                                            const int do_scale_page =
                                                cta2_fused_dense_mxfp4_scale_page_index(
                                                    batch_idx,
                                                    q_tile_idx,
                                                    head_idx,
                                                    q_tile_count,
                                                    g.q.rows()
                                                );
                                            cta2_fused_dense_load_fp4_score_qdo_mixed_dp_elected<
                                                true
                                            >(
                                                score_q_nvfp4,
                                                g.score_q_fp4,
                                                do_dp,
                                                g.dout_dp_fp8,
                                                do_dv,
                                                g.dout_fp8,
                                                do_scale,
                                                g.dout_dp_mxfp4_scale,
                                                do_scale_page,
                                                coord<
                                                    cta2_fused_dense_score_q_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    q_tile_idx * 2 + cta_rank,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                >{
                                                    batch_idx,
                                                    q_tile_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_fp8_tile
                                                >{
                                                    batch_idx,
                                                    q_tile_idx,
                                                    head_idx,
                                                    cta_rank
                                                },
                                                qdo_load_done,
                                                mixed_do_scale_ready
                                            );
                                        } else {
                                            cta2_fused_dense_load_fp4_score_qdo_dual_elected<
                                                true
                                            >(
                                                score_q_nvfp4,
                                                g.score_q_fp4,
                                                do_dp,
                                                g.dout_dp_fp8,
                                                do_dv,
                                                g.dout_fp8,
                                                coord<
                                                    cta2_fused_dense_score_q_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    q_tile_idx * 2 + cta_rank,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                >{
                                                    batch_idx,
                                                    q_tile_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                coord<cta2_fused_dense_do_fp8_tile>{
                                                    batch_idx,
                                                    q_tile_idx,
                                                    head_idx,
                                                    cta_rank
                                                },
                                                qdo_load_done
                                            );
                                        }
                                    }
                                } else {
                                    cta2_fused_dense_load_fp8_score_qdo_elected_pair<
                                        true
                                    >(
                                        score_q_fp4,
                                        g.q_fp4,
                                        main.dout,
                                        g.dout,
                                        coord<cta2_fused_dense_score_q_fp8_tile>{
                                            batch_idx,
                                            head_idx,
                                            0,
                                            q_tile_idx * 2 + cta_rank
                                        },
                                        coord<cta2_fused_dense_do_tile>{
                                            batch_idx,
                                            q_tile_idx * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        qdo_load_done
                                    );
                                }
                            } else {
                                coord<cta2_fused_dense_q_tile>
                                    q_tile_coord = {
                                        batch_idx,
                                        q_tile_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                };
                                cta2_fused_dense_load_qdo_elected_pair(
                                    main.q.q,
                                    g.q,
                                    main.dout,
                                    g.dout,
                                    q_tile_coord,
                                    qdo_load_done
                                );
                            }
                        } else if (lane == 0) {
                            coord<cta2_fused_dense_do_tile> do_tile_coord = {
                                batch_idx,
                                q_tile_idx * 2 + cta_rank,
                                head_idx,
                                0
                            };
                            if constexpr (UseFp8DqDk) {
                                auto &score_q_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                tma::expect_bytes(
                                    qdo_load_done,
                                    sizeof(score_q_fp8) + sizeof(main.dout)
                                );
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    score_q_fp8,
                                    g.q_fp8,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        q_tile_idx * 2 + cta_rank
                                    },
                                    qdo_load_done
                                );
                            } else if constexpr (UseFp4DqDk) {
                                auto &score_q_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                tma::expect_bytes(
                                    qdo_load_done,
                                    sizeof(score_q_fp4) + sizeof(main.dout)
                                );
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    score_q_fp4,
                                    g.q_fp4,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        q_tile_idx * 2 + cta_rank
                                    },
                                    qdo_load_done
                                );
                            } else {
                                tma::expect_bytes(
                                    qdo_load_done,
                                    sizeof(main.q.q) + sizeof(main.dout)
                                );
                                tma::load_async<
                                    dim::DEPTH,
                                    cache_policy::NORMAL
                                >(
                                    main.q.q,
                                    g.q,
                                    coord<cta2_fused_dense_q_tile>{
                                        batch_idx,
                                        q_tile_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    qdo_load_done
                                );
                            }
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                main.dout,
                                g.dout,
                                do_tile_coord,
                                qdo_load_done
                            );
                        }
                    }
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        qdo_load_done,
                        owner_once_phase
                    );
                } else {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        qdo_prefetch_done,
                        local_phase ^ 1
                    );
                    if constexpr (!DirectNextQdoDuringDqDrain) {
                        auto &next_q =
                            storage.phase.dq.operands.exchange.next_q;
                        auto &next_dout =
                            *reinterpret_cast<cta2_fused_dense_do_tile *>(
                                &storage.ds
                            );
                        #pragma unroll 1
                        for (
                            int logical_warp = 0;
                            logical_warp < 4;
                            ++logical_warp
                        ) {
                            rt_bf<16, kB300QKDim> q_reg;
                            auto q_source =
                                next_q.template subtile<16, kB300QKDim>(
                                    {logical_warp, 0}
                                );
                            auto q_destination =
                                main.q.q.template subtile<16, kB300QKDim>(
                                    {logical_warp, 0}
                                );
                            warp::load(q_reg, q_source);
                            warp::store(q_destination, q_reg);
                        }
                        #pragma unroll 1
                        for (
                            int logical_warp = 0;
                            logical_warp < 4;
                            ++logical_warp
                        ) {
                            rt_bf<16, kB300VDim> do_reg;
                            auto do_source =
                                next_dout.template subtile<16, kB300VDim>(
                                    {logical_warp, 0}
                                );
                            auto do_destination =
                                main.dout.template subtile<16, kB300VDim>(
                                    {logical_warp, 0}
                                );
                            warp::load(do_reg, do_source);
                            warp::store(do_destination, do_reg);
                        }
                    }
                }
                if constexpr (PublishNextQdoAtDqAliasRelease) {
                    if (iteration == 0 && lane == 0) {
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        if constexpr (CacheQdoReadyClusterAddress) {
                            cta2_fused_dense_cluster_arrive_mapped(
                                qdo_ready_cluster_address
                            );
                        } else {
                            ::kittens::tma::cluster::arrive(qdo_ready, 0);
                        }
                    }
                } else {
                    if constexpr (LeaderOnlyQdoPublishFence) {
                        if (lane == 0) {
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                            if constexpr (CacheQdoReadyClusterAddress) {
                                cta2_fused_dense_cluster_arrive_mapped(
                                    qdo_ready_cluster_address
                                );
                            } else {
                                ::kittens::tma::cluster::arrive(qdo_ready, 0);
                            }
                        }
                    } else {
                        asm volatile(
                            "fence.proxy.async.shared::cta;"
                            ::: "memory"
                        );
                        __syncwarp();
                        if (lane == 0) {
                            ::kittens::tma::cluster::arrive(qdo_ready, 0);
                        }
                    }
                }
#if !TK_FA4_BWD_PURE_MXFP4_EARLY_NEXT_SCORE_Q
                if constexpr (UseDoubleBufferedScoreQ) {
                    if (has_next_q_tile && lane == 0) {
                        if constexpr (UseScoreQScratchTail) {
                            if constexpr (UseCrossIterationN64Score) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(score_tail_done, phase);
                            } else {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(score_done, phase);
                            }
                        }
                        const int next_score_q_epoch = iteration + 1;
                        auto &next_score_q =
                            cta2_fused_dense_route_score_q_scratch<
                                UseScoreQScratchTail
                            >(
                                storage.qdo_phase,
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            );
                        tma::expect_bytes(
                            score_q_scratch_ready[
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            ],
                            sizeof(next_score_q)
                        );
                        tma::load_async<dim::ROW, cache_policy::NORMAL>(
                            next_score_q,
                            g.score_q_fp4,
                            coord<cta2_fused_dense_score_q_fp4_tile>{
                                batch_idx,
                                head_idx,
                                (q_tile_idx + q_tile_step) * 2 + cta_rank,
                                0
                            },
                            score_q_scratch_ready[
                                TK_FA4_BWD_PURE_MXFP4_EARLY_FIRST_SCORE_Q
                                    ? (next_score_q_epoch & 1)
                                    : (iteration & 1)
                            ]
                        );
                    }
                }
#endif
                if constexpr (LoaderOwnedDkQ) {
                    if constexpr (SplitScoreQReady) {
                        // dO has an independent transaction and main.dout is
                        // not touched by score.  Publish its completion while
                        // the tensor warp executes score instead of adding a
                        // loader round trip after score_done.
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            qdo_exchange_done,
                            phase
                        );
                        if (lane == 0) {
                            asm volatile(
                                "fence.proxy.async.shared::cta;"
                                ::: "memory"
                            );
                            ::kittens::tma::cluster::arrive(do_ready, 0);
                        }
                    }
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        score_done,
                        phase
                    );
                    if constexpr (
                        UseCrossIterationN64Score || UseSplitN96Score
                    ) {
                        // score_done covers only the progressive score head.
                        // Keep compact score-Q intact until the tail MMA has
                        // completed, then reuse main.q for dK.
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_tail_done,
                            phase
                        );
                    }
                    if constexpr (UseFp8DqDk) {
                        if (lane == 0) {
                            auto &q_fp8 = *reinterpret_cast<
                                cta2_fused_dense_q_fp8_transposed_wide_tile *
                            >(&main.q);
                            tma::expect_bytes(
                                q_source_loaded,
                                sizeof(q_fp8)
                            );
                            tma::load_async<
                                dim::ROW,
                                cache_policy::NORMAL
                            >(
                                q_fp8,
                                g.q_fp8,
                                coord<
                                    cta2_fused_dense_q_fp8_transposed_wide_tile
                                >{
                                    batch_idx,
                                    head_idx,
                                    cta_rank,
                                    q_tile_idx
                                },
                                q_source_loaded
                            );
                        }
                    } else if constexpr (UseFp4DqDk) {
                        if (lane == 0) {
                            if constexpr (UsePureMxFp4DqDk) {
                                auto &q_mxfp4_tma = *reinterpret_cast<
                                    cta2_fused_dense_dk_q_mxfp4_tma_tile *
                                >(&main.q);
                                tma::expect_bytes(
                                    q_source_loaded,
                                    sizeof(q_mxfp4_tma)
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    !TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                                        + 2 * sizeof(
                                            cta2_fused_dense_nvfp4_scale_tile
                                        )
#endif
                                );
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    q_mxfp4_tma,
                                    g.q_dk_mxfp4,
                                    coord<
                                        cta2_fused_dense_dk_q_mxfp4_tma_tile
                                    >{
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        q_tile_idx
                                    },
                                    q_source_loaded
                                );
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    !TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                                cta2_fused_dense_load_q_nvfp4_scales(
                                    storage,
                                    g,
                                    batch_idx,
                                    head_idx,
                                    cta_rank,
                                    q_tile_idx,
                                    q_source_loaded
                                );
#endif
                            } else {
                                auto &q_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_q_fp4_transposed_wide_tile *
                                >(&main.q);
                                tma::expect_bytes(
                                    q_source_loaded,
                                    sizeof(q_fp4)
                                );
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    q_fp4,
                                    g.q_fp4,
                                    coord<
                                        cta2_fused_dense_q_fp4_transposed_wide_tile
                                    >{
                                        batch_idx,
                                        head_idx,
                                        cta_rank,
                                        q_tile_idx
                                    },
                                    q_source_loaded
                                );
                            }
                        }
                    } else {
                        cta2_fused_dense_load_dk_q_wide_elected(
                            main.q.normal_wide,
                            g.q,
                            coord<cta2_fused_dense_q_normal_wide_tile>{
                                batch_idx,
                                q_tile_idx,
                                head_idx,
                                cta_rank
                            },
                            q_source_loaded
                        );
                    }
                }
                const bool prefetch_next_owner =
                    PrefetchNextOwnerQdo && owner_pass == 0 && !has_next_q_tile;
                if (has_next_q_tile || prefetch_next_owner) {
                    if constexpr (DirectNextQdoDuringDqDrain) {
                        semaphore *prefetch_done = &qdo_prefetch_done;
                        semaphore *score_prefetch_done = &qdo_prefetch_done;
                        if constexpr (JoinNextQdoWithDqAliasRelease) {
                            if (has_next_q_tile) {
                                if constexpr (SplitScoreQReady) {
                                    prefetch_done = &qdo_exchange_done;
                                    score_prefetch_done =
                                        UseCrossIterationScoreHead &&
                                                !UseDoubleBufferedScoreQ
                                            ? &qdo_prefetch_done
                                            : &dq_reduce_done;
                                } else {
                                    prefetch_done = &dq_reduce_done;
                                }
                            }
                        }
                        if constexpr (PrefetchNextOwnerQdo) {
                            if (prefetch_next_owner) {
                                prefetch_done = &qdo_load_done;
                            }
                        }
                        if constexpr (PrearmNextQdoBeforeDkDone) {
                            if constexpr (SplitScoreQReady) {
                                if constexpr (!UseDoubleBufferedScoreQ) {
                                    cta2_fused_dense_arm_elected_transaction(
                                        *score_prefetch_done,
                                        (UseEarlyRawN96Score
                                            ? sizeof(
                                                cta2_fused_dense_score_q_fp8_tile
                                              ) + sizeof(
                                                cta2_fused_dense_score_q_fp4_tile
                                              )
                                            : sizeof(
                                                cta2_fused_dense_score_q_fp4_tile
                                              )) + (UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0)
                                    );
                                }
                                cta2_fused_dense_arm_elected_transaction(
                                    *prefetch_done,
                                    UseMxFp4Dv
                                        ? ((UseMxFp4Dp
                                            ? sizeof(
                                                cta2_fused_dense_do_dp_mxfp4_tile
                                              )
                                            : sizeof(
                                                cta2_fused_dense_do_dp_fp8_tile
                                              )) + sizeof(
                                                cta2_fused_dense_do_mxfp4_tile
                                              ) + sizeof(
                                                cta2_fused_dense_mxfp4_scale_tile
                                              ) + (UseMxFp4Dp
                                                ? sizeof(
                                                    cta2_fused_dense_mxfp4_scale_tile
                                                  )
                                                : 0))
                                        : (UseMixedFp8MxFp4Dv
                                            ? sizeof(
                                                cta2_fused_dense_do_dp_fp8_tile
                                              ) + sizeof(
                                                cta2_fused_dense_do_fp8_head_tile
                                              )
                                            : sizeof(
                                            cta2_fused_dense_do_dp_fp8_tile
                                          ) + sizeof(
                                            cta2_fused_dense_do_fp8_tile
                                          ))
                                );
                            } else {
                                cta2_fused_dense_arm_elected_transaction(
                                    *prefetch_done,
                                    (UseNvFp4Score
                                        ? (UseDoubleBufferedScoreQ
                                            ? 0
                                            : sizeof(
                                                cta2_fused_dense_score_q_fp4_tile
                                              ))
                                        : ((UseFp8DqDk || UseFp4DqDk)
                                            ? sizeof(
                                                cta2_fused_dense_score_q_fp8_tile
                                            )
                                            : sizeof(
                                                cta2_fused_dense_q_tile
                                            ))) +
                                        (UseMxFp4Dv
                                            ? (UseMxFp4Dp
                                                ? sizeof(
                                                    cta2_fused_dense_do_dp_mxfp4_tile
                                                  )
                                                : sizeof(
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                  )) + sizeof(
                                                cta2_fused_dense_do_mxfp4_tile
                                              )
                                            : (UseMixedFp8MxFp4Dv
                                                ? sizeof(
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                  ) + sizeof(
                                                    cta2_fused_dense_do_fp8_head_tile
                                                  )
                                                : sizeof(
                                                cta2_fused_dense_do_tile
                                              ))) +
                                        (UseMxFp4Dv
                                            ? sizeof(
                                                cta2_fused_dense_mxfp4_scale_tile
                                              )
                                            : 0) +
                                        (UseMxFp4Dp
                                            ? sizeof(
                                                cta2_fused_dense_mxfp4_scale_tile
                                              )
                                            : 0) +
                                        (UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0)
                                );
                            }
                        }
                        if constexpr (PrefetchNextQdoAfterDkdv) {
                            if constexpr (
                                UsePureMxFp4DqDk &&
                                TK_FA4_BWD_PURE_MXFP4_RELOAD_DO_AFTER_DV
                            ) {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dkdv_done, phase);
                            } else {
                                cta2_fused_dense_role_wait<
                                    TimeoutAllRoleWaits
                                >(dk_done, phase);
                            }
                        } else if constexpr (TimeoutDqWait) {
                            cta2_fused_dense_wait_timeout(dq_done, phase);
                        } else {
                            cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                                dq_done,
                                phase
                            );
                        }
                        int next_q_tile_idx = q_tile_idx + q_tile_step;
                        if constexpr (PrefetchNextOwnerQdo) {
                            if (prefetch_next_owner) {
                                const int next_owner_idx =
                                    owner_count - 1 - owner_pair_idx;
                                next_q_tile_idx = 2 * next_owner_idx;
                            }
                        }
                        if constexpr (GroupQdoTmaLoads) {
                            if constexpr (UseFp8DqDk) {
                                auto &score_q_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                constexpr bool kArmQdo =
                                    !PrearmNextQdoBeforeDkDone;
                                cta2_fused_dense_load_fp8_score_qdo_lowp_elected_pair<
                                    kArmQdo
                                >(
                                    score_q_fp8,
                                    g.q_fp8,
                                    main.dout,
                                    g.dout_dp_fp8,
                                    g.dout_fp8,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        next_q_tile_idx * 2 + cta_rank
                                    },
                                    batch_idx,
                                    next_q_tile_idx,
                                    head_idx,
                                    cta_rank,
                                    *prefetch_done,
                                    UseLongSeqStatsCache
                                        ? sizeof(sv_fl<128>)
                                        : 0
                                );
                            } else if constexpr (UseFp4DqDk) {
                                auto &score_q_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                constexpr bool kArmQdo =
                                    !PrearmNextQdoBeforeDkDone;
                                if constexpr (UseMxFp4Dp) {
                                    auto &score_q_nvfp4 = *reinterpret_cast<
                                        cta2_fused_dense_score_q_fp4_tile *
                                    >(&main.q);
                                    auto &do_dp =
                                        cta2_fused_dense_mxfp4_dp_do_tma_stage(
                                            main.dout
                                        );
                                    auto &do_dv =
                                        cta2_fused_dense_mxfp4_dv_do_stage_pure(
                                            main.dout
                                        );
                                    auto &do_dp_scale =
                                        cta2_fused_dense_mxfp4_dp_do_scale_stage(
                                            main.dout
                                        );
                                    auto &do_dv_scale =
                                        cta2_fused_dense_mxfp4_do_scale_smem(
                                            storage.k
                                        );
                                    const int dp_scale_page =
                                        cta2_fused_dense_mxfp4_scale_page_index(
                                            batch_idx,
                                            next_q_tile_idx,
                                            head_idx,
                                            q_tile_count,
                                            g.q.rows()
                                        );
                                    const int dv_scale_page =
                                        cta2_fused_dense_mxfp4_scale_page_index(
                                            batch_idx,
                                            next_q_tile_idx,
                                            head_idx,
                                            q_tile_count,
                                            g.q.rows()
                                        );
                                    cta2_fused_dense_load_fp4_score_qdo_pure_mxfp4_elected<
                                        kArmQdo,
                                        SplitScoreQReady,
                                        !UseDoubleBufferedScoreQ
                                    >(
                                        score_q_nvfp4,
                                        g.score_q_fp4,
                                        do_dp,
                                        g.dout_dp_mxfp4,
                                        do_dv,
                                        g.dout_mxfp4,
                                        do_dp_scale,
                                        g.dout_dp_mxfp4_scale,
                                        dp_scale_page,
                                        do_dv_scale,
                                        g.dout_mxfp4_scale,
                                        dv_scale_page,
                                        coord<
                                            cta2_fused_dense_score_q_fp4_tile
                                        >{
                                            batch_idx,
                                            head_idx,
                                            next_q_tile_idx * 2 + cta_rank,
                                            0
                                        },
                                        coord<
                                            cta2_fused_dense_do_dp_mxfp4_tma_tile
                                        >{
                                            batch_idx,
                                            next_q_tile_idx * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        coord<
                                            cta2_fused_dense_do_mxfp4_tile
                                        >{
                                            batch_idx,
                                            head_idx,
                                            cta_rank,
                                            next_q_tile_idx
                                        },
                                        *prefetch_done,
                                        UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0,
                                        score_prefetch_done
                                    );
                                } else if constexpr (UseFp8Dp) {
                                    auto &score_q_nvfp4 = *reinterpret_cast<
                                        cta2_fused_dense_score_q_fp4_tile *
                                    >(&main.q);
                                    auto &do_dp =
                                        cta2_fused_dense_fp8_dp_do_stage(
                                            main.dout
                                        );
                                    if constexpr (UseEarlyRawN96Score) {
                                        auto &do_dv =
                                            cta2_fused_dense_fp8_dv_do_stage(
                                                main.dout
                                            );
                                        auto &score_q_compact =
                                            cta2_fused_dense_early_compact_score_q_smem(
                                                main.q
                                            );
                                        cta2_fused_dense_load_dual_fp4_score_qdo_dual_elected<
                                            kArmQdo,
                                            SplitScoreQReady
                                        >(
                                            score_q_fp4,
                                            g.q_fp4,
                                            score_q_compact,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv,
                                            g.dout_fp8,
                                            coord<
                                                cta2_fused_dense_score_q_fp8_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                0,
                                                next_q_tile_idx * 2 + cta_rank
                                            },
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_fp8_tile
                                            >{
                                                batch_idx,
                                                next_q_tile_idx,
                                                head_idx,
                                                cta_rank
                                            },
                                            *prefetch_done,
                                            UseLongSeqStatsCache
                                                ? sizeof(sv_fl<128>)
                                                : 0,
                                            score_prefetch_done
                                        );
                                    } else if constexpr (UseMxFp4Dv) {
                                        auto &do_dv =
                                            cta2_fused_dense_mxfp4_dv_do_stage(
                                                main.dout
                                            );
                                        auto &do_scale =
                                            cta2_fused_dense_mxfp4_do_scale_smem(
                                                storage.k
                                            );
                                        const int scale_page =
                                            cta2_fused_dense_mxfp4_scale_page_index(
                                                batch_idx,
                                                next_q_tile_idx,
                                                head_idx,
                                                q_tile_count,
                                                g.q.rows()
                                            );
                                        cta2_fused_dense_load_fp4_score_qdo_mxfp4_elected<
                                            kArmQdo,
                                            SplitScoreQReady,
                                            !UseDoubleBufferedScoreQ
                                        >(
                                            score_q_nvfp4,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv,
                                            g.dout_mxfp4,
                                            do_scale,
                                            g.dout_mxfp4_scale,
                                            scale_page,
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_mxfp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                cta_rank,
                                                next_q_tile_idx
                                            },
                                            *prefetch_done,
                                            UseLongSeqStatsCache
                                                ? sizeof(sv_fl<128>)
                                                : 0,
                                            score_prefetch_done
                                        );
                                    } else if constexpr (
                                        UseMixedFp8MxFp4Dv
                                    ) {
                                        auto &do_dv_head =
                                            cta2_fused_dense_mixed_dv_fp8_head_stage(
                                                main.dout
                                            );
                                        auto &do_dv_tail =
                                            cta2_fused_dense_mixed_dv_mxfp4_tail_stage(
                                                main.dout
                                            );
                                        auto &do_dv_scale =
                                            cta2_fused_dense_mxfp4_do_scale_smem(
                                                storage.k
                                            );
                                        const int scale_page =
                                            cta2_fused_dense_mxfp4_scale_page_index(
                                                batch_idx,
                                                next_q_tile_idx,
                                                head_idx,
                                                q_tile_count,
                                                g.q.rows()
                                            );
                                        cta2_fused_dense_load_fp4_score_qdo_mixed_dv_elected<
                                            kArmQdo,
                                            SplitScoreQReady,
                                            !UseDoubleBufferedScoreQ
                                        >(
                                            score_q_nvfp4,
                                            g.score_q_fp4,
                                            do_dp,
                                            g.dout_dp_fp8,
                                            do_dv_head,
                                            g.dout_fp8,
                                            do_dv_tail,
                                            g.dout_mxfp4,
                                            do_dv_scale,
                                            g.dout_mxfp4_scale,
                                            scale_page,
                                            coord<
                                                cta2_fused_dense_score_q_fp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_dp_fp8_tile
                                            >{
                                                batch_idx,
                                                next_q_tile_idx * 2 + cta_rank,
                                                head_idx,
                                                0
                                            },
                                            coord<
                                                cta2_fused_dense_do_fp8_head_tile
                                            >{
                                                batch_idx,
                                                next_q_tile_idx * 2,
                                                head_idx,
                                                cta_rank
                                            },
                                            coord<
                                                cta2_fused_dense_do_mxfp4_tile
                                            >{
                                                batch_idx,
                                                head_idx,
                                                cta_rank,
                                                next_q_tile_idx
                                            },
                                            *prefetch_done,
                                            mixed_do_scale_ready,
                                            UseLongSeqStatsCache
                                                ? sizeof(sv_fl<128>)
                                                : 0,
                                            score_prefetch_done
                                        );
                                    } else {
                                        auto &do_dv =
                                            cta2_fused_dense_fp8_dv_do_stage(
                                                main.dout
                                            );
                                        if constexpr (
                                            UseMixedFp8MxFp4Dp &&
                                            !UseJointMixedDpScale
                                        ) {
                                            auto &do_scale =
                                                cta2_fused_dense_mixed_dp_do_scale_stage(
                                                    storage.ds
                                                );
                                            const int do_scale_page =
                                                cta2_fused_dense_mxfp4_scale_page_index(
                                                    batch_idx,
                                                    next_q_tile_idx,
                                                    head_idx,
                                                    q_tile_count,
                                                    g.q.rows()
                                                );
                                            cta2_fused_dense_load_fp4_score_qdo_mixed_dp_elected<
                                                kArmQdo,
                                                SplitScoreQReady,
                                                !UseDoubleBufferedScoreQ
                                            >(
                                                score_q_nvfp4,
                                                g.score_q_fp4,
                                                do_dp,
                                                g.dout_dp_fp8,
                                                do_dv,
                                                g.dout_fp8,
                                                do_scale,
                                                g.dout_dp_mxfp4_scale,
                                                do_scale_page,
                                                coord<
                                                    cta2_fused_dense_score_q_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    next_q_tile_idx * 2 + cta_rank,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                >{
                                                    batch_idx,
                                                    next_q_tile_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_fp8_tile
                                                >{
                                                    batch_idx,
                                                    next_q_tile_idx,
                                                    head_idx,
                                                    cta_rank
                                                },
                                                *prefetch_done,
                                                mixed_do_scale_ready,
                                                UseLongSeqStatsCache
                                                    ? sizeof(sv_fl<128>)
                                                    : 0,
                                                score_prefetch_done
                                            );
                                        } else {
                                            cta2_fused_dense_load_fp4_score_qdo_dual_elected<
                                                kArmQdo,
                                                SplitScoreQReady,
                                                !UseDoubleBufferedScoreQ
                                            >(
                                                score_q_nvfp4,
                                                g.score_q_fp4,
                                                do_dp,
                                                g.dout_dp_fp8,
                                                do_dv,
                                                g.dout_fp8,
                                                coord<
                                                    cta2_fused_dense_score_q_fp4_tile
                                                >{
                                                    batch_idx,
                                                    head_idx,
                                                    next_q_tile_idx * 2 + cta_rank,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_dp_fp8_tile
                                                >{
                                                    batch_idx,
                                                    next_q_tile_idx * 2 + cta_rank,
                                                    head_idx,
                                                    0
                                                },
                                                coord<
                                                    cta2_fused_dense_do_fp8_tile
                                                >{
                                                    batch_idx,
                                                    next_q_tile_idx,
                                                    head_idx,
                                                    cta_rank
                                                },
                                                *prefetch_done,
                                                UseLongSeqStatsCache
                                                    ? sizeof(sv_fl<128>)
                                                    : 0,
                                                score_prefetch_done
                                            );
                                        }
                                    }
                                } else {
                                    cta2_fused_dense_load_fp8_score_qdo_elected_pair<
                                        kArmQdo
                                    >(
                                        score_q_fp4,
                                        g.q_fp4,
                                        main.dout,
                                        g.dout,
                                        coord<cta2_fused_dense_score_q_fp8_tile>{
                                            batch_idx,
                                            head_idx,
                                            0,
                                            next_q_tile_idx * 2 + cta_rank
                                        },
                                        coord<cta2_fused_dense_do_tile>{
                                            batch_idx,
                                            next_q_tile_idx * 2 + cta_rank,
                                            head_idx,
                                            0
                                        },
                                        *prefetch_done,
                                        UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0
                                    );
                                }
                            } else {
                                coord<cta2_fused_dense_q_tile>
                                    next_q_tile_coord = {
                                        batch_idx,
                                        next_q_tile_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                };
                                if constexpr (PrearmNextQdoBeforeDkDone) {
                                    cta2_fused_dense_load_qdo_elected_pair_no_arm(
                                        main.q.q,
                                        g.q,
                                        main.dout,
                                        g.dout,
                                        next_q_tile_coord,
                                        *prefetch_done
                                    );
                                } else {
                                    cta2_fused_dense_load_qdo_elected_pair(
                                        main.q.q,
                                        g.q,
                                        main.dout,
                                        g.dout,
                                        next_q_tile_coord,
                                        *prefetch_done,
                                        UseLongSeqStatsCache
                                            ? sizeof(sv_fl<128>)
                                            : 0
                                    );
                                }
                            }
                        } else if (lane == 0) {
                            tma::expect_bytes(
                                *prefetch_done,
                                (UseFp8DqDk
                                    ? sizeof(
                                        cta2_fused_dense_score_q_fp8_tile
                                    )
                                    : (UseFp4DqDk
                                        ? sizeof(
                                            cta2_fused_dense_score_q_fp8_tile
                                        )
                                        : sizeof(main.q.q))) +
                                    sizeof(main.dout) +
                                    (UseLongSeqStatsCache
                                        ? sizeof(sv_fl<128>)
                                        : 0)
                            );
                            coord<cta2_fused_dense_do_tile>
                                next_do_tile_coord = {
                                    batch_idx,
                                    next_q_tile_idx * 2 + cta_rank,
                                    head_idx,
                                    0
                            };
                            if constexpr (UseFp8DqDk) {
                                auto &score_q_fp8 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    score_q_fp8,
                                    g.q_fp8,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        next_q_tile_idx * 2 + cta_rank
                                    },
                                    *prefetch_done
                                );
                            } else if constexpr (UseFp4DqDk) {
                                auto &score_q_fp4 = *reinterpret_cast<
                                    cta2_fused_dense_score_q_fp8_tile *
                                >(&main.q);
                                tma::load_async<
                                    dim::ROW,
                                    cache_policy::NORMAL
                                >(
                                    score_q_fp4,
                                    g.q_fp4,
                                    coord<cta2_fused_dense_score_q_fp8_tile>{
                                        batch_idx,
                                        head_idx,
                                        0,
                                        next_q_tile_idx * 2 + cta_rank
                                    },
                                    *prefetch_done
                                );
                            } else {
                                tma::load_async<
                                    dim::DEPTH,
                                    cache_policy::NORMAL
                                >(
                                    main.q.q,
                                    g.q,
                                    coord<cta2_fused_dense_q_tile>{
                                        batch_idx,
                                        next_q_tile_idx * 2 + cta_rank,
                                        head_idx,
                                        0
                                    },
                                    *prefetch_done
                                );
                            }
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                main.dout,
                                g.dout,
                                next_do_tile_coord,
                                *prefetch_done
                            );
                        }
                        if constexpr (UseLongSeqStatsCache) {
                            if (lane == 0) {
                                const int next_stats_stage =
                                    (loader_stats_iteration + 1) & 1;
                                auto &next_stats = next_stats_stage == 0
                                    ? storage.stats
                                    : storage.stats_next;
                                cta2_fused_dense_load_dpsum(
                                    g,
                                    next_stats,
                                    SplitScoreQReady
                                        ? *score_prefetch_done
                                        : *prefetch_done,
                                    batch_idx,
                                    next_q_tile_idx,
                                    head_idx
                                );
                            }
                        }
                        if constexpr (PublishNextQdoAtDqAliasRelease) {
                            if (has_next_q_tile) {
                                if constexpr (SplitScoreQReady) {
                                    if constexpr (
                                        UseCrossIterationScoreHead
                                    ) {
                                        if constexpr (
                                            !UseDoubleBufferedScoreQ
                                        ) {
                                            // Q has its own transaction
                                            // barrier, so expose it as soon
                                            // as the compact payload lands.
                                            cta2_fused_dense_role_wait<
                                                TimeoutAllRoleWaits
                                            >(
                                                *score_prefetch_done,
                                                local_phase
                                            );
                                            if (lane == 0) {
                                                asm volatile(
                                                    "fence.proxy.async.shared::cta;"
                                                    ::: "memory"
                                                );
                                                if constexpr (
                                                    CacheQdoReadyClusterAddress
                                                ) {
                                                    cta2_fused_dense_cluster_arrive_mapped(
                                                        qdo_ready_cluster_address
                                                    );
                                                } else {
                                                    ::kittens::tma::cluster::arrive(
                                                        qdo_ready,
                                                        0
                                                    );
                                                }
                                            }
                                        }
                                        // The safe score head may now issue.
                                        // Publish a second, independent gate
                                        // once all local dQ reducers have
                                        // released the overlapping tail.
                                        cta2_fused_dense_role_wait<
                                            TimeoutAllRoleWaits
                                        >(dq_reduce_done, phase);
                                        if (lane == 0) {
                                            asm volatile(
                                                "fence.proxy.async.shared::cta;"
                                                ::: "memory"
                                            );
                                            ::kittens::tma::cluster::arrive(
                                                score_alias_ready,
                                                0
                                            );
                                        }
                                    } else {
                                        cta2_fused_dense_role_wait<
                                            TimeoutAllRoleWaits
                                        >(dq_reduce_done, phase);
                                        if constexpr (
                                            !UseDoubleBufferedScoreQ ||
                                            WaitDoubleBufferedScoreAliasRelease
                                        ) {
                                            if (lane == 0) {
                                                asm volatile(
                                                    "fence.proxy.async.shared::cta;"
                                                    ::: "memory"
                                                );
                                                if constexpr (
                                                    CacheQdoReadyClusterAddress
                                                ) {
                                                    cta2_fused_dense_cluster_arrive_mapped(
                                                        qdo_ready_cluster_address
                                                    );
                                                } else {
                                                    ::kittens::tma::cluster::arrive(
                                                        qdo_ready,
                                                        0
                                                    );
                                                }
                                            }
                                        }
                                    }
                                } else {
                                    if constexpr (!UseLowpDp) {
                                        cta2_fused_dense_load_peer_do_elected(
                                            g,
                                            storage.qdo_phase.qdo,
                                            qdo_exchange_done,
                                            batch_idx,
                                            next_q_tile_idx,
                                            head_idx,
                                            cta_rank
                                        );
                                    }
                                    cta2_fused_dense_role_wait<
                                        TimeoutAllRoleWaits
                                    >(dq_reduce_done, phase);
                                    if constexpr (
                                        !JoinNextQdoWithDqAliasRelease
                                    ) {
                                        cta2_fused_dense_role_wait<
                                            TimeoutAllRoleWaits
                                        >(*prefetch_done, local_phase);
                                    }
                                    if (lane == 0) {
                                        asm volatile(
                                            "fence.proxy.async.shared::cta;"
                                            ::: "memory"
                                        );
                                        if constexpr (
                                            CacheQdoReadyClusterAddress
                                        ) {
                                            cta2_fused_dense_cluster_arrive_mapped(
                                                qdo_ready_cluster_address
                                            );
                                        } else {
                                            ::kittens::tma::cluster::arrive(
                                                qdo_ready,
                                                0
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dkdv_done,
                            phase
                        );
                        auto &next_q =
                            storage.phase.dq.operands.exchange.next_q;
                        if (lane == 0) {
                            tma::expect_bytes(
                                qdo_prefetch_done,
                                sizeof(next_q) +
                                    sizeof(cta2_fused_dense_do_tile)
                            );
                            coord<cta2_fused_dense_q_tile>
                                next_q_tile_coord = {
                                    batch_idx,
                                    (q_tile_idx + q_tile_step) * 2 + cta_rank,
                                    head_idx,
                                    0
                                };
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                next_q,
                                g.q,
                                next_q_tile_coord,
                                qdo_prefetch_done
                            );
                        }

                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dq_done,
                            phase
                        );
                        auto &next_dout =
                            *reinterpret_cast<cta2_fused_dense_do_tile *>(
                                &storage.ds
                            );
                        if (lane == 0) {
                            coord<cta2_fused_dense_do_tile>
                                next_do_tile_coord = {
                                    batch_idx,
                                    (q_tile_idx + q_tile_step) * 2 + cta_rank,
                                    head_idx,
                                    0
                                };
                            tma::load_async<dim::DEPTH, cache_policy::NORMAL>(
                                next_dout,
                                g.dout,
                                next_do_tile_coord,
                                qdo_prefetch_done
                            );
                        }
                    }
                }
                if constexpr (LoaderOwnedDkQ) {
                    current_qdo_done = &qdo_prefetch_done;
                    current_qdo_phase = local_phase;
                }
                if constexpr (PublishNextQdoAtDqAliasRelease) {
                    if (!has_next_q_tile) {
                        if constexpr (
                            JoinNextQdoWithDqAliasRelease &&
                            !UseDoubleBufferedScoreQ &&
                            !UseCrossIterationScoreHead
                        ) {
                            warp::arrive(dq_reduce_done);
                        }
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            dq_reduce_done,
                            phase
                        );
                    }
                } else {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dq_reduce_done,
                        phase
                    );
                }
                if constexpr (CarryAllRolePhases) {
                    loader_phase ^= 1;
                    loader_local_phase ^= 1;
                }
            }
        }
        return;
    }

    if (physical_warp == 14) {
        asm volatile("setmaxnreg.dec.sync.aligned.u32 104;" ::: "memory");
        uint32_t dq_operands_ready_cluster_address = 0;
        uint32_t dkdv_operands_ready_cluster_address = 0;
        if constexpr (CacheRoleClusterAddresses) {
            if (lane == 0) {
                dq_operands_ready_cluster_address =
                    cta2_fused_dense_map_cluster_semaphore(
                        dq_operands_ready,
                        0
                    );
                if constexpr (UseAsyncDkReady) {
                    dkdv_operands_ready_cluster_address =
                        cta2_fused_dense_map_cluster_semaphore(
                            dkdv_operands_ready,
                            0
                        );
                }
            }
        }
        #pragma unroll 1
        for (
            int owner_pass = 0;
            owner_pass < (SingleOwnerCluster ? 1 : 2);
            ++owner_pass
        ) {
            const int owner_idx = SingleOwnerCluster
                ? owner_pair_idx
                : (owner_pass == 0
                    ? owner_pair_idx
                    : owner_count - 1 - owner_pair_idx);
            const int owner_phase = OwnerQWorkSplitId >= 0
                ? (owner_pass == 0
                    ? 0
                    : ((owner_count - owner_pair_idx) & 1))
                : (SingleOwnerCluster || IntegrateCausalFrontier
                    ? 0
                    : (owner_pass & 1));
            const int first_dense_q_tile =
                2 * owner_idx + (IntegrateCausalFrontier ? 0 : 1) +
                (OwnerQWorkSplitId < 0 ? 0 : OwnerQWorkSplitId);
            int iteration = 0;
            int exchange_phase = owner_phase;
            for (
                int q_tile_idx = first_dense_q_tile;
                q_tile_idx < q_tile_count;
                q_tile_idx += q_tile_step, ++iteration
            ) {
                const int phase = CarryAllRolePhases
                    ? exchange_phase
                    : ((iteration + owner_phase) & 1);
                if constexpr (UseAsyncDkReady) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dkdv_local_ready,
                        phase
                    );
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        q_source_loaded,
                        phase
                    );
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                    if constexpr (UsePureMxFp4DqDk) {
                        // Each exchange warp publishes its own rank-local N96
                        // Q half.  Two K64 pages occupy eight TMEM columns;
                        // dK's N64 tail addresses the third N32 group in each.
                        tensor_after_thread_sync();
                        const int q_scale_page_base =
                            (((batch_idx * static_cast<int>(gridDim.y) +
                               head_idx) * 2 + cta_rank) *
                                 (g.seq_len / 64)) +
                            2 * q_tile_idx;
                        cta2_fused_dense_publish_nvfp4_scale_pages_direct_tmem<
                            2
                        >(
                            qk_unit_scale_tmem.addr,
                            g.q_dk_nvfp4_scale,
                            q_scale_page_base
                        );
                        tensor_before_thread_sync();
                    }
#endif
                    if (lane == 0) {
                        if constexpr (CacheRoleClusterAddresses) {
                            cta2_fused_dense_cluster_arrive_mapped(
                                dkdv_operands_ready_cluster_address
                            );
                        } else {
                            ::kittens::tma::cluster::arrive(
                                dkdv_operands_ready,
                                0
                            );
                        }
                    }
#if TK_FA4_BWD_PURE_NVFP4_QK && \
    TK_FA4_BWD_PURE_NVFP4_QK_DIRECT_TMEM_SCALE
                    if constexpr (UsePureMxFp4DqDk) {
                        // dK is now released.  Each rank publishes its four
                        // consecutive K64 pages for the local N96 K half while
                        // dK/dV and the dQ operand exchange proceed.
                        tensor_after_thread_sync();
                        const int k_scale_page_base =
                            (((batch_idx * static_cast<int>(gridDim.y) +
                               head_idx) * 2 + cta_rank) *
                                 (g.seq_len / 64)) +
                            4 * owner_idx;
                        cta2_fused_dense_publish_nvfp4_scale_pages_direct_tmem<
                            4
                        >(
                            score_dp_tmem.addr + 16,
                            g.k_dq_nvfp4_scale,
                            k_scale_page_base
                        );
                        tensor_before_thread_sync();
                    }
#endif
                }
                if constexpr (
                    RelayDoDvCompletionViaExchangeWarp && !UseFp8Pv
                ) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        do_source_loaded,
                        phase
                    );
                    if (lane == 0) {
                        ::kittens::tma::cluster::arrive(
                            owner_output_loaded,
                            0
                        );
                    }
                }
                if constexpr (StageDqPeerBeforeDv) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dq_peer_ready,
                        phase
                    );
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dkdv_done,
                        phase
                    );
                } else {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dq_local_ready,
                        phase
                    );
                }
                if (lane == 0) {
                    if constexpr (
                        !DirectAsyncPeerDs && !ProducerBulkPeerDs
                    ) {
                        auto &main = storage.phase.main;
                        auto &dq_operands = storage.phase.dq.operands;
                        auto &dq_a = [&]() -> cta2_fused_dense_dq_a_tile & {
                            if constexpr (StageDqAfterDv) {
                                return *reinterpret_cast<
                                    cta2_fused_dense_dq_a_tile *
                                >(&main.p.p);
                            } else {
                                return dq_operands.a;
                            }
                        }();
                        const int peer_rank = cta_rank ^ 1;
                        void *destination = reinterpret_cast<void *>(
                            &dq_a.data[cta_rank * 128 * 64]
                        );
                        ::kittens::tma::cluster::expect_bytes(
                            dq_exchange_done,
                            sizeof(storage.qdo_phase.ds),
                            peer_rank
                        );
                        ::kittens::tma::cluster::store_async(
                            destination,
                            reinterpret_cast<void *>(
                                &storage.qdo_phase.ds
                            ),
                            sizeof(storage.qdo_phase.ds),
                            peer_rank,
                            dq_exchange_done
                        );
                    }
                }
                ::kittens::tma::cluster::wait(
                    dq_exchange_done,
                    phase
                );
                if constexpr (StageDqPeerBeforeDv) {
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dq_local_ready,
                        phase
                    );
                }
#if TK_FA4_BWD_PURE_MXFP4_DIRECT_DQ_SCALE_TMEM_ACTIVE
                if constexpr (UsePureMxFp4DqDk) {
                    // dK uses p_tmem+48 as its scale page and p_tmem+64 as
                    // its compact native-dS operand.  Wait only until those
                    // instructions have issued, then reuse the same aligned
                    // pages for the two exact dQ K128 scale records.
                    cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                        dk_scale_slots_released,
                        phase
                    );
                    tensor_after_thread_sync();
                    auto &dq_scale0 =
                        cta2_fused_dense_mxfp4_dsdq_scale_stage<0>(storage);
                    auto &dq_scale1 =
                        cta2_fused_dense_mxfp4_dsdq_scale_stage<1>(storage);
                    #pragma unroll
                    for (int reader_warp = 0; reader_warp < 4; ++reader_warp) {
                        const int scale_row = reader_warp * 32 + lane;
                        const uint32_t packed_scale0 =
                            cta2_role_split_load_mxfp4_scale_word(
                                dq_scale0,
                                scale_row
                            );
                        const uint32_t packed_scale1 =
                            cta2_role_split_load_mxfp4_scale_word(
                                dq_scale1,
                                scale_row
                            );
                        cta2_role_split_store_mxfp4_scale_tmem_x1(
                            ds_qk_scale0_tmem.addr,
                            reader_warp,
                            packed_scale0
                        );
                        cta2_role_split_store_mxfp4_scale_tmem_x1(
                            ds_qk_scale1_tmem.addr,
                            reader_warp,
                            packed_scale1
                        );
                    }
                    cta2_role_split_tmem_store_wait();
                    tensor_before_thread_sync();
                }
#endif
                if (lane == 0) {
                    if constexpr (CacheRoleClusterAddresses) {
                        cta2_fused_dense_cluster_arrive_mapped(
                            dq_operands_ready_cluster_address
                        );
                    } else {
                        ::kittens::tma::cluster::arrive(
                            dq_operands_ready,
                            0
                        );
                    }
                }
                if constexpr (CarryAllRolePhases) {
                    exchange_phase ^= 1;
                }
            }
        }
        return;
    }

    if (physical_warp == 15) {
        if constexpr (UseX32TmemComputeLayout) {
            asm volatile("setmaxnreg.dec.sync.aligned.u32 104;" ::: "memory");
            bool have_previous_stats = false;
            int previous_stats_phase = 0;
            #pragma unroll 1
            for (int owner_pass = 0; owner_pass < 2; ++owner_pass) {
                const int owner_idx = owner_pass == 0
                    ? owner_pair_idx
                    : owner_count - 1 - owner_pair_idx;
                const int first_dense_q_tile = 2 * owner_idx;
                #pragma unroll 1
                for (
                    int q_tile_idx = first_dense_q_tile;
                    q_tile_idx < q_tile_count;
                    ++q_tile_idx
                ) {
                    const int phase =
                        (q_tile_idx - first_dense_q_tile) & 1;
                    const size_t offset =
                        (static_cast<size_t>(batch_idx) *
                                g.lse_log2.depth() +
                            head_idx) *
                            g.seq_len +
                        q_tile_idx * 128;
                    float prefetched_lse[4];
                    float prefetched_dpsum[4];
                    if constexpr (
                        UseWinningFp8DpDv &&
                        TK_FA4_BWD_FP8DPDV_PREFETCH_STATS_ACROSS_REUSE
                    ) {
                        #pragma unroll
                        for (int item = 0; item < 4; ++item) {
                            const int element = lane + item * 32;
                            prefetched_lse[item] =
                                g.lse_log2.raw_ptr[offset + element];
                            prefetched_dpsum[item] =
                                g.dpsum.raw_ptr[offset + element];
                        }
                    }
                    if (have_previous_stats) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            storage.stats_consumed,
                            previous_stats_phase
                        );
                    }
                    #pragma unroll
                    for (int element = lane; element < 128; element += 32) {
                        float lse_value;
                        float dpsum_value;
                        if constexpr (
                            UseWinningFp8DpDv &&
                            TK_FA4_BWD_FP8DPDV_PREFETCH_STATS_ACROSS_REUSE
                        ) {
                            const int item = element >> 5;
                            lse_value = prefetched_lse[item];
                            dpsum_value = prefetched_dpsum[item];
                        } else {
                            lse_value =
                                g.lse_log2.raw_ptr[offset + element];
                            dpsum_value =
                                g.dpsum.raw_ptr[offset + element];
                        }
                        storage.stats.lse_log2[element] = lse_value;
                        if constexpr (UseHalfDpsum) {
                            auto &dpsum_half = *reinterpret_cast<
                                sv_hf<128> *
                            >(&storage.stats.dpsum);
                            dpsum_half[element] = __float2half_rn(dpsum_value);
                        } else {
                            storage.stats.dpsum[element] = dpsum_value;
                        }
                    }
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    __syncwarp();
                    asm volatile("bar.sync 5, 320;" ::: "memory");
                    have_previous_stats = true;
                    previous_stats_phase = phase;
                }
            }
            return;
        } else if constexpr (UseWarpStatsCache) {
            asm volatile("setmaxnreg.dec.sync.aligned.u32 104;" ::: "memory");
            const int first_dense_q_tile =
                2 * owner_pair_idx + (IntegrateCausalFrontier ? 0 : 1);
            int iteration = 0;
            #pragma unroll 1
            for (
                int q_tile_idx = first_dense_q_tile;
                q_tile_idx < q_tile_count;
                ++q_tile_idx, ++iteration
            ) {
                const int phase = iteration & 1;
                if (iteration != 0) {
                    if constexpr (!PipelineLsePrefetch) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            storage.stats_consumed,
                            phase ^ 1
                        );
                    }
                }
                const size_t offset =
                    (static_cast<size_t>(batch_idx) *
                            g.lse_log2.depth() +
                        head_idx) *
                            g.seq_len +
                    q_tile_idx * 128;
                if constexpr (PipelineLsePrefetch) {
                    auto &lse_stage = phase == 0
                        ? storage.stats.lse_log2
                        : storage.lse_log2_next;
                    #pragma unroll
                    for (
                        int element = lane;
                        element < 128;
                        element += 32
                    ) {
                        const float lse_value =
                            g.lse_log2.raw_ptr[offset + element];
                        if constexpr (UseMxFp4Dv) {
                            lse_stage[element] = -lse_value;
                        } else {
                            lse_stage[element] = lse_value;
                        }
                    }
                    if (iteration != 0) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            storage.stats_consumed,
                            phase ^ 1
                        );
                    }
                    if constexpr (!DeferFp4DpsumAfterScoreFanout) {
                        #pragma unroll
                        for (
                            int element = lane;
                            element < 128;
                            element += 32
                        ) {
                            const float dpsum_value =
                                g.dpsum.raw_ptr[offset + element];
                            if constexpr (UseHalfDpsum) {
                                auto &dpsum_half = *reinterpret_cast<
                                    sv_hf<128> *
                                >(&storage.stats.dpsum);
                                dpsum_half[element] =
                                    __float2half_rn(dpsum_value);
                            } else {
                                storage.stats.dpsum[element] = dpsum_value;
                            }
                        }
                    }
                } else {
                    #pragma unroll
                    for (
                        int element = lane;
                        element < 128;
                        element += 32
                    ) {
                        const float lse_value =
                            g.lse_log2.raw_ptr[offset + element];
                        if constexpr (UseMxFp4Dv) {
                            storage.stats.lse_log2[element] = -lse_value;
                        } else {
                            storage.stats.lse_log2[element] = lse_value;
                        }
                        if constexpr (!DeferFp4DpsumAfterScoreFanout) {
                            const float dpsum_value =
                                g.dpsum.raw_ptr[offset + element];
                            if constexpr (UseHalfDpsum) {
                                auto &dpsum_half = *reinterpret_cast<
                                    sv_hf<128> *
                                >(&storage.stats.dpsum);
                                dpsum_half[element] =
                                    __float2half_rn(dpsum_value);
                            } else {
                                storage.stats.dpsum[element] = dpsum_value;
                            }
                        }
                    }
                }
                asm volatile(
                    "fence.proxy.async.shared::cta;"
                    ::: "memory"
                );
                __syncwarp();
                if constexpr (UseFp4ComputeLeaderScoreFanout) {
                    if constexpr (
                        UseLowpDp &&
                        !(UsePureMxFp4DqDk &&
                          TK_FA4_BWD_PURE_MXFP4_LEADER_SCORE_FANOUT)
                    ) {
                        asm volatile("bar.arrive 12, 288;" ::: "memory");
                    } else {
                        asm volatile("bar.arrive 12, 96;" ::: "memory");
                    }
                }
                if constexpr (!DeferFp4DpsumAfterScoreFanout) {
                    warp::arrive(storage.stats_ready);
                }
                if constexpr (UseStatsWarpScoreFanout) {
                    if constexpr (UseFp4ComputeLeaderScoreFanout) {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_done,
                            phase
                        );
                    } else {
                        cta2_fused_dense_role_wait<TimeoutAllRoleWaits>(
                            score_done,
                            phase
                        );
                        asm volatile("bar.sync 5, 288;" ::: "memory");
                    }
                }
                if constexpr (DeferFp4DpsumAfterScoreFanout) {
                    #pragma unroll
                    for (int element = lane; element < 128; element += 32) {
                        const float dpsum_value =
                            g.dpsum.raw_ptr[offset + element];
                        if constexpr (UseHalfDpsum) {
                            auto &dpsum_half = *reinterpret_cast<
                                sv_hf<128> *
                            >(&storage.stats.dpsum);
                            dpsum_half[element] = __float2half_rn(dpsum_value);
                        } else {
                            storage.stats.dpsum[element] = dpsum_value;
                        }
                    }
                    asm volatile(
                        "fence.proxy.async.shared::cta;"
                        ::: "memory"
                    );
                    __syncwarp();
                    warp::arrive(storage.stats_ready);
                }
            }
            return;
        }
    }

    asm volatile("setmaxnreg.dec.sync.aligned.u32 24;" ::: "memory");
}

}  // namespace detail

inline void launch_backward_cta2_fused_dense_with_frontier(
    at::Tensor &q,
    at::Tensor &k,
    at::Tensor &v,
    at::Tensor &dout,
    at::Tensor &lse_log2,
    at::Tensor &dpsum,
    at::Tensor &dq,
    at::Tensor &dk,
    at::Tensor &dv,
    float scale,
    cudaStream_t stream,
    cudaStream_t frontier_stream,
    cudaEvent_t dense_ready,
    cudaEvent_t frontier_done,
    at::Tensor &frontier_dk,
    at::Tensor &frontier_dv,
    bool use_tmem_ds = true,
    bool overlap_ds_exchange = true,
    bool overlap_q_with_dp = true,
    bool use_tmem_p = false,
    bool overlap_do_with_dp = false,
    bool use_dp_operand_ready_mbar = false,
    bool use_dq_operand_ready_mbar = false,
    bool overlap_dv_with_ds = false,
    bool pipeline_next_score = false,
    bool preload_dq_a = false,
    bool use_score_operand_ready_mbar = false,
    bool use_ds_warp_multicast_mbar = false,
    bool use_role_split = false,
    bool retain_ds_exchange = false,
    bool retain_ds_local = false,
    bool use_normal_do_dv = false,
    bool use_tma_score_k = false,
    bool direct_next_qdo_during_dq_drain = false,
    bool single_owner_cluster = false,
    bool use_fast_exp2 = false,
    bool use_warp_stats_cache = false,
    bool pipeline_lse_prefetch = false,
    bool use_direct_stats_loads = false,
    bool split_dv_dk_ready = false,
    bool stage_dq_after_dv = false,
    bool stage_dq_peer_before_dv = false,
    bool use_wide_dk_n192 = false,
    bool direct_ds_half_store = false,
    bool asymmetric_dv_publish = false
) {
    using DenseG = detail::cta2_fused_dense_globals;
    using FrontierC = dense_tmem_frontier_config<
        kForwardTileM,
        kForwardTileN,
        kB300QKDim,
        kB300VDim
    >;
    using FrontierG = dense_tmem_frontier_globals<FrontierC>;

    TORCH_CHECK(q.size(0) == 1, "2-CTA fused dense route requires batch size 1");
    TORCH_CHECK(
        q.size(1) == 4096 || q.size(1) == 8192 || q.size(1) == 16384,
        "2-CTA fused dense route requires S4096, S8192, or S16384"
    );
    TORCH_CHECK(
        q.size(1) % 256 == 0,
        "2-CTA fused dense route requires sequence divisible by 256"
    );
    TORCH_CHECK(
        frontier_dk.sizes() == dk.sizes() && frontier_dv.sizes() == dv.sizes(),
        "2-CTA fused dense frontier scratch shape mismatch"
    );

    DenseG dense_g{
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_k_gl>(k),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_q_gl>(q),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_v_gl>(v),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_do_gl>(dout),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_output_gl>(dk),
