        use_dq_operand_ready_mbar && overlap_dv_with_ds
    ) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true,
                true,
                true,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (
        use_tmem_ds && overlap_ds_exchange && overlap_q_with_dp &&
        use_tmem_p && overlap_do_with_dp && use_dp_operand_ready_mbar &&
        use_dq_operand_ready_mbar
    ) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true,
                true,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (
        use_tmem_ds && overlap_ds_exchange && overlap_q_with_dp &&
        use_tmem_p && overlap_do_with_dp && use_dp_operand_ready_mbar
    ) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (
        use_tmem_ds && overlap_ds_exchange && overlap_q_with_dp &&
        use_tmem_p && overlap_do_with_dp
    ) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (
        use_tmem_ds && overlap_ds_exchange && overlap_q_with_dp && use_tmem_p
    ) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (use_tmem_ds && overlap_ds_exchange && overlap_q_with_dp) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                true
            >,
            dense_g
        ));
    } else if (use_tmem_ds && overlap_ds_exchange) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                true,
                false
            >,
            dense_g
        ));
    } else if (use_tmem_ds) {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                true,
                false,
                false
            >,
            dense_g
        ));
    } else {
        CUDACHECK(cudaLaunchKernelEx(
            dense_config,
            detail::main_kernel_causal_cta2_fused_dense<
                false,
                false,
                false,
                false
            >,
            dense_g
        ));
    }

    const int frontier_grid_x = static_cast<int>(q.size(1) / 128);
    kittens::LaunchConfig<true, false> frontier_config(
        dim3(
            frontier_grid_x,
            static_cast<int>(q.size(2)),
            static_cast<int>(q.size(0))
        ),
        dim3(FrontierC::FusedDqLoadOverlapBlockThreads, 1, 1),
        0,
        frontier_stream,
        dim3(FrontierC::ClusterSize, 1, 1)
    );
    CUDACHECK(cudaLaunchKernelEx(
        frontier_config,
        detail::main_kernel_causal_dense_tmem_dkdv<
            FrontierC,
            1,
            true,
            true,
            true,
            false,
            true,
            false,
            true,
            true
        >,
        frontier_g,
        frontier_g.dk,
        frontier_g.dv
    ));
    CUDACHECK(cudaEventRecord(frontier_done, frontier_stream));
    CUDACHECK(cudaStreamWaitEvent(stream, frontier_done));

    constexpr int kThreads = 256;
    TORCH_CHECK(
        dk.numel() % 4 == 0 && dv.numel() % 4 == 0,
        "2-CTA fused dense frontier add requires float4-aligned shapes"
    );
    const int64_t dk_vecs = dk.numel() / 4;
    const int64_t dv_vecs = dv.numel() / 4;
    const int64_t max_vecs = dk_vecs > dv_vecs ? dk_vecs : dv_vecs;
    const int blocks = static_cast<int>((max_vecs + kThreads - 1) / kThreads);
    detail::dense_tmem_frontier_add_kernel<<<blocks, kThreads, 0, stream>>>(
        reinterpret_cast<float4 *>(dk.data_ptr()),
        reinterpret_cast<const float4 *>(frontier_dk.data_ptr()),
        dk_vecs,
        reinterpret_cast<float4 *>(dv.data_ptr()),
        reinterpret_cast<const float4 *>(frontier_dv.data_ptr()),
        dv_vecs
    );
    CHECK_CUDA_ERROR(cudaGetLastError());
}

template <
    bool CoalescedBf16Store = false,
    bool DirectAsyncPeerDs = false,
    bool ProducerBulkPeerDs = false,
    bool ProducerBulkPeerDsCtaFenceOnly = false,
    bool DqReadHandoffBeforeCompletion = false,
    bool AggregateScoreConsumed = false,
    bool DirectTmaDkQ = false,
    bool TimeoutDqWait = false,
    bool UseWideDkN192 = false,
    bool TimeoutAllRoleWaits = false,
    bool UseNamedDoSourceBarrier = false,
    bool UseComputeScoreFanout = false,
    bool UseRuntimeAccumulationPredicate = false,
    bool UseReducerDqFanout = false,
    bool UseReducerDqLeaderArrive = false,
    bool MergeScoreDpReady = false,
    bool WideCoalescedBf16Store = false,
    bool BulkPeerDsFromFullTile = false,
    bool CoalescedPeerDsBulk = false,
    bool WideDqKGlobalToShared = false,
    bool IntegrateCausalFrontier = false,
    int ExactQTileCount = 0,
    bool FenceDsBeforeDkdvReady = false,
    bool UseNamedDkdvLocalFanIn = false,
    bool LeaderOnlyQdoPublishFence = false,
    bool CacheQdoReadyClusterAddress = false,
    bool GroupQdoTmaLoads = false,
    bool ElectedWideDkQTmaLoad = false,
    bool ElectedPeerDoTmaLoad = false,
    bool CacheRoleClusterAddresses = false,
    bool CacheTensorCommitAddresses = false,
    bool EnsureReducerOutputDrain = false,
    bool ElectedScoreKTmaLoad = false,
    bool UseExactClusterCoordinates = false,
    bool EnforceDpTmemConsumerRelease = false,
    bool SplitDpTmemConsumerRelease = false,
    bool UseIterationCausalMask = false,
    bool UseFusedTmemPAndDs = false,
    bool OverlapFusedDqAPublication = false,
    bool PrefetchNextQdoAfterDkdv = false,
    bool PrefetchNextOwnerQdo = false,
    bool UseFusedTmemRuntimeAccumulationPredicate = false,
    bool UseBitwisePExpansion = false,
    bool UseFusedExp2Pack = false,
    bool PeelCausalPrefix = false,
    bool BranchlessDoSourceLoad = false,
    bool BranchlessDoSourceBaseSelect = false,
    bool PublishVOncePerOwner = false,
    bool BulkDoDvStage = false,
    bool LoaderOwnedDkQ = false,
    bool FuseScoreScaleLse = false,
    bool RetainPackedP = false,
    bool SplitDirectDpsumAcrossDpDoneWait = false,
    bool FusedExp2Fragment4First = false,
    bool CarryDirectStatsOffset = false,
    bool CarryAllRolePhases = false,
    bool UseExactDefaultScaleLog2e = false,
    bool ReverseDkTailTmemLoadIssue = false,
    bool PrearmNextQdoBeforeDkDone = false,
    bool UseX32TmemComputeLayout = false,
    bool UseLongSeqStatsCache = false,
    bool UseCompactScoreMma = false,
    bool UseCompactDpMma = false,
    bool UsePackedBf16DsProduct = false,
    bool SplitDqTmemAndSharedHandoff = false,
    bool DistributedDqSharedReadWait = false,
    bool BalancedSingleOwnerSchedule = false,
    bool UseSingleOwnerWarpStatsCache = false,
    bool CacheDqStageLanePointers = false,
    bool UseSlicedFp32PForDs = false,
    bool UseTmaVWithScoreK = false,
    bool UseStatsWarpScoreFanout = false,
    bool UseBatchedDqTmemLoads = false,
    bool UseDynamicDpReleaseBarrierId = false,
    bool PreissueFirstDpHalfBeforeQdoWait = false,
    bool OverlapSecondDpLoadWithReleaseBarrier = false,
    bool RelayDoDvCompletionViaExchangeWarp = false,
    bool OverlapDqPeerCopyWithDoDvCompletion = false,
    bool OverlapLocalDqStoreWithPeerCopy = false,
    bool UseNonblockingDqPublicationFollowers = false,
    bool SplitDqAliasLifetimeWithCuteTmemMap = false,
    bool DeferFirstDsTmemStoreWait = false,
    bool OverlapFinalDsTmemStoreWithPeerSharedStores = false,
    bool DelayScoreAliasReleaseUntilFirstDqTailLoad = false,
    bool InterleaveSteadyScoreExpPairs = false,
    bool ShiftOverlappingScoreHalfBeforeDpRelease = false,
    bool BuildCompactDpDescriptorsAfterWait = false,
    int LateTensorCommitAddressSharedMask = 0,
    bool CacheCompactDpDescriptorsInShared = false,
    bool OverlapFirstDpsumQuarterWithSecondPStore = false,
    bool HoistReducerDpReadyBeforeScoreWait = false,
    bool PipelineFirstDpQuarterLoads = false,
    bool PublishNextQdoAtDqAliasRelease = false,
    bool JoinNextQdoWithDqAliasRelease = false,
    bool PrecomputePostScoreFanoutAddresses = false,
    bool PrecomputeScoreIterationDeltaUnderFanout = false,
    bool UseNativeX32Lowp = false,
    int LowpMode = detail::kCta2DenseLowpNone,
    bool ReuseDqDsForDk = false,
    bool UseAdaptiveQkScales = false,
    bool SignalDqTileReady = false,
    bool UseRank128Score = false
>
inline void launch_backward_cta2_fused_dense_bf16_with_frontier(
    at::Tensor &q,
    at::Tensor &k,
    at::Tensor &v,
    at::Tensor &dout,
    at::Tensor &lse_log2,
    at::Tensor &dpsum,
    at::Tensor &dq,
    at::Tensor &dk,
    at::Tensor &dv,
    float scale,
    cudaStream_t stream,
    cudaStream_t frontier_stream,
    cudaEvent_t dense_ready,
    cudaEvent_t frontier_done,
    at::Tensor &frontier_dk,
    at::Tensor &frontier_dv,
    at::Tensor *q_lowp = nullptr,
    at::Tensor *k_lowp = nullptr,
    float dq_output_scale = 1.0f,
    float dk_output_scale = 1.0f,
    float ds_quant_scale =
        detail::kCta2DenseFp8DefaultDsQuantScale,
    at::Tensor *score_q_lowp = nullptr,
    at::Tensor *score_k_lowp = nullptr,
    at::Tensor *dout_fp8 = nullptr,
    at::Tensor *dout_dp_fp8 = nullptr,
    at::Tensor *v_fp8 = nullptr,
    at::Tensor *dout_mxfp4 = nullptr,
    at::Tensor *dout_mxfp4_scale = nullptr,
    at::Tensor *dout_dp_mxfp4 = nullptr,
    at::Tensor *v_dp_mxfp4 = nullptr,
    at::Tensor *dout_dp_mxfp4_scale = nullptr,
    at::Tensor *v_dp_mxfp4_scale = nullptr,
    at::Tensor *q_dk_mxfp4 = nullptr,
    at::Tensor *k_dq_mxfp4 = nullptr,
    at::Tensor *q_dk_nvfp4_scale = nullptr,
    at::Tensor *k_dq_nvfp4_scale = nullptr,
    at::Tensor *adaptive_qk_scales = nullptr,
    at::Tensor *dq_bf16_reduce = nullptr,
    at::Tensor *projection_qkv_output = nullptr,
    bool widen_bf16_dq_output = true,
    uint32_t *dq_tile_arrivals = nullptr,
    int dq_reduction_lanes = 1,
    at::Tensor *dq_nvfp4 = nullptr,
    at::Tensor *dq_nvfp4_scales = nullptr,
    at::Tensor *dq_nvfp4_global_scale = nullptr,
    at::Tensor *dq_nvfp4_ready = nullptr
) {
    static_assert(
        !UseSingleOwnerWarpStatsCache ||
            (BalancedSingleOwnerSchedule && !UseLongSeqStatsCache)
    );
    using DenseBaseG = detail::cta2_fused_dense_globals_t<
        bf16,
        DirectTmaDkQ,
        detail::kCta2DenseLowpNone
    >;
    using DenseG = detail::cta2_fused_dense_globals_t<
        bf16,
        DirectTmaDkQ,
        LowpMode
    >;
    using FrontierC = dense_tmem_frontier_config<
        kForwardTileM,
        kForwardTileN,
        kB300QKDim,
        kB300VDim
    >;
    using FrontierG = dense_tmem_frontier_globals<FrontierC>;
    constexpr bool UseBf16DqReduction =
        LowpMode == detail::kCta2DenseLowpFp4Fp8DpPvReuseP &&
        TK_FA4_BWD_FP8DPDV_BF16_DQ_REDUCTION;
    static_assert(
        !SignalDqTileReady ||
            (UseBf16DqReduction && UseAdaptiveQkScales &&
             BalancedSingleOwnerSchedule && IntegrateCausalFrontier),
        "dQ tile signaling is valid only for the balanced adaptive BF16 "
        "reduction route"
    );
    TORCH_CHECK(
        SignalDqTileReady == (dq_tile_arrivals != nullptr),
        "dQ tile arrival storage must match the signaling specialization"
    );
    TORCH_CHECK(
        dq_reduction_lanes == 1 ||
            (SignalDqTileReady && dq_reduction_lanes == 2),
        "hierarchical dQ projection supports one or two reduction lanes"
    );
    const bool pack_dq_nvfp4 = dq_nvfp4 != nullptr;
    TORCH_CHECK(
        pack_dq_nvfp4 == (dq_nvfp4_scales != nullptr) &&
            pack_dq_nvfp4 == (dq_nvfp4_global_scale != nullptr) &&
            pack_dq_nvfp4 == (dq_nvfp4_ready != nullptr),
        "producer-native dQ NVFP4 payload, scales, global scale, and "
        "readiness storage must be supplied together"
    );
    TORCH_CHECK(
        !pack_dq_nvfp4 ||
            (SignalDqTileReady && UseBf16DqReduction &&
             dq_reduction_lanes == 1),
        "producer-native dQ NVFP4 packing requires single-lane signaled "
        "BF16 reduction"
    );
    if constexpr (UseBf16DqReduction) {
        if (projection_qkv_output != nullptr) {
            TORCH_CHECK(
                dq_reduction_lanes == 1 &&
                dq_bf16_reduce != nullptr &&
                    dq_bf16_reduce->data_ptr() ==
                        projection_qkv_output->data_ptr() &&
                    projection_qkv_output->scalar_type() ==
                        at::ScalarType::BFloat16 &&
                    projection_qkv_output->dim() == 4 &&
                    projection_qkv_output->size(0) == q.size(0) &&
                    projection_qkv_output->size(1) == q.size(1) &&
                    projection_qkv_output->size(2) == q.size(2) &&
                    projection_qkv_output->size(3) ==
                        kB300QKDim * 2 + kB300VDim &&
                    projection_qkv_output->is_cuda() &&
                    projection_qkv_output->is_contiguous(),
                "projection QKV output must be contiguous BF16 "
                "[B, S, H, 512]"
            );
        } else {
            TORCH_CHECK(
                dq_bf16_reduce != nullptr &&
                    dq_bf16_reduce->scalar_type() ==
                        at::ScalarType::BFloat16 &&
                    dq_bf16_reduce->dim() == 4 &&
                    dq_bf16_reduce->size(0) ==
                        q.size(0) * dq_reduction_lanes &&
                    dq_bf16_reduce->size(1) == q.size(1) &&
                    dq_bf16_reduce->size(2) == q.size(2) &&
                    dq_bf16_reduce->size(3) == q.size(3) &&
                    dq_bf16_reduce->is_cuda() &&
                    dq_bf16_reduce->is_contiguous(),
                "BF16 dQ reduction requires contiguous BF16 scratch "
                "with [reduction_lanes * B, S, H, D] layout"
            );
        }
    } else {
        TORCH_CHECK(
            projection_qkv_output == nullptr,
            "projection QKV output requires the BF16 dQ reduction route"
        );
    }

    const bool supported_shape =
        q.size(0) == 1 &&
        ((q.size(1) == 2048 && q.size(2) == 8) ||
         (q.size(1) == 4096 &&
          (q.size(2) == 4 || q.size(2) == 8 || q.size(2) == 24 ||
           q.size(2) == 64)) ||
         (q.size(1) == 8192 &&
          (q.size(2) == 2 || q.size(2) == 4 || q.size(2) == 8 ||
           q.size(2) == 16 || q.size(2) == 24 || q.size(2) == 64)) ||
         (q.size(1) == 16384 &&
          (q.size(2) == 4 || q.size(2) == 8 || q.size(2) == 16 ||
           q.size(2) == 24 || q.size(2) == 32 || q.size(2) == 64 ||
           q.size(2) == 128)) ||
         (q.size(1) == 32768 &&
          (q.size(2) == 16 || q.size(2) == 32 || q.size(2) == 64 ||
           q.size(2) == 128)) ||
         (q.size(1) == 65536 &&
          (q.size(2) == 16 || q.size(2) == 32 || q.size(2) == 64 ||
           q.size(2) == 128)));
    TORCH_CHECK(
        supported_shape,
        "BF16 dK/dV 2-CTA route does not support this sequence/head shape; "
        "S32768 H16/H32/H64/H128, or S65536 H16/H32/H64/H128"
    );
    TORCH_CHECK(
        dk.scalar_type() == at::ScalarType::BFloat16 &&
            dv.scalar_type() == at::ScalarType::BFloat16,
        "BF16 dK/dV 2-CTA route requires BF16 dK and dV outputs"
    );
    if (projection_qkv_output != nullptr) {
        TORCH_CHECK(
            frontier_dk.sizes() == k.sizes() &&
                frontier_dv.sizes() == v.sizes(),
            "projection QKV frontier scratch shape mismatch"
        );
    } else {
        TORCH_CHECK(
            frontier_dk.sizes() == dk.sizes() &&
                frontier_dv.sizes() == dv.sizes(),
            "BF16 dK/dV 2-CTA frontier scratch shape mismatch"
        );
    }

    auto make_projection_output_gl = [&, projection_qkv_output](
        int feature_offset
    ) -> detail::cta2_fused_dense_output_gl_t<bf16> {
        TORCH_INTERNAL_ASSERT(projection_qkv_output != nullptr);
        const uint64_t base = reinterpret_cast<uint64_t>(
            projection_qkv_output->data_ptr()
        );
        return ::kittens::make_gl<
            detail::cta2_fused_dense_output_gl_t<bf16>
        >(
            base + static_cast<uint64_t>(feature_offset) * sizeof(bf16),
            static_cast<int>(q.size(0)),
            static_cast<int>(q.size(1)),
            static_cast<int>(q.size(2)),
            kB300QKDim * 2 + kB300VDim
        );
    };
    const auto dk_output_gl = projection_qkv_output == nullptr
        ? kittens::py::tensor_to_gl<
            detail::cta2_fused_dense_output_gl_t<bf16>
        >(dk)
        : make_projection_output_gl(kB300QKDim);
    const auto dv_output_gl = projection_qkv_output == nullptr
        ? kittens::py::tensor_to_gl<
            detail::cta2_fused_dense_output_gl_t<bf16>
        >(dv)
        : make_projection_output_gl(kB300QKDim * 2);

    DenseBaseG dense_base_g{
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_k_gl>(k),
        kittens::py::tensor_to_gl<typename DenseBaseG::q_gl>(q),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_v_gl>(v),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_do_gl>(dout),
        dk_output_gl,
        dv_output_gl,
        kittens::py::tensor_to_gl<
            detail::cta2_fused_dense_dq_gl,
            false
        >(
            dq,
            q.size(0),
            q.size(1),
            q.size(2),
            q.size(3)
        ),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_stats_gl>(
            lse_log2,
            q.size(0),
            q.size(2),
            1,
            q.size(1)
        ),
        kittens::py::tensor_to_gl<detail::cta2_fused_dense_stats_gl>(
            dpsum,
            q.size(0),
            q.size(2),
            1,
            q.size(1)
        ),
        scale,
        scale * kLog2E,
        static_cast<int>(q.size(1)),
    };
    auto make_dq_bf16_output_gl = [&]()
        -> detail::cta2_fused_dense_dq_bf16_gl {
        if (projection_qkv_output == nullptr) {
            return kittens::py::tensor_to_gl<
                detail::cta2_fused_dense_dq_bf16_gl
            >(*dq_bf16_reduce);
        }
        return ::kittens::make_gl<
            detail::cta2_fused_dense_dq_bf16_gl
        >(
            reinterpret_cast<uint64_t>(
                projection_qkv_output->data_ptr()
            ),
            static_cast<int>(q.size(0)),
            static_cast<int>(q.size(1)),
            static_cast<int>(q.size(2)),
            kB300QKDim * 2 + kB300VDim
        );
    };
    DenseG dense_g = [&]() -> DenseG {
        if constexpr (LowpMode == detail::kCta2DenseLowpNone) {
            return dense_base_g;
        } else if constexpr (
            LowpMode == detail::kCta2DenseLowpFp8
        ) {
            TORCH_CHECK(
                q_lowp != nullptr && k_lowp != nullptr &&
                    dout_fp8 != nullptr && dout_dp_fp8 != nullptr &&
                    v_fp8 != nullptr,
                "native FP8 requires prequantized Q/K and E4M3 dO/V operands"
            );
            // Recover 1 / (q_quant_scale * k_quant_scale) from the two
            // low-precision output scales already carried by this launcher.
            // This keeps score dequantization inside the softmax multiplier.
            return DenseG{
                dense_base_g,
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_q_fp8_gl
                >(*q_lowp),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_k_fp8_gl
                >(*k_lowp),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_do_fp8_gl
                >(*dout_fp8),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_do_dp_fp8_gl
                >(*dout_dp_fp8),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_v_fp8_gl
                >(*v_fp8),
                dq_output_scale,
                dk_output_scale,
                ds_quant_scale,
                dense_base_g.scale_log2e *
                    (dq_output_scale * dk_output_scale *
                     ds_quant_scale * ds_quant_scale) /
                    (dense_base_g.scale * dense_base_g.scale),
            };
        } else if constexpr (
            LowpMode == detail::kCta2DenseLowpFp4
        ) {
            static_assert(
                LowpMode == detail::kCta2DenseLowpFp4
            );
            TORCH_CHECK(
                q_lowp != nullptr && score_q_lowp != nullptr &&
                    k_lowp != nullptr && score_k_lowp != nullptr,
                "native FP4 score/dQ/dK requires aligned and compact Q/K layouts"
            );
            return DenseG{
                dense_base_g,
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_q_fp4_gl,
                    false
                >(*q_lowp),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_score_q_fp4_gl,
                    false
                >(*score_q_lowp),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_k_fp4_gl,
                    false
                >(*k_lowp),
                kittens::py::tensor_to_gl<
                    detail::cta2_fused_dense_score_k_fp4_gl,
                    false
                >(*score_k_lowp),
                dq_output_scale,
                dk_output_scale,
                ds_quant_scale,
                dense_base_g.scale_log2e *
                    (dq_output_scale * dk_output_scale *
                     ds_quant_scale * ds_quant_scale) /
                    (dense_base_g.scale * dense_base_g.scale),
            };
        } else {
            static_assert(
                LowpMode == detail::kCta2DenseLowpFp4Fp8Pv ||
                    LowpMode ==
